# Index by key for O(1) lookups.
SETTINGS_BY_KEY = {s["key"]: s for s in SETTINGS_SCHEMA}

def _coerce_setting(schema, raw):
    """Coerce `raw` into the right type for `schema`, clamping to the
    declared range / valid options. Returns the schema's default on
    type errors so a malformed JSON can't crash the loader."""
    kind = schema["kind"]
    # Buttons aren't values — they're action triggers. Nothing to coerce.
    if kind == "button":
        return None
    try:
        if kind == "bool":
            if isinstance(raw, bool):
                return raw
            if isinstance(raw, (int, float)):
                return bool(raw)
            if isinstance(raw, str):
                return raw.strip().lower() in ("true", "1", "yes", "on")
            return bool(schema["default"])
        if kind == "int":
            v = int(raw)
            if "min" in schema:
                v = max(schema["min"], v)
            if "max" in schema:
                v = min(schema["max"], v)
            return v
        if kind == "float":
            v = float(raw)
            if "min" in schema:
                v = max(schema["min"], v)
            if "max" in schema:
                v = min(schema["max"], v)
            return v
        if kind == "string":
            return str(raw)
        if kind == "enum":
            options = schema.get("options", [])
            # chat_main_char holds a character name whose validity depends
            # on who's logged in *right now* (checked at use-time in
            # _mb_chat_lock_target). Its option list is built dynamically
            # and may not include a saved/away character at load time, so
            # accept any non-empty string here rather than snapping it back
            # to default on every reload.
            if schema.get("key") == "chat_main_char":
                return str(raw) if raw else schema.get("default", "")
            # Normalise int-from-json: enum option might be the int 300
            # but raw might be the string "300". Coerce raw to match.
            if options and isinstance(options[0], int):
                try:
                    raw = int(raw)
                except (ValueError, TypeError):
                    pass
            if raw in options:
                return raw
            return schema["default"]
        if kind == "json":
            # Free-form JSON value (list / dict). Used for settings
            # that store collections — e.g. hidden_chat_tabs holds a
            # list of tab indices. We trust the JSON loader to give
            # us the right shape; the consumer is responsible for
            # any deeper validation. Falls back to default on a None
            # explicitly (so a stray null doesn't replace a list).
            if raw is None:
                return schema["default"]
            return raw
    except (ValueError, TypeError):
        pass
    return schema["default"]

def load_settings():
    """Load (or write the default) settings JSON. Returns dict
    keyed by setting key. Missing keys fall back to the schema
    default — this means adding a new setting is an additive
    schema change, no migration needed.

    Excluded from the persistent dict:
      - Button-kind entries (they're action triggers, no value)
      - live_key bools (they read/write a module global directly,
        not the persistent settings — e.g. setup_mode)
    """
    def _persistable(s):
        if s["kind"] == "button":
            return False
        if s.get("live_key"):
            return False
        return True

    out = {s["key"]: s["default"] for s in SETTINGS_SCHEMA
           if _persistable(s)}
    try:
        if os.path.exists(SETTINGS_FILE):
            with open(SETTINGS_FILE) as f:
                raw = json.load(f)
            if not isinstance(raw, dict):
                raw = {}
            for key, schema in SETTINGS_BY_KEY.items():
                if not _persistable(schema):
                    continue
                if key in raw:
                    # NOTE: use the STATIC schema here, not _setting_schema()
                    # — load_settings runs at module-import time, before
                    # _setting_schema is defined later in the file. Calling
                    # it here raised NameError and made the WHOLE load fall
                    # back to defaults (settings never persisted). The enum
                    # coercion already special-cases chat_main_char to accept
                    # any character name, so the dynamic schema isn't needed
                    # for a correct load.
                    out[key] = _coerce_setting(schema, raw[key])
            # Preserve any persisted keys that aren't in the schema.
            # Some settings are stored directly via `settings[key] = ...`
            # rather than the schema (e.g. the hide-nub's x/y/size are
            # drag-driven, no settings-menu entry). Without this loop
            # those keys would be silently dropped on every reload,
            # which is why the eye nub kept resetting to its default
            # position even though `save_settings` wrote it to disk.
            #
            # We don't coerce here — values stay as the JSON gave us.
            # The reading site (e.g. `_hide_nub_geometry`) handles
            # coercion and clamping per-key, which is more flexible
            # for drag-only state than the schema's coerce_setting.
            for key, val in raw.items():
                if key in SETTINGS_BY_KEY:
                    continue   # already handled above
                if key.startswith("_"):
                    continue   # private/internal keys, skip
                out[key] = val
            print(f"[OmniWatch] Loaded settings from {SETTINGS_FILE}")
        else:
            with open(SETTINGS_FILE, "w") as f:
                json.dump(out, f, indent=2)
            print(f"[OmniWatch] Created default settings at "
                  f"{SETTINGS_FILE}")
    except Exception as e:
        print(f"[OmniWatch] Could not load settings: {e}. "
              f"Using defaults.")
    return out

# Live settings dict. Read via setting(key); write via set_setting(key,
# value) — the latter handles persistence and side effects.
settings = load_settings()

# Load augment nicknames (cross-character, USER_DIR-scoped).
_load_aug_nicknames()

# Load the saved sim-import gear-root path (USER_DIR-scoped).
_sim_load_import_root()

def setting(key):
    """Return the current value of the named setting, or its schema
    default if the key isn't recognised (defensive — protects against
    typos elsewhere in the code).

    Returns None for button-kind entries (they're action triggers, not
    values) and for any schema that lacks a default."""
    if key in settings:
        return settings[key]
    s = SETTINGS_BY_KEY.get(key)
    if not s:
        return None
    if s.get("kind") == "button":
        return None
    return s.get("default")

def _eff(panel_scale):
    """Effective render scale for a panel: its own scale times the
    global UI scale multiplier (global_ui_scale setting). Lets 4K /
    high-DPI users enlarge everything at once, or pack more on screen
    below 1.0, without per-panel resizing. Clamped to the setting's
    schema range; falls back to panel_scale unchanged on any error."""
    try:
        g = float(setting("global_ui_scale") or 1.0)
        if g < 0.5:
            g = 0.5
        elif g > 3.0:
            g = 3.0
        return float(panel_scale) * g
    except (TypeError, ValueError):
        return panel_scale

def _menu_g():
    """Clamped global UI scale for the 'chrome' that isn't a draggable
    panel — the settings dropdown, the Configure modals, and the header.
    Panels fold global_ui_scale in via _eff(panel_scale); chrome has no
    per-panel scale of its own, so it reads the multiplier directly here
    and applies it to its fonts and geometry. Same 0.5–3.0 clamp as
    _eff so everything scales by one consistent factor. Falls back to
    1.0 on any error."""
    try:
        g = float(setting("global_ui_scale") or 1.0)
        if g < 0.5:
            g = 0.5
        elif g > 3.0:
            g = 3.0
        return g
    except (TypeError, ValueError):
        return 1.0

def save_settings():
    """Write the current settings dict back to disk."""
    try:
        with open(SETTINGS_FILE, "w") as f:
            json.dump(settings, f, indent=2)
    except Exception as e:
        print(f"[OmniWatch] Could not save settings: {e}")


# ── Whole-display hide nub ───────────────────────────────────────────
def _hide_nub_geometry():
    """Resolve the nub's (x, y, size) from settings, clamped to the
    current window and the min/max size. Returns ints. Defaults apply
    when the keys are absent (first run)."""
    try:
        size = int(settings.get("hide_nub_size", _HIDE_NUB_DEFAULT_SIZE))
    except (TypeError, ValueError):
        size = _HIDE_NUB_DEFAULT_SIZE
    size = max(_HIDE_NUB_MIN_SIZE, min(_HIDE_NUB_MAX_SIZE, size))
    try:
        x = int(settings.get("hide_nub_x", _HIDE_NUB_DEFAULT_X))
    except (TypeError, ValueError):
        x = _HIDE_NUB_DEFAULT_X
    try:
        y = int(settings.get("hide_nub_y", _HIDE_NUB_DEFAULT_Y))
    except (TypeError, ValueError):
        y = _HIDE_NUB_DEFAULT_Y
    # Keep at least partly on-screen so it can't be lost off an edge.
    x = max(0, min(WIDTH - size, x))
    y = max(0, min(HEIGHT - size, y))
    return x, y, size


def _hide_nub_save_geometry(x, y, size):
    """Persist nub geometry to the settings dict and write to disk.
    Stored directly (not via set_setting) because the nub is drag-
    driven and has no settings-menu schema entry."""
    settings["hide_nub_x"] = int(x)
    settings["hide_nub_y"] = int(y)
    settings["hide_nub_size"] = int(size)
    save_settings()


def draw_hide_nub(surface):
    """Draw the small persistent toggle nub. Always drawn (in both the
    shown and hidden states) so the user can always toggle back. An eye
    glyph indicates state: open eye = display visible, slashed eye =
    display hidden. A small corner handle affords resizing.

    Records _hide_nub_rect and _hide_nub_handle_rect for the event
    handler's hit-testing."""
    global _hide_nub_rect, _hide_nub_handle_rect
    if not setting("show_hide_nub"):
        # User disabled the nub entirely. Clear rects so stale geometry
        # can't be clicked.
        _hide_nub_rect = None
        _hide_nub_handle_rect = None
        return

    x, y, size = _hide_nub_geometry()
    rect = pygame.Rect(x, y, size, size)
    _hide_nub_rect = rect

    # Body: rounded translucent square. Slightly more opaque when
    # hidden so it stands out against an otherwise empty screen.
    body_alpha = 210 if display_hidden else 150
    body = pygame.Surface((size, size), pygame.SRCALPHA)
    body.fill((24, 26, 32, body_alpha))
    surface.blit(body, (x, y))
    pygame.draw.rect(surface, (90, 100, 120), rect, 1, border_radius=4)

    # Eye glyph, scaled to the nub. Drawn with primitives so it scales
    # cleanly at any size and needs no font/asset.
    cx, cy = x + size / 2, y + size / 2
    eye_w = size * 0.62
    eye_h = size * 0.36
    col = (210, 220, 235) if not display_hidden else (235, 200, 120)
    eye_rect = pygame.Rect(0, 0, int(eye_w), int(eye_h))
    eye_rect.center = (int(cx), int(cy))
    pygame.draw.ellipse(surface, col, eye_rect, max(1, size // 16))
    pr = max(2, int(size * 0.10))
    pygame.draw.circle(surface, col, (int(cx), int(cy)), pr)
    if display_hidden:
        # Slash across the eye to signal "hidden".
        pygame.draw.line(
            surface, (235, 200, 120),
            (int(x + size * 0.22), int(y + size * 0.74)),
            (int(x + size * 0.78), int(y + size * 0.26)),
            max(1, size // 12))

    # Resize handle: a couple diagonal ticks in the bottom-right corner.
    hs = max(6, size // 4)
    handle = pygame.Rect(x + size - hs, y + size - hs, hs, hs)
    _hide_nub_handle_rect = handle
    for i in range(1, 3):
        off = int(hs * i / 3)
        pygame.draw.line(
            surface, (140, 150, 165),
            (x + size - off, y + size - 1),
            (x + size - 1, y + size - off), 1)


def set_setting(key, value):
    """Update a setting's value, persist to disk, and dispatch any
    side effects declared by the schema. Returns the coerced value
    that was actually stored."""
    schema = SETTINGS_BY_KEY.get(key)
    if not schema:
        print(f"[OmniWatch] set_setting: unknown key {key!r}")
        return None
    # Use the DYNAMIC schema for keys whose enum options are filled in at
    # runtime (e.g. chat_main_char's character list). The static
    # SETTINGS_BY_KEY copy only has placeholder options, so coercing
    # against it would reject every real value and snap back to default —
    # which is exactly why the chat-main arrows appeared to do nothing.
    dyn = _setting_schema(key)
    if dyn is not None:
        schema = dyn
    coerced = _coerce_setting(schema, value)
    settings[key] = coerced
    save_settings()
    apply_setting_side_effects(key, coerced)
    return coerced

def dispatch_setting_action(key):
    """Run a button-kind setting's action. Looks up the action name in
    the schema and routes to the matching handler. Each action is just
    a python function; add new ones below as new buttons are needed."""
    schema = SETTINGS_BY_KEY.get(key)
    if not schema or schema.get("kind") != "button":
        print(f"[OmniWatch] dispatch_setting_action: not a button: {key!r}")
        return
    action = schema.get("action")
    handler = _SETTINGS_ACTIONS.get(action)
    if handler is None:
        print(f"[OmniWatch] no handler for setting action {action!r}")
        return
    try:
        handler()
    except Exception as e:
        print(f"[OmniWatch] action {action!r} failed: {e!r}")

def _open_path(path, label="file"):
    """Open `path` in the OS default handler (Notepad for .json on
    Windows, etc.). Catches and logs any failure so the action button
    never raises. Used by all the 'Edit X' / 'Open X log' buttons."""
    try:
        if hasattr(os, "startfile"):
            os.startfile(path)         # type: ignore[attr-defined]
        else:
            import subprocess
            opener = "open" if sys.platform == "darwin" else "xdg-open"
            subprocess.Popen([opener, path])
        print(f"[OmniWatch] opened {label}: {path}")
    except Exception as e:
        print(f"[OmniWatch] could not open {path}: {e!r}")

def _open_buff_config_in_editor():
    """Open omniwatch_buffs.json (party-panel buff/debuff blacklists +
    aliases). Re-creates from template if missing so opening always
    succeeds."""
    if not os.path.exists(BUFF_CFG):
        try:
            with open(BUFF_CFG, "w") as f:
                json.dump(_BUFF_CFG_TEMPLATE, f, indent=2)
        except Exception as e:
            print(f"[OmniWatch] could not create buff config: {e!r}")
            return
    _open_path(BUFF_CFG, "buff config")


def _open_stats_layout_global():
    """Open omniwatch_stats_layout.json so the user can edit the GLOBAL
    layout (the fallback used for any job without a per-job override).

    Adds a helpful comment-like top-level _help field if the file
    doesn't exist yet. JSON doesn't support real comments, but a
    leading "_help" string gives users guidance when they first open
    the file.
    """
    if not os.path.exists(STATS_LAYOUT_FILE):
        try:
            # Build a starter file: defaults + an in-file help string
            # listing the available cell keys so users don't have to
            # guess what to put in the "hidden" array.
            all_keys = [c[0] for c in STATS_CELLS]
            starter = {
                "_help": (
                    "Hide stat cells by adding their key to "
                    "the 'hidden' array under 'global' or under "
                    "a job name in 'per_job'. Re-enter setup "
                    "mode (//ow setup) to apply changes. "
                    "Available cell keys: " + ", ".join(all_keys)
                ),
                "version": 1,
                "global": _default_stats_layout(),
                "per_job": {},
            }
            with open(STATS_LAYOUT_FILE, "w") as f:
                json.dump(starter, f, indent=2)
        except Exception as e:
            print(f"[OmniWatch] could not create stats layout: {e!r}")
            return
    _open_path(STATS_LAYOUT_FILE, "stats layout (global)")


