# ── Layout ───────────────────────────────────────────────────────────────────
HEADER_H     = 36


# ── Header geometry ──────────────────────────────────────────────────
# Single source of truth for the header bar's position, drawn height,
# and screen footprint, so the panels' layout origin and the header-
# region hit guards stay consistent no matter where the bar sits.
#
# Two display modes (header_autohide):
#   • always-visible — the bar draws every frame and the panels reserve
#     space for it (layout_top/layout_bottom exclude the bar).
#   • auto-hide — taskbar style: the bar is normally hidden and the
#     panels get the full window; pushing the mouse to its screen edge
#     reveals it, and it hides again when the cursor leaves. Here the bar
#     OVERLAYS the panels (no reserved space), like the Windows taskbar
#     over a maximized window. Revealing the bar is also how the settings
#     gear is reached, so no separate hotkey is needed.
#
# header_h() is the *drawn* bar height (base 36 for now; the bar-resize
# pass will switch it to round(HEADER_H * _menu_g()) once draw_header
# scales its own contents). Reserved-space decisions live in
# layout_top()/layout_bottom(), not header_h(), so auto-hide can show a
# full-height bar while reserving zero layout space.

# Thin strip at the very screen edge that reveals an auto-hidden header
# when the cursor enters it. Once revealed the bar stays up while the
# cursor is anywhere over it (see _update_header_reveal).
_HEADER_REVEAL_TRIGGER = 3
# Live reveal state for auto-hide mode, refreshed each frame from the
# mouse position. Ignored when auto-hide is off.
_header_revealed = False

def header_at_top():
    try:
        return (setting("header_position") or "top") != "bottom"
    except Exception:
        return True

def header_autohide_on():
    try:
        return bool(setting("header_autohide"))
    except Exception:
        return False

def header_h():
    """Drawn header bar height in px, scaled by the global UI factor so
    the bar grows/shrinks in step with the panels. draw_header() scales
    its own fonts and offsets by the same factor."""
    return max(1, round(HEADER_H * _menu_g()))

def header_y():
    """Top edge of the bar: 0 at the top, HEIGHT - header_h() at the
    bottom. Determined purely by header_position."""
    return 0 if header_at_top() else HEIGHT - header_h()

def header_rect():
    """Screen rect the bar occupies at its edge. Used for reveal
    detection and, when the bar is shown, the header-region click/wheel
    guards."""
    return pygame.Rect(0, header_y(), WIDTH, header_h())

def header_shown():
    """Whether the bar is currently drawn / interactive. Always true when
    auto-hide is off; in auto-hide mode it tracks the reveal state."""
    if not header_autohide_on():
        return True
    return _header_revealed

def _update_header_reveal():
    """Refresh the auto-hide reveal state from the current mouse position.
    Called once per frame before the header is drawn. Taskbar-style
    hysteresis: a thin edge strip triggers the reveal, then the bar stays
    up while the cursor is anywhere over it (or while the settings
    dropdown that hangs off the gear is open, so it can't vanish out from
    under the menu)."""
    global _header_revealed
    if not header_autohide_on():
        _header_revealed = False
        return
    if settings_menu_open:
        _header_revealed = True
        return
    mx, my = pygame.mouse.get_pos()
    if _header_revealed:
        _header_revealed = header_rect().collidepoint(mx, my)
    else:
        if header_at_top():
            trig = pygame.Rect(0, 0, WIDTH, _HEADER_REVEAL_TRIGGER)
        else:
            trig = pygame.Rect(0, HEIGHT - _HEADER_REVEAL_TRIGGER,
                               WIDTH, _HEADER_REVEAL_TRIGGER)
        if trig.collidepoint(mx, my):
            _header_revealed = True

def layout_top():
    """Smallest y panel content should occupy. Reserves space for a
    top-anchored bar only when it's always-visible; an auto-hidden bar
    overlays instead, freeing the top edge for panels."""
    if header_at_top() and not header_autohide_on():
        return header_h()
    return 0

def layout_bottom():
    """Largest y panel content should reach. Reserves space for a
    bottom-anchored always-visible bar; otherwise the full window."""
    if (not header_at_top()) and not header_autohide_on():
        return HEIGHT - header_h()
    return HEIGHT

def _clear_header_click_rects():
    """Null out the header's click targets. Called when the header is
    hidden so a click where the gear / clock / inventory / events button
    used to sit doesn't still register over whatever panel now occupies
    that space. Each dispatch site already None-guards these."""
    global settings_button_rect, char_view_button_rect
    global header_clock_button_rect, inventory_button_rect
    global events_button_rect
    settings_button_rect = None
    char_view_button_rect = None
    header_clock_button_rect = None
    inventory_button_rect = None
    events_button_rect = None
PANEL_X      = 20
# Extra space reserved at the right end of the header (after the
# coordinates) so the block doesn't sit flush to the edge and the
# hide/show eye nub has a place to live. ~30px clears the default
# 24px nub plus a small gap.
HEADER_RIGHT_BUFFER = 30
ROW_PAD      = 8
START_Y      = HEADER_H + 12   # rows start below header
BAR_W        = 240
BAR_H        = 12
BAR_GAP      = 16
NAME_W       = 120
BARS_X_OFF   = NAME_W + 12
BUFF_X_OFF   = BARS_X_OFF + BAR_W + 16
BUFF_COL_W   = 110
DEBUFF_COL_W = 110
DEBUFF_X_OFF = BUFF_X_OFF + BUFF_COL_W + 12
BUFF_LINE_H  = 15
ROW_MIN_H    = 96
ROW_PAD_V    = 12
PANEL_W      = BARS_X_OFF + BAR_W + 16 + BUFF_COL_W + 12 + DEBUFF_COL_W + 20

# ── Equip Viewer layout ───────────────────────────────────────────────────────
EV_COLS      = 4
EV_ROWS      = 4
EV_SLOT_SIZE = 52          # px per cell (icon area)
EV_PAD       = 6           # inner padding around icon
EV_TITLE_H   = 22          # header label height
EV_BORDER    = 1
EV_GRID_W    = EV_COLS * EV_SLOT_SIZE
EV_GRID_H    = EV_ROWS * EV_SLOT_SIZE
EV_PANEL_W   = EV_GRID_W + 2
EV_PANEL_H   = EV_TITLE_H + EV_GRID_H + 2
EV_X         = PANEL_X     # anchored to left edge, same as party panels
# EV_Y is computed each frame from the bottom of the last party row


# ── Helpers ──────────────────────────────────────────────────────────────────
def hp_color(hpp, flashing):
    """HP bar color by percentage.
    76-100 = green, 51-75 = yellow, 31-50 = orange, 0-30 = red (flashes)."""
    if hpp <= 30:
        return COL_HP_FLASH if flashing else COL_HP_LOW
    if hpp <= 50:
        return COL_HP_ORANGE
    if hpp <= 75:
        return COL_HP_MID
    return COL_HP_HI

def tp_color(tp):
    """TP bar color by absolute TP value.
    0-999 = yellow, 1000-1999 = light green, 2000-2999 = medium green,
    3000+ pulses between COL_TP_MAX and a brighter shade for visibility."""
    if tp >= 3000:
        # Pulse at ~1.5 Hz between COL_TP_MAX and a brighter highlight.
        # Mirrors the hate-pulse cadence so it feels consistent.
        t = time.time()
        phase = (math.sin(t * 6.0) + 1.0) * 0.5  # 0..1
        base = COL_TP_MAX
        bright = (255, 255, 200)
        r = int(base[0] + (bright[0] - base[0]) * phase)
        g = int(base[1] + (bright[1] - base[1]) * phase)
        b = int(base[2] + (bright[2] - base[2]) * phase)
        return (r, g, b)
    if tp >= 2000:
        return COL_TP_HI
    if tp >= 1000:
        return COL_TP_MID
    return COL_TP_LOW

def draw_bar(surface, x, y, w, h, percent, color, label=None, label_font=None):
    pygame.draw.rect(surface, COL_BAR_BG, (x, y, w, h))
    fill_w = max(0, int(w * min(percent, 1.0)))
    if fill_w > 0:
        pygame.draw.rect(surface, color, (x, y, fill_w, h))
    pygame.draw.rect(surface, COL_BORDER, (x, y, w, h), 1)
    if label:
        lf = label_font or font_label
        # Draw a 1-pixel dark outline behind the label for readability
        # against any fill color (especially bright greens).
        shadow = lf.render(label, True, (0, 0, 0))
        main   = lf.render(label, True, (255, 255, 255))
        lx = x + 3
        ly = y + (h - main.get_height()) // 2
        for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            surface.blit(shadow, (lx + dx, ly + dy))
        surface.blit(main, (lx, ly))

def classify(buff_names, buff_ids=None):
    """Split buff list into (buffs, debuffs), applying hide/priority/alias
    rules. Each entry is first classified as buff vs debuff (by keyword
    match), THEN run through the context-aware blacklist so a name in
    hide_party_debuffs only hides debuffs (not its buff sibling, if a
    name happens to match both contexts). Priority entries come first
    within each bucket, in the order listed in the config file. Aliases
    are applied at display time.

    If `buff_ids` is provided, returns 4 lists:
      (buff_names, buff_ids_aligned, debuff_names, debuff_ids_aligned)
    Otherwise returns 2 lists (buff_names, debuff_names) — back-compat
    for callers that don't track IDs (e.g. older code paths and the
    standalone buff timer panel).
    """
    has_ids = buff_ids is not None
    # Walk both lists in lockstep so the bucket assignments preserve
    # the matching id for each name.
    if has_ids:
        # Tolerate length mismatch (defensive against legacy feeds that
        # filled `buffs` but not `buff_ids`): pad with None.
        if len(buff_ids) < len(buff_names):
            buff_ids = list(buff_ids) + [None] * (len(buff_names) - len(buff_ids))
        buff_pairs   = []      # list of (name, id) for the buffs bucket
        debuff_pairs = []      # list of (name, id) for the debuffs bucket
        for i, b in enumerate(buff_names):
            bid = buff_ids[i] if i < len(buff_ids) else None
            if any(k.lower() in b.lower() for k in DEBUFF_KEYWORDS):
                if not is_hidden_in(b, "party_debuff"):
                    debuff_pairs.append((b, bid))
            else:
                if not is_hidden_in(b, "party_buff"):
                    buff_pairs.append((b, bid))
    else:
        buffs, debuffs = [], []
        for b in buff_names:
            if any(k.lower() in b.lower() for k in DEBUFF_KEYWORDS):
                if not is_hidden_in(b, "party_debuff"):
                    debuffs.append(b)
            else:
                if not is_hidden_in(b, "party_buff"):
                    buffs.append(b)

    # Sort so priority items appear first, preserving the user's priority order.
    def _sort_key_name(name):
        lower = name.lower()
        if lower in _buff_priority_set:
            for i, p in enumerate(_buff_priority):
                if p.lower() == lower:
                    return (0, i)
        return (1, 0)
    def _sort_key_pair(pair):
        return _sort_key_name(pair[0])

    if has_ids:
        buff_pairs.sort(key=_sort_key_pair)
        debuff_pairs.sort(key=_sort_key_pair)
        # Apply aliases at display time. IDs travel through unchanged.
        buff_names_out   = [display_name(p[0]) for p in buff_pairs]
        buff_ids_out     = [p[1] for p in buff_pairs]
        debuff_names_out = [display_name(p[0]) for p in debuff_pairs]
        debuff_ids_out   = [p[1] for p in debuff_pairs]
        return (buff_names_out, buff_ids_out,
                debuff_names_out, debuff_ids_out)
    else:
        buffs.sort(key=_sort_key_name)
        debuffs.sort(key=_sort_key_name)
        buffs   = [display_name(b) for b in buffs]
        debuffs = [display_name(d) for d in debuffs]
        return buffs, debuffs

def scaled_panel_dims(scale):
    """Return a dict of scaled geometry + fonts for a party panel at the given scale."""
    s = _eff(scale)
    bar_w        = int(BAR_W        * s)
    bar_h        = max(4, int(BAR_H * s))
    bar_gap      = max(6, int(BAR_GAP * s))
    name_w       = int(NAME_W       * s)
    bars_x_off   = name_w + int(12 * s)
    buff_col_w   = int(BUFF_COL_W   * s)
    debuff_col_w = int(DEBUFF_COL_W * s)
    buff_x_off   = bars_x_off + bar_w + int(16 * s)
    debuff_x_off = buff_x_off + buff_col_w + int(12 * s)
    # Buff/debuff column lines: smaller than the main panel text so more
    # entries fit per row when the user enables 'specific_buff_names'
    # (Honor March vs March is longer, so we win some space back). The
    # line height is paired with the font so they scale together.
    # User-configurable size via party_buff_font_size: Small for higher
    # density, Large for at-a-glance readability. The multiplier is
    # applied on top of the per-panel scale `s` so manual panel scale
    # and font-size preference compose cleanly.
    _buff_size_pref = (setting("party_buff_font_size")
                       if "party_buff_font_size" in SETTINGS_BY_KEY
                       else "medium")
    _buff_size_mult = {"small": 0.85, "medium": 1.0, "large": 1.20}.get(
        _buff_size_pref, 1.0)
    # Sizing: the base px below sets Medium; Small/Large stay proportional
    # via _buff_size_mult. Base was 8 (Medium~8px); bumped to 9 for
    # slightly more readable text at the default. Lifts all three by the
    # same ratio: Small~7.65px, Medium 9px, Large~10.8px. Line height base
    # nudged from -5 to -4 so rows keep pace with the taller glyphs.
    buff_font_px = max(7, int(9 * s * _buff_size_mult))
    buff_line_h  = max(7, int((BUFF_LINE_H - 4) * s * _buff_size_mult))
    row_min_h    = int(ROW_MIN_H * s)
    row_pad_v    = int(ROW_PAD_V * s)
    panel_w      = bars_x_off + bar_w + int(16 * s) + buff_col_w + int(12 * s) + debuff_col_w + int(20 * s)
    return {
        "s": s,
        "bar_w": bar_w, "bar_h": bar_h, "bar_gap": bar_gap,
        "name_w": name_w, "bars_x_off": bars_x_off,
        "buff_col_w": buff_col_w, "debuff_col_w": debuff_col_w,
        "buff_x_off": buff_x_off, "debuff_x_off": debuff_x_off,
        "buff_line_h": buff_line_h,
        "row_min_h": row_min_h, "row_pad_v": row_pad_v,
        "panel_w": panel_w,
        "f_name":      get_font("Consolas", 17 * s, bold=True),
        "f_small":     get_font("Consolas", 14 * s),
        "f_buff":      get_font("Consolas", buff_font_px),
        "f_label":     get_font("Consolas", 13 * s),
        "f_bar_label": get_font("Consolas", 13 * s, bold=True),
    }

def row_height(member, scale=1.0):
    """Panel height for a given member.

    Previously this grew to fit all buffs/debuffs, which caused panels below
    to get covered when a neighbor's buff list got long. Now height is fixed
    at row_min_h and overflow is handled at render time via '+N more' + scroll.
    The `member` argument is kept for API compatibility but ignored.
    """
    return scaled_panel_dims(scale)["row_min_h"]


def scaled_ally_dims(scale):
    """Geometry for an alliance row.

    Alliance rows are a simplified party row: name + jobs on the left,
    HP/MP/TP bars on the right. No buff/debuff columns. Shorter overall
    height since there's less to display. Used for alliance party 1 and
    alliance party 2 (a10..a15, a20..a25).
    """
    s = _eff(scale)
    bar_w        = int(160 * s)        # narrower bars than main party
    bar_h        = max(3, int(8 * s))  # thinner too
    bar_gap      = max(4, int(11 * s))
    name_w       = int(110 * s)
    bars_x_off   = name_w + int(10 * s)
    row_min_h    = int(56 * s)
    row_pad_v    = int(8 * s)
    panel_w      = bars_x_off + bar_w + int(14 * s)
    return {
        "s": s,
        "bar_w": bar_w, "bar_h": bar_h, "bar_gap": bar_gap,
        "name_w": name_w, "bars_x_off": bars_x_off,
        "row_min_h": row_min_h, "row_pad_v": row_pad_v,
        "panel_w": panel_w,
        "f_name":  get_font("Consolas", 13 * s, bold=True),
        "f_label": get_font("Consolas", 10 * s),
        "f_bar_label": get_font("Consolas", 9 * s),
    }


def ally_row_height(scale=1.0):
    return scaled_ally_dims(scale)["row_min_h"]


def draw_ally_panel(surface, x, y, member, scale=1.0):
    """Render a single alliance member panel.

    Smaller than the main party panel. Layout: name + job/sub line on the
    left, three thin bars (HP/MP/TP) on the right. No buff/debuff columns,
    no targeting indicator (alliance targeting context is rare and the
    indicator clutters small panels).
    """
    d  = scaled_ally_dims(scale)
    rh = d["row_min_h"]
    pw = d["panel_w"]
    _es = _eff(scale)   # effective scale for raw positioning offsets

    pygame.draw.rect(surface, COL_PANEL,  (x, y, pw, rh), border_radius=4)
    pygame.draw.rect(surface, COL_BORDER, (x, y, pw, rh), 1, border_radius=4)
    draw_accent_stripe(surface, x, y, rh, ACCENT_ALLY)

    # Name + job/sub stacked on the left.
    name_surf = d["f_name"].render(member.get("name", "?"), True, COL_NAME)
    mj  = member.get("main_job", "")
    mjl = member.get("main_lvl", 0)
    sj  = member.get("sub_job",  "")
    sjl = member.get("sub_lvl",  0)
    job_str = ""
    if mj:
        job_str = f"{mj}{mjl}" if mjl else mj
        if sj:
            job_str += f" / {sj}{sjl}" if sjl else f" / {sj}"
    job_surf = d["f_label"].render(job_str, True, COL_LABEL_DIM) if job_str else None

    block_h = name_surf.get_height() + (job_surf.get_height() + 2 if job_surf else 0)
    block_y = y + (rh - block_h) // 2
    surface.blit(name_surf, (x + int(8 * _es), block_y))
    if job_surf:
        surface.blit(job_surf, (x + int(8 * _es),
                                block_y + name_surf.get_height() + 2))

    # Three bars on the right, vertically centered.
    bx = x + d["bars_x_off"]
    bars_block_h = d["bar_h"] * 3 + d["bar_gap"] * 2
    by = y + (rh - bars_block_h) // 2

    hpp = member.get("hpp", 0)
    hp  = member.get("hp",  0)
    mp  = member.get("mp",  0)
    tp  = member.get("tp",  0)
    hc = hp_color(hpp, flash) if 'flash' in globals() else (200, 80, 80)
    draw_bar(surface, bx, by,
             d["bar_w"], d["bar_h"], hpp / 100.0, hc,
             f"HP {hp} ({hpp}%)", d["f_bar_label"])
    draw_bar(surface, bx, by + d["bar_gap"],
             d["bar_w"], d["bar_h"], min(mp / 1500, 1.0), COL_MP,
             f"MP {mp}", d["f_bar_label"])
    draw_bar(surface, bx, by + d["bar_gap"] * 2,
             d["bar_w"], d["bar_h"], min(tp / 3000, 1.0), tp_color(tp),
             f"TP {tp}", d["f_bar_label"])


# ── Recast panel ──────────────────────────────────────────────────────────
# Vertical stack of horizontal progress bars showing currently-cooling-down
# spells and abilities. Each entry: name on left, countdown on right,
# fill from left-to-right showing progress (empty = just cast, full = ready).
# Driven by recast_state (populated by RECAST_BATCH packets from lua).
RECAST_PANEL_PAD       = 6      # internal padding
RECAST_PANEL_BAR_H     = 18     # height per bar
RECAST_PANEL_BAR_GAP   = 3      # vertical gap between bars
RECAST_PANEL_BAR_W     = 220    # base bar width (scaled)

# Tracks the peak recast value we've seen for each entry within its current
# cooldown cycle. Used to compute the fill ratio so each bar starts empty
# and fills as the countdown progresses toward zero. Dict shape:
#   {(kind, id): {"max_secs": float, "first_seen_at": float}}
# Cleared when an entry leaves recast_state (i.e. its cooldown ended) so
# the next cast starts fresh.
_recast_peaks = {}

# Tracks recently-ready entries so they flash briefly before disappearing.
# When an entry that was in recast_state on the previous tick is no longer
# present, the receive loop pops it into here. The render loop draws these
# alongside live recasts, blinking, until RECAST_FLASH_SEC has elapsed.
# Dict shape: {(kind, id): {"name": str, "ready_at": float}}
_recast_flashes = {}
RECAST_FLASH_SEC = 2.0  # how long the green ready-flash plays

# Tracks recently-expired buffs so they flash briefly (red) before
# disappearing. Same mechanism as _recast_flashes but rendered as a red
# wear-off warning instead of a green ready signal. Dict keyed by buff_id.
_buff_flashes = {}
BUFF_FLASH_SEC = 2.0

# Worn-buff state. The "keep_worn_buffs" setting keeps buffs visible
# after they wear off, grayed out at the bottom of the panel. We
# don't track these in a separate dict any more — instead, when a
# buff disappears from a BUFF_BATCH, we keep its entry in buff_state
# and mark it worn=True. The same data the live timer was showing
# (name, source, etc.) carries through unchanged. See BUFF_BATCH
# parsing for the wear-detection logic.
# When this many seconds remain on a buff, it begins flashing in-panel
# (warning: about to expire). Distinct from the wear-off flash which
# fires AFTER it's gone. user prefers a tight 2-second window so the
# warning isn't visible long enough to feel naggy.
BUFF_EXPIRY_WARNING_SEC = 2.0


def _recast_color(secs):
    """Red for long waits, transitioning through yellow to green near zero."""
    if secs >= 60:    return (220, 80, 80)        # solid red
    if secs >= 30:    return (220, 140, 80)       # red-orange
    if secs >= 10:    return (220, 200, 80)       # yellow
    if secs >  0:     return (160, 220, 100)      # yellow-green
    return (120, 220, 120)                         # green (READY)


def _format_recast_time(secs):
    if secs <= 0:
        return "READY"
    if secs >= 60:
        m = int(secs // 60)
        s = int(secs % 60)
        return f"{m}:{s:02d}"
    return f"{secs:.1f}"


def scaled_recast_dims(scale):
    s = _eff(scale)
    return {
        "s":         s,
        "bar_w":     max(120, int(RECAST_PANEL_BAR_W * s)),
        "bar_h":     max(12, int(RECAST_PANEL_BAR_H * s)),
        "bar_gap":   max(2,  int(RECAST_PANEL_BAR_GAP * s)),
        "pad":       max(4,  int(RECAST_PANEL_PAD * s)),
        "f_entry":   get_font("Consolas", max(9, int(12 * s)), bold=True),
        "f_label":   get_font("Consolas", max(8, int(11 * s))),
    }


def recast_panel_size(scale, entries):
    """Compute (width, height) for the vertical bar stack.

    Width is fixed by scale (constant column). Height grows with entry
    count: pad + N * (bar_h + gap) - gap + pad. Empty list shows a
    minimal placeholder so the panel is still findable in setup mode.
    """
    d = scaled_recast_dims(scale)
    pad   = d["pad"]
    bar_w = d["bar_w"]
    bar_h = d["bar_h"]
    gap   = d["bar_gap"]
    if not entries:
        return (bar_w + pad * 2, bar_h + pad * 2)
    total_h = pad + len(entries) * (bar_h + gap) - gap + pad
    return (bar_w + pad * 2, total_h)


def draw_recast_panel(surface, x, y, entries, scale=1.0, locked=False):
    """Render vertical stack of horizontal recast bars at (x, y).

    Each bar: name text on left, time text on right, fill from left as
    the cooldown elapses (empty = just cast, full = ready). Color is
    driven by remaining seconds, not fill amount, so a long-cycle ability
    near ready looks the same color as a short-cycle one near ready.
    """
    d = scaled_recast_dims(scale)
    pw, ph = recast_panel_size(scale, entries)
    pad   = d["pad"]
    bar_w = d["bar_w"]
    bar_h = d["bar_h"]
    gap   = d["bar_gap"]

    # Panel background.
    pygame.draw.rect(surface, COL_PANEL,  (x, y, pw, ph), border_radius=4)
    pygame.draw.rect(surface, COL_BORDER, (x, y, pw, ph), 1, border_radius=4)
    draw_accent_stripe(surface, x, y, ph, ACCENT_RECAST)

    if not entries:
        title_surf = d["f_label"].render("Recast", True, COL_LABEL_DIM)
        surface.blit(title_surf, (x + pad,
                                   y + (ph - title_surf.get_height()) // 2))
        return pw, ph

    # Track peaks for fill calculation. Real entries have a (kind,id)
    # identity; setup-mode mocks don't, so we use the name as a fallback.
    # Flash entries are skipped — their secs is 0 and they shouldn't
    # influence the peak (which represents the cast-moment maximum).
    _now = time.time()
    seen_keys = set()
    for e in entries:
        key = (e.get("kind", "?"), e.get("id", e.get("name")))
        seen_keys.add(key)
        if e.get("is_flash"):
            continue
        secs = e.get("secs", 0.0)
        peak = _recast_peaks.get(key)
        if peak is None or secs > peak["max_secs"]:
            _recast_peaks[key] = {"max_secs": max(secs, 0.1),
                                   "first_seen_at": _now}

    # Prune peaks for entries no longer in the panel (cooldown completed).
    stale = [k for k in _recast_peaks if k not in seen_keys]
    for k in stale:
        del _recast_peaks[k]

    # Draw each bar.
    by = y + pad
    for e in entries:
        secs    = e.get("secs", 0.0)
        name    = e.get("name", "?")
        is_flash = e.get("is_flash", False)
        bx = x + pad

        if is_flash:
            # Just-ready flash: bar fully filled, alternating between
            # bright green and dim green so it blinks. ~3 Hz blink rate.
            age = e.get("flash_age", 0.0)
            phase = int(age * 6) % 2   # toggles every ~0.17s
            bright = phase == 0
            col      = (140, 255, 140) if bright else (60, 160, 60)
            fill_col = (40, 130, 60)   if bright else (25, 75, 35)
            # Trough.
            pygame.draw.rect(surface, (30, 30, 40),
                              (bx, by, bar_w, bar_h), border_radius=3)
            # Fully filled.
            pygame.draw.rect(surface, fill_col,
                              (bx, by, bar_w, bar_h), border_radius=3)
            # Border.
            pygame.draw.rect(surface, COL_BORDER,
                              (bx, by, bar_w, bar_h), 1, border_radius=3)
            # Text overlays.
            name_surf = d["f_entry"].render(name, True, col)
            time_surf = d["f_entry"].render("READY", True, col)
            text_y    = by + (bar_h - name_surf.get_height()) // 2
            surface.blit(name_surf, (bx + 4, text_y))
            surface.blit(time_surf, (bx + bar_w - time_surf.get_width() - 4,
                                      text_y))
        else:
            col   = _recast_color(secs)
            key   = (e.get("kind", "?"), e.get("id", name))
            peak  = _recast_peaks.get(key, {}).get("max_secs", max(secs, 0.1))
            # Fill ratio: 0 when freshly cast (secs == peak), 1 when ready.
            # Clamp so floating-point drift doesn't leak past edges.
            ratio = 1.0 - (secs / peak) if peak > 0 else 1.0
            ratio = max(0.0, min(1.0, ratio))

            # Background trough for the bar.
            pygame.draw.rect(surface, (30, 30, 40),
                              (bx, by, bar_w, bar_h), border_radius=3)
            # Filled portion.
            fill_w = int(bar_w * ratio)
            if fill_w > 0:
                # Slightly darker fill so text on top still reads well.
                fill_col = tuple(int(c * 0.55) for c in col)
                pygame.draw.rect(surface, fill_col,
                                  (bx, by, fill_w, bar_h), border_radius=3)
            # Border.
            pygame.draw.rect(surface, COL_BORDER,
                              (bx, by, bar_w, bar_h), 1, border_radius=3)

            # Text overlays: name on left, countdown on right.
            time_str  = _format_recast_time(secs)
            name_surf = d["f_entry"].render(name, True, col)
            time_surf = d["f_entry"].render(time_str, True, col)
            text_y    = by + (bar_h - name_surf.get_height()) // 2
            surface.blit(name_surf, (bx + 4, text_y))
            surface.blit(time_surf, (bx + bar_w - time_surf.get_width() - 4,
                                      text_y))

        by += bar_h + gap

    return pw, ph


# ── Buff timer panel ──────────────────────────────────────────────────────
# Mirrors the recast panel: vertical stack of horizontal bars. Each bar
# shows buff name + time remaining. Bar STARTS full and empties as the
# buff burns down (opposite of recast which fills up). Color shifts from
# green (fresh) → yellow (warning) → red (about to wear off). Driven by
# buff_state. When a buff disappears from buff_state (wore off), it gets
# a brief red flash via _buff_flashes before being removed entirely.
BUFF_PANEL_PAD       = 6
BUFF_PANEL_BAR_H     = 18
BUFF_PANEL_BAR_GAP   = 3
BUFF_PANEL_BAR_W     = 220


# Tracks initial duration for each buff so we can draw a meaningful fill
# ratio. The lua side sends only seconds-remaining; the first time we see
# a given buff_id, we treat that value as the "max" for fill calculation.
# Wiped when buff_state loses the entry (it wore off).
_buff_durations = {}


def _buff_color(secs):
    """Green when fresh, yellow as warning approaches, red right before expire."""
    if secs >= 60:                          return (140, 220, 140)   # green
    if secs >= 30:                          return (200, 220, 140)   # yellow-green
    if secs >= BUFF_EXPIRY_WARNING_SEC:     return (220, 200, 80)    # yellow
    if secs >  3:                           return (220, 140, 80)    # orange
    return (220, 80, 80)                                              # red


def _format_buff_time(secs):
    """Format seconds as M:SS for >60s, else '12.3' decimal seconds.

    For exactly 0 we show '?:??' rather than '0.0' to communicate that
    the displayed timer is an estimated value that has elapsed but the
    buff is still active in player.buffs (we use base duration as a
    best guess for buffs already running when OmniWatch loaded). When
    the buff truly wears off, buff_loss fires and the entry is removed
    + flashed separately by the wear-off mechanism.
    """
    if secs <= 0:
        return "?:??"
    if secs >= 60:
        m = int(secs // 60)
        s = int(secs % 60)
        return f"{m}:{s:02d}"
    return f"{secs:.1f}"


def scaled_buff_dims(scale):
    s = _eff(scale)
    return {
        "s":         s,
        "bar_w":     max(120, int(BUFF_PANEL_BAR_W * s)),
        "bar_h":     max(12, int(BUFF_PANEL_BAR_H * s)),
        "bar_gap":   max(2,  int(BUFF_PANEL_BAR_GAP * s)),
        "pad":       max(4,  int(BUFF_PANEL_PAD * s)),
        "f_entry":   get_font("Consolas", max(9, int(12 * s)), bold=True),
        "f_label":   get_font("Consolas", max(8, int(11 * s))),
    }


def buff_panel_size(scale, entries):
    d = scaled_buff_dims(scale)
    pad = d["pad"]; bar_w = d["bar_w"]; bar_h = d["bar_h"]; gap = d["bar_gap"]
    if not entries:
        return (bar_w + pad * 2, bar_h + pad * 2)
    total_h = pad + len(entries) * (bar_h + gap) - gap + pad
    return (bar_w + pad * 2, total_h)


def draw_buff_panel(surface, x, y, entries, scale=1.0, locked=False):
    """Render vertical stack of buff timer bars at (x, y). Returns (w, h).

    entries: list of dicts. Real entries: {buff_id, name, secs, source}.
             Flash entries: {flash:True, name, source, flash_age, secs:0}.
    """
    d = scaled_buff_dims(scale)
    pw, ph = buff_panel_size(scale, entries)
    pad = d["pad"]; bar_w = d["bar_w"]; bar_h = d["bar_h"]; gap = d["bar_gap"]

    pygame.draw.rect(surface, COL_PANEL,  (x, y, pw, ph), border_radius=4)
    pygame.draw.rect(surface, COL_BORDER, (x, y, pw, ph), 1, border_radius=4)
    draw_accent_stripe(surface, x, y, ph, ACCENT_BUFF)

    if not entries:
        title_surf = d["f_label"].render("Buffs", True, COL_LABEL_DIM)
        surface.blit(title_surf, (x + pad,
                                   y + (ph - title_surf.get_height()) // 2))
        return pw, ph

    # Update peak duration tracking. When we first see a buff_id, the
    # current secs IS the max (it can only count down from here). If we
    # see a higher value later it's because the buff was re-cast.
    # NOTE: when the wire provides an absolute full_duration (v3 wire,
    # built from expires_at - started_at), we use that DIRECTLY since
    # it's authoritative — survives Python reloads, etc. The peak
    # heuristic remains as a fallback for legacy wire and for buffs
    # without a known start time.
    seen_ids = set()
    for e in entries:
        if e.get("flash") or e.get("worn"):
            continue
        bid = e.get("buff_id")
        if bid is None:
            continue
        seen_ids.add(bid)
        secs = e.get("secs", 0.0)
        full_dur = e.get("full_duration")
        if full_dur and full_dur > 0:
            # Authoritative — use this as the peak. Clamp against secs
            # in case full_dur < secs (e.g. clock drift), which would
            # display a > 100% ratio.
            _buff_durations[bid] = max(full_dur, secs, 0.1)
        else:
            peak = _buff_durations.get(bid)
            if peak is None or secs > peak:
                _buff_durations[bid] = max(secs, 0.1)
    # Prune durations for buffs that left the panel.
    stale = [k for k in _buff_durations if k not in seen_ids
                                            and not any(
                                                (ent.get("flash") or
                                                 ent.get("worn")) and
                                                ent.get("buff_id") == k
                                                for ent in entries)]
    for k in stale:
        del _buff_durations[k]

    by = y + pad
    for e in entries:
        bx = x + pad
        is_flash = e.get("flash", False)
        secs = e.get("secs", 0.0)
        name = e.get("name", "?")
        is_other = name.startswith("~")
        is_debuff = (e.get("source") == "debuff")
        # Capitalize for display. Preserve the leading ~ (other-player
        # marker) by capitalizing the part after it.
        if is_other:
            name = "~" + _capitalize_status_name(name[1:])
        else:
            name = _capitalize_status_name(name)

        if is_flash:
            # Wore-off flash: solid red bar blinking ~3 Hz.
            age = e.get("flash_age", 0.0)
            phase = int(age * 6) % 2
            bright = phase == 0
            col      = (255, 120, 120) if bright else (160, 60, 60)
            fill_col = (130, 40, 40)   if bright else (80, 25, 25)
            pygame.draw.rect(surface, (30, 30, 40),
                              (bx, by, bar_w, bar_h), border_radius=3)
            pygame.draw.rect(surface, fill_col,
                              (bx, by, bar_w, bar_h), border_radius=3)
            pygame.draw.rect(surface, COL_BORDER,
                              (bx, by, bar_w, bar_h), 1, border_radius=3)
            name_surf = d["f_entry"].render(name, True, col)
            time_surf = d["f_entry"].render("WORE OFF", True, col)
            text_y = by + (bar_h - name_surf.get_height()) // 2
            surface.blit(name_surf, (bx + 4, text_y))
            surface.blit(time_surf,
                         (bx + bar_w - time_surf.get_width() - 4, text_y))
        else:
            col = _buff_color(secs)
            # Debuffs (Disease, etc.) get the debuff red regardless of
            # remaining time, so they read as debuffs in the timer panel
            # rather than looking like a normal (green) buff.
            if is_debuff:
                col = COL_DEBUFF
            bid = e.get("buff_id")
            peak = _buff_durations.get(bid, max(secs, 0.1))
            # Fill ratio: 1.0 fresh, 0.0 expired (decreasing).
            ratio = secs / peak if peak > 0 else 0.0
            ratio = max(0.0, min(1.0, ratio))

            pygame.draw.rect(surface, (30, 30, 40),
                              (bx, by, bar_w, bar_h), border_radius=3)
            fill_w = int(bar_w * ratio)
            if fill_w > 0:
                fill_col = tuple(int(c * 0.55) for c in col)
                pygame.draw.rect(surface, fill_col,
                                  (bx, by, fill_w, bar_h), border_radius=3)
            pygame.draw.rect(surface, COL_BORDER,
                              (bx, by, bar_w, bar_h), 1, border_radius=3)

            # Other-player buffs render dimmer to visually distinguish.
            text_col = col
            if is_other:
                text_col = tuple(int(c * 0.7) for c in col)

            time_str = _format_buff_time(secs)
            name_surf = d["f_entry"].render(name, True, text_col)
            time_surf = d["f_entry"].render(time_str, True, text_col)
            text_y = by + (bar_h - name_surf.get_height()) // 2
            surface.blit(name_surf, (bx + 4, text_y))
            surface.blit(time_surf,
                         (bx + bar_w - time_surf.get_width() - 4, text_y))

        by += bar_h + gap

    return pw, ph


# ── Per-panel accent palette ─────────────────────────────────────────────
# A 2px colored stripe along the left edge of each panel telegraphs what
# kind of panel it is at a glance — your eye finds "the red one" before
# reading the title. Colors are deliberately desaturated so they don't
# fight the data; they sit inside the existing border so the rounded-rect
# silhouette stays intact.
ACCENT_PARTY    = (140, 200, 220)   # cool blue — party
ACCENT_ALLY     = ( 90, 130, 160)   # dimmer blue — alliance
ACCENT_RECAST   = (200, 170,  70)   # amber — recasts (time-pressure feel)
ACCENT_BUFF     = (180, 140, 220)   # violet — buffs (status effects)
ACCENT_DPS      = (220, 100,  90)   # crimson — DPS (combat output)
ACCENT_BUTTONS  = (140, 200, 140)   # soft green — buttons (action)
ACCENT_STATS    = (210, 200, 130)   # parchment — stats (reference)
ACCENT_EQUIP    = (180, 160, 110)   # bronze — equipment
ACCENT_TARGET   = (220, 180, 110)   # warm amber — target
ACCENT_CHAT     = (140, 220, 180)   # mint — chat (communication/signal)
ACCENT_SC       = (220, 130, 210)   # magenta — skillchain (resonance / flash)
ACCENT_CHEATSHEET = (150, 175, 235) # cornflower — cheat sheet (reference)
ACCENT_WARP       = (130, 225, 200) # teal-green — warp (travel / go)
# Skillchain property → display color. Canonical FFXI element palette
# via Ivaar's Skillchains addon (originally from Sammeh). Same colors
# the player sees on element icons in the game UI, so muscle memory
# carries over. Used by draw_skillchain_panel to color each resonating
# property in the props row and each suggestion's resulting chain.
SC_PROPERTY_COLORS = {
    # Lv.4 (rare 4-property closes)
    "Light":         (255, 255, 255),
    "Darkness":      ( 80,  80, 220),
    "Radiance":      (255, 255, 255),
    "Umbra":         ( 80,  80, 220),
    # Lv.3
    "Gravitation":   (140,  90,  40),
    "Fragmentation": (240, 160, 240),
    "Fusion":        (255, 120, 120),
    "Distortion":    (100, 170, 255),
    # Lv.2 / Lv.1 — element-themed
    "Compression":   ( 80,  80, 220),   # darkness-family
    "Liquefaction":  (255,  90,  90),   # fire
    "Induration":    (120, 230, 230),   # ice
    "Reverberation": ( 90, 130, 240),   # water
    "Transfixion":   (255, 255, 200),   # light-family
    "Scission":      (150,  90,  60),   # earth
    "Detonation":    (120, 230, 130),   # wind
    "Impaction":     (220, 130, 240),   # lightning
}

# Magic-burst element groups by closing skillchain property. When a
# chain closes, you can magic burst with ANY element in the closing
# property's group — not just the element the SC is named after. This
# is the real FFXI rule and the reason the burst row needs to expand
# the property rather than echo it:
#   Light / Radiance   → Fire, Wind, Lightning, Light
#   Darkness / Umbra   → Ice, Earth, Water, Dark
#   Lv.3 properties    → their two component elements
#   Lv.1/2 properties  → their single element
# Order within each list is the canonical FFXI element order so the
# row reads consistently.
SC_PROPERTY_BURST_ELEMENTS = {
    # Lv.4
    "Light":         ["Fire", "Wind", "Lightning", "Light"],
    "Radiance":      ["Fire", "Wind", "Lightning", "Light"],
    "Darkness":      ["Ice", "Earth", "Water", "Dark"],
    "Umbra":         ["Ice", "Earth", "Water", "Dark"],
    # Lv.3 (two elements each)
    "Gravitation":   ["Earth", "Dark"],
    "Fragmentation": ["Wind", "Lightning"],
    "Fusion":        ["Fire", "Light"],
    "Distortion":    ["Ice", "Water"],
    # Lv.1 / Lv.2 (single element)
    "Liquefaction":  ["Fire"],
    "Induration":    ["Ice"],
    "Detonation":    ["Wind"],
    "Scission":      ["Earth"],
    "Impaction":     ["Lightning"],
    "Reverberation": ["Water"],
    "Transfixion":   ["Light"],
    "Compression":   ["Dark"],
}

# Element name → display color for the burst row. Reuses the SC
# property palette where the element shares a name, plus the six
# elements that don't appear as property names.
SC_ELEMENT_COLORS = {
    "Fire":      (255,  90,  90),
    "Ice":       (120, 230, 230),
    "Wind":      (120, 230, 130),
    "Earth":     (200, 160, 110),
    "Lightning": (220, 130, 240),
    "Water":     ( 90, 130, 240),
    "Light":     (255, 255, 255),
    "Dark":      (140, 110, 220),
}

def draw_accent_stripe(surface, x, y, h, color, w=2):
    """Draw a vertical accent stripe `w` pixels wide at the left edge of
    a panel of height `h`. Stops 3px short of the top and bottom so the
    rounded corners aren't clipped through. Idempotent — call after the
    main border draw."""
    if h < 8:
        return
    pygame.draw.rect(surface, color,
                     (x + 1, y + 3, w, h - 6))


def draw_resize_grip(surface, x, y):
    """Draw a small diagonal-stripe resize handle at (x, y) bottom-right corner.

    Suppressed outside of setup mode: the grip is a UI affordance for
    resizing panels, but resizing is gated to setup_mode. Showing the
    grip in normal play just obscures content in the corners of small
    panels (target list, hotbar slots, etc.).
    """
    if not setup_mode:
        return
    g = RESIZE_GRIP
    pygame.draw.rect(surface, COL_SLOT_BG,  (x - g, y - g, g, g))
    pygame.draw.rect(surface, COL_SLOT_BDR, (x - g, y - g, g, g), 1)
    # Two diagonal hash lines for visual affordance.
    for off in (3, 7):
        pygame.draw.line(surface, COL_SLOT_TEXT,
                         (x - off,     y - 1),
                         (x - 1,       y - off))

# ── Cheat sheet window ───────────────────────────────────────────────────
# A keybind/macro reference shown as a large, draggable, resizable overlay
# window toggled by the header [CS] button. Two stacked sections, each a
# banner plus named sub-groups laid out into columns:
#   • GLOBAL KEYBINDS — shared across every profile, CHEATSHEET_COMMON_FILE.
#   • JOB KEYBINDS    — the active profile's own sheet, CHEATSHEET_JOB_FILE
#                       (banner falls back to the profile name).
# Content comes from JSON if the files exist, else the baked-in defaults
# below (the keybinds from the reference image). JSON shape:
#   {"title": "GLOBAL KEYBINDS",
#    "groups": [ {"label": "ADD-ONS", "col": 0,
#                 "rows": [ {"key": "HOME", "desc": "RELOAD GEARSWAP"} ]} ]}
# A group's "col" places it in a column; the column count per section is
# derived from the largest "col" used. Columns auto-size to their widest
# key/description so nothing is truncated. The window resize grip scales
# the content; position + scale persist in the layout file.
CHEATSHEET_BASE_FONT = 12          # base px (scaled by _eff) for rows

# Baked-in EXAMPLE/mock sheets shipped with the addon. New users see
# these until they edit. A user's own edits are saved to their local
# JSON files (omniwatch_cheatsheet_common.json + omniwatch_cheatsheet*
# .json) which are NOT part of this file and override these defaults,
# so personal sheets stay local and are never shipped.
_CHEATSHEET_COMMON_DEFAULT = {
    "title": "GLOBAL KEYBINDS",
    "groups": [
        {"label": "OFFENSE", "col": 0, "rows": [
            {"key": "(F9)",  "desc": "CYCLE OFFENSE MODE"},
            {"key": "(F10)", "desc": "CYCLE CASTING MODE"},
            {"key": "(F11)", "desc": "CYCLE WEAPONSKILL MODE"},
        ]},
        {"label": "DEFENSE", "col": 0, "rows": [
            {"key": "(F12)",      "desc": "CYCLE DEFENSE MODE"},
            {"key": "CNTRL (F12)", "desc": "CYCLE PHYSICAL DEF"},
            {"key": "ALT (F12)",  "desc": "CYCLE MAGIC DEF"},
        ]},
        {"label": "GENERAL", "col": 1, "rows": [
            {"key": "CNTRL (M)", "desc": "MOUNT"},
            {"key": "CNTRL (W)", "desc": "WARP"},
            {"key": "(F1-F6)",   "desc": "/TARGET <P0-P5>"},
        ]},
    ],
}
_CHEATSHEET_JOB_DEFAULT = {
    "title": "JOB KEYBINDS",
    "groups": [
        {"label": "UTILITY", "col": 0, "rows": [
            {"key": "(NUMPAD.1)",     "desc": "CYCLE STANCE"},
            {"key": "(NUMPAD.4)",     "desc": "CYCLE SKILLCHAIN MODE"},
            {"key": "(LEFT / RIGHT)", "desc": "CYCLE MACROSETS"},
        ]},
    ],
}

# path -> (mtime, {"title","groups"}). Reloaded when mtime changes.
_cheatsheet_cache = {}


def _cheatsheet_extract_rows(raw):
    rows = []
    if isinstance(raw, list):
        for r in raw:
            if isinstance(r, dict) and (r.get("key") or r.get("desc")):
                rows.append({"key": str(r.get("key", "")),
                             "desc": str(r.get("desc", ""))})
    return rows


def _load_cheatsheet_file(path):
    """Load + cache a cheat sheet JSON into {"title","groups"}. Only the
    rich {title, groups:[{label,col,rows}]} form is honored — older flat
    {entries:[...]} / bare-list files (placeholders from earlier builds)
    are ignored so the caller falls back to the baked image defaults.
    Returns empty groups if the file is absent or not in the rich form."""
    try:
        mtime = os.path.getmtime(path)
    except OSError:
        return {"title": None, "groups": []}
    cached = _cheatsheet_cache.get(path)
    if cached and cached[0] == mtime:
        return cached[1]
    result = {"title": None, "groups": []}
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict) and isinstance(data.get("groups"), list):
            result["title"] = data.get("title")
            for g in data["groups"]:
                if not isinstance(g, dict):
                    continue
                rows = _cheatsheet_extract_rows(g.get("rows"))
                if not (rows or g.get("label")):
                    continue
                try:
                    col = int(g.get("col", 0) or 0)
                except (TypeError, ValueError):
                    col = 0
                result["groups"].append({"label": str(g.get("label", "")),
                                         "col": col, "rows": rows})
    except Exception as e:
        print(f"[OmniWatch] cheat sheet load {path}: {e!r}")
    _cheatsheet_cache[path] = (mtime, result)
    return result


def _cheatsheet_sections():
    """Return [(banner_title, groups, which)] top→bottom. While editing,
    returns the live working copy; otherwise loads each section's file and
    falls back to the baked defaults so the window always has content."""
    if cheatsheet_edit_mode and _cs_work is not None:
        return [
            (_cs_work["common"].get("title") or "GLOBAL KEYBINDS",
             _cs_work["common"]["groups"], "common"),
            (_cs_work["job"].get("title") or (active_profile_name or "JOB KEYBINDS"),
             _cs_work["job"]["groups"], "job"),
        ]
    common = _load_cheatsheet_file(CHEATSHEET_COMMON_FILE)
    if not common["groups"]:
        common = _CHEATSHEET_COMMON_DEFAULT
    job = _load_cheatsheet_file(CHEATSHEET_JOB_FILE)
    if not job["groups"]:
        job = _CHEATSHEET_JOB_DEFAULT
    job_title = job.get("title") or (active_profile_name or "JOB KEYBINDS")
    return [
        (common.get("title") or "GLOBAL KEYBINDS", common["groups"], "common"),
        (job_title, job["groups"], "job"),
    ]


def _cheatsheet_path_for_which(which):
    return CHEATSHEET_COMMON_FILE if which == "common" else CHEATSHEET_JOB_FILE


def _cheatsheet_persist(which):
    """Write the working copy for `which` to its JSON file and refresh the
    load cache so non-edit reads reflect the change."""
    if _cs_work is None:
        return
    sec = _cs_work[which]
    path = _cheatsheet_path_for_which(which)
    data = {
        "title": sec.get("title") or
                 ("GLOBAL KEYBINDS" if which == "common"
                  else (active_profile_name or "JOB KEYBINDS")),
        "groups": [
            {"label": g.get("label", ""), "col": int(g.get("col", 0) or 0),
             "rows": [{"key": r.get("key", ""), "desc": r.get("desc", "")}
                      for r in g.get("rows", [])]}
            for g in sec.get("groups", [])
        ],
    }
    try:
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2)
        # Refresh cache so a later (non-edit) load returns this content.
        try:
            _cheatsheet_cache[path] = (os.path.getmtime(path),
                                       {"title": data["title"],
                                        "groups": data["groups"]})
        except OSError:
            _cheatsheet_cache.pop(path, None)
    except Exception as e:
        print(f"[OmniWatch] cheat sheet save {path}: {e!r}")


def _cheatsheet_enter_edit():
    """Snapshot the current sheets into a mutable working copy and turn on
    edit mode. Defaults are materialized into the working copy so edits
    have something concrete to modify."""
    global cheatsheet_edit_mode, _cs_work, _cs_edit
    work = {}
    for title, groups, which in _cheatsheet_sections():
        work[which] = {
            "title": title,
            "groups": [
                {"label": g.get("label", ""), "col": int(g.get("col", 0) or 0),
                 "rows": [{"key": r.get("key", ""), "desc": r.get("desc", "")}
                          for r in g.get("rows", [])]}
                for g in groups
            ],
        }
    _cs_work = work
    _cs_edit = None
    cheatsheet_edit_mode = True


def _cheatsheet_exit_edit():
    """Commit any in-flight cell edit, persist both sheets, and leave edit
    mode."""
    global cheatsheet_edit_mode, _cs_work, _cs_edit, _cs_ctx_menu
    _cheatsheet_commit_edit()
    if _cs_work is not None:
        _cheatsheet_persist("common")
        _cheatsheet_persist("job")
    _cs_work = None
    _cs_edit = None
    _cs_ctx_menu = None
    cheatsheet_edit_mode = False


def _cheatsheet_begin_cell(which, gi, ri, field):
    """Open an inline edit on a specific cell. ri is None for the group
    label. field ∈ {"key","desc","label"}."""
    global _cs_edit
    _cheatsheet_commit_edit()
    if _cs_work is None:
        return
    grp = _cs_work[which]["groups"]
    if gi >= len(grp):
        return
    if field == "label":
        cur = grp[gi].get("label", "")
    else:
        rows = grp[gi].get("rows", [])
        if ri is None or ri >= len(rows):
            return
        cur = rows[ri].get(field, "")
    _cs_edit = {"which": which, "gi": gi, "ri": ri, "field": field,
                "buf": cur, "cursor": len(cur)}


def _cheatsheet_commit_edit():
    """Write the active cell buffer back into the working copy + persist."""
    global _cs_edit
    if _cs_edit is None or _cs_work is None:
        return
    e = _cs_edit
    grp = _cs_work[e["which"]]["groups"]
    if e["gi"] < len(grp):
        if e["field"] == "label":
            grp[e["gi"]]["label"] = e["buf"]
        else:
            rows = grp[e["gi"]].get("rows", [])
            if e["ri"] is not None and e["ri"] < len(rows):
                rows[e["ri"]][e["field"]] = e["buf"]
        _cheatsheet_persist(e["which"])
    _cs_edit = None


def _cheatsheet_add_row(which, gi):
    """Append a blank row to a group and open its key for editing."""
    if _cs_work is None:
        return
    _cheatsheet_commit_edit()
    grp = _cs_work[which]["groups"]
    if gi < len(grp):
        grp[gi].setdefault("rows", []).append({"key": "", "desc": ""})
        _cheatsheet_persist(which)
        _cheatsheet_begin_cell(which, gi, len(grp[gi]["rows"]) - 1, "key")


def _cheatsheet_del_row(which, gi, ri):
    if _cs_work is None:
        return
    _cheatsheet_commit_edit()
    grp = _cs_work[which]["groups"]
    if gi < len(grp):
        rows = grp[gi].get("rows", [])
        if 0 <= ri < len(rows):
            rows.pop(ri)
            # Drop the group entirely if it has no rows and no label.
            if not rows and not grp[gi].get("label"):
                grp.pop(gi)
            _cheatsheet_persist(which)


def _cheatsheet_add_group(which, col):
    """Append a new (empty-labelled) category in a column and edit its
    label."""
    if _cs_work is None:
        return
    _cheatsheet_commit_edit()
    grp = _cs_work[which]["groups"]
    grp.append({"label": "NEW", "col": int(col),
                "rows": [{"key": "", "desc": ""}]})
    _cheatsheet_persist(which)
    _cheatsheet_begin_cell(which, len(grp) - 1, None, "label")


def _cheatsheet_del_group(which, gi):
    if _cs_work is None:
        return
    _cheatsheet_commit_edit()
    grp = _cs_work[which]["groups"]
    if 0 <= gi < len(grp):
        grp.pop(gi)
        _cheatsheet_persist(which)


def _cheatsheet_section_columns(groups):
    """Column count for a section = (largest 'col' used) + 1, clamped 1-6."""
    if not groups:
        return 1
    try:
        m = max(int(g.get("col", 0) or 0) for g in groups)
    except (TypeError, ValueError):
        m = 0
    return max(1, min(6, m + 1))


def scaled_cheatsheet_dims(scale):
    s = _eff(scale)
    base = {"small": 10, "medium": 12, "large": 15}.get(
        setting("cheatsheet_font_size"), CHEATSHEET_BASE_FONT)
    px = max(9, int(base * s))
    f_row    = get_font("Consolas", px)
    f_label  = get_font("Consolas", px, bold=True)
    f_key    = get_font("Consolas", px)
    f_desc   = get_font("Consolas", px, italic=True)
    f_banner = get_font("Consolas", max(8, int((base - 1) * s)),
                        bold=True)
    f_title  = get_font("Consolas", max(9, int((base + 1) * s)),
                        bold=True)
    row_h = max(f_row.get_height(), f_desc.get_height()) + max(1, int(2 * s))
    return {
        "s":        s,
        "pad":      max(5, int(10 * s)),
        "gap":      max(4, int(8 * s)),
        "col_gap":  max(8, int(24 * s)),
        "group_gap": max(4, int(9 * s)),
        "sec_gap":  max(6, int(14 * s)),
        "banner_h": f_banner.get_height() + max(3, int(8 * s)),
        "row_h":    row_h,
        "f_row":    f_row, "f_label": f_label, "f_key": f_key,
        "f_desc":   f_desc, "f_banner": f_banner, "f_title": f_title,
    }


def _cheatsheet_full_layout(scale):
    """Measure all sections with SHARED column widths so the [ / key / desc
    columns line up vertically across both GLOBAL and JOB. Returns
    (dims, sections, shared). Each section carries its per-column group
    buckets + heights; `shared` holds the common column x-offsets and the
    label/key/desc widths used by every section."""
    d = scaled_cheatsheet_dims(scale)
    f_row = d["f_row"]; f_label = d["f_label"]
    f_key = d["f_key"]; f_desc = d["f_desc"]
    bracket_w = f_row.size("[")[0]
    gap = d["gap"]; col_gap = d["col_gap"]

    secs_raw = _cheatsheet_sections()
    ncols = max((_cheatsheet_section_columns(g) for _, g, _ in secs_raw),
                default=1)

    # Pass 1: shared per-column widths = max across ALL sections.
    label_w = [0] * ncols
    key_w   = [0] * ncols
    desc_w  = [0] * ncols
    for _t, groups, _w in secs_raw:
        for g in groups:
            ci = max(0, min(ncols - 1, g.get("col", 0)))
            if g.get("label"):
                label_w[ci] = max(label_w[ci], f_label.size(g["label"])[0])
            for r in g["rows"]:
                key_w[ci]  = max(key_w[ci],  f_key.size(r["key"])[0])
                desc_w[ci] = max(desc_w[ci], f_desc.size(r["desc"])[0])

    col_w = []
    for i in range(ncols):
        w = (label_w[i] + (gap if label_w[i] else 0)
             + bracket_w + gap + key_w[i]
             + (gap + desc_w[i] if desc_w[i] else 0))
        col_w.append(w)
    col_x = [0] * ncols
    acc = 0
    for i in range(ncols):
        col_x[i] = acc
        acc += col_w[i] + col_gap

    # Pass 2: bucket each section's groups into the shared columns. Each
    # bucket entry is (orig_index, group) so the editor can target groups
    # by their index in the section's groups list.
    edit = cheatsheet_edit_mode
    sections = []
    for title, groups, which in secs_raw:
        buckets = [[] for _ in range(ncols)]
        for oi, g in enumerate(groups):
            buckets[max(0, min(ncols - 1, g.get("col", 0)))].append((oi, g))
        used = [i for i in range(ncols) if buckets[i]]
        max_used = max(used) if used else 0
        col_h = [0] * ncols
        for i in used:
            ch = 0
            for gi, (oi, g) in enumerate(buckets[i]):
                if gi > 0:
                    ch += d["group_gap"]
                ch += len(g["rows"]) * d["row_h"]
            col_h[i] = ch
        if edit:
            # Reserve room for the per-group "+ row" lines and a per-column
            # "+ category" line (empty columns get just the +category line),
            # and span every column so a 2nd column can be started anywhere.
            for i in range(ncols):
                ng = len(buckets[i])
                if ng:
                    col_h[i] += ng * d["row_h"]              # one "+row" per group
                    col_h[i] += d["group_gap"] + d["row_h"]  # the "+category" line
                else:
                    col_h[i] = d["row_h"]                    # "+category" only
            max_used = ncols - 1
        sec_w = (col_x[max_used] + col_w[max_used]) if (used or edit) else 0
        sec_h = d["banner_h"] + (max(col_h) if (used or edit) else 0)
        sections.append({"title": title, "which": which, "buckets": buckets,
                         "col_h": col_h, "w": sec_w, "h": sec_h})

    shared = {"col_w": col_w, "col_x": col_x, "label_w": label_w,
              "key_w": key_w, "desc_w": desc_w, "bracket_w": bracket_w,
              "ncols": ncols}
    return d, sections, shared


def _cheatsheet_content_size():
    """(width, height) of the laid-out content at the current UI scale
    (no window frame). Used to size the window on first open and to bound
    the vertical scroll range."""
    d, sections, _shared = _cheatsheet_full_layout(1.0)
    if not sections:
        return (int(200 * d["s"]), d["row_h"])
    w = max(s["w"] for s in sections)
    h = sum(s["h"] for s in sections) + d["sec_gap"] * (len(sections) - 1)
    return (int(w), int(h))


def _draw_cheatsheet_content(surface, x, y):
    """Draw the banners + grouped rows starting at (x, y). No background —
    the window frame provides that. Columns are shared across sections so
    keys/descriptions line up; no leading dashes. In edit mode it also draws
    the inline-edit affordances ("+ row" / "+ category" lines, the active
    cell's cursor) and records click targets into _cs_edit_rects."""
    global _cs_edit_rects
    d, sections, shared = _cheatsheet_full_layout(1.0)
    f_row = d["f_row"]; f_label = d["f_label"]
    f_key = d["f_key"]; f_desc = d["f_desc"]; f_banner = d["f_banner"]
    gap = d["gap"]
    C_GLABEL  = (180, 188, 202)
    C_BRACKET = (80, 85, 105)
    C_KEY     = (212, 214, 224)
    C_DESC    = (190, 174, 140)
    C_BANNER  = (150, 175, 235)
    C_ADD     = (110, 130, 110)
    col_x = shared["col_x"]; label_w = shared["label_w"]
    key_w = shared["key_w"]; desc_w = shared["desc_w"]; bracket_w = shared["bracket_w"]
    edit = cheatsheet_edit_mode
    minw = max(28, int(34 * d["s"]))
    clip = surface.get_clip()   # content area; skip targets scrolled out of it
    if edit:
        _cs_edit_rects = []

    def _rec(rect, action):
        """Record a click target only if it's within the visible content
        area, so rows scrolled behind the title bar aren't clickable."""
        if clip is None or clip.colliderect(rect):
            _cs_edit_rects.append((rect, action))

    def _cell(field, gx, gy, w, which, gi, ri, text, font, color):
        """Draw a cell's text (or the live edit buffer + cursor) and, in
        edit mode, record its click rect."""
        active = (edit and _cs_edit is not None
                  and _cs_edit["which"] == which and _cs_edit["gi"] == gi
                  and _cs_edit["ri"] == ri and _cs_edit["field"] == field)
        if active:
            buf = _cs_edit["buf"]
            cur = _cs_edit["cursor"]
            box = pygame.Rect(gx - 2, gy - 1, max(w, font.size(buf)[0]) + 6,
                              d["row_h"])
            pygame.draw.rect(surface, (40, 44, 60), box)
            pygame.draw.rect(surface, ACCENT_CHEATSHEET, box, 1)
            surface.blit(font.render(buf, True, color), (gx, gy))
            cxp = gx + font.size(buf[:cur])[0]
            pygame.draw.line(surface, (235, 235, 245),
                             (cxp, gy + 1), (cxp, gy + font.get_height() - 1))
        else:
            if text:
                surface.blit(font.render(text, True, color), (gx, gy))
        if edit:
            _rec(pygame.Rect(gx, gy, max(w, minw), d["row_h"]),
                 ("cell", which, gi, ri, field))

    cy = y
    for si, sec in enumerate(sections):
        if si > 0:
            cy += d["sec_gap"]
        which = sec["which"]
        banner = f"----- {sec['title'].upper()} -----"
        surface.blit(f_banner.render(banner, True, C_BANNER), (x, cy))
        cy += d["banner_h"]
        block_h = 0
        for ci, gs in enumerate(sec["buckets"]):
            base_x    = x + col_x[ci]
            x_label   = base_x
            x_bracket = base_x + label_w[ci] + (gap if label_w[ci] else 0)
            x_key     = x_bracket + bracket_w + gap
            x_desc    = x_key + key_w[ci] + gap
            ry = cy
            for within_i, (oi, g) in enumerate(gs):
                if within_i > 0:
                    ry += d["group_gap"]
                for ri, r in enumerate(g["rows"]):
                    if ri == 0:
                        # Group label cell (editable in edit mode).
                        if edit:
                            _cell("label", x_label, ry, label_w[ci],
                                  which, oi, None, g.get("label", ""),
                                  f_label, C_GLABEL)
                        elif g["label"]:
                            surface.blit(f_label.render(g["label"], True,
                                         C_GLABEL), (x_label, ry))
                    surface.blit(f_row.render("[", True, C_BRACKET),
                                 (x_bracket, ry))
                    _cell("key", x_key, ry, key_w[ci], which, oi, ri,
                          r["key"], f_key, C_KEY)
                    _cell("desc", x_desc, ry, desc_w[ci], which, oi, ri,
                          r["desc"], f_desc, C_DESC)
                    ry += d["row_h"]
                if edit:
                    # "+ row" affordance under the group.
                    surface.blit(f_row.render("+ row", True, C_ADD),
                                 (x_key, ry))
                    _rec(pygame.Rect(x_key, ry, max(key_w[ci], minw),
                                     d["row_h"]), ("addrow", which, oi))
                    ry += d["row_h"]
            if edit:
                # "+ category" affordance at the bottom of the column
                # (also for an empty column → start a new column here).
                if gs:
                    ry += d["group_gap"]
                surface.blit(f_label.render("+ category", True, C_ADD),
                             (x_label, ry))
                _rec(pygame.Rect(x_label, ry,
                                 max(label_w[ci] + bracket_w + key_w[ci], minw * 3),
                                 d["row_h"]), ("addcat", which, ci))
            block_h = max(block_h, sec["col_h"][ci])
        cy += block_h          # advance past this section's columns



def _cheatsheet_toggle():
    """Open/close the cheat sheet window (floating [CS] button / [X])."""
    global cheatsheet_window_open
    cheatsheet_window_open = not cheatsheet_window_open


def _clear_cheatsheet_rects():
    """Null the cheat sheet button + window hit rects (called when the
    overlay is hidden so stale rects can't fire)."""
