def _unity_bucket(z):
    c = z[0].upper()
    if c <= "B":
        return "A – B"
    if c <= "G":
        return "C – G"
    if c <= "M":
        return "H – M"
    if c <= "S":
        return "N – S"
    return "T – Z"

_un_groups = {}
for _z in sorted(_UNITY_ZONES):
    _un_groups.setdefault(_unity_bucket(_z), []).append(
        {"label": _z, "zone": _z.lower()})
WARP_DEFAULT_CONFIG["un"] = {
    "label": "Unity Warp",
    "command": "sw un",
    "destinations": [{"label": b, "children": _un_groups[b]}
                     for b in ("A – B", "C – G", "H – M",
                               "N – S", "T – Z")
                     if b in _un_groups],
}

