# Networks, in menu order. Keys must match lua's WARPNEAR| fields.
WARP_NETWORKS = ("hp", "sg", "wp", "ab", "ew", "po", "pwp", "un", "vw")

# Travel menu shows at most this many rows at once; the rest scroll.
WARP_MENU_MAX_ROWS = 12


def _warp_load_config():
    """Lazy-load the warp destinations config. Reads WARP_FILE if present;
    otherwise writes the defaults so the file exists for the user to edit.
    Normalizes structure so the renderer can trust it. Cached in the
    module global warp_config."""
    global warp_config
    if warp_config is not None:
        return warp_config
    cfg = None
    try:
        if os.path.exists(WARP_FILE):
            with open(WARP_FILE, "r", encoding="utf-8") as f:
                raw = json.load(f)
            if isinstance(raw, dict):
                cfg = raw
    except Exception as e:
        print(f"[OmniWatch] warp config load failed: {e!r}")
    wrote_default = False
    if cfg is None:
        cfg = json.loads(json.dumps(WARP_DEFAULT_CONFIG))   # deep copy
        wrote_default = True
    # Normalize each network to {label, command, destinations:[{label,zone}]}.
    for net in WARP_NETWORKS:
        n = cfg.get(net)
        if not isinstance(n, dict):
            n = {}
            cfg[net] = n
        n.setdefault("label",   WARP_DEFAULT_CONFIG[net]["label"])
        n.setdefault("command", WARP_DEFAULT_CONFIG[net]["command"])
        dests = n.get("destinations")
        clean = []
        if isinstance(dests, list):
            for d in dests:
                if not isinstance(d, dict):
                    continue
                kids = d.get("children")
                if isinstance(kids, list) and kids:
                    # Group entry: expands to a submenu of sub-areas.
                    ck = []
                    for c in kids:
                        if isinstance(c, dict) and c.get("zone"):
                            ck.append({
                                "label": str(c.get("label") or c.get("zone")),
                                "zone":  str(c.get("zone")),
                            })
                    if ck:
                        clean.append({
                            "label":    str(d.get("label") or "?"),
                            "children": ck,
                        })
                elif d.get("zone"):
                    # Direct entry: one-click warp.
                    clean.append({
                        "label": str(d.get("label") or d.get("zone")),
                        "zone":  str(d.get("zone")),
                    })
        n["destinations"] = clean
    if wrote_default:
        try:
            with open(WARP_FILE, "w", encoding="utf-8") as f:
                json.dump(cfg, f, indent=2, ensure_ascii=False)
        except Exception as e:
            print(f"[OmniWatch] warp config write failed: {e!r}")
    warp_config = cfg
    return warp_config


# Region grouping for the auto-built destination list. Zones in the same
# region collapse into one expandable submenu (e.g. the Jeuno zones under
# "Jeuno"); zones with several Home Points drill one level deeper into the
# specific points (e.g. Lower Jeuno -> Entrance / Mog House). Order here is
# the order region groups appear in the menu.
WARP_REGION_ORDER = ["San d'Oria", "Bastok", "Windurst", "Jeuno", "Adoulin"]

_SW_HP_LANDMARK = {
    # (zone, homepoint number) -> landmark name, parsed from
    # superwarp's map/homepoints.lua. Used to label specific Home
    # Points (e.g. Lower Jeuno #1 = Entrance) and to target them via
    # `sw hp <zone> <#>`. Static reference data; safe to regenerate.
    ('Aht Urhgan Whitegate', '3'): 'Auction House', ('Aht Urhgan Whitegate', '4'): 'Mog House',
    ('Bastok Markets', '1'): 'Entrance', ('Bastok Markets', '2'): 'Auction House', ('Bastok Markets', '3'): 'Mog House',
    ('Bastok Mines', '1'): 'Auction House', ('Bastok Mines', '2'): 'Mog House',
    ('Eastern Adoulin', '2'): 'Mog House',
    ('Lower Jeuno', '1'): 'Entrance', ('Lower Jeuno', '2'): 'Mog House',
    ('Norg', '1'): 'Entrance', ('Norg', '2'): 'Auction House',
    ("Northern San d'Oria", '1'): 'Entrance', ("Northern San d'Oria", '3'): 'Mog House',
    ('Port Bastok', '1'): 'Entrance', ('Port Bastok', '2'): 'Mog House',
    ('Port Jeuno', '1'): 'Entrance', ('Port Jeuno', '2'): 'Mog House',
    ("Port San d'Oria", '2'): 'Mog House', ("Port San d'Oria", '3'): 'Auction House',
    ('Port Windurst', '2'): 'Entrance', ('Port Windurst', '3'): 'Mog House',
    ('Rabao', '1'): 'Entrance',
    ("Ru'Lude Gardens", '2'): 'Mog House', ("Ru'Lude Gardens", '3'): 'Auction House',
    ("Southern San d'Oria", '1'): 'Entrance', ("Southern San d'Oria", '2'): 'Auction House', ("Southern San d'Oria", '3'): 'Mog House',
    ('Upper Jeuno', '1'): 'Entrance', ('Upper Jeuno', '2'): 'Mog House', ('Upper Jeuno', '3'): 'Auction House',
    ('Western Adoulin', '1'): 'Entrance', ('Western Adoulin', '2'): 'Mog House',
    ('Windurst Walls', '2'): 'Mog House', ('Windurst Walls', '3'): 'Auction House',
    ('Windurst Waters', '1'): 'Entrance', ('Windurst Waters', '2'): 'Mog House',
    ('Windurst Woods', '2'): 'Entrance', ('Windurst Woods', '3'): 'Mog House', ('Windurst Woods', '4'): 'Auction House',
}


def _warp_region_for_zone(zone):
    if "San d'Oria" in zone:
        return "San d'Oria"
    if "Bastok" in zone or zone == "Metalworks":
        return "Bastok"
    if "Windurst" in zone:
        return "Windurst"
    if "Jeuno" in zone or "Ru'Lude" in zone:
        return "Jeuno"
    if "Adoulin" in zone:
        return "Adoulin"
    return None


# Destination nodes are recursive:
#   leaf  = {"label": str, "zone": str, "sub": str|None}  -> one warp
#   group = {"label": str, "children": [node, ...]}       -> expandable
# "sub" is the Home Point number within a multi-HP zone (superwarp resolves
# `sw hp <zone> <sub>`); None means the zone has a single point.


def _warp_attuned_zones(cat_key, by_idx, strip_hash):
    """De-duplicated list of zone names attuned for a checklist category
    (auto u manual). Used for Survival Guides (one point per zone)."""
    st = checklist_known.get(cat_key, {})
    idxs = set(st.get("auto", set())) | set(st.get("manual", set()))
    zones, seen = [], set()
    for k in idxs:
        try:
            disp = by_idx.get(int(k))
        except (TypeError, ValueError):
            disp = None
        if not disp:
            continue
        zone = disp.split(" #")[0] if strip_hash else disp
        if zone not in seen:
            seen.add(zone)
            zones.append(zone)
    return zones


def _warp_region_wrap(zone_nodes):
    """Wrap a list of (zone_name, node) into region groups. A region with a
    single attuned zone promotes that zone's node directly (no 1-item
    group); ungrouped zones list alphabetically after the region groups."""
    regions, flat = {}, []
    for zname, node in zone_nodes:
        r = _warp_region_for_zone(zname)
        if r:
            regions.setdefault(r, []).append((zname, node))
        else:
            flat.append((zname, node))
    entries = []
    for r in WARP_REGION_ORDER:
        zs = regions.get(r)
        if not zs:
            continue
        zs.sort(key=lambda t: t[0])
        if len(zs) == 1:
            entries.append(zs[0][1])
        else:
            entries.append({"label": r, "children": [n for _, n in zs]})
    for _, node in sorted(flat, key=lambda t: t[0]):
        entries.append(node)
    return entries


def _warp_hp_zone_node(zone, nums):
    """Build the node for one Home Point zone. `nums` is the sorted list of
    attuned point numbers (strings) in that zone, or [] for a single-point
    zone. Multiple attuned points -> a group that drills into each point
    (labelled by its landmark, e.g. Entrance); a single attuned point ->
    a leaf naming the landmark; no number -> a plain single-point leaf."""
    if not nums:
        return {"label": zone, "zone": zone, "sub": None}
    if len(nums) == 1:
        n = nums[0]
        lm = _SW_HP_LANDMARK.get((zone, n))
        tag = lm if lm else "#" + n
        return {"label": "%s (%s)" % (zone, tag), "zone": zone, "sub": n}
    pts = []
    for n in nums:
        lm = _SW_HP_LANDMARK.get((zone, n))
        plabel = ("#%s %s" % (n, lm)) if lm else ("#%s" % n)
        pts.append({"label": plabel, "zone": zone, "sub": n})
    return {"label": zone, "children": pts}


def _warp_destinations_for(net):
    """Destination node tree for a network's menu. Primary source is the
    player's attuned list from the checklist; if nothing is attuned yet,
    fall back to the JSON config so the menu isn't empty before the first
    Home Point / Survival Guide visit populates the checklist.

    Home Points build three levels where applicable (region -> zone ->
    specific point); Survival Guides build two (region -> zone), since each
    guide zone has a single destination."""
    if net == "hp":
        st = checklist_known.get("homepoints", {})
        idxs = set(st.get("auto", set())) | set(st.get("manual", set()))
        byzone = {}
        for k in idxs:
            try:
                disp = _HOMEPOINTS_BY_IDX.get(int(k))
            except (TypeError, ValueError):
                disp = None
            if not disp:
                continue
            if " #" in disp:
                zone, num = disp.rsplit(" #", 1)
            else:
                zone, num = disp, None
            byzone.setdefault(zone, set()).add(num)
        if byzone:
            zone_nodes = []
            for zone, nums in byzone.items():
                realnums = sorted(n for n in nums if n is not None)
                zone_nodes.append((zone, _warp_hp_zone_node(zone, realnums)))
            return _warp_region_wrap(zone_nodes)
    elif net == "sg":
        zones = _warp_attuned_zones("survival_guides",
                                    _SURVIVAL_GUIDES_BY_IDX, False)
        if zones:
            zone_nodes = [(z, {"label": z, "zone": z, "sub": None})
                          for z in zones]
            return _warp_region_wrap(zone_nodes)
    cfg = _warp_load_config()
    return cfg.get(net, {}).get("destinations", [])

def _warp_is_near():
    """Return {net: bool} for every network in WARP_NETWORKS. Treats the
    proximity status as not-near once it goes stale (no WARPNEAR for
    >3s — e.g. after zoning), so the button stops pulsing when the
    player walks away or changes zone."""
    if (time.time() - warp_near.get("ts", 0.0)) > 3.0:
        return {net: False for net in WARP_NETWORKS}
    return {net: bool(warp_near.get(net)) for net in WARP_NETWORKS}


def _warp_send(command):
    """Send a superwarp command to lua, tagged with the locked character so
    only that game client acts on it (multibox-safe). Wire form:
    WARP|<char>|<command>."""
    try:
        target = _mb_lock_target() or ""
        payload = f"WARP|{target}|{command}"
        sock_cmd_out.sendto(payload.encode("utf-8"), CMD_OUT_ADDR)
    except Exception as e:
        print(f"[OmniWatch] warp send failed: {e!r}")


def _warp_toggle_menu():
    global warp_menu_open, warp_config, warp_confirm, warp_menu_scroll
    warp_confirm = None
    warp_menu_open = not warp_menu_open
    if warp_menu_open:
        warp_menu_scroll = 0
        # Re-read the JSON on open so hand-edits to omniwatch_warp.json
        # take effect without restarting the overlay.
        warp_config = None
        _warp_load_config()


def _lerp_color(a, b, t):
    t = max(0.0, min(1.0, t))
    return tuple(int(a[i] + (b[i] - a[i]) * t) for i in range(3))


def draw_warp_button(surface):
    """Floating, draggable, resizable Warp button (sibling of the [CS]
    button). Pulses when a Home Point or Survival Guide is in range (per
    lua's WARPNEAR). Click toggles the travel menu; drag repositions;
    drag the corner handle resizes; right-click opens Configure. Sets
    warp_button_rect / warp_button_handle_rect / _warp_btn_draw_pos."""
    global warp_button_pos, warp_button_rect, _warp_btn_draw_pos
    global warp_button_handle_rect
    warp_button_rect = None
    warp_button_handle_rect = None
    g = _menu_g() * max(0.5, min(5.0, warp_button_scale))
    def _bs(v):
        return max(1, round(v * g))
    f = get_font("Consolas", _bs(13), bold=True)
    label = f.render("Warp", True, (225, 225, 235))
    pad  = _bs(8)
    padv = _bs(4)
    bw = label.get_width() + pad * 2
    bh = label.get_height() + padv * 2
    sw, shh = surface.get_size()
    if warp_button_pos is None:
        # Default: just below the cheat sheet button's default spot.
        warp_button_pos = [PANEL_X, layout_top() + 4 + bh + 6]
    # Clamp for display only (same rationale as the [CS] button).
    x = max(0, min(int(warp_button_pos[0]), max(0, sw - bw)))
    y = max(0, min(int(warp_button_pos[1]), max(0, shh - bh)))
    _warp_btn_draw_pos = [x, y]
    warp_button_rect = pygame.Rect(x, y, bw, bh)
    mx, my = pygame.mouse.get_pos()
    hov = warp_button_rect.collidepoint(mx, my)
    near = any(_warp_is_near().values())

    base_bg = (62, 62, 78) if (hov or warp_menu_open) else (44, 44, 54)
    if near:
        # Pulse 0..1 on a ~1.25s cycle; blend bg + border toward the accent.
        pulse = (math.sin(time.time() * 5.0) + 1.0) * 0.5
        bg  = _lerp_color(base_bg, ACCENT_WARP, 0.20 * pulse)
        bdr = _lerp_color((70, 120, 108), ACCENT_WARP, pulse)
        bdr_w = 2
    else:
        bg  = base_bg
        bdr = (180, 180, 200) if warp_menu_open else (100, 100, 115)
        bdr_w = 1
    pygame.draw.rect(surface, bg, warp_button_rect, border_radius=4)
    pygame.draw.rect(surface, bdr, warp_button_rect, bdr_w, border_radius=4)
    draw_accent_stripe(surface, x, y, bh, ACCENT_WARP, w=max(2, _bs(2)))
    surface.blit(label, (x + (bw - label.get_width()) // 2, y + padv))

    # Corner resize handle (bottom-right), shown on hover like the [CS] one.
    hsz = max(6, _bs(6))
    warp_button_handle_rect = pygame.Rect(x + bw - hsz, y + bh - hsz, hsz, hsz)
    if hov or _warp_btn_resize is not None:
        for off in (2, 5):
            if off < hsz:
                pygame.draw.line(surface, (200, 200, 215),
                                 (x + bw - off, y + bh - 1),
                                 (x + bw - 1, y + bh - off))


def draw_warp_menu(surface):
    """Travel menu popover. One section per network (Home Point, Survival
    Guide). When in range, a network's destinations are listed as a tree:
    region -> zone -> (for multi-Home-Point zones) specific point, e.g.
    Jeuno -> Lower Jeuno -> Entrance / Mog House. Groups expand/collapse on
    click (multi-level). When out of range, the network shows only a greyed
    header pinned at the bottom (it doesn't scroll away) so you know it's an
    option once you're there. The scroll region is windowed to
    WARP_MENU_MAX_ROWS rows (mouse wheel + right-edge scrollbar). Records
    click targets in warp_menu_rects and the envelope in warp_menu_rect.
    Clicking a destination opens the confirm popover (draw_warp_confirm).
    """
    global warp_menu_rects, warp_menu_rect, warp_menu_scroll
    warp_menu_rects = []
    warp_menu_rect = None
    if not warp_menu_open:
        return
    cfg = _warp_load_config()
    near_map = _warp_is_near()

    title_font = get_font("Consolas", 12, bold=True)
    row_font   = get_font("Consolas", 12)
    foot_font  = get_font("Consolas", 10, italic=True)

    pad     = 8
    line_h  = row_font.get_height() + 6
    hdr_h   = title_font.get_height() + 6
    indent  = row_font.size("  ")[0]   # px per tree depth level

    # Build the scroll region (in-range networks, flattened tree) + the
    # pinned footer (out-of-range network headers). Row tuple kinds:
    #   ("hdr",   net, netlabel)
    #   ("empty", net)
    #   ("grp",   net, depth, label, path, expanded)
    #   ("leaf",  net, depth, label, zone, sub)
    scroll_entries = []
    pinned = []
    width_cands = []

    def _flatten(nodes, net, parent_path, depth):
        for node in nodes:
            if "children" in node:
                path = parent_path + "/" + node["label"]
                expanded = path in _warp_expanded
                scroll_entries.append(
                    ("grp", net, depth, node["label"], path, expanded))
                width_cands.append("  " * (depth + 1) + "+ " + node["label"])
                if expanded:
                    _flatten(node["children"], net, path, depth + 1)
            else:
                scroll_entries.append(
                    ("leaf", net, depth, node["label"],
                     node.get("zone", ""), node.get("sub")))
                width_cands.append("  " * (depth + 1) + "• " + node["label"])

    for net in WARP_NETWORKS:
        n = cfg.get(net, {})
        netlabel = n.get("label", net)
        near = near_map.get(net, False)
        width_cands.append(netlabel + "    out of range")
        if not near:
            pinned.append(("hdr", net, netlabel))
            continue
        scroll_entries.append(("hdr", net, netlabel))
        dests = _warp_destinations_for(net)
        if not dests:
            scroll_entries.append(("empty", net))
            width_cands.append("   (none attuned yet)")
            continue
        _flatten(dests, net, net, 0)
    foot = "right-click button for settings"
    width_cands.append(foot)

    # Window the scroll region to at most WARP_MENU_MAX_ROWS rows.
    total = len(scroll_entries)
    max_scroll = max(0, total - WARP_MENU_MAX_ROWS)
    warp_menu_scroll = max(0, min(warp_menu_scroll, max_scroll))
    visible = scroll_entries[warp_menu_scroll:
                             warp_menu_scroll + WARP_MENU_MAX_ROWS]
    overflow = max_scroll > 0
    sb_w = 6 if overflow else 0

    def _eh(e):
        return hdr_h if e[0] == "hdr" else line_h
    scroll_h = sum(_eh(e) for e in visible)
    pinned_h = sum(hdr_h for _ in pinned)
    sep_h    = 6 if (pinned and visible) else 0
    foot_blk = foot_font.get_height() + 8

    w = max(row_font.size(s)[0] for s in width_cands) + pad * 2 + sb_w
    w = max(w, 180)
    h = pad + scroll_h + sep_h + pinned_h + foot_blk + pad

    sw, shh = surface.get_size()
    ax = (_warp_btn_draw_pos[0] if _warp_btn_draw_pos else PANEL_X)
    ay = (_warp_btn_draw_pos[1] if _warp_btn_draw_pos else layout_top())
    bh = warp_button_rect.height if warp_button_rect else 24
    my0 = ay + bh + 4
    if my0 + h > shh:
        my0 = ay - h - 4
    mx0 = max(0, min(int(ax), sw - w))
    my0 = max(0, min(int(my0), shh - h))
    warp_menu_rect = pygame.Rect(mx0, my0, w, h)

    pygame.draw.rect(surface, (28, 28, 36), (mx0, my0, w, h), border_radius=5)
    pygame.draw.rect(surface, COL_BORDER, (mx0, my0, w, h), 1, border_radius=5)
    draw_accent_stripe(surface, mx0, my0, h, ACCENT_WARP, w=2)

    def _draw_hdr(e, cy, near):
        netlabel = e[2]
        col = (210, 210, 225) if near else (120, 120, 140)
        surface.blit(title_font.render(netlabel, True, col),
                     (mx0 + pad, cy + (hdr_h - title_font.get_height()) // 2))
        status = "in range" if near else "out of range"
        scol = ACCENT_WARP if near else (110, 110, 125)
        ss = foot_font.render(status, True, scol)
        surface.blit(ss, (mx0 + w - ss.get_width() - pad - sb_w,
                          cy + (hdr_h - ss.get_height()) // 2))

    mxp, myp = pygame.mouse.get_pos()
    rw = w - 4 - sb_w
    cy = my0 + pad
    for e in visible:
        kind = e[0]
        net  = e[1]
        if kind == "hdr":
            _draw_hdr(e, cy, near_map.get(net, False))
            cy += hdr_h
        elif kind == "empty":
            ph = foot_font.render("(none attuned yet — visit one)",
                                  True, (110, 110, 125))
            surface.blit(ph, (mx0 + pad + 12,
                              cy + (line_h - ph.get_height()) // 2))
            cy += line_h
        elif kind == "grp":
            depth, glabel, path, expanded = e[2], e[3], e[4], e[5]
            tx = mx0 + pad + 4 + depth * indent
            row_rect = pygame.Rect(mx0 + 2, cy, rw, line_h)
            if row_rect.collidepoint(mxp, myp):
                pygame.draw.rect(surface, (48, 56, 66), row_rect,
                                 border_radius=3)
            warp_menu_rects.append((row_rect, {"kind": "toggle",
                                                "path": path}))
            arrow = "-" if expanded else "+"
            surface.blit(row_font.render("%s %s" % (arrow, glabel), True,
                                         (215, 220, 230)),
                         (tx, cy + (line_h - row_font.get_height()) // 2))
            cy += line_h
        else:  # leaf
            depth, dlabel, dzone, dsub = e[2], e[3], e[4], e[5]
            tx = mx0 + pad + 6 + depth * indent
            row_rect = pygame.Rect(mx0 + 2, cy, rw, line_h)
            if row_rect.collidepoint(mxp, myp):
                pygame.draw.rect(surface, (52, 66, 62), row_rect,
                                 border_radius=3)
            warp_menu_rects.append((row_rect,
                                    {"kind": "warp", "net": net,
                                     "zone": dzone, "sub": dsub,
                                     "label": dlabel}))
            surface.blit(row_font.render("• " + dlabel, True,
                                         (225, 230, 235)),
                         (tx, cy + (line_h - row_font.get_height()) // 2))
            cy += line_h

    # Scrollbar indicator spans only the scroll region.
    if overflow:
        track_x = mx0 + w - sb_w + 1
        track_y = my0 + pad
        track_h = scroll_h
        pygame.draw.rect(surface, (50, 50, 62),
                         (track_x, track_y, sb_w - 3, track_h),
                         border_radius=2)
        frac_vis = len(visible) / float(total) if total else 1.0
        thumb_h = max(12, int(track_h * frac_vis))
        thumb_y = track_y + int((track_h - thumb_h)
                                * (warp_menu_scroll / float(max_scroll)))
        pygame.draw.rect(surface, ACCENT_WARP,
                         (track_x, thumb_y, sb_w - 3, thumb_h),
                         border_radius=2)

    # Pinned out-of-range headers at the bottom (do not scroll).
    if pinned:
        if visible:
            sep_y = cy + sep_h // 2
            pygame.draw.line(surface, (60, 60, 74),
                             (mx0 + pad, sep_y),
                             (mx0 + w - pad - sb_w, sep_y))
            cy += sep_h
        for e in pinned:
            _draw_hdr(e, cy, False)
            cy += hdr_h

    # Footer hint, always at the very bottom.
    cy += 4
    surface.blit(foot_font.render(foot, True, (120, 120, 138)),
                 (mx0 + pad, cy))


def draw_warp_confirm(surface):
    """Confirmation popover shown after a destination is clicked. A small
    box naming the destination with a [Warp] (accent) and [Cancel]
    button, so a single stray click can't fire a warp. Records button
    rects in warp_confirm_rects and the envelope in warp_confirm_rect."""
    global warp_confirm_rects, warp_confirm_rect
    warp_confirm_rects = []
    warp_confirm_rect = None
    if warp_confirm is None:
        return
    c = warp_confirm

    title_font = get_font("Consolas", 12, bold=True)
    btn_font   = get_font("Consolas", 12, bold=True)
    sub_font   = get_font("Consolas", 10, italic=True)

    pad = 10
    sendall = bool(setting("warp_use_sendall"))
    head = f"Warp to {c.get('label', c.get('zone', '?'))}?"
    sub  = "all characters" if sendall else "active character"

    bw_warp   = btn_font.size("Warp")[0] + 22
    bw_cancel = btn_font.size("Cancel")[0] + 22
    btn_h     = btn_font.get_height() + 10
    content_w = max(title_font.size(head)[0],
                    sub_font.size(sub)[0],
                    bw_warp + bw_cancel + 8)
    w = content_w + pad * 2
    h = pad + title_font.get_height() + 4 + sub_font.get_height() + 10 \
        + btn_h + pad

    sw, shh = surface.get_size()
    ax = (_warp_btn_draw_pos[0] if _warp_btn_draw_pos else PANEL_X)
    ay = (_warp_btn_draw_pos[1] if _warp_btn_draw_pos else layout_top())
    bh = warp_button_rect.height if warp_button_rect else 24
    y0 = ay + bh + 4
    if y0 + h > shh:
        y0 = ay - h - 4
    x0 = max(0, min(int(ax), sw - w))
    y0 = max(0, min(int(y0), shh - h))
    warp_confirm_rect = pygame.Rect(x0, y0, w, h)

    pygame.draw.rect(surface, (30, 30, 40), (x0, y0, w, h), border_radius=6)
    pygame.draw.rect(surface, ACCENT_WARP, (x0, y0, w, h), 1, border_radius=6)

    surface.blit(title_font.render(head, True, (230, 232, 240)),
                 (x0 + pad, y0 + pad))
    surface.blit(sub_font.render(sub, True, (150, 165, 160)),
                 (x0 + pad, y0 + pad + title_font.get_height() + 4))

    by = y0 + h - pad - btn_h
    mxp, myp = pygame.mouse.get_pos()
    # Warp (accent) on the left, Cancel on the right.
    warp_rect = pygame.Rect(x0 + pad, by, bw_warp, btn_h)
    cancel_rect = pygame.Rect(x0 + pad + bw_warp + 8, by, bw_cancel, btn_h)
    wbg = _lerp_color((40, 70, 62), ACCENT_WARP,
                      0.5 if warp_rect.collidepoint(mxp, myp) else 0.25)
    pygame.draw.rect(surface, wbg, warp_rect, border_radius=4)
    pygame.draw.rect(surface, ACCENT_WARP, warp_rect, 1, border_radius=4)
    _wt = btn_font.render("Warp", True, (20, 28, 26))
    surface.blit(_wt, (warp_rect.centerx - _wt.get_width() // 2,
                       warp_rect.centery - _wt.get_height() // 2))
    cbg = (70, 70, 84) if cancel_rect.collidepoint(mxp, myp) else (52, 52, 64)
    pygame.draw.rect(surface, cbg, cancel_rect, border_radius=4)
    pygame.draw.rect(surface, (110, 110, 125), cancel_rect, 1, border_radius=4)
    _ct = btn_font.render("Cancel", True, (220, 220, 230))
    surface.blit(_ct, (cancel_rect.centerx - _ct.get_width() // 2,
                       cancel_rect.centery - _ct.get_height() // 2))

    warp_confirm_rects = [(warp_rect, "warp"), (cancel_rect, "cancel")]


def draw_header(surface, w):
    """Draw the game-clock header bar. Honors header_position: hy0 is the
    bar's top edge (0 at top, HEIGHT-HEADER_H at bottom). All vertical
    positioning is relative to hy0 / cy, so the same code draws the bar
    at either edge. Whether it draws at all (auto-hide reveal state) is
    decided by the caller via header_shown()."""
    global settings_button_rect
    hours, minutes, day_name, moon_pct, moon_phase = get_vana_time()

    # Top edge of the bar. Everything vertical below is anchored to this
    # (or to cy, which is derived from it), so top vs bottom is a single
    # offset rather than a per-element change.
    hy0 = header_y()
    g   = _menu_g()
    hh  = header_h()
    def _hs(v):
        """Scale a base-design header measurement by the global UI factor."""
        return max(1, round(v * g))
    # Scaled fonts. Assigning these names here shadows the module-level
    # globals for the rest of this function, so every render call below
    # picks up the scaled size without per-call edits.
    font_clock = pygame.font.SysFont("Consolas", _hs(15), bold=True)
    font_day   = pygame.font.SysFont("Consolas", _hs(13), bold=True)
    font_moon  = pygame.font.SysFont("Consolas", _hs(12))

    # Background
    pygame.draw.rect(surface, COL_HEADER, (0, hy0, w, hh))
    # Separator line on the edge that faces the panels: the bottom edge
    # for a top-anchored header, the top edge for a bottom-anchored one.
    _border_y = (hy0 + hh - 1) if header_at_top() else hy0
    pygame.draw.line(surface, COL_BORDER, (0, _border_y), (w, _border_y))

    # ── Settings gear button (leftmost) ─────────────────────────────────────
    # Click to open/close the settings dropdown. Sized to roughly match
    # the clock height; uses a unicode gear glyph rendered in the day
    # font (bold, readable at small sizes).
    gear_size = _hs(22)
    gx = _hs(6)
    gy = hy0 + (hh - gear_size) // 2
    settings_button_rect = pygame.Rect(gx, gy, gear_size, gear_size)
    # Hover / open feedback.
    mx, my = pygame.mouse.get_pos()
    is_hover = settings_button_rect.collidepoint(mx, my)
    btn_bg = (62, 62, 78) if (is_hover or settings_menu_open) else (44, 44, 54)
    btn_bdr = (180, 180, 200) if settings_menu_open else (100, 100, 115)
    pygame.draw.rect(surface, btn_bg, settings_button_rect, border_radius=3)
    pygame.draw.rect(surface, btn_bdr, settings_button_rect, 1, border_radius=3)
    # Hamburger menu: three horizontal bars drawn as rectangles. We
    # don't use a font glyph here because ⚙ / ☰ aren't reliably
    # available in all system fonts (Consolas in particular renders
    # both as tofu boxes on many Windows setups). Drawing the bars
    # ourselves means it always renders the same size and is
    # obviously a menu affordance.
    bar_color = (220, 220, 230)
    bar_w     = gear_size - _hs(10)
    bar_h     = _hs(2)
    bar_gap   = _hs(4)
    bar_x     = gx + (gear_size - bar_w) // 2
    # Center the 3-bar stack vertically.
    stack_h   = bar_h * 3 + bar_gap * 2
    bar_y     = gy + (gear_size - stack_h) // 2
    for i in range(3):
        pygame.draw.rect(
            surface, bar_color,
            (bar_x, bar_y + i * (bar_h + bar_gap), bar_w, bar_h),
        )

    # Reserve room for the gear button before the rest of the header
    # starts. Use max(PANEL_X, gear-right) so the existing layout still
    # gets its left margin even if the gear is small.
    cx = max(PANEL_X, gx + gear_size + _hs(8))
    cy = hy0 + hh // 2

    # ── Character display (plain text or dropdown depending on count) ─────
    # Single-character setup → just show the name as plain text (no pill,
    # no caret, not clickable). Multi-character setup → show as a pill
    # button that opens the picker dropdown. The "is this the live char"
    # red-border highlight is preserved for the multi case so users know
    # when they're viewing a non-live character's configs.
    global char_view_button_rect
    char_view_button_rect = None
    display_name = active_view_char or current_char_name
    if display_name:
        # Truncate to keep the header tidy.
        if len(display_name) > 14:
            display_name = display_name[:13] + "…"

        # How many characters have configs on this machine? Multi-char
        # rigs see a clickable picker; solo users see just the name.
        # We re-enumerate every frame because the count changes rarely
        # and the directory listing is essentially free.
        known_chars = list_known_characters()
        # Previously this only became a clickable pill button when
        # multiple characters were known (so the dropdown was
        # exclusively for character switching). With layout profiles
        # added to the same dropdown, single-character users also
        # need access — otherwise they have no UI surface for saving
        # or switching profiles. Always show the clickable button.
        is_multi = True

        is_off_live = (active_view_char and current_char_name
                       and active_view_char != current_char_name)
        cv_label = font_moon.render(display_name, True, (220, 220, 230))

        if not is_multi:
            # Dead code retained as a comment: this branch used to
            # render a plain non-clickable name for single-character
            # rigs. Kept as a no-op so the indentation around the
            # multi-char branch below stays unchanged.
            pass
        else:
            # Multi-character: pill button with caret. Click opens dropdown.
            cv_caret = font_moon.render(" ▼", True, (180, 180, 200))
            if cv_caret.get_width() < 4:
                cv_caret = font_moon.render(" v", True, (180, 180, 200))
            cv_w = cv_label.get_width() + cv_caret.get_width() + _hs(12)
            cv_h = _hs(18)
            cv_x = cx
            cv_y = cy - cv_h // 2
            char_view_button_rect = pygame.Rect(cv_x, cv_y, cv_w, cv_h)
            is_hover_cv = char_view_button_rect.collidepoint(mx, my)
            if is_off_live:
                cv_bg = (88, 60, 60) if is_hover_cv else (66, 44, 44)
                cv_bdr = (220, 140, 140)
            else:
                cv_bg = (62, 62, 78) if (is_hover_cv or char_view_dropdown_open) else (44, 44, 54)
                cv_bdr = (180, 180, 200) if char_view_dropdown_open else (100, 100, 115)
            pygame.draw.rect(surface, cv_bg, char_view_button_rect,
                             border_radius=3)
            pygame.draw.rect(surface, cv_bdr, char_view_button_rect, 1,
                             border_radius=3)
            surface.blit(cv_label,
                (cv_x + _hs(6), cv_y + (cv_h - cv_label.get_height()) // 2))
            surface.blit(cv_caret,
                (cv_x + _hs(6) + cv_label.get_width(),
                 cv_y + (cv_h - cv_caret.get_height()) // 2))
            cx += cv_w + _hs(8)

    # ── Time / Day / Moon ───────────────────────────────────────────────────
    # All three blocks are temporal info from get_vana_time(); they
    # share a single show_time guard so the user can hide the whole
    # Vana'diel-clock cluster as a unit rather than per-element. When
    # off, the cluster (including the two dividers between time/day
    # and day/moon, plus the trailing space before weather) is
    # skipped entirely — no phantom gap.
    # Clear the clock click-rect first so a stale rect from a previous
    # frame can't fire click-routing when the time widget is hidden.
    global header_time_cycle_phase, header_time_cycle_last_advance
    global header_clock_button_rect
    header_clock_button_rect = None
    if setting("show_time"):
        # ── Combined Vana'diel + OS time widget ─────────────────────────
        # This single widget (at the Vana'diel clock's original left-side
        # position) shows EITHER Vana'diel time ("HH:MM VT") or OS/real
        # time ("H:MM[:SS] am/pm OS"). When clock_cycle_enabled is on it
        # alternates between the two every clock_cycle_sec seconds; when
        # off it shows only Vana time. The OS clock that used to live on
        # the right side is merged in here — clicking the widget still
        # opens the stopwatch/countdown modal (header_clock_button_rect
        # is set below), and a running timer overrides the display with
        # its own value/color regardless of cycle phase. Day + Moon stay
        # exactly where they were, immediately to the right.

        # Advance the VT/OS cycle phase on the user-set interval. Computed
        # against os.time() so dwell time is honored without per-frame
        # drift. Clamped 2-10s. Only cycles when enabled AND no timer is
        # running (a running timer pins the display, see below).
        cycle_on = bool(setting("clock_cycle_enabled"))
        try:
            cycle_sec = int(setting("clock_cycle_sec") or 5)
        except (TypeError, ValueError):
            cycle_sec = 5
        cycle_sec = max(2, min(10, cycle_sec))
        now_t = time.time()
        if cycle_on:
            if header_time_cycle_last_advance == 0.0:
                header_time_cycle_last_advance = now_t
            if now_t - header_time_cycle_last_advance >= cycle_sec:
                header_time_cycle_phase = 1 - header_time_cycle_phase
                header_time_cycle_last_advance = now_t
        else:
            header_time_cycle_phase = 0   # Vana only

        # Build the OS-time string (respecting timezone + seconds toggle),
        # mirroring the former right-side clock block.
        tz_name   = setting("clock_timezone") or "Local"
        tz_offset = CLOCK_TIMEZONES.get(tz_name)
        if tz_offset is None:
            local_now = time.localtime()
        else:
            local_now = time.gmtime(time.time() + tz_offset * 3600)
        hh12  = local_now.tm_hour % 12 or 12
        am_pm = "am" if local_now.tm_hour < 12 else "pm"
        if setting("show_clock_seconds"):
            os_time_str = (f"{hh12:d}:{local_now.tm_min:02d}:"
                           f"{local_now.tm_sec:02d} {am_pm}")
        else:
            os_time_str = f"{hh12:d}:{local_now.tm_min:02d} {am_pm}"
        vana_time_str = f"{hours:02d}:{minutes:02d}"

        # Decide what this frame shows. Running timers take priority over
        # the cycle so the user always sees an active countdown/stopwatch.
        if countdown_running:
            _tick_countdown()   # keep live even with modal closed
        show_label = "VT"
        time_text  = vana_time_str
        time_color = COL_CLOCK
        if countdown_running:
            rem        = _countdown_remaining_now()
            time_text  = _format_countdown(rem)
            time_color = (220, 110, 110)   # red — counting down
            show_label = "TMR"
        elif stopwatch_running:
            sw_elapsed = _stopwatch_elapsed()
            s = max(0, int(sw_elapsed))
            time_text  = f"{s // 3600:d}:{(s % 3600) // 60:02d}:{s % 60:02d}"
            time_color = (220, 200, 130)   # amber — stopwatch running
            show_label = "SW"
        elif cycle_on and header_time_cycle_phase == 1:
            time_text  = os_time_str
            time_color = COL_CLOCK
            show_label = "OS"
        # else: Vana time (already the default above)

        # Render the time value + small label, as a clickable button so
        # it opens the stopwatch/countdown modal (same affordance the OS
        # clock had). Track the widget's full extent for the click rect.
        #
        # Fixed-width time field: the displayed string varies in width
        # (Vana "HH:MM", OS "H:MM pm" vs "12:48:59 pm", timer "0:05:09"),
        # so without a reservation the label and every header element to
        # its right would shift each time the digit count changes. We
        # reserve a constant width sized to the widest realistic string
        # ("12:48:59 pm") and RIGHT-ALIGN the time inside it, so the label
        # — and the rest of the header — stays put regardless of content.
        widget_x0 = cx
        t_surf    = font_clock.render(time_text, True, time_color)
        # Width to reserve for the time field, measured against the widest
        # plausible string ("12:48:59 pm"). Measured fresh each frame so it
        # tracks the scaled clock font — a cross-frame cache would lock to
        # whatever scale it was first measured at.
        time_field_w = font_clock.render(
            "12:48:59 pm", True, COL_CLOCK).get_width()
        # Gap between the time field and the VT/OS label.
        TIME_LABEL_GAP = _hs(12)
        # Compute the label up front so we can size the click box.
        lbl_surf_pre = font_moon.render(show_label, True, COL_LABEL_DIM)
        widget_w = time_field_w + TIME_LABEL_GAP + lbl_surf_pre.get_width()
        time_click_rect = pygame.Rect(
            widget_x0 - _hs(4), cy - (t_surf.get_height() // 2) - _hs(3),
            widget_w + _hs(8), t_surf.get_height() + _hs(6))
        is_hover_time = time_click_rect.collidepoint(mx, my)
        if is_hover_time:
            pygame.draw.rect(surface, (40, 44, 56), time_click_rect,
                             border_radius=3)
            hover_color = (
                min(255, time_color[0] + 35),
                min(255, time_color[1] + 35),
                min(255, time_color[2] + 35))
            t_surf = font_clock.render(time_text, True, hover_color)
        # Right-align the time within the reserved field so its right edge
        # (next to the label) is stable; shorter strings pad on the left.
        time_x = widget_x0 + (time_field_w - t_surf.get_width())
        surface.blit(t_surf, (time_x, cy - t_surf.get_height() // 2))
        cx = widget_x0 + time_field_w + TIME_LABEL_GAP

        lbl_surf = font_moon.render(show_label, True, COL_LABEL_DIM)
        surface.blit(lbl_surf, (cx, cy - lbl_surf.get_height() // 2))
        cx += lbl_surf.get_width() + _hs(18)

        header_clock_button_rect = time_click_rect

        # Divider.
        pygame.draw.line(surface, COL_DIVIDER, (cx, hy0 + _hs(6)), (cx, hy0 + hh - _hs(6)))
        cx += _hs(14)

        # Day name.
        day_color = DAY_COLORS.get(day_name, COL_CLOCK)
        d_surf    = font_day.render(day_name, True, day_color)
        surface.blit(d_surf, (cx, cy - d_surf.get_height() // 2))
        cx += d_surf.get_width() + _hs(18)

        # Divider.
        pygame.draw.line(surface, COL_DIVIDER, (cx, hy0 + _hs(6)), (cx, hy0 + hh - _hs(6)))
        cx += _hs(14)

        # Moon phase + percent.
        moon_label = font_moon.render("Moon:", True, COL_LABEL_DIM)
        surface.blit(moon_label, (cx, cy - moon_label.get_height() // 2))
        cx += moon_label.get_width() + _hs(6)

        moon_str  = f"{moon_phase}  {moon_pct}%"
        m_surf    = font_moon.render(moon_str, True, COL_MOON)
        surface.blit(m_surf, (cx, cy - m_surf.get_height() // 2))
        cx += m_surf.get_width()

    # ── Weather (right after moon, part of the left block) ────────────────
    # Renders the current FFXI weather as a colored label. Color uses the
    # weather's element family (Fire = red, Water = blue, etc.); double-
    # intensity weathers (Heat Wave, Squall, Blizzards, ...) brighten the
    # color so they stand out from their single-intensity counterparts.
    # When weather id is 0 (None) or unmapped, nothing draws.
    # Also gated on the show_weather setting — off = skip entirely.
    if setting("show_weather"):
        w_name, w_color = weather_display(zone_info.get("weather", 0))
    else:
        w_name, w_color = None, None
    if w_name:
        # Divider before weather, matching the moon/day separator style.
        cx += _hs(14)
        pygame.draw.line(surface, COL_DIVIDER, (cx, hy0 + _hs(6)), (cx, hy0 + hh - _hs(6)))
        cx += _hs(14)
        w_lab_surf = font_moon.render("Weather:", True, COL_LABEL_DIM)
        surface.blit(w_lab_surf, (cx, cy - w_lab_surf.get_height() // 2))
        cx += w_lab_surf.get_width() + _hs(6)
        w_val_surf = font_moon.render(w_name, True, w_color)
        surface.blit(w_val_surf, (cx, cy - w_val_surf.get_height() // 2))
        cx += w_val_surf.get_width()

    # End-x of the left block. Used below to make sure the centered gil
    # doesn't overlap left content.
    left_block_end_x = cx

    # ── Pre-compute right block start (for true middle-block centering) ─
    # The whole middle band — points widget, currency cycler, inventory
    # button — should visually center between the end of the left block
    # (weather) and the start of the right block (zone-time). The right
    # block isn't rendered yet, but we can predict where it'll land
    # by re-doing the same width math used down below.
    #
    # Mirrors the calculation in the "Zone info on the right side"
    # block. Kept in sync by reading the same state fields and using
    # the same font + separator widths.
    def _predict_right_block_start():
        # When show_location is off, the right block doesn't render —
        # return the window's right edge so the centered band gets
        # the full remaining width.
        if not setting("show_location"):
            return WIDTH
        timer_t = ""
        if zone_entered_at is not None:
            elapsed = max(0, int(time.time() - zone_entered_at))
            h_, rem_ = divmod(elapsed, 3600)
            m_, s_   = divmod(rem_, 60)
            if h_ > 0:
                timer_t = f"Zone Time - {h_:d}:{m_:02d}:{s_:02d}"
            else:
                timer_t = f"Zone Time - {m_:02d}:{s_:02d}"
        region_t = region_for_zone(zone_info["zone_id"]) or ""
        zname_t  = zone_info["zone_name"] or ""
        mapi_t   = zone_info["map_index"]
        pos_t    = (zone_info.get("pos_str") or "").strip()
        right_p = []
        if mapi_t == -1:
            right_p.append("Mog")
        elif mapi_t > 0:
            right_p.append(f"Map {mapi_t}")
        if zname_t:
            x_, y_, z_ = zone_info["x"], zone_info["y"], zone_info["z"]
            right_p.append(f"x:{x_:.3f} y:{y_:.3f} z:{z_:.3f}")
        right_t = "  ".join(right_p)
        left_p = []
        if timer_t:  left_p.append(timer_t)
        if region_t: left_p.append(region_t)
        left_t = "  ".join(left_p)
        sep_l_   = (font_moon.size("  ")[0] if left_t and zname_t else 0)
        sep_pos_ = (font_moon.size(" ")[0]  if zname_t and pos_t  else 0)
        sep_r_   = (font_moon.size("  ")[0]
                    if (zname_t or pos_t) and right_t else 0)
        total_w_ = 0
        if left_t:  total_w_ += font_moon.size(left_t)[0]
        total_w_ += sep_l_
        if zname_t: total_w_ += font_moon.size(zname_t)[0]
        total_w_ += sep_pos_
        if pos_t:   total_w_ += font_moon.size(pos_t)[0]
        total_w_ += sep_r_
        if right_t: total_w_ += font_moon.size(right_t)[0]
        # Match the right-block render's edge (PANEL_X + the buffer that
        # reserves room for the eye nub) so the middle band centers
        # against the same boundary the coordinates actually draw to.
        return (w - PANEL_X - HEADER_RIGHT_BUFFER) - total_w_

    right_block_start_x = _predict_right_block_start()

    # ── Header points tracker (EXP / CP / Exemplar) ─────────────────────
    # Renders one of the three trackable point types as "current/needed"
    # plus a short label. Sits between the left content (clock/weather)
    # and the currency cycler. Hidden when show_header_points is off.
    # Width is locked to the widest possible entry across all three
    # types so the currency cycler to its right doesn't jitter when
    # the user switches focus or when values cross a digit boundary.
    #
    # Position is finalized BELOW (after measuring the currency block
    # and inventory button) so the whole middle band can be centered
    # as one unit between left and right content. This block just
    # measures the points widget; rendering happens after centering.
    pts_visible = bool(setting("show_header_points"))
    pts_max_w   = 0
    pts_left_pad  = _hs(18)
    pts_right_pad = _hs(18)
    pts_entry    = None  # (num_surf, lbl_surf) for the focused type
    if pts_visible:
        pts_col = (220, 195, 90)
        pts_dim = COL_LABEL_DIM
        # Pre-measure widest possible entry for width locking.
        for key, label, _ in HEADER_POINTS_KEYS:
            cur_v = points_state.get(key, 0)
            tnl_v = points_state.get(key + "_tnl", 0) or 1
            cur_s = f"{cur_v:,}/{tnl_v:,}"
            num_surf = font_clock.render(cur_s, True, pts_col)
            lbl_surf = font_moon.render(f" {label}", True, pts_dim)
            w_entry = num_surf.get_width() + lbl_surf.get_width()
            if w_entry > pts_max_w:
                pts_max_w = w_entry
        # Resolve which type the user wants shown.
        focus = setting("header_points_focus") or "exp"
        chosen = None
        for key, label, val in HEADER_POINTS_KEYS:
            if val == focus:
                chosen = (key, label)
                break
        if chosen is None:
            chosen = HEADER_POINTS_KEYS[0][:2]
        key, label = chosen
        cur_v = points_state.get(key, 0)
        tnl_v = points_state.get(key + "_tnl", 0)
        cur_s = f"{cur_v:,}/{tnl_v:,}"
        pts_entry = (
            font_clock.render(cur_s, True, pts_col),
            font_moon.render(f" {label}", True, pts_dim),
        )

    # ── Currency cycler (centered between left and right blocks) ──────────
    # Was just gil; now cycles through up to 6 currencies (gil + 5 tier-1/2)
    # at a settings-controlled interval. The block has a locked width
    # (widest possible entry) so the inventory button to its right doesn't
    # jitter every cycle when the displayed value changes.
    global inventory_button_rect, events_button_rect
    global currency_cycle_index, currency_cycle_last_advance
    inventory_button_rect = None
    events_button_rect = None

    # Read settings: which currencies are enabled and the cycle interval.
    enabled_entries = []   # list of (state_key, display_name)
    for key, name, setting_key in CURRENCY_CYCLE_KEYS:
        if setting(setting_key):
            enabled_entries.append((key, name))
    cycle_seconds = setting("header_currency_cycle_seconds") or 5
    try:
        cycle_seconds = max(2, min(10, int(cycle_seconds)))
    except (TypeError, ValueError):
        cycle_seconds = 5

    # Colors and fonts (same palette gil used to use).
    cur_col = (220, 195, 90)
    cur_dim = COL_LABEL_DIM

    # Advance the cycle index when the interval elapses. Wrap modulo
    # the enabled list length so a settings change that drops the
    # current entry doesn't index past the end.
    now_t = time.time()
    if enabled_entries:
        if now_t - currency_cycle_last_advance >= cycle_seconds:
            # Catch up if we skipped multiple intervals (e.g. game
            # was paused). Single increment is fine here — we only
            # advance once per slow tick, the visual just resumes.
            currency_cycle_index = (currency_cycle_index + 1) \
                                   % len(enabled_entries)
            currency_cycle_last_advance = now_t
        else:
            # Clamp index in case the enabled set shrank.
            currency_cycle_index %= len(enabled_entries)

    # Measure widest possible entry to lock the block width. We use the
    # CURRENT value of every enabled currency as the candidate; the
    # widest of these sets our reserved block. This means the block
    # width can still grow as a currency increases (e.g. gil going
    # from 9,999 to 10,000), but only on those transition frames —
    # not every cycle tick. Acceptable trade-off vs. globally locking
    # to "biggest possible 64-bit int."
    if enabled_entries:
        max_w = 0
        for key, name in enabled_entries:
            val = currency_state.get(key, 0)
            val_str = f"{val:,}"
            num_surf = font_clock.render(val_str, True, cur_col)
            suf_surf = font_moon.render(f" {name}", True, cur_dim)
            entry_w = num_surf.get_width() + suf_surf.get_width()
            if entry_w > max_w:
                max_w = entry_w
        block_w = max_w
    else:
        # No currencies enabled: reserve space for the placeholder.
        placeholder = font_moon.render(
            "No currencies enabled", True, cur_dim)
        block_w = placeholder.get_width()

    # ── Center the WHOLE middle band as one unit ─────────────────────
    # The middle band consists of:
    #   [points widget + paddings] → [currency block] → [gap + inventory btn]
    # All three move together so they stay visually grouped and the
    # combined unit centers between the left content (weather) and the
    # right content (zone-time). Earlier code centered only the currency
    # block, which left the band shifted left when points and inventory
    # are both present.
    inv_gap     = _hs(10)
    inv_btn_w   = _hs(96)    # matches the value used in the inventory-button render
    inv_visible = bool(setting("show_inventory_button"))

    # Events button — always shown, sits at the leftmost edge of the
    # centered band so it doesn't conflict with the inventory button
    # on the right. Width fits the label "Events" comfortably at our
    # header font sizes. Gap between it and the points/currency block
    # is the same as inv_gap for visual symmetry.
    # Gated on show_events — when off, the band collapses without it
    # and the points widget anchors the left edge instead.
    events_visible = bool(setting("show_events"))
    events_btn_w   = _hs(60)
    events_btn_gap = _hs(10)
    events_total_w = (events_btn_w + events_btn_gap) if events_visible else 0

    pts_total_w = (pts_left_pad + pts_max_w + pts_right_pad) if pts_visible else 0
    inv_total_w = (inv_gap + inv_btn_w) if inv_visible else 0
    band_w      = events_total_w + pts_total_w + block_w + inv_total_w

    # Available horizontal space and ideal centered position. Floor at
    # left_block_end_x + 12 so we never overlap the weather block — if
    # the window's been resized to be very narrow, the band slides
    # right against the left content rather than under it.
    avail_lo   = left_block_end_x + _hs(12)
    avail_hi   = max(avail_lo, right_block_start_x - _hs(12))
    ideal_band = (avail_lo + avail_hi - band_w) // 2
    band_x     = max(avail_lo, min(ideal_band,
                                   avail_hi - band_w))

    # ── Events button (leftmost in the band) ──
    # Click opens the campaigns/events modal (the same target the now-
    # removed settings menu item used to fire). Drawn first so it
    # anchors the left edge of the band. We size it to match the
    # inventory button's vertical metrics so they line up across
    # the centered band. When show_events is off, the button is
    # skipped entirely and events_button_rect stays None so the
    # click handler can't fire stale geometry.
    if events_visible:
        ev_btn_x = band_x
        ev_btn_h = _hs(18)
        ev_btn_y = cy - ev_btn_h // 2
        ev_btn_rect = pygame.Rect(ev_btn_x, ev_btn_y, events_btn_w, ev_btn_h)
        is_hover_ev = ev_btn_rect.collidepoint(mx, my)
        ev_bg  = (62, 62, 78) if is_hover_ev else (44, 44, 54)
        ev_bdr = (100, 100, 115)
        pygame.draw.rect(surface, ev_bg,  ev_btn_rect, border_radius=3)
        pygame.draw.rect(surface, ev_bdr, ev_btn_rect, 1, border_radius=3)
        ev_label = font_moon.render("Events", True, (220, 220, 230))
        surface.blit(ev_label,
                     (ev_btn_x + (events_btn_w - ev_label.get_width()) // 2,
                      ev_btn_y + (ev_btn_h - ev_label.get_height()) // 2))
        events_button_rect = ev_btn_rect

    # Render the points widget at the left edge of the band (shifted
    # right by the events button + gap).
    if pts_visible:
        pts_x = band_x + events_total_w + pts_left_pad
        if pts_entry is not None:
            num_surf, lbl_surf = pts_entry
            entry_w  = num_surf.get_width() + lbl_surf.get_width()
            entry_x  = pts_x + (pts_max_w - entry_w) // 2
            gy  = cy - num_surf.get_height() // 2
            surface.blit(num_surf, (entry_x, gy))
            gy2 = cy - lbl_surf.get_height() // 2
            surface.blit(lbl_surf, (entry_x + num_surf.get_width(), gy2))

    # The currency block sits right after the points widget's right-pad.
    block_x = band_x + events_total_w + pts_total_w

    # Render the current entry (or placeholder) inside the locked block.
    if enabled_entries:
        cur_key, cur_name = enabled_entries[currency_cycle_index]
        cur_val = currency_state.get(cur_key, 0)
        val_str = f"{cur_val:,}"
        num_surf = font_clock.render(val_str, True, cur_col)
        suf_surf = font_moon.render(f" {cur_name}", True, cur_dim)
        entry_w  = num_surf.get_width() + suf_surf.get_width()
        # Center the entry within the locked block so shorter entries
        # don't all left-justify under the widest one (looks ragged).
        entry_x = block_x + (block_w - entry_w) // 2
        gy = cy - num_surf.get_height() // 2
        surface.blit(num_surf, (entry_x, gy))
        gy2 = cy - suf_surf.get_height() // 2
        surface.blit(suf_surf, (entry_x + num_surf.get_width(), gy2))
    else:
        placeholder = font_moon.render(
            "No currencies enabled", True, cur_dim)
        py = cy - placeholder.get_height() // 2
        surface.blit(placeholder, (block_x, py))

    # Inventory button anchored to the right edge of the LOCKED block,
    # not the current entry. This is what stops the button from jittering
    # when the cycle advances to a shorter/longer entry.
    if setting("show_inventory_button"):
        inv_btn_x = block_x + block_w + _hs(10)
        # Width sized to fit "▼ Inventory" comfortably at the header font.
        inv_btn_w, inv_btn_h = _hs(96), _hs(18)
        inv_btn_y = cy - inv_btn_h // 2
        inv_btn_rect = pygame.Rect(inv_btn_x, inv_btn_y,
                                   inv_btn_w, inv_btn_h)
        # Hover/open feedback.
        is_hover_inv = inv_btn_rect.collidepoint(mx, my)
        bg  = (62, 62, 78) if (is_hover_inv or inventory_dropdown_open) else (44, 44, 54)
        bdr = (180, 180, 200) if inventory_dropdown_open else (100, 100, 115)
        pygame.draw.rect(surface, bg,  inv_btn_rect, border_radius=3)
        pygame.draw.rect(surface, bdr, inv_btn_rect, 1, border_radius=3)
        # Tiny down-caret + "Inventory" label.
        caret_color = (220, 220, 230)
        cax = inv_btn_x + _hs(6)
        cay = inv_btn_y + _hs(6)
        pygame.draw.polygon(surface, caret_color, [
            (cax, cay), (cax + _hs(6), cay), (cax + _hs(3), cay + _hs(4))])
        bag_label = font_moon.render("Inventory", True, caret_color)
        surface.blit(bag_label,
            (cax + _hs(10), inv_btn_y + (inv_btn_h - bag_label.get_height()) // 2))
        inventory_button_rect = inv_btn_rect

    # ── OS clock (right-side) — REMOVED, merged into the left time ─────
    # The standalone right-side OS clock was combined with the Vana'diel
    # time into the single cycling widget at the left cluster (see the
    # "Combined Vana'diel + OS time widget" block above). That widget now
    # owns header_clock_button_rect and the running-timer takeover, so
    # there is intentionally nothing to render here. The old show_clock /
    # clock_timezone / show_clock_seconds settings still apply — they're
    # consumed by the combined widget. Kept as a comment (rather than
    # silently deleted) so the merge is obvious to the next reader and the
    # right-side layout math below isn't accidentally fed a clock width.

    # ── Zone info on the right side ────────────────────────────────────────
    # Build parts left to right: ZoneTimer, Region, Zone (clickable),
    # Map, Coords. The timer prefix is "Zone Time - HH:MM:SS" (or
    # MM:SS if under an hour) and counts up from the last zone change.
    region = region_for_zone(zone_info["zone_id"])
    zname  = zone_info["zone_name"]
    mapi   = zone_info["map_index"]
    x, y, z = zone_info["x"], zone_info["y"], zone_info["z"]
    pos_grid = (zone_info.get("pos_str") or "").strip()

    # Format elapsed seconds as HH:MM:SS or MM:SS depending on length.
    # Skip the timer string entirely if we haven't seen a zone packet
    # yet (zone_entered_at is None) so the header doesn't show a
    # frozen "00:00".
    timer_text = ""
    if zone_entered_at is not None:
        elapsed = max(0, int(time.time() - zone_entered_at))
        h, rem = divmod(elapsed, 3600)
        m, s   = divmod(rem, 60)
        if h > 0:
            timer_text = f"Zone Time - {h:d}:{m:02d}:{s:02d}"
        else:
            timer_text = f"Zone Time - {m:02d}:{s:02d}"

    # Left part = timer + region. Right part = map + coords. Zone name
    # rendered separately so we can give it a hyperlink rect. The
    # pos_grid string ("(K-9)" style) is rendered as a dim suffix
    # right after the zone name so the BG-wiki hyperlink stays scoped
    # to just the name.
    left_pieces = []
    if timer_text:
        left_pieces.append(timer_text)
    if region:
        left_pieces.append(region)
    left_text = "  ".join(left_pieces)
    right_parts = []
    if mapi == -1:
        right_parts.append("Mog")
    elif mapi > 0:
        right_parts.append(f"Map {mapi}")
    if zname:
        right_parts.append(f"x:{x:.3f} y:{y:.3f} z:{z:.3f}")
    right_text = "  ".join(right_parts)

    if (region or zname or right_text) and setting("show_location"):
        # Measure all four pieces to right-align together: left, zone,
        # pos-grid suffix, right.
        gap = font_moon.size("  ")[0]
        sep_l   = (font_moon.size("  ")[0] if left_text and zname     else 0)
        sep_pos = (font_moon.size(" ")[0]  if zname and pos_grid      else 0)
        sep_r   = (font_moon.size("  ")[0] if (zname or pos_grid) and right_text else 0)

        l_surf = font_moon.render(left_text,  True, COL_LABEL_DIM) if left_text  else None
        z_surf = font_moon.render(zname,      True, COL_CLOCK)     if zname      else None
        p_surf = font_moon.render(pos_grid,   True, COL_LABEL_DIM) if pos_grid   else None
        r_surf = font_moon.render(right_text, True, COL_CLOCK)     if right_text else None

        total_w = ((l_surf.get_width() if l_surf else 0) + sep_l +
                   (z_surf.get_width() if z_surf else 0) + sep_pos +
                   (p_surf.get_width() if p_surf else 0) + sep_r +
                   (r_surf.get_width() if r_surf else 0))
        # Extra right-side breathing room at the end of the coordinates.
        # Reserves a small gap so the right block doesn't run flush to
        # the window edge — and gives the hide/show eye nub a natural
        # home there. Sized to clear the default nub (24px) plus a hair
        # of spacing; if the user resizes the nub larger, it may overlap
        # slightly, but the nub draws on top so it stays usable.
        right_edge = w - PANEL_X - HEADER_RIGHT_BUFFER
        draw_x = right_edge - total_w
        y_mid  = cy - (z_surf or l_surf or r_surf).get_height() // 2

        if l_surf:
            surface.blit(l_surf, (draw_x, y_mid))
            draw_x += l_surf.get_width() + sep_l
        if z_surf:
            zrect = pygame.Rect(draw_x, y_mid, z_surf.get_width(), z_surf.get_height())
            # Hover: brighten + underline.
            is_hover = zrect.collidepoint(pygame.mouse.get_pos())
            color = (255, 255, 180) if is_hover else COL_CLOCK
            z_surf = font_moon.render(zname, True, color)
            surface.blit(z_surf, (draw_x, y_mid))
            if is_hover:
                pygame.draw.line(surface, color,
                                 (draw_x, y_mid + z_surf.get_height() - 1),
                                 (draw_x + z_surf.get_width(), y_mid + z_surf.get_height() - 1))
            register_click_target(zrect, bgwiki_url(zname))
            draw_x += z_surf.get_width() + sep_pos
        if p_surf:
            surface.blit(p_surf, (draw_x, y_mid))
            draw_x += p_surf.get_width() + sep_r
        if r_surf:
            surface.blit(r_surf, (draw_x, y_mid))


# ── Settings dropdown menu ───────────────────────────────────────────────
# Renders a panel below the header gear button when settings_menu_open
# is True. Each row is one schema entry with an inline control:
#   - bool   → click anywhere on the row to toggle (or tap [ON]/[OFF])
#   - int    → [-]  value  [+]  buttons
#   - float  → same as int
#   - enum   → [<]  current  [>]  buttons cycle through options
#   - string → not yet implemented (will need a focus/text-edit pass)
#
# Hits are recorded in settings_menu_rects each frame so the click
# handler can resolve them.
def settings_menu_size():
    """Compute (w, h) of the menu based on the canonical section list
    and the schema's row count. Width is fixed; height grows with
    content. Empty sections still get a header + a small placeholder
    row so the user sees the full organizational structure.

    All dimensions are multiplied by the global UI scale (_menu_g) so
    the dropdown grows/shrinks with the same setting that scales the
    panels. draw_settings_menu() applies the identical factor to the
    same base constants, so the computed size and the rendered rows
    stay in agreement."""
    g = _menu_g()
    width = round(320 * g)
    row_h = round(24 * g)
    sec_h = round(22 * g)       # section header row
    placeholder_h = round(18 * g)  # "(no settings yet)" row for empty sections
    pad   = round(8 * g)
    # Group entries by section so we know which sections are empty.
    grouped = {sec: [] for sec in SETTINGS_SECTIONS}
    for s in SETTINGS_SCHEMA:
        sec = s.get("section")
        # The "Update available" button only appears when the
        # startup update check found a newer release.
        if s.get("key") == "open_update" and not _update_available:
            continue
        if sec in grouped:
            grouped[sec].append(s)
    height = pad
    for sec in SETTINGS_SECTIONS:
        is_loose = sec.startswith("_")
        entries = grouped[sec]
        if is_loose and not entries:
            # Empty unnamed sections contribute nothing.
            continue
        # Header strip height: same for both named and unnamed
        # (unnamed renders just the underline at the same Y position
        # a name would occupy).
        height += sec_h
        if entries:
            height += row_h * len(entries)
        else:
            height += placeholder_h
    height += pad
    return width, height


# ── Inventory dropdown ───────────────────────────────────────────────────────
# Bag-list view → click bag → bag-detail view (scrollable list of items).
# Each item row in detail view is a click target that opens its BG-Wiki
# page. A small ✓ appears next to items that match anything in the
# gearswap_referenced_items index.
#
# Bag display order matches FFXI menus (most-used first).
INVENTORY_BAG_ORDER = [
    ("inventory", "Inventory"),
    ("wardrobe",  "Wardrobe 1"),
    ("wardrobe2", "Wardrobe 2"),
    ("wardrobe3", "Wardrobe 3"),
    ("wardrobe4", "Wardrobe 4"),
    ("wardrobe5", "Wardrobe 5"),
    ("wardrobe6", "Wardrobe 6"),
    ("wardrobe7", "Wardrobe 7"),
    ("wardrobe8", "Wardrobe 8"),
    ("safe",      "Safe"),
    ("safe2",     "Safe 2"),
    ("storage",   "Storage"),
    ("locker",    "Locker"),
    ("satchel",   "Satchel"),
    ("sack",      "Sack"),
    ("case",      "Case"),
]

# ── Header currency cycle order ────────────────────────────────────────
# Tuple of (state_key, display_name, settings_key). The header cycles
# through every entry where setting(settings_key) is True (which is the
# default for all six). Order here is also the order presented in the
# Settings panel under the "Header" section. state_key matches the keys
# emitted by lua's CURRENCY|...; display_name is what appears next to
# the value (e.g. "12,345 Gil").
CURRENCY_CYCLE_KEYS = [
    ("gil",          "Gil",         "show_currency_gil"),
    ("sparks",       "Sparks",      "show_currency_sparks"),
    ("accolades",    "Accolades",   "show_currency_accolades"),
    ("gallimaufry",  "Gallimaufry", "show_currency_gallimaufry"),
    ("temenos",      "Temenos",     "show_currency_temenos"),
    ("apollyon",     "Apollyon",    "show_currency_apollyon"),
    # Display labels for the new currencies use single-word forms to
    # match the existing convention (and the natural FFXI shorthand)
    # — using "Escha Beads" / "Nyzul Tokens" overflowed the centered
    # header band on narrower windows. Storage keys keep the long
    # form for clarity in logs and at the wire.
    ("escha_beads",  "Beads",       "show_currency_escha_beads"),
    ("nyzul_tokens", "Tokens",      "show_currency_nyzul_tokens"),
    ("ichor",        "Ichor",       "show_currency_ichor"),
]

# ── Header points tracker ────────────────────────────────────────────
# Tuple of (state_key, display_label, settings_value). state_key is
# what lua emits in POINTS|...; display_label is the suffix shown after
# the value in the header (e.g. "12,847 EXP"); settings_value is the
# string stored for the 'header_points_focus' enum setting.
HEADER_POINTS_KEYS = [
    ("exp",      "EXP",      "exp"),
    ("cp",       "CP",       "cp"),
    ("exemplar", "Exemplar", "exemplar"),
]


def _bgwiki_item_url(item_name):
    """Build a BG-Wiki URL for an item. Spaces → underscores; the rest
    of the name passes through. BG-Wiki is case-sensitive but tolerant
    of mismatches via redirects."""
    if not item_name:
        return ""
    return "https://www.bg-wiki.com/ffxi/" + item_name.replace(" ", "_")


# ── Porter slip nicknames ────────────────────────────────────────────────
# Per-character nickname overrides for porter slip rows. Slips have
# generic default names ("Porter Slip 01") that don't convey what the
# user actually stores on them, so the dropdown lets the user
# right-click any slip and assign a custom label (e.g. "NIN Body
# Wardrobe"). Nicknames are persisted to disk so they survive restarts.
#
# Scope: per-character. Each character file is at
#   SETTINGS_DIR/omniwatch_porter_slip_names_<charname>.json
# Format: { "<slip_id>": "<nickname>", ... }   keys are stringified ints
# (JSON limitation; we coerce back to int on load).
#
# A character-specific file is read lazily on first lookup and cached in
# _inventory_slip_nicknames_cache so subsequent draws don't hit disk.
# Saves are immediate and synchronous — the file is small and writes are
# rare (one per nickname edit), so async/throttle isn't worth the
# complexity.

def _porter_slip_nicknames_path(charname):
    """Return the JSON file path for a character's slip nicknames.

    Empty/None charname yields None (no file path — caller treats as
    "no nicknames available"). Character name is lowercased for the
    filename to avoid case-sensitivity surprises on Windows vs other
    filesystems where the user might create the file with one case
    and later look it up with another.
    """
    if not charname:
        return None
    try:
        safe = "".join(c for c in charname.lower()
                       if c.isalnum() or c in ("_", "-"))
        if not safe:
            return None
        return os.path.join(
            SETTINGS_DIR, f"omniwatch_porter_slip_names_{safe}.json")
    except NameError:
        # SETTINGS_DIR not defined yet (early in startup). Caller
        # treats None as "no nicknames yet"; the slip rows just show
        # their default names until SETTINGS_DIR is available.
        return None


def _porter_slip_nicknames_for_player():
    """Return the {slip_id: nickname} dict for the current character.

    Lazy-loads from disk on first call per character. Cached for
    subsequent calls so the renderer can call this every frame
    without disk I/O. Returns an empty dict (not None) when there
    are no nicknames yet — caller can do .get() against the result
    without nil-check noise.

    If player_self_name is empty (haven't received it from lua yet),
    returns an empty dict that ISN'T cached — so once the name does
    arrive, the next lookup loads properly.
    """
    name = (player_self_name or "").strip().lower()
    if not name:
        return {}
    cached = _inventory_slip_nicknames_cache.get(name)
    if cached is not None:
        return cached
    path = _porter_slip_nicknames_path(name)
    nicks = {}
    if path and os.path.exists(path):
        try:
            with open(path, "r", encoding="utf-8") as f:
                raw = json.load(f)
            if isinstance(raw, dict):
                for k, v in raw.items():
                    try:
                        sid = int(k)
                    except (TypeError, ValueError):
                        continue
                    if isinstance(v, str) and v.strip():
                        nicks[sid] = v.strip()
        except Exception as e:
            print(f"[OmniWatch] porter slip nicknames load failed "
                  f"({path}): {e!r}")
    _inventory_slip_nicknames_cache[name] = nicks
    return nicks


def _porter_slip_set_nickname(slip_id, nickname):
    """Persist a nickname for `slip_id` on the current character.

    Updates the in-memory cache AND writes the per-character JSON
    file. An empty/whitespace nickname REMOVES the entry (lets the
    user clear a nickname by editing it to empty). Returns True on
    success, False if the file can't be written (path resolution
    failed, disk error, etc.) — caller decides whether to surface
    the failure.

    No-op if there's no current character name yet.
    """
    name = (player_self_name or "").strip().lower()
    if not name:
        return False
    path = _porter_slip_nicknames_path(name)
    if not path:
        return False
    # Update cache first so the renderer reflects the change
    # immediately, even if the write fails.
    nicks = _porter_slip_nicknames_for_player()
    cleaned = (nickname or "").strip()
    if cleaned:
        nicks[slip_id] = cleaned
    else:
        nicks.pop(slip_id, None)
    # Persist. Empty dict still writes (creates an empty file) so the
    # user can see in the filesystem that we're managing the slot.
    try:
        out = {str(k): v for k, v in nicks.items()}
        with open(path, "w", encoding="utf-8") as f:
            json.dump(out, f, indent=2, ensure_ascii=False)
        return True
    except Exception as e:
        print(f"[OmniWatch] porter slip nicknames save failed "
              f"({path}): {e!r}")
        return False


def _inventory_panel_geometry():
    """Single source of truth for the inventory dropdown panel's
    position and size. The renderer, the dispatch function, and the
    outside-click envelope all call this so they stay in sync — when
    only one of them gets the clamping right, click hit-testing
    silently falls out of agreement with what was drawn.

    Returns (x, y, w, h) or None when the panel can't be positioned
    (no anchor button rect exists yet)."""
    if not inventory_button_rect:
        return None
    panel_w = 320
    panel_h = 380
    panel_x = inventory_button_rect.x
    panel_y = inventory_button_rect.bottom + 2
    # Horizontal clamp: don't bleed off the right edge.
    if panel_x + panel_w > WIDTH:
        panel_x = max(0, WIDTH - panel_w)
    # Vertical clamp: shrink height if we'd run off the bottom.
    if panel_y + panel_h > HEIGHT:
        panel_h = max(120, HEIGHT - panel_y)
    return (panel_x, panel_y, panel_w, panel_h)


def _item_in_gearswap(item_name):
    """True if `item_name` is referenced anywhere in the user's
    gearswap files (case-insensitive lookup)."""
    if not item_name or not gearswap_referenced_items:
        return False
    return item_name.lower() in gearswap_referenced_items


def draw_char_view_dropdown(surface):
    """Render the character-view dropdown if char_view_dropdown_open.
    Lists every character that has a subfolder under USER_DIR plus an
    explicit 'follow live character' option that tracks whoever is
    logged in. For the ACTIVE character, also lists their saved
    layout profiles indented under their row, with a green dot next
    to the currently active profile and a '+ New profile…' row at
    the bottom. Populates char_view_dropdown_rects for click
    dispatch."""
    global char_view_dropdown_rects
    char_view_dropdown_rects = []
    if not char_view_dropdown_open:
        return
    if not char_view_button_rect:
        return

    # Discover characters via the shared helper. Same enumeration
    # logic the header uses to decide whether to show a dropdown.
    chars = list_known_characters()
    # Pull profiles for the ACTIVE character so we can size the
    # panel correctly upfront. list_profiles() always returns at
    # least ["Default"] so this set is non-empty whenever there's
    # an active character.
    profiles = list_profiles() if active_view_char else ["Default"]
    # Profile block size: separator (~6) + header (~14) + N profile
    # rows + Save-as row, all at 18px each.
    profile_rows_h = 20 + (len(profiles) + 1) * 18

    pad   = 6
    row_h = 20
    item_count = max(1, len(chars)) + 1
    panel_w = 260   # wider — needs room for "+ Save current as new profile…"
    panel_h = item_count * row_h + profile_rows_h + pad * 2
    panel_x = char_view_button_rect.x
    panel_y = char_view_button_rect.bottom + 2
    if panel_x + panel_w > WIDTH:
        panel_x = max(0, WIDTH - panel_w)

    pygame.draw.rect(surface, (28, 28, 36),
                     (panel_x, panel_y, panel_w, panel_h),
                     border_radius=4)
    pygame.draw.rect(surface, (140, 140, 160),
                     (panel_x, panel_y, panel_w, panel_h), 1,
                     border_radius=4)

    f_row     = pygame.font.SysFont("Consolas", 12)
    f_profile = pygame.font.SysFont("Consolas", 10)
    f_dim     = pygame.font.SysFont("Consolas", 10, italic=True)
    cy = panel_y + pad

    # Top row: "Follow live character"
    follow_rect = pygame.Rect(panel_x + 2, cy, panel_w - 4, row_h)
    is_hover = follow_rect.collidepoint(pygame.mouse.get_pos())
    if is_hover:
        pygame.draw.rect(surface, (40, 40, 52), follow_rect)
    is_following = (active_view_char == current_char_name) and bool(current_char_name)
    follow_label = "● Follow live char" if is_following else "○ Follow live char"
    follow_color = (140, 220, 140) if is_following else (200, 200, 210)
    fs = f_row.render(follow_label, True, follow_color)
    surface.blit(fs, (panel_x + 8, cy + (row_h - fs.get_height()) // 2))
    char_view_dropdown_rects.append((follow_rect, {"kind": "follow_live"}))
    cy += row_h

    if not chars:
        msg = f_dim.render("(no saved characters yet)",
                           True, COL_LABEL_DIM)
        surface.blit(msg, (panel_x + 8, cy + 2))
        return

    # Per-character rows.
    for name in chars:
        row_rect = pygame.Rect(panel_x + 2, cy, panel_w - 4, row_h)
        is_hover = row_rect.collidepoint(pygame.mouse.get_pos())
        if is_hover:
            pygame.draw.rect(surface, (40, 40, 52), row_rect)
        is_active = (name == active_view_char)
        is_live   = (name == current_char_name)
        prefix = "●" if is_active else "○"
        suffix = "  (live)" if is_live else ""
        color = (220, 220, 230) if is_active else (180, 180, 195)
        label = f"{prefix} {name}{suffix}"
        ls = f_row.render(label, True, color)
        surface.blit(ls, (panel_x + 8, cy + (row_h - ls.get_height()) // 2))
        char_view_dropdown_rects.append((row_rect, {
            "kind": "select_char", "name": name,
        }))
        cy += row_h

    # Profile section — ALWAYS renders at the bottom of the dropdown
    # for the currently active character. Was previously gated on
    # `is_active` inside the per-character loop, which meant if
    # active_view_char didn't match any folder (empty / new install /
    # mismatched casing), the entire profile UI silently disappeared.
    # Rendering it unconditionally as its own section guarantees the
    # save row is always reachable.
    if profiles:
        # Separator line above the profile section so it reads as
        # distinct from the character list.
        pygame.draw.line(surface, (60, 60, 75),
                         (panel_x + 8, cy + 2),
                         (panel_x + panel_w - 8, cy + 2))
        cy += 4
        # Small header label.
        section_who = active_view_char or "(no character)"
        hdr_label = f"Profiles for {section_who}"
        hs = f_dim.render(hdr_label, True, (180, 180, 200))
        surface.blit(hs, (panel_x + 8, cy))
        cy += hs.get_height() + 2
        for prof in profiles:
            prow_rect = pygame.Rect(panel_x + 12, cy,
                                     panel_w - 16, 18)
            ph = prow_rect.collidepoint(pygame.mouse.get_pos())
            if ph:
                pygame.draw.rect(surface, (38, 42, 56), prow_rect)
            is_active_prof = (prof == active_profile_name)
            p_prefix = "●" if is_active_prof else "○"
            p_color  = ((140, 220, 140) if is_active_prof
                        else (200, 205, 220))
            p_label  = f"{p_prefix} {prof}"
            ps = f_profile.render(p_label, True, p_color)
            surface.blit(ps,
                (panel_x + 20,
                 cy + (18 - ps.get_height()) // 2))
            # Delete button on the right (except Default).
            if prof != "Default":
                del_rect = pygame.Rect(prow_rect.right - 18,
                                        cy + 3, 14, 12)
                pygame.draw.rect(surface, (90, 50, 60),
                                 del_rect, border_radius=2)
                dx = f_profile.render("×", True, (240, 200, 200))
                surface.blit(dx,
                    (del_rect.x + (del_rect.w - dx.get_width()) // 2,
                     del_rect.y + (del_rect.h - dx.get_height()) // 2 - 1))
                char_view_dropdown_rects.append(
                    (del_rect, {"kind": "delete_profile",
                                "name": prof}))
            char_view_dropdown_rects.append((prow_rect, {
                "kind": "select_profile", "name": prof,
            }))
            cy += 18
        # "+ Save current as new profile…" row — clearly highlighted
        # in light blue so it stands out as the action row.
        new_rect = pygame.Rect(panel_x + 12, cy, panel_w - 16, 18)
        nh = new_rect.collidepoint(pygame.mouse.get_pos())
        if nh:
            pygame.draw.rect(surface, (45, 55, 80), new_rect)
        ns = f_profile.render("+ Save current as new profile…", True,
                               (180, 200, 255))
        surface.blit(ns,
            (panel_x + 20, cy + (18 - ns.get_height()) // 2))
        char_view_dropdown_rects.append((new_rect, {
            "kind": "new_profile",
        }))
        cy += 18


def dispatch_char_view_dropdown_click(mx, my):
    """Handle clicks against the character-view dropdown. Returns True
    if the click was consumed."""
    global char_view_dropdown_open

    if char_view_button_rect and char_view_button_rect.collidepoint(mx, my):
        char_view_dropdown_open = not char_view_dropdown_open
        return True

    if not char_view_dropdown_open:
        return False

    for rect, action in char_view_dropdown_rects:
        if rect.collidepoint(mx, my):
            kind = action.get("kind")
            if kind == "follow_live":
                # Switch view back to the live character.
                if current_char_name:
                    _switch_active_view(current_char_name)
            elif kind == "select_char":
                target = action.get("name")
                if target:
                    _switch_active_view(target)
            elif kind == "select_profile":
                # Switch to the named profile under the active char.
                # Profile rows only render under the active character,
                # so we don't need to re-resolve which char this is for.
                target = action.get("name")
                if target:
                    switch_to_profile(target)
                # Keep the dropdown open so the user can immediately
                # confirm the switch / pick another profile.
                return True
            elif kind == "new_profile":
                # Open the small naming modal. Dropdown stays open so
                # cancelling the modal returns the user to the same
                # picker they were on.
                global profile_name_modal_open, profile_name_modal_text
                profile_name_modal_open = True
                profile_name_modal_text = ""
                return True
            elif kind == "delete_profile":
                target = action.get("name")
                if target:
                    delete_profile(target)
                return True
            char_view_dropdown_open = False
            return True

    # Click anywhere else closes the dropdown without changing selection.
    char_view_dropdown_open = False
    return True


def _inventory_bag_label(bag_key):
    """Return the human-readable label for a bag key (e.g. 'wardrobe3'
    → 'Wardrobe 3'). Falls back to the key itself if unknown so search
    results don't break on a bag that was added since INVENTORY_BAG_ORDER
    was last updated."""
    for k, lbl in INVENTORY_BAG_ORDER:
        if k == bag_key:
            return lbl
    return bag_key.title()


def _inventory_rank_matches(query):
    """Walk every bag in inventory_state and return a ranked list of
    matches for `query`. Each entry is (bag_key, item_dict, score).

    Ranking (case-insensitive):
      - Exact name match               → 100
      - Name starts with query         → 80 - (0)            = 80
      - Name contains query as token   → 70 - word_position
      - Name contains query (substring)→ 50 - position_in_name

    Higher score = better match. List is sorted descending by score,
    then alphabetically by item name as a tiebreaker. Empty/whitespace
    query returns empty.

    The list is materialized fresh on each call — caller should cache
    against the query string to avoid re-ranking every frame.
    """
    q = (query or "").strip().lower()
    if not q:
        return []
    matches = []
    for bag_key, _label in INVENTORY_BAG_ORDER:
        items = inventory_state.get(bag_key, [])
        for it in items:
            name = (it.get("name") or "").strip()
            if not name:
                continue
            nl = name.lower()
            if nl == q:
                score = 100
            elif nl.startswith(q):
                score = 80
            else:
                # Token-start match (e.g. "shorinken" matches the second
                # word of "Heishi Shorinken"): rank above substring,
                # below prefix.
                tokens = nl.split()
                tok_pos = None
                for i, tok in enumerate(tokens):
                    if tok.startswith(q):
                        tok_pos = i
                        break
                if tok_pos is not None:
                    score = 70 - tok_pos
                else:
                    pos = nl.find(q)
                    if pos < 0:
                        continue
                    score = 50 - min(pos, 49)
            matches.append((bag_key, it, score))
    # Sort by score desc, then by item name asc.
    matches.sort(key=lambda m: (-m[2], (m[1].get("name") or "").lower()))
    return matches


def _inventory_get_search_results():
    """Return the cached or freshly-ranked search results for the
    current query. Cache key is (query, last_update_ts) so a new
    inventory snapshot from lua also invalidates."""
    global inventory_search_results, inventory_search_results_key
    cache_key = (inventory_search_query, inventory_last_update_ts)
    if inventory_search_results_key != cache_key:
        inventory_search_results = _inventory_rank_matches(inventory_search_query)
        inventory_search_results_key = cache_key
    return inventory_search_results


def draw_inventory_dropdown(surface):
    """Render the inventory dropdown panel below the 'Inventory' button if
    inventory_dropdown_open is True. Populates inventory_dropdown_rects
    with click targets for the main click handler.

    Two views:
      - Bag-list view (inventory_active_bag is None): shows a button per
        bag with item-count. Clicking a bag enters detail view.
      - Bag-detail view (inventory_active_bag is set): shows scrollable
        list of items in that bag with a back arrow up top. Each row is
        a hyperlink to BG-Wiki and shows a ✓ if the item appears in
        gearswap_referenced_items.
    """
    global inventory_dropdown_rects
    # Globals rebound inside View A (search-box rect) and View C (slip
    # navigation back-out) must be declared at the function scope's
    # top, BEFORE any read of those names. Python's syntactic rule:
    # if a name appears in `global` anywhere in a function, it can't
    # be read earlier than that declaration. View C's entry guard
    # (`if inventory_active_slip is not None:`) is a read, so the
    # `global` for it has to live up here, not down inside the if.
    global inventory_active_slip
    global inventory_show_slip_list
    global inventory_search_box_rect, inventory_search_scroll
    inventory_dropdown_rects = []
    if not inventory_dropdown_open:
        return
    if not inventory_button_rect:
        return

    # Layout: anchor below the Inventory button. Width fixed, height
    # bounded; we'll scroll if we overflow.
    geom = _inventory_panel_geometry()
    if not geom:
        return
    panel_x, panel_y, panel_w, panel_h = geom

    pygame.draw.rect(surface, (28, 28, 36),
                     (panel_x, panel_y, panel_w, panel_h),
                     border_radius=4)
    pygame.draw.rect(surface, (140, 140, 160),
                     (panel_x, panel_y, panel_w, panel_h), 1,
                     border_radius=4)

    pad        = 8
    row_h      = 18
    title_font = pygame.font.SysFont("Consolas", 12, bold=True)
    label_font = pygame.font.SysFont("Consolas", 11)
    small_font = pygame.font.SysFont("Consolas", 10, italic=True)

    cy = panel_y + pad

    # ── View C: slip detail (drill-in from Porter Slips section) ────────
    # Highest priority — when the user clicked a slip in the bag-list,
    # this branch renders its contents instead of either View A or B.
    # Mirrors View B's layout closely (back arrow, title, scrollable
    # list of items as BG-Wiki hyperlinks) but reads from
    # inventory_slip_state instead of inventory_state.
    if inventory_active_slip is not None:
        slip_id = inventory_active_slip
        slip = inventory_slip_state.get(slip_id)
        if slip is None:
            # Slip no longer in the snapshot (e.g. player sold it
            # between clicks). Fall back to bag list.
            inventory_active_slip = None
            return
        slip_items = list(slip.get("items") or [])
        slip_items.sort(key=lambda it: (it.get("name") or "").lower())
        default_name = slip.get("name") or f"Slip #{slip_id}"
        slip_nicks = _porter_slip_nicknames_for_player()
        nick = slip_nicks.get(slip_id, "").strip()
        title_text = nick if nick else default_name

        # Header: back button + slip name + count. Mirrors View B.
        back_w = 28
        back_rect = pygame.Rect(panel_x + 2, cy, back_w, row_h)
        if back_rect.collidepoint(pygame.mouse.get_pos()):
            pygame.draw.rect(surface, (40, 40, 52), back_rect)
        back_surf = title_font.render("‹", True, (220, 220, 230))
        if back_surf.get_width() < 4:
            back_surf = title_font.render("<", True, (220, 220, 230))
        surface.blit(back_surf,
            (back_rect.x + (back_w - back_surf.get_width()) // 2,
             back_rect.y + (row_h - back_surf.get_height()) // 2))
        inventory_dropdown_rects.append((back_rect, {"kind": "back_slip"}))

        title_surf = title_font.render(
            f"{title_text}  ({len(slip_items)} items)",
            True, (220, 200, 150))
        surface.blit(title_surf,
            (panel_x + back_w + 6,
             cy + (row_h - title_surf.get_height()) // 2))
        cy += row_h
        # When a nickname is showing, append the default name as a
        # dim subline so the user still knows which slip this is.
        if nick:
            sub = small_font.render(default_name, True, COL_LABEL_DIM)
            surface.blit(sub, (panel_x + back_w + 6, cy))
            cy += sub.get_height() + 2
        else:
            cy += 4

        # Scrollable item list. Reuse the per-bag scroll dict but key
        # it on a synthetic bag name so the slip's scroll position
        # doesn't clobber a real bag's. Per-frame storage; not
        # persisted, which is fine since the dropdown closes often.
        slip_scroll_key = f"__slip__{slip_id}"
        list_top    = cy
        list_bottom = panel_y + panel_h - pad
        available_rows = max(1, (list_bottom - list_top) // row_h)
        scroll = inventory_bag_scroll.get(slip_scroll_key, 0)
        max_scroll = max(0, len(slip_items) - available_rows)
        scroll = max(0, min(scroll, max_scroll))
        inventory_bag_scroll[slip_scroll_key] = scroll

        if not slip_items:
            ph = small_font.render("(no items stored on this slip)",
                                   True, COL_LABEL_DIM)
            surface.blit(ph, (panel_x + pad, cy + 2))
            return

        visible = slip_items[scroll:scroll + available_rows]
        for it in visible:
            nm = it.get("name", "") or f"#{it.get('id', 0)}"
            row_rect = pygame.Rect(panel_x + 2, cy,
                                   panel_w - 4, row_h)
            is_hover = row_rect.collidepoint(pygame.mouse.get_pos())
            if is_hover:
                pygame.draw.rect(surface, (40, 40, 52), row_rect)

            # Check mark column (left): ✓ if referenced in gearswap.
            # Matches the bag-detail view's visual language.
            if _item_in_gearswap(nm):
                ck = label_font.render("✓", True, (140, 200, 140))
                if ck.get_width() < 3:
                    ck = label_font.render("*", True, (140, 200, 140))
                surface.blit(ck,
                    (panel_x + pad,
                     cy + (row_h - ck.get_height()) // 2))

            # Item name. Truncated if it overflows the row.
            name_x = panel_x + pad + 18
            name_max_w = panel_w - (name_x - panel_x) - pad - 4
            name_color = ((140, 220, 255) if is_hover
                          else (220, 220, 230))
            name_surf = label_font.render(nm, True, name_color)
            if name_surf.get_width() > name_max_w:
                # Binary-search for the longest fitting prefix.
                lo, hi = 1, len(nm)
                while lo < hi:
                    mid = (lo + hi + 1) // 2
                    trial = nm[:mid] + "…"
                    if label_font.size(trial)[0] <= name_max_w:
                        lo = mid
                    else:
                        hi = mid - 1
                nm_disp = nm[:lo] + "…"
                name_surf = label_font.render(nm_disp,
                                              True, name_color)
            name_y = cy + (row_h - name_surf.get_height()) // 2
            surface.blit(name_surf, (name_x, name_y))
            if is_hover:
                pygame.draw.line(surface, name_color,
                    (name_x, name_y + name_surf.get_height() - 1),
                    (name_x + name_surf.get_width(),
                     name_y + name_surf.get_height() - 1))

            inventory_dropdown_rects.append((row_rect, {
                "kind": "open_item_url",
                "url":  _bgwiki_item_url(nm),
            }))
            cy += row_h

        # Scroll buttons (top-right) when overflow. Same shape as
        # the bag-detail view. We bind the same "scroll" kind but
        # with the slip_scroll_key so the click handler routes it
        # to inventory_bag_scroll[slip_scroll_key].
        if max_scroll > 0:
            up_rect = pygame.Rect(panel_x + panel_w - 44,
                                  panel_y + 4, 18, 18)
            dn_rect = pygame.Rect(panel_x + panel_w - 22,
                                  panel_y + 4, 18, 18)
            for r, label in ((up_rect, "▲"), (dn_rect, "▼")):
                pygame.draw.rect(surface, (60, 60, 75), r,
                                 border_radius=2)
                ts = label_font.render(label, True, (220, 220, 230))
                if ts.get_width() < 4:
                    ts = label_font.render(
                        "^" if label == "▲" else "v",
                        True, (220, 220, 230))
                surface.blit(ts,
                    (r.x + (r.w - ts.get_width()) // 2,
                     r.y + (r.h - ts.get_height()) // 2))
            inventory_dropdown_rects.append((up_rect, {
                "kind": "scroll", "bag": slip_scroll_key, "delta": -1,
            }))
            inventory_dropdown_rects.append((dn_rect, {
                "kind": "scroll", "bag": slip_scroll_key, "delta": 1,
            }))
        return

    # ── View D: porter-slip LIST (middle level) ─────────────────────────
    # Reached when the user clicked the "Porter Slips" entry in the
    # bag-list view. Shows one row per slip the player owns; click a
    # slip to drill into View C (its contents). Back arrow returns to
    # the bag-list. Mirrors View B's header layout (back + title).
    if inventory_show_slip_list:
        # Header.
        back_w = 28
        back_rect = pygame.Rect(panel_x + 2, cy, back_w, row_h)
        if back_rect.collidepoint(pygame.mouse.get_pos()):
            pygame.draw.rect(surface, (40, 40, 52), back_rect)
        back_surf = title_font.render("‹", True, (220, 220, 230))
        if back_surf.get_width() < 4:
            back_surf = title_font.render("<", True, (220, 220, 230))
        surface.blit(back_surf,
            (back_rect.x + (back_w - back_surf.get_width()) // 2,
             back_rect.y + (row_h - back_surf.get_height()) // 2))
        inventory_dropdown_rects.append((back_rect,
                                          {"kind": "back_slip_list"}))

        slips_owned = sorted(inventory_slip_state.keys())
        title_surf = title_font.render(
            f"Porter Slips  ({len(slips_owned)} slips)",
            True, (220, 200, 150))
        surface.blit(title_surf,
            (panel_x + back_w + 6,
             cy + (row_h - title_surf.get_height()) // 2))
        cy += row_h + 4

        if not slips_owned:
            ph = small_font.render("(no porter slips in inventory)",
                                   True, COL_LABEL_DIM)
            surface.blit(ph, (panel_x + pad, cy + 2))
            return

        # Per-slip rows. Reuses the nickname display logic from the
        # earlier inline-section build: nickname (bright) + dim
        # default-name suffix when set, else default name only.
        slip_nicks = _porter_slip_nicknames_for_player()
        for slip_id in slips_owned:
            slip = inventory_slip_state.get(slip_id) or {}
            default_name = slip.get("name") or f"Slip #{slip_id}"
            stored_items = slip.get("items") or []
            row_rect = pygame.Rect(panel_x + 2, cy,
                                   panel_w - 4, row_h)
            if row_rect.collidepoint(pygame.mouse.get_pos()):
                pygame.draw.rect(surface, (40, 40, 52), row_rect)

            nick = slip_nicks.get(slip_id, "").strip()
            count_str = f"{len(stored_items):>3}"
            count_surf = label_font.render(
                count_str, True, COL_LABEL_DIM)
            label_max_x = (panel_x + panel_w
                           - count_surf.get_width() - pad - 4)
            label_x = panel_x + pad

            if nick:
                nick_surf = label_font.render(
                    nick, True, (220, 220, 230))
                suffix_text = f"  ({default_name})"
                suffix_surf = small_font.render(
                    suffix_text, True, COL_LABEL_DIM)
                avail = label_max_x - label_x
                if (nick_surf.get_width()
                        + suffix_surf.get_width() > avail):
                    if nick_surf.get_width() + 20 <= avail:
                        budget = avail - nick_surf.get_width()
                        trimmed = suffix_text
                        while (suffix_surf.get_width() > budget
                               and len(trimmed) > 4):
                            trimmed = trimmed[:-2] + "…"
                            suffix_surf = small_font.render(
                                trimmed, True, COL_LABEL_DIM)
                    else:
                        trimmed = nick
                        while (nick_surf.get_width() > avail
                               and len(trimmed) > 4):
                            trimmed = trimmed[:-2] + "…"
                            nick_surf = label_font.render(
                                trimmed, True, (220, 220, 230))
                        suffix_surf = None
                surface.blit(nick_surf,
                    (label_x,
                     cy + (row_h - nick_surf.get_height()) // 2))
                if suffix_surf is not None:
                    surface.blit(suffix_surf,
                        (label_x + nick_surf.get_width(),
                         cy + (row_h - suffix_surf.get_height()) // 2))
            else:
                label_surf = label_font.render(
                    default_name, True, (220, 220, 230))
                if label_x + label_surf.get_width() > label_max_x:
                    trimmed = default_name
                    while (label_surf.get_width()
                            > label_max_x - label_x
                            and len(trimmed) > 4):
                        trimmed = trimmed[:-2] + "…"
                        label_surf = label_font.render(
                            trimmed, True, (220, 220, 230))
                surface.blit(label_surf,
                    (label_x,
                     cy + (row_h - label_surf.get_height()) // 2))

            surface.blit(count_surf,
                (panel_x + panel_w - count_surf.get_width() - pad,
                 cy + (row_h - count_surf.get_height()) // 2))

            # Same hit-test shape as the old inline section so the
            # dispatch code path didn't have to fork. Right-click on
            # this row still opens the nickname editor.
            inventory_dropdown_rects.append((row_rect, {
                "kind":         "open_slip",
                "slip_id":      slip_id,
                "default_name": default_name,
            }))
            cy += row_h
        return

    # ── View A: bag list (or search results when query is set) ─────────
    if inventory_active_bag is None:
        # Header line: total items + freshness.
        total_items = sum(len(inventory_state.get(b, []))
                          for b, _ in INVENTORY_BAG_ORDER)
        if inventory_last_update_ts > 0:
            age_s = int(time.time() - inventory_last_update_ts)
            hdr_text = f"Inventory  ({total_items} items, {age_s}s ago)"
        else:
            hdr_text = "Inventory  (waiting for lua…)"
        hdr_surf = title_font.render(hdr_text, True, (220, 200, 150))
        surface.blit(hdr_surf, (panel_x + pad, cy))
        cy += hdr_surf.get_height() + 4

        # Search box: always present at the top of the bag-list view.
        # Click to focus, type to filter, Escape to clear. When the
        # query is non-empty the result list takes over the rest of
        # the panel and the bag list is hidden.
        search_h = row_h + 4
        search_rect = pygame.Rect(panel_x + pad, cy,
                                   panel_w - pad * 2, search_h)
        inventory_search_box_rect = search_rect
        # Background + border (border tint depends on focus).
        border_color = ((180, 200, 240) if inventory_search_focused
                        else (90, 90, 110))
        pygame.draw.rect(surface, (20, 22, 28), search_rect, border_radius=3)
        pygame.draw.rect(surface, border_color, search_rect, 1, border_radius=3)
        # Magnifying-glass icon (text fallback if font lacks the glyph)
        # then the query text or a dim placeholder.
        icon_surf = label_font.render("⌕", True, (170, 180, 200))
        if icon_surf.get_width() < 4:
            icon_surf = label_font.render("?", True, (170, 180, 200))
        surface.blit(icon_surf,
            (search_rect.x + 6,
             search_rect.y + (search_h - icon_surf.get_height()) // 2))
        text_left = search_rect.x + 6 + icon_surf.get_width() + 4
        if inventory_search_query:
            q_surf = label_font.render(inventory_search_query, True,
                                       (230, 230, 240))
            surface.blit(q_surf,
                (text_left,
                 search_rect.y + (search_h - q_surf.get_height()) // 2))
            # Caret on focus.
            if inventory_search_focused and (int(time.time() * 2) % 2) == 0:
                cx = text_left + q_surf.get_width() + 1
                pygame.draw.line(surface, (220, 220, 230),
                    (cx, search_rect.y + 3),
                    (cx, search_rect.y + search_h - 3), 1)
            # Clear-X at the right edge.
            clear_w = 16
            clear_rect = pygame.Rect(search_rect.right - clear_w - 2,
                                      search_rect.y + 2,
                                      clear_w, search_h - 4)
            clear_surf = label_font.render("×", True, (180, 180, 200))
            surface.blit(clear_surf,
                (clear_rect.x + (clear_w - clear_surf.get_width()) // 2,
                 clear_rect.y + (clear_rect.h - clear_surf.get_height()) // 2))
            inventory_dropdown_rects.append((clear_rect,
                {"kind": "search_clear"}))
        else:
            placeholder = "Search all bags…"
            ph_surf = small_font.render(placeholder, True, COL_LABEL_DIM)
            surface.blit(ph_surf,
                (text_left,
                 search_rect.y + (search_h - ph_surf.get_height()) // 2))
            if inventory_search_focused and (int(time.time() * 2) % 2) == 0:
                pygame.draw.line(surface, (220, 220, 230),
                    (text_left, search_rect.y + 3),
                    (text_left, search_rect.y + search_h - 3), 1)
        # The search box itself is a click-target (focus).
        inventory_dropdown_rects.append((search_rect,
            {"kind": "search_focus"}))
        cy += search_h + 4

        # ── Results view (query non-empty): replaces bag list ─────────
        if inventory_search_query.strip():
            results = _inventory_get_search_results()
            # Header showing match count.
            res_hdr = f"{len(results)} match{'' if len(results) == 1 else 'es'}"
            res_hdr_surf = small_font.render(res_hdr, True, COL_LABEL_DIM)
            surface.blit(res_hdr_surf, (panel_x + pad, cy))
            cy += res_hdr_surf.get_height() + 2

            # Scrollable result list.
            list_top    = cy
            list_bottom = panel_y + panel_h - pad
            available_rows = max(1, (list_bottom - list_top) // row_h)
            max_scroll = max(0, len(results) - available_rows)
            inventory_search_scroll = max(0, min(inventory_search_scroll,
                                                  max_scroll))

            if not results:
                ph = small_font.render("(no matches)", True, COL_LABEL_DIM)
                surface.blit(ph, (panel_x + pad, cy + 2))
                return

            visible = results[inventory_search_scroll
                              :inventory_search_scroll + available_rows]
            for bag_key, it, _score in visible:
                nm  = it.get("name", "") or f"#{it.get('id', 0)}"
                cnt = it.get("count", 1)
                row_rect = pygame.Rect(panel_x + 2, cy,
                                       panel_w - 4, row_h)
                is_hover = row_rect.collidepoint(pygame.mouse.get_pos())
                if is_hover:
                    pygame.draw.rect(surface, (40, 40, 52), row_rect)

                # Check mark (left): ✓ if referenced in gearswap.
                check_w = 14
                if _item_in_gearswap(nm):
                    ck = label_font.render("✓", True, (140, 200, 140))
                    if ck.get_width() < 3:
                        ck = label_font.render("*", True, (140, 200, 140))
                    surface.blit(ck,
                        (panel_x + pad,
                         cy + (row_h - ck.get_height()) // 2))

                # Bag tag (right edge): which bag this item is in.
                # Compact label, dim color so the eye sees item names
                # first and the location as secondary info.
                bag_tag = _inventory_bag_label(bag_key)
                # Truncate long bag names for the tag column.
                if len(bag_tag) > 12:
                    bag_tag = bag_tag[:11] + "…"
                tag_surf = small_font.render(bag_tag, True, (170, 160, 200))
                tag_x = panel_x + panel_w - tag_surf.get_width() - pad

                # Count column (just left of the bag tag, when >1).
                cnt_x = tag_x
                if cnt > 1:
                    cnt_surf = label_font.render(f"x{cnt}",
                                                  True, COL_LABEL_DIM)
                    cnt_x = (tag_x - cnt_surf.get_width() - 6)
                    surface.blit(cnt_surf,
                        (cnt_x,
                         cy + (row_h - cnt_surf.get_height()) // 2))

                # Name (link blue). Truncate if it would overlap the
                # count/tag columns — measure-then-trim approach.
                name_color = (130, 180, 230)
                name_x = panel_x + pad + check_w
                name_max_w = cnt_x - name_x - 6
                name_text = nm
                name_surf = label_font.render(name_text, True, name_color)
                if name_surf.get_width() > name_max_w and name_max_w > 16:
                    # Binary trim to fit.
                    lo, hi = 1, len(name_text)
                    while lo < hi:
                        mid = (lo + hi + 1) // 2
                        trial = name_text[:mid] + "…"
                        if label_font.size(trial)[0] <= name_max_w:
                            lo = mid
                        else:
                            hi = mid - 1
                    name_text = name_text[:lo] + "…"
                    name_surf = label_font.render(name_text,
                                                   True, name_color)
                name_y = cy + (row_h - name_surf.get_height()) // 2
                surface.blit(name_surf, (name_x, name_y))
                if is_hover:
                    pygame.draw.line(surface, name_color,
                        (name_x, name_y + name_surf.get_height() - 1),
                        (name_x + name_surf.get_width(),
                         name_y + name_surf.get_height() - 1))

                # Bag tag last so it sits on top.
                surface.blit(tag_surf,
                    (tag_x,
                     cy + (row_h - tag_surf.get_height()) // 2))

                inventory_dropdown_rects.append((row_rect, {
                    "kind": "open_item_url",
                    "url":  _bgwiki_item_url(nm),
                    # Item identity for the right-click menu. bag_key is
                    # this result's actual bag, so the menu can decide
                    # whether a one-shot drop is possible (inventory only).
                    "item_id":    it.get("id", 0),
                    "item_name":  it.get("name", "") or nm,
                    "item_count": cnt,
                    "bag":        bag_key,
                }))
                cy += row_h

            # Scroll buttons when overflow.
            if max_scroll > 0:
                up_rect = pygame.Rect(panel_x + panel_w - 44,
                                      panel_y + 4, 18, 18)
                dn_rect = pygame.Rect(panel_x + panel_w - 22,
                                      panel_y + 4, 18, 18)
                for r, lbl in ((up_rect, "▲"), (dn_rect, "▼")):
                    pygame.draw.rect(surface, (60, 60, 75), r,
                                     border_radius=2)
                    ts = label_font.render(lbl, True, (220, 220, 230))
                    if ts.get_width() < 4:
                        ts = label_font.render(
                            "^" if lbl == "▲" else "v",
                            True, (220, 220, 230))
                    surface.blit(ts,
                        (r.x + (r.w - ts.get_width()) // 2,
                         r.y + (r.h - ts.get_height()) // 2))
                inventory_dropdown_rects.append((up_rect, {
                    "kind": "search_scroll", "delta": -1,
                }))
                inventory_dropdown_rects.append((dn_rect, {
                    "kind": "search_scroll", "delta": 1,
                }))
            return

        # Render one row per known bag with item count.
        for bag_key, bag_label in INVENTORY_BAG_ORDER:
            row_rect = pygame.Rect(panel_x + 2, cy,
                                   panel_w - 4, row_h)
            if row_rect.collidepoint(pygame.mouse.get_pos()):
                pygame.draw.rect(surface, (40, 40, 52), row_rect)
            items_here = inventory_state.get(bag_key, [])
            count_str  = f"{len(items_here):>3}"
            label_surf = label_font.render(bag_label, True, (220, 220, 230))
            count_surf = label_font.render(count_str, True, COL_LABEL_DIM)
            surface.blit(label_surf,
                (panel_x + pad,
                 cy + (row_h - label_surf.get_height()) // 2))
            surface.blit(count_surf,
                (panel_x + panel_w - count_surf.get_width() - pad,
                 cy + (row_h - count_surf.get_height()) // 2))
            # Empty bags get a dim row but still hover/click — the
            # detail view will show a "no items" placeholder.
            inventory_dropdown_rects.append((row_rect, {
                "kind": "open_bag", "bag": bag_key,
            }))
            cy += row_h

        # ── Porter Slips entry row ──────────────────────────────────
        # Single bag-style row showing how many slips the player owns.
        # Clicking enters View D (the slip-list) — same drill-in
        # pattern as clicking a bag enters View B. We DON'T enumerate
        # individual slips here so the bag-list view stays tidy and
        # consistent with the wardrobe/safe rows above it.
        #
        # Always shown, even when the player owns zero slips, so the
        # entry is a stable navigation landmark rather than something
        # that pops in and out of the bag list as you trade slips
        # around. The count column reflects current ownership; the
        # sub-view (View D) shows actual slip rows only for slips
        # in inventory.
        row_rect = pygame.Rect(panel_x + 2, cy,
                               panel_w - 4, row_h)
        if row_rect.collidepoint(pygame.mouse.get_pos()):
            pygame.draw.rect(surface, (40, 40, 52), row_rect)
        label_surf = label_font.render(
            "Porter Slips", True, (220, 220, 230))
        count_str  = f"{len(inventory_slip_state):>3}"
        count_surf = label_font.render(
            count_str, True, COL_LABEL_DIM)
        surface.blit(label_surf,
            (panel_x + pad,
             cy + (row_h - label_surf.get_height()) // 2))
        surface.blit(count_surf,
            (panel_x + panel_w - count_surf.get_width() - pad,
             cy + (row_h - count_surf.get_height()) // 2))
        # Click → enter slip-list (View D). Right-click on this
        # top-level row is intentionally a no-op (no nickname to
        # set on the Porter-Slips section itself); individual
        # slip nicknames are set from the View D row right-click.
        inventory_dropdown_rects.append((row_rect, {
            "kind": "open_slip_list",
        }))
        cy += row_h

        # Footer hint about gearswap scan status.
        cy += 4
        if gearswap_folder_path:
            hint = (f"GearSwap scan: {len(gearswap_referenced_items)} "
                    f"items referenced")
        else:
            hint = "GearSwap scan off — set folder in Settings → Inventory"
        hint_surf = small_font.render(hint, True, COL_LABEL_DIM)
        surface.blit(hint_surf, (panel_x + pad, cy))
        return

    # ── View B: bag detail ──────────────────────────────────────────────
    bag_key   = inventory_active_bag
    bag_label = next((lbl for k, lbl in INVENTORY_BAG_ORDER if k == bag_key),
                     bag_key)
    items     = list(inventory_state.get(bag_key, []))
    # Sort alphabetically by name for predictable scanning.
    items.sort(key=lambda it: (it.get("name") or "").lower())

    # Header: back button + bag name + count.
    back_w = 28
    back_rect = pygame.Rect(panel_x + 2, cy, back_w, row_h)
    if back_rect.collidepoint(pygame.mouse.get_pos()):
        pygame.draw.rect(surface, (40, 40, 52), back_rect)
    back_surf = title_font.render("‹", True, (220, 220, 230))
    if back_surf.get_width() < 4:
        back_surf = title_font.render("<", True, (220, 220, 230))
    surface.blit(back_surf,
        (back_rect.x + (back_w - back_surf.get_width()) // 2,
         back_rect.y + (row_h - back_surf.get_height()) // 2))
    inventory_dropdown_rects.append((back_rect, {"kind": "back"}))

    title_surf = title_font.render(
        f"{bag_label}  ({len(items)} items)",
        True, (220, 200, 150))
    surface.blit(title_surf,
        (panel_x + back_w + 6, cy + (row_h - title_surf.get_height()) // 2))
    cy += row_h + 4

    # Scrollable item list.
    list_top    = cy
    list_bottom = panel_y + panel_h - pad
    available_rows = max(1, (list_bottom - list_top) // row_h)
    scroll = inventory_bag_scroll.get(bag_key, 0)
    max_scroll = max(0, len(items) - available_rows)
    scroll = max(0, min(scroll, max_scroll))
    inventory_bag_scroll[bag_key] = scroll

    if not items:
        ph = small_font.render("(empty)", True, COL_LABEL_DIM)
        surface.blit(ph, (panel_x + pad, cy + 2))
        return

    visible = items[scroll:scroll + available_rows]
    for it in visible:
        nm  = it.get("name", "") or f"#{it.get('id', 0)}"
        cnt = it.get("count", 1)
        row_rect = pygame.Rect(panel_x + 2, cy,
                               panel_w - 4, row_h)
        # Hover highlight + reserve as click target.
        is_hover = row_rect.collidepoint(pygame.mouse.get_pos())
        if is_hover:
            pygame.draw.rect(surface, (40, 40, 52), row_rect)

        # Check mark column (left): ✓ if referenced in gearswap.
        check_w = 14
        if _item_in_gearswap(nm):
            ck = label_font.render("✓", True, (140, 200, 140))
            if ck.get_width() < 3:
                # Some fonts don't ship the check glyph — fall back to '*'.
                ck = label_font.render("*", True, (140, 200, 140))
            surface.blit(ck,
                (panel_x + pad,
                 cy + (row_h - ck.get_height()) // 2))

        # Name (link styling: light blue).
        name_color = (130, 180, 230)
        name_surf  = label_font.render(nm, True, name_color)
        # Underline-on-hover using a 1px line at the bottom of the
        # text — same convention as the rest of OmniWatch's hyperlinks.
        name_x = panel_x + pad + check_w
        name_y = cy + (row_h - name_surf.get_height()) // 2
        surface.blit(name_surf, (name_x, name_y))
        if is_hover:
            pygame.draw.line(surface, name_color,
                (name_x, name_y + name_surf.get_height() - 1),
                (name_x + name_surf.get_width(),
                 name_y + name_surf.get_height() - 1))

        # Count column (right). Only show when >1.
        if cnt > 1:
            cnt_surf = label_font.render(f"x{cnt}", True, COL_LABEL_DIM)
            surface.blit(cnt_surf,
                (panel_x + panel_w - cnt_surf.get_width() - pad,
                 cy + (row_h - cnt_surf.get_height()) // 2))

        inventory_dropdown_rects.append((row_rect, {
            "kind": "open_item_url",
            "url":  _bgwiki_item_url(nm),
            # Item identity for the right-click menu (drop / auto-drop).
            "item_id":    it.get("id", 0),
            "item_name":  it.get("name", "") or nm,
            "item_count": cnt,
            "bag":        bag_key,
        }))
        cy += row_h

    # Scroll buttons (top-right of panel) when we have overflow.
    if max_scroll > 0:
        up_rect = pygame.Rect(panel_x + panel_w - 44,
                              panel_y + 4, 18, 18)
        dn_rect = pygame.Rect(panel_x + panel_w - 22,
                              panel_y + 4, 18, 18)
        for r, label in ((up_rect, "▲"), (dn_rect, "▼")):
            pygame.draw.rect(surface, (60, 60, 75), r, border_radius=2)
            ts = label_font.render(label, True, (220, 220, 230))
            if ts.get_width() < 4:
                ts = label_font.render(
                    "^" if label == "▲" else "v", True, (220, 220, 230))
            surface.blit(ts,
                (r.x + (r.w - ts.get_width()) // 2,
                 r.y + (r.h - ts.get_height()) // 2))
        inventory_dropdown_rects.append((up_rect, {
            "kind": "scroll", "bag": bag_key, "delta": -1,
        }))
        inventory_dropdown_rects.append((dn_rect, {
            "kind": "scroll", "bag": bag_key, "delta": 1,
        }))


def dispatch_inventory_dropdown_click(mx, my):
    """Resolve a click against the inventory dropdown. Returns True if
    the click was consumed (hit a control rect, was inside the panel
    chrome, OR was on the Bags button itself). When True, the main
    handler should `continue` so the click doesn't fall through to
    panel drag/url handlers underneath."""
    global inventory_dropdown_open, inventory_active_bag
    global inventory_active_slip
    global inventory_show_slip_list
    global inventory_bag_scroll
    global inventory_search_query, inventory_search_focused
    global inventory_search_scroll, inventory_search_results_key

    # Always-eat the toggle button click — clicking 'Inventory' should
    # never fall through to drag.
    if inventory_button_rect and inventory_button_rect.collidepoint(mx, my):
        inventory_dropdown_open = not inventory_dropdown_open
        if not inventory_dropdown_open:
            inventory_active_bag = None    # reset to bag-list view next open
            inventory_active_slip = None
            inventory_show_slip_list = False
            inventory_search_focused = False
        return True

    if not inventory_dropdown_open:
        return False

    # Hit-test individual rects first.
    for rect, action in inventory_dropdown_rects:
        if rect.collidepoint(mx, my):
            kind = action.get("kind")
            if kind == "open_bag":
                inventory_active_bag = action["bag"]
                inventory_active_slip = None
                inventory_show_slip_list = False
                inventory_bag_scroll[action["bag"]] = 0
                inventory_search_focused = False
            elif kind == "open_slip_list":
                # Enter the middle view (one row per owned slip).
                # Click came from the bag-list view's "Porter Slips"
                # row. Reset bag/slip detail state so the
                # View-priority chain resolves to View D.
                inventory_show_slip_list = True
                inventory_active_bag = None
                inventory_active_slip = None
                inventory_search_focused = False
            elif kind == "open_slip":
                # Drill into a porter slip's contents (deepest view).
                # Came from View D (slip-list). We KEEP
                # inventory_show_slip_list True so back-arrow from
                # the detail returns here, not all the way to the
                # bag-list — matches the "back goes one level up"
                # behavior the user asked for.
                inventory_active_slip = action["slip_id"]
                inventory_active_bag = None
                inventory_search_focused = False
            elif kind == "back":
                # Back from bag-detail (View B) → bag-list (View A).
                inventory_active_bag = None
                inventory_search_focused = False
            elif kind == "back_slip":
                # Back from slip-detail (View C). Returns to the
                # slip-list (View D), NOT the bag-list — one level
                # up. inventory_show_slip_list stays True from the
                # earlier open_slip_list; we only clear active_slip.
                inventory_active_slip = None
                inventory_search_focused = False
            elif kind == "back_slip_list":
                # Back from slip-list (View D) → bag-list (View A).
                inventory_show_slip_list = False
                inventory_search_focused = False
            elif kind == "scroll":
                # Used for both bag-detail and slip-detail scroll.
                # action["bag"] holds either a real bag key OR a
                # synthetic "__slip__<id>" key — both route through
                # the same inventory_bag_scroll dict.
                bag = action["bag"]
                cur = inventory_bag_scroll.get(bag, 0)
                inventory_bag_scroll[bag] = max(0, cur + action["delta"])
            elif kind == "open_item_url":
                url = action.get("url", "")
                if url:
                    open_url(url)
            elif kind == "search_focus":
                inventory_search_focused = True
            elif kind == "search_clear":
                inventory_search_query = ""
                inventory_search_scroll = 0
                inventory_search_results_key = None
                # Keep focus so the user can immediately type a new
                # query without a second click.
                inventory_search_focused = True
            elif kind == "search_scroll":
                inventory_search_scroll = max(
                    0, inventory_search_scroll + action["delta"])
            return True

    # Click anywhere inside the panel envelope — eat it so the click
    # doesn't reach drag or url handlers underneath. Use the same
    # geometry the renderer used.
    if inventory_button_rect:
        geom = _inventory_panel_geometry()
        if geom:
            env = pygame.Rect(*geom)
            if env.collidepoint(mx, my):
                return True

    # Click outside panel + outside button = close the dropdown.
    inventory_dropdown_open = False
    inventory_active_bag = None
    inventory_active_slip = None
    inventory_show_slip_list = False
    inventory_search_focused = False
    return False


def dispatch_inventory_dropdown_right_click(mx, my):
    """Right-click dispatcher for the inventory dropdown.

    Two cases:
      * Right-clicking a porter slip row (bag-list view) opens the
        nickname editor modal for that slip.
      * Right-clicking an item row (bag-detail or search results)
        opens the item context menu (drop / auto-drop).
    All other right-clicks (anywhere else in the panel, or when the
    panel is closed) return False so the click can fall through to
    other handlers.

    Returns True if the right-click was consumed.
    """
    global inventory_slip_nickname_editor
    global inventory_item_ctx_menu
    if not inventory_dropdown_open:
        return False
    for rect, action in inventory_dropdown_rects:
        if not rect.collidepoint(mx, my):
            continue
        kind = action.get("kind")
        if kind == "open_slip":
            # Open the editor pre-filled with the current nickname (or
            # empty if none set). The default name is shown as the
            # placeholder/hint in the modal.
            slip_id = action["slip_id"]
            default_name = action.get("default_name") or f"Slip #{slip_id}"
            slip_nicks = _porter_slip_nicknames_for_player()
            current_nick = slip_nicks.get(slip_id, "")
            inventory_slip_nickname_editor = {
                "slip_id":      slip_id,
                "default_name": default_name,
                "text":         current_nick,
                "cursor":       len(current_nick),
                "cursor_blink": time.time(),
            }
            return True
        if kind == "open_item_url" and action.get("item_id"):
            # Open the drop / auto-drop context menu anchored at the
            # click point. Snapshots the item identity so a later
            # re-render of the dropdown rects can't change what the
            # menu acts on.
            inventory_item_ctx_menu = {
                "x":          mx,
                "y":          my,
                "item_id":    action.get("item_id", 0),
                "item_name":  action.get("item_name", "") or "?",
                "item_count": action.get("item_count", 1),
                "bag":        action.get("bag", ""),
            }
            return True
    return False


def draw_inventory_slip_nickname_editor(surface):
    """Render the porter-slip nickname editor modal if open.

    A small centered modal anchored to the inventory dropdown panel
    (NOT the whole screen — keeps the editor visually connected to
    what the user right-clicked). Title shows the default slip name
    so the user knows which slip they're editing. Single-line text
    input below; Enter to save, Esc to cancel, empty string clears
    the nickname. Mirrors the sim_nickname_editor style for visual
    consistency.

    State lives in inventory_slip_nickname_editor (or None when not
    open). The text input event handler in the KEYDOWN dispatcher
    reads/writes that state; this function just renders it.

    No-op when state is None.
    """
    if inventory_slip_nickname_editor is None:
        return
    ed = inventory_slip_nickname_editor
    geom = _inventory_panel_geometry()
    if not geom:
        return
    panel_x, panel_y, panel_w, panel_h = geom

    # Modal: centered over the dropdown panel, slightly narrower so
    # the panel chrome shows around the edges (signals modality).
    ep_w = max(260, panel_w - 24)
    ep_h = 110
    ep_x = panel_x + (panel_w - ep_w) // 2
    ep_y = panel_y + (panel_h - ep_h) // 2

    # Backdrop dim over the dropdown panel only (not the whole
    # screen — the dropdown is itself a popover, dimming the rest
    # of OmniWatch would be visually confusing).
    backdrop = pygame.Surface((panel_w, panel_h), pygame.SRCALPHA)
    backdrop.fill((0, 0, 0, 160))
    surface.blit(backdrop, (panel_x, panel_y))

    # Modal panel
    pygame.draw.rect(surface, (32, 32, 42),
                     (ep_x, ep_y, ep_w, ep_h), border_radius=6)
    pygame.draw.rect(surface, (90, 100, 130),
                     (ep_x, ep_y, ep_w, ep_h), 1, border_radius=6)

    # Fonts — match the dropdown's font choices.
    title_font  = pygame.font.SysFont("Consolas", 12, bold=True)
    label_font  = pygame.font.SysFont("Consolas", 11)
    small_font  = pygame.font.SysFont("Consolas", 10, italic=True)

    # Title: which slip is being renamed.
    default_name = ed.get("default_name") or "?"
    title_text = f"Rename: {default_name}"
    t_surf = title_font.render(title_text, True, (220, 200, 150))
    surface.blit(t_surf, (ep_x + 10, ep_y + 8))

    # Hint line below title.
    hint = "Enter to save · Esc to cancel · empty clears"
    h_surf = small_font.render(hint, True, (140, 145, 155))
    surface.blit(h_surf, (ep_x + 10, ep_y + 28))

    # Input box.
    box = pygame.Rect(ep_x + 10, ep_y + 52, ep_w - 20, 28)
    pygame.draw.rect(surface, (20, 20, 28), box, border_radius=3)
    pygame.draw.rect(surface, (110, 130, 170), box, 1, border_radius=3)

    # Text + blinking cursor. Cursor toggles ~every 530ms.
    txt = ed.get("text", "")
    show_cursor = (
        int((time.time() - ed.get("cursor_blink", 0)) * 1.9) % 2 == 0)
    rendered = txt + ("|" if show_cursor else "")
    i_surf = label_font.render(rendered, True, (230, 230, 240))
    surface.blit(i_surf, (box.x + 6,
                          box.y + (box.height - i_surf.get_height()) // 2))


def draw_inventory_item_ctx_menu(surface):
    """Render the inventory item right-click menu when one is open.

    A small popup at the click point with the item name as a dim,
    non-clickable header and one or two clickable actions below it.
    Mirrors draw_cheatsheet_ctx_menu so a destructive drop is always a
    deliberate two-step (right-click → click the action). Records each
    action's rect in inventory_item_ctx_rects for the click dispatcher.

    "Drop item" is only offered when the item is in the main inventory
    bag — you can't drop from storage/wardrobe/etc. without moving the
    item to inventory first. "Auto-drop (Treasury)" is always offered;
    it adds to Treasury's per-character Drop list by name, which works
    regardless of which bag the item is currently in.
    """
    global inventory_item_ctx_rects
    inventory_item_ctx_rects = []
    if inventory_item_ctx_menu is None or not inventory_dropdown_open:
        return
    m = inventory_item_ctx_menu

    title_font = pygame.font.SysFont("Consolas", 11, bold=True)
    item_font  = pygame.font.SysFont("Consolas", 11)

    # Build the action list. Each entry: (action_str, label, color).
    actions = []
    if m.get("bag") == "inventory":
        actions.append(("drop", "Drop item", (235, 170, 170)))
    actions.append(("autodrop", "Auto-drop (Treasury)", (235, 205, 150)))

    # Header: item name (+ count when >1), truncated to keep it tidy.
    cnt = m.get("item_count", 1) or 1
    head = m.get("item_name", "?") or "?"
    if cnt > 1:
        head = f"{head} x{cnt}"
    if len(head) > 34:
        head = head[:33] + "…"

    pad    = 8
    line_h = item_font.get_height() + 6
    # Width fits the header and the widest action label.
    w = title_font.size(head)[0]
    for _a, lbl, _c in actions:
        w = max(w, item_font.size(lbl)[0])
    w += pad * 2
    h = line_h * (len(actions) + 1) + pad

    sw, shh = surface.get_size()
    mx0 = max(0, min(int(m["x"]), sw - w))
    my0 = max(0, min(int(m["y"]), shh - h))

    pygame.draw.rect(surface, (28, 28, 36), (mx0, my0, w, h), border_radius=4)
    pygame.draw.rect(surface, COL_BORDER, (mx0, my0, w, h), 1, border_radius=4)

    # Header (dim, non-clickable).
    surface.blit(title_font.render(head, True, (150, 150, 168)),
                 (mx0 + pad, my0 + pad // 2))
    sep_y = my0 + line_h + pad // 2 - 1
    pygame.draw.line(surface, COL_BORDER,
                     (mx0 + 2, sep_y), (mx0 + w - 2, sep_y))

    # Action rows.
    row_y = my0 + line_h + pad // 2
    mxp, myp = pygame.mouse.get_pos()
    for action_str, label, color in actions:
        item_rect = pygame.Rect(mx0 + 2, row_y, w - 4, line_h)
        if item_rect.collidepoint(mxp, myp):
            # Drop hovers red-ish (destructive), auto-drop neutral.
            hov_bg = (90, 48, 48) if action_str == "drop" else (52, 52, 66)
            pygame.draw.rect(surface, hov_bg, item_rect, border_radius=3)
        surface.blit(item_font.render(label, True, color),
                     (mx0 + pad,
                      row_y + (line_h - item_font.get_height()) // 2))
        inventory_item_ctx_rects.append((item_rect, action_str))
        row_y += line_h


# ── Simulation window ───────────────────────────────────────────────────────
# Floating, draggable. Shown only when sim_window_open is true (set by
# the sim_mode setting). Drives sim_state and pushes each change to lua
# over UDP. Per-frame: render + populate sim_window_rects with click
# targets the dispatch handler consumes.

# Module-level rect lists. Cleared and refilled each frame in draw_sim_window.
sim_window_rects     = []   # list of (pygame.Rect, action_dict)
sim_window_titlebar_rect = None   # for drag-handle hit-test
sim_window_resize_rect   = None   # for resize-grip hit-test

SIM_WIN_W       = 280
SIM_WIN_PAD     = 10
SIM_WIN_ROW_H   = 22
SIM_WIN_HDR_H   = 26
SIM_WIN_BG      = (24, 24, 32)
SIM_WIN_BORDER  = (140, 140, 160)
SIM_WIN_TITLE   = (200, 200, 220)
SIM_WIN_LABEL   = (180, 180, 195)
SIM_WIN_VALUE   = (220, 220, 240)
SIM_WIN_BTN_BG  = (50, 50, 62)
SIM_WIN_BTN_HOV = (70, 70, 84)
SIM_WIN_DIM     = (110, 110, 125)


def _sim_compute_height():
    """Return the natural height of the sim window for the current state.
    Recomputed each frame because dropdown lengths depend on state.
    """
    h = SIM_WIN_HDR_H + SIM_WIN_PAD
    # HP / MP block: header + 1 row.
    h += SIM_WIN_ROW_H            # "HP / MP" header
    h += SIM_WIN_ROW_H            # the HP/MP pair row
    h += 4
    # Equipment section: header + 8 rows (2-column layout, 16 slots).
    # Plus expanded dropdown if a slot is active (full-width below row).
    # No item-count cap — the sim window itself is scrollable, so an
    # arbitrarily long inventory list is reachable by scrolling.
    h += SIM_WIN_ROW_H            # equipment header
    h += 8 * SIM_WIN_ROW_H        # 8 rows of 2 slots each
    if (sim_active_field
            and sim_active_field.get("kind") == "equip_slot"):
        slot = sim_active_field.get("slot", "")
        n_items = len(_sim_get_slot_options(slot))
        h += (n_items + 1) * 18   # +1 for "(empty)"
    h += 4
    # Food section: header + 1 dropdown row. If open, expanded list.
    h += SIM_WIN_ROW_H            # food header
    h += SIM_WIN_ROW_H            # food row
    if sim_active_field and sim_active_field.get("kind") == "food":
        h += min(12, len(SIM_FOOD_LIST) + 1) * 18  # +1 for "(none)"
    h += 4
    # Buffs section: header + active buffs + picker UI.
    h += SIM_WIN_ROW_H            # buffs header
    for entry in sim_state.get("active_buffs", []):
        bid = entry.get("id", "")
        # Pull catalog row to read kind + category. Category determines
        # whether the song-kind buff has a 3rd row (SV/Marcato — Songs
        # only) or is just 2 rows (name+X, plus controls).
        crow = next((c for c in SIM_BUFF_CATALOG if c[0] == bid), None)
        if crow is None:
            continue
        ckind = crow[3]
        ccat  = crow[1]
        # Row count per kind/category:
        #   Songs song (kind='song', cat='Songs'): 3 rows
        #     (name+X, plus +/-, SV/Marcato boost toggles)
        #   Geomancy indi-* (kind='song', cat='Geomancy'): 2 rows
        #     (name+X, plus +/- — no boost row applies)
        #   Rolls roll (kind='roll'): 3 rows
        #     (name+X, level/plus, C.Cards/Job-present checkboxes)
        #   Spells spell (kind='spell'): 1 row
        #     (just name+X — flat values, no controls)
        if ckind == "spell":
            h += 1 * SIM_WIN_ROW_H
        elif ckind == "song":
            h += (3 * SIM_WIN_ROW_H) if ccat == "Songs" else (2 * SIM_WIN_ROW_H)
        else:  # roll
            h += 3 * SIM_WIN_ROW_H
    # Picker UI height varies by stage.
    picker_stage = sim_buff_picker.get("stage") if sim_buff_picker else None
    if picker_stage is None:
        h += SIM_WIN_ROW_H        # add button
    elif picker_stage == "job":
        h += SIM_WIN_ROW_H        # prompt
        h += len(SIM_BUFF_JOB_LIST) * SIM_WIN_ROW_H
        h += SIM_WIN_ROW_H        # cancel
    elif picker_stage == "buff":
        h += SIM_WIN_ROW_H        # prompt
        chosen_job = sim_buff_picker.get("job", "")
        h += len(SIM_BUFF_BY_JOB.get(chosen_job, [])) * SIM_WIN_ROW_H
        h += SIM_WIN_ROW_H        # cancel
    h += 4
    # Import Set + Export Set + Reset buttons + bottom pad.
    h += SIM_WIN_ROW_H            # import
    h += SIM_WIN_ROW_H            # export
    h += SIM_WIN_ROW_H            # reset
    h += SIM_WIN_PAD
    return h


def draw_sim_window(surface):
    """Render the floating sim window (title bar, sections, buttons).
    Populates sim_window_rects with click targets the dispatcher reads.
    Skipped entirely when sim_window_open is False.

    Resizable: bottom-right corner has a grip. User can shrink below
    natural-content-height (content scrolls) or expand to leave blank
    space. Width applies linearly to the row layout.
    """
    global sim_window_rects, sim_window_titlebar_rect, sim_window_resize_rect
    global sim_window_scroll
    sim_window_rects = []
    sim_window_titlebar_rect = None
    sim_window_resize_rect = None
    if not sim_window_open:
        return

    # Window dimensions. Width comes from sim_window_size[0]; height
    # is the user-resized value if set, else natural-fit.
    nat_h = _sim_compute_height()
    ww = max(220, min(WIDTH, int(sim_window_size[0])))
    user_h = int(sim_window_size[1])
    wh = user_h if user_h > 0 else nat_h
    wh = max(SIM_WIN_HDR_H + 60, min(HEIGHT, wh))
    # If natural content is taller than rendered height, scrolling is
    # available. Clamp scroll to valid range so resizing the window
    # bigger doesn't leave us scrolled past the new bottom.
    body_h = max(0, wh - SIM_WIN_HDR_H - SIM_WIN_PAD * 2)
    overflow = max(0, nat_h - SIM_WIN_HDR_H - SIM_WIN_PAD * 2 - body_h)
    if sim_window_scroll < 0:
        sim_window_scroll = 0
    if sim_window_scroll > overflow:
        sim_window_scroll = overflow

    # Position. Clamp to screen so a previously-saved offscreen
    # position can't trap the window where it can't be reached.
    wx, wy = sim_window_pos
    wx = max(0, min(WIDTH - ww, int(wx)))
    wy = max(0, min(HEIGHT - wh, int(wy)))
    sim_window_pos[0], sim_window_pos[1] = wx, wy

    # Background + border.
    pygame.draw.rect(surface, SIM_WIN_BG, (wx, wy, ww, wh),
                     border_radius=4)
    pygame.draw.rect(surface, SIM_WIN_BORDER, (wx, wy, ww, wh), 1,
                     border_radius=4)

    # Title bar.
    title_font = pygame.font.SysFont("Consolas", 13, bold=True)
    label_font = pygame.font.SysFont("Consolas", 12)
    value_font = pygame.font.SysFont("Consolas", 12, bold=True)

    title_rect = pygame.Rect(wx, wy, ww, SIM_WIN_HDR_H)
    pygame.draw.rect(surface, (40, 40, 52), title_rect,
                     border_top_left_radius=4, border_top_right_radius=4)
    pygame.draw.line(surface, SIM_WIN_BORDER,
                     (wx, wy + SIM_WIN_HDR_H),
                     (wx + ww, wy + SIM_WIN_HDR_H))
    t_surf = title_font.render("Simulation", True, SIM_WIN_TITLE)
    surface.blit(t_surf, (wx + SIM_WIN_PAD,
                          wy + (SIM_WIN_HDR_H - t_surf.get_height()) // 2))
    # Close X — clicking it just turns sim_mode off (which closes window).
    close_size = 16
    close_rect = pygame.Rect(wx + ww - close_size - 6,
                             wy + (SIM_WIN_HDR_H - close_size) // 2,
                             close_size, close_size)
    pygame.draw.rect(surface, (90, 50, 60), close_rect, border_radius=2)
    x_surf = title_font.render("×", True, (240, 220, 220))
    surface.blit(x_surf, (close_rect.x + (close_size - x_surf.get_width()) // 2,
                          close_rect.y + (close_size - x_surf.get_height()) // 2 - 2))
    sim_window_rects.append((close_rect, {"action": "close"}))
    # Title bar (minus close button) is the drag handle.
    sim_window_titlebar_rect = pygame.Rect(
        wx, wy, ww - close_size - 12, SIM_WIN_HDR_H)

    # Clip the body region so scrolled content doesn't bleed past the
    # rounded border or the title bar. Save/restore the previous clip
    # so other panels later in the frame aren't affected.
    body_top = wy + SIM_WIN_HDR_H + 1
    body_bottom = wy + wh - 1
    prev_clip = surface.get_clip()
    surface.set_clip(pygame.Rect(wx + 1, body_top, ww - 2, body_bottom - body_top))

    # Subtract scroll from row baseline so content scrolls under the
    # body region. Click rects added during render are in screen
    # coords (already offset by -scroll), so hit-tests stay correct.
    cy = wy + SIM_WIN_HDR_H + SIM_WIN_PAD - sim_window_scroll

    # Helper: render one row with a label on the left and an editable
    # value/selector on the right. Returns the pygame.Rect of the
    # right-side editor for hit-testing.
    def _row(label_text, value_text, action_payload, hl=False):
        nonlocal cy
        l_surf = label_font.render(label_text, True, SIM_WIN_LABEL)
        surface.blit(l_surf, (wx + SIM_WIN_PAD,
                              cy + (SIM_WIN_ROW_H - l_surf.get_height()) // 2))
        # Editor area: right half of the row.
        ed_x = wx + ww // 2
        ed_w = ww // 2 - SIM_WIN_PAD
        ed_rect = pygame.Rect(ed_x, cy + 2, ed_w, SIM_WIN_ROW_H - 4)
        bg = SIM_WIN_BTN_HOV if hl else SIM_WIN_BTN_BG
        pygame.draw.rect(surface, bg, ed_rect, border_radius=3)
        v_col = SIM_WIN_VALUE if value_text else SIM_WIN_DIM
        v_text = value_text if value_text else "—"
        v_surf = value_font.render(v_text, True, v_col)
        surface.blit(v_surf, (ed_rect.x + 6,
                              ed_rect.y + (ed_rect.height - v_surf.get_height()) // 2))
        sim_window_rects.append((ed_rect, action_payload))
        cy += SIM_WIN_ROW_H
        return ed_rect

    # ── HP / MP overview ─────────────────────────────────────────────────
    # Two-cell summary at the top of the sim. Reads from the live
    # player_stats dict that lua pushes via the stats stream — the same
    # source as the main stats panel. When sim is active and you've
    # picked gear/food/buffs, these values reflect the simulated total
    # (lua's compute path stores hp/mp under the same keys regardless
    # of sim state). Useful for checking that an HP set keeps you
    # above some min HP threshold without having to leave sim mode.
    h_surf = title_font.render("HP / MP", True, SIM_WIN_TITLE)
    surface.blit(h_surf, (wx + SIM_WIN_PAD,
                          cy + (SIM_WIN_ROW_H - h_surf.get_height()) // 2))
    cy += SIM_WIN_ROW_H

    def _hp_mp_pair(label_a, key_a, label_b, key_b):
        nonlocal cy
        # Render two side-by-side cells: [label] [value] [label] [value]
        # Each takes half the width.
        cell_w = (ww - SIM_WIN_PAD * 2) // 2
        for idx, (lbl, key) in enumerate([(label_a, key_a), (label_b, key_b)]):
            cell_x = wx + SIM_WIN_PAD + idx * cell_w
            l_surf = label_font.render(lbl, True, SIM_WIN_LABEL)
            surface.blit(l_surf, (cell_x,
                                  cy + (SIM_WIN_ROW_H - l_surf.get_height()) // 2))
            val = player_stats.get(key, None)
            if val is None:
                val_text = "—"
                v_col = SIM_WIN_DIM
            else:
                try:
                    f = float(val)
                    val_text = f"{int(f)}" if abs(f - int(f)) < 0.001 else f"{f:.1f}"
                except (TypeError, ValueError):
                    val_text = str(val)
                v_col = SIM_WIN_VALUE
            v_surf = value_font.render(val_text, True, v_col)
            # Right-align the value within its half-cell.
            v_x = cell_x + cell_w - v_surf.get_width() - 6
            surface.blit(v_surf, (v_x,
                                  cy + (SIM_WIN_ROW_H - v_surf.get_height()) // 2))
        cy += SIM_WIN_ROW_H

    _hp_mp_pair("HP", "hp", "MP", "mp")
    cy += 4

    # ── Equipment section ─────────────────────────────────────────────────
    # 16 gear-slot rows. Each row has the slot label on the left and a
    # dropdown showing either the sim-overridden item OR the live equipped
    # item (greyed) for context. Click → opens the slot's dropdown showing
    # all items in inventory the current job can equip in that slot, plus
    # an "(empty)" option to sim the slot unequipped.
    h_surf = title_font.render("Equipment", True, SIM_WIN_TITLE)
    surface.blit(h_surf, (wx + SIM_WIN_PAD,
                          cy + (SIM_WIN_ROW_H - h_surf.get_height()) // 2))
    cy += SIM_WIN_ROW_H

    sim_eq = sim_state.get("equipment", {}) or {}
    cur_job = _inv_for_sim.get("main_job", "")

    # Two-column layout: each row holds 2 slot cells side-by-side.
    # 16 slots / 2 columns = 8 rows total, halving the equipment
    # section's height vs. the previous one-slot-per-row layout.
    # When a dropdown opens for a slot in column A, it expands BELOW
    # the entire 2-cell row taking the full width (so option labels
    # have room to breathe). The other slot in that row stays visible
    # but its dropdown is collapsed.
    col_count = 2
    col_w = (ww - SIM_WIN_PAD * 2) // col_count
    label_w = 38   # short slot labels: "Main", "L.Ear", etc.
    val_w   = col_w - label_w - 4

    def _equip_cell(slot_key, slot_label, col_x, row_y):
        """Draw one slot cell at (col_x, row_y); return its dropdown rect."""
        sim_val = sim_eq.get(slot_key, None)
        # sim_val can be:
        #   None        → no override, slot is "(real)" (pre-seed state)
        #   0           → explicit empty
        #   int > 0     → legacy id-only ref
        #   dict {...}  → instance ref {id, bag, idx}
        is_empty = (sim_val == 0)
        is_dict  = isinstance(sim_val, dict) and (sim_val.get("id", 0) or 0) > 0
        is_int   = isinstance(sim_val, int) and sim_val > 0
        if is_empty:
            display, dim = "(empty)", False
        elif is_dict or is_int:
            # Resolve display name from inventory snapshot.
            target_id = sim_val["id"] if is_dict else sim_val
            target_loc = (sim_val.get("bag", 0), sim_val.get("idx", 0)) if is_dict else None
            display = f"id:{target_id}"
            for entry in _sim_get_slot_options(slot_key):
                # Match exact instance when possible (dict ref), else by id.
                if target_loc and (entry.get("bag", 0), entry.get("idx", 0)) == target_loc:
                    display = _display_name_for_item(entry)
                    break
                if not target_loc and entry.get("id") == target_id:
                    display = _display_name_for_item(entry)
                    break
            dim = False
        else:
            display, dim = "(real)", True
        # Slot label on left
        l_surf = label_font.render(slot_label, True, SIM_WIN_LABEL)
        surface.blit(l_surf, (col_x,
                              row_y + (SIM_WIN_ROW_H - l_surf.get_height()) // 2))
        # Dropdown box on right
        ed_rect = pygame.Rect(col_x + label_w, row_y + 2,
                              val_w, SIM_WIN_ROW_H - 4)
        active = (sim_active_field
                  and sim_active_field.get("kind") == "equip_slot"
                  and sim_active_field.get("slot") == slot_key)
        bg = SIM_WIN_BTN_HOV if active else SIM_WIN_BTN_BG
        pygame.draw.rect(surface, bg, ed_rect, border_radius=3)
        v_col = SIM_WIN_DIM if dim else SIM_WIN_VALUE
        max_chars = max(6, (val_w - 8) // 6)
        truncated = display if len(display) <= max_chars else display[:max_chars-1] + "…"
        v_surf = value_font.render(truncated, True, v_col)
        surface.blit(v_surf, (ed_rect.x + 4,
                              ed_rect.y + (ed_rect.height - v_surf.get_height()) // 2))
        sim_window_rects.append((ed_rect,
            {"action": "open_dropdown", "kind": "equip_slot", "slot": slot_key}))
        return ed_rect, active, sim_val

    # Walk slots in groups of `col_count`. After each row, if any cell
    # in that row was active, expand its dropdown below the row using
    # full window width.
    for row_start in range(0, len(SIM_GEAR_SLOTS), col_count):
        row_slots = SIM_GEAR_SLOTS[row_start:row_start + col_count]
        active_slot = None
        active_sim_val = None
        for col_idx, (slot_key, slot_label) in enumerate(row_slots):
            col_x = wx + SIM_WIN_PAD + col_idx * col_w
            _rect, active, sim_val = _equip_cell(slot_key, slot_label,
                                                  col_x, cy)
            if active:
                active_slot = slot_key
                active_sim_val = sim_val
        cy += SIM_WIN_ROW_H

        # If a dropdown is open in this row, render the option list now,
        # taking the full window width (centered below the row of two
        # cells). 18px-tall option rows.
        if active_slot is not None:
            options = _sim_get_slot_options(active_slot)
            full_w = ww - SIM_WIN_PAD * 2
            opt_x = wx + SIM_WIN_PAD
            opt_max_chars = max(8, (full_w - 12) // 6)

            # "(empty)" sentinel
            opt_rect = pygame.Rect(opt_x, cy, full_w, 18)
            hov = (active_sim_val == 0)
            pygame.draw.rect(surface,
                SIM_WIN_BTN_HOV if hov else SIM_WIN_BTN_BG,
                opt_rect, border_radius=2)
            o_surf = label_font.render("(empty)", True, SIM_WIN_DIM)
            surface.blit(o_surf, (opt_rect.x + 6,
                                  opt_rect.y + (opt_rect.height - o_surf.get_height()) // 2))
            sim_window_rects.append((opt_rect,
                {"action": "select", "kind": "equip_slot",
                 "slot": active_slot, "value": 0}))
            cy += 18

            if not options:
                msg = ("(no inventory yet)" if not _inv_for_sim.get("by_slot")
                       else "(no items equippable)")
                e_surf = label_font.render(msg, True, SIM_WIN_DIM)
                surface.blit(e_surf, (opt_x + 6, cy + 2))
                cy += 18
            else:
                # Show ALL options. Each option is an entry dict; click
                # action sends an instance ref so augmented items resolve
                # to the exact (bag, idx). The current sim_val is matched
                # by exact location if dict-form, by id otherwise.
                cur_loc = None
                cur_id  = None
                if isinstance(active_sim_val, dict):
                    cur_loc = (active_sim_val.get("bag", 0),
                               active_sim_val.get("idx", 0))
                    cur_id  = active_sim_val.get("id")
                elif isinstance(active_sim_val, int) and active_sim_val > 0:
                    cur_id = active_sim_val
                for entry in options:
                    iid    = entry.get("id")
                    bag_id = entry.get("bag", 0)
                    idx_id = entry.get("idx", 0)
                    name = _display_name_for_item(entry)
                    opt_rect = pygame.Rect(opt_x, cy, full_w, 18)
                    # Highlight if this is the currently-selected instance.
                    is_hov = False
                    if cur_loc is not None:
                        is_hov = (cur_loc == (bag_id, idx_id))
                    elif cur_id is not None:
                        is_hov = (iid == cur_id)
                    pygame.draw.rect(surface,
                        SIM_WIN_BTN_HOV if is_hov else SIM_WIN_BTN_BG,
                        opt_rect, border_radius=2)
                    short = name if len(name) <= opt_max_chars else name[:opt_max_chars-1] + "…"
                    o_surf = label_font.render(short, True, SIM_WIN_VALUE)
                    surface.blit(o_surf, (opt_rect.x + 6,
                                          opt_rect.y + (opt_rect.height - o_surf.get_height()) // 2))
                    # Click action carries the full instance ref so lua
                    # gets <id>@<bag>:<idx> and resolves to this exact
                    # augmented copy.
                    sim_window_rects.append((opt_rect,
                        {"action": "select", "kind": "equip_slot",
                         "slot": active_slot,
                         "value": {"id": iid, "bag": bag_id, "idx": idx_id}}))
                    cy += 18

    cy += 4

    # ── Food section ───────────────────────────────────────────────────────
    # Single dropdown row, picks one food from SIM_FOOD_LIST (curated).
    h_surf = title_font.render("Food", True, SIM_WIN_TITLE)
    surface.blit(h_surf, (wx + SIM_WIN_PAD,
                          cy + (SIM_WIN_ROW_H - h_surf.get_height()) // 2))
    cy += SIM_WIN_ROW_H

    food_id = sim_state.get("food", None)
    food_disp = "(none)"
    if food_id is not None:
        for fid, fname, _stats in SIM_FOOD_LIST:
            if fid == food_id:
                food_disp = fname
                break
        else:
            food_disp = f"food:{food_id}"

    l_surf = label_font.render("Food", True, SIM_WIN_LABEL)
    surface.blit(l_surf, (wx + SIM_WIN_PAD,
                          cy + (SIM_WIN_ROW_H - l_surf.get_height()) // 2))
    fd_x = wx + ww // 2 - 30
    fd_w = ww - (fd_x - wx) - SIM_WIN_PAD
    fd_rect = pygame.Rect(fd_x, cy + 2, fd_w, SIM_WIN_ROW_H - 4)
    fd_active = (sim_active_field and sim_active_field.get("kind") == "food")
    pygame.draw.rect(surface,
        SIM_WIN_BTN_HOV if fd_active else SIM_WIN_BTN_BG,
        fd_rect, border_radius=3)
    fd_col = SIM_WIN_DIM if food_id is None else SIM_WIN_VALUE
    fd_max_chars = max(8, (fd_w - 12) // 6)
    fd_short = food_disp if len(food_disp) <= fd_max_chars else food_disp[:fd_max_chars-1] + "…"
    fd_surf = value_font.render(fd_short, True, fd_col)
    surface.blit(fd_surf, (fd_rect.x + 6,
                           fd_rect.y + (fd_rect.height - fd_surf.get_height()) // 2))
    sim_window_rects.append((fd_rect, {"action": "open_dropdown", "kind": "food"}))
    cy += SIM_WIN_ROW_H

    if fd_active:
        # "(none)" sentinel.
        opt_rect = pygame.Rect(fd_x, cy, fd_w, 18)
        hov = (food_id is None)
        pygame.draw.rect(surface,
            SIM_WIN_BTN_HOV if hov else SIM_WIN_BTN_BG,
            opt_rect, border_radius=2)
        o_surf = label_font.render("(none)", True, SIM_WIN_DIM)
        surface.blit(o_surf, (opt_rect.x + 6,
                              opt_rect.y + (opt_rect.height - o_surf.get_height()) // 2))
        sim_window_rects.append((opt_rect,
            {"action": "select", "kind": "food", "value": None}))
        cy += 18
        for fid, fname, _ in SIM_FOOD_LIST[:11]:
            opt_rect = pygame.Rect(fd_x, cy, fd_w, 18)
            hov = (food_id == fid)
            pygame.draw.rect(surface,
                SIM_WIN_BTN_HOV if hov else SIM_WIN_BTN_BG,
                opt_rect, border_radius=2)
            short = fname if len(fname) <= fd_max_chars else fname[:fd_max_chars-1] + "…"
            o_surf = label_font.render(short, True, SIM_WIN_VALUE)
            surface.blit(o_surf, (opt_rect.x + 6,
                                  opt_rect.y + (opt_rect.height - o_surf.get_height()) // 2))
            sim_window_rects.append((opt_rect,
                {"action": "select", "kind": "food", "value": fid}))
            cy += 18

    cy += 4

    # ── Buffs section: job→buff picker + active buff list ──────────────────
    # Two-stage picker. Closed by default (just an "Add Buff +" button).
    # Click → stage="job" shows BRD/COR. Pick a job → stage="buff" shows
    # the buffs for that job. Pick a buff → entry appended to
    # sim_state["active_buffs"] and lua is notified via SIM|buff_add.
    #
    # Each active buff renders as one row with controls appropriate to
    # its kind (songs: plus +/- only; rolls: plus +/- AND level +/- AND
    # optimal-job toggle).
    h_surf = title_font.render("Buffs", True, SIM_WIN_TITLE)
    surface.blit(h_surf, (wx + SIM_WIN_PAD,
                          cy + (SIM_WIN_ROW_H - h_surf.get_height()) // 2))
    cy += SIM_WIN_ROW_H

    # Render active buffs first (above the picker) so the list grows
    # downward and the "Add" button stays at the bottom of the section.
    for bidx, entry in enumerate(sim_state.get("active_buffs", [])):
        bid = entry.get("id", "")
        # Look up display info from catalog.
        catalog_entry = next(
            (c for c in SIM_BUFF_CATALOG if c[0] == bid), None)
        if catalog_entry is None:
            continue
        _, bcat, bname, bkind = catalog_entry[:4]
        # plus_max is optional in the catalog tuple; default 8 for back-
        # compat with songs/rolls that don't carry it explicitly.
        bplus_max = catalog_entry[4] if len(catalog_entry) > 4 else 8

        # Row 1: category + name + remove X. Compact label like
        # "Songs: Honor March" or "Spells: Haste".
        lbl = f"{bcat}: {bname}"
        l_surf = label_font.render(lbl, True, SIM_WIN_LABEL)
        surface.blit(l_surf, (wx + SIM_WIN_PAD,
                              cy + (SIM_WIN_ROW_H - l_surf.get_height()) // 2))
        x_size = 14
        x_rect = pygame.Rect(wx + ww - SIM_WIN_PAD - x_size,
                             cy + (SIM_WIN_ROW_H - x_size) // 2,
                             x_size, x_size)
        pygame.draw.rect(surface, (90, 50, 60), x_rect, border_radius=2)
        x_surf = label_font.render("×", True, (240, 220, 220))
        surface.blit(x_surf,
            (x_rect.x + (x_size - x_surf.get_width()) // 2,
             x_rect.y + (x_size - x_surf.get_height()) // 2 - 1))
        sim_window_rects.append((x_rect,
            {"action": "buff_remove", "idx": bidx}))
        cy += SIM_WIN_ROW_H

        # Spell-kind buffs (Haste, Flurry, etc.) have no plus/level/
        # optimal — flat values straight out of the catalog. Just the
        # name+remove row, then move on to the next buff.
        if bkind == "spell":
            continue

        # Row 2: controls. Plus +/- always; level +/- + optimal toggle for rolls.
        cur_plus = int(entry.get("plus", 0))
        if bkind == "song":
            # Just plus +/- right-aligned.
            l2 = label_font.render("  Plus", True, SIM_WIN_DIM)
            surface.blit(l2, (wx + SIM_WIN_PAD,
                              cy + (SIM_WIN_ROW_H - l2.get_height()) // 2))
            m_rect = pygame.Rect(wx + ww // 2, cy + 2, 22, SIM_WIN_ROW_H - 4)
            p_rect = pygame.Rect(wx + ww - SIM_WIN_PAD - 22, cy + 2,
                                 22, SIM_WIN_ROW_H - 4)
            v_x = m_rect.right + 4
            v_w = p_rect.left - v_x - 4
            v_rect = pygame.Rect(v_x, cy + 2, v_w, SIM_WIN_ROW_H - 4)
            pygame.draw.rect(surface, SIM_WIN_BTN_BG, m_rect, border_radius=3)
            pygame.draw.rect(surface, SIM_WIN_BTN_BG, p_rect, border_radius=3)
            pygame.draw.rect(surface, (32, 32, 40), v_rect, border_radius=3)
            m2 = value_font.render("−", True, SIM_WIN_VALUE)
            p2 = value_font.render("+", True, SIM_WIN_VALUE)
            v2 = value_font.render(f"+{cur_plus}", True, SIM_WIN_VALUE)
            surface.blit(m2, (m_rect.x + (m_rect.width - m2.get_width()) // 2,
                              m_rect.y + (m_rect.height - m2.get_height()) // 2 - 2))
            surface.blit(p2, (p_rect.x + (p_rect.width - p2.get_width()) // 2,
                              p_rect.y + (p_rect.height - p2.get_height()) // 2 - 2))
            surface.blit(v2, (v_rect.x + (v_rect.width - v2.get_width()) // 2,
                              v_rect.y + (v_rect.height - v2.get_height()) // 2))
            sim_window_rects.append((m_rect,
                {"action": "active_buff_field", "idx": bidx,
                 "field": "plus", "delta": -1, "min": 0, "max": bplus_max}))
            sim_window_rects.append((p_rect,
                {"action": "active_buff_field", "idx": bidx,
                 "field": "plus", "delta": +1, "min": 0, "max": bplus_max}))
            cy += SIM_WIN_ROW_H

            # Row 3 (BRD songs only): per-buff Soul Voice + Marcato
            # toggles. Both are BRD boosts that multiply the song's
            # output. SV is a 1-hour (x2); Marcato is a JA (x1.5) that
            # in real play only boosts the NEXT song cast — but since
            # each active buff has its own toggle here, the user picks
            # which song Marcato applies to. Stacks multiplicatively.
            # Skip for non-Songs categories (e.g. Geomancy Indi-*
            # spells, which share the song UI shape but have no BRD-
            # style boost mechanics).
            if bcat == "Songs":
                sv_on   = bool(entry.get("boost_sv", False))
                marc_on = bool(entry.get("boost_marcato", False))
                half_w  = (ww - SIM_WIN_PAD * 2) // 2
                for ti, (tkey, tlabel, ton) in enumerate([
                    ("boost_sv",      "Soul Voice", sv_on),
                    ("boost_marcato", "Marcato",    marc_on),
                ]):
                    tx = wx + SIM_WIN_PAD + ti * half_w
                    # Whole half is clickable; checkbox square at left.
                    box_size = 11
                    cb_rect = pygame.Rect(tx + 4,
                                          cy + (SIM_WIN_ROW_H - box_size) // 2,
                                          box_size, box_size)
                    pygame.draw.rect(surface, (40, 50, 65) if ton else (24, 26, 34),
                                     cb_rect, border_radius=2)
                    pygame.draw.rect(surface, (110, 130, 170), cb_rect, 1, border_radius=2)
                    if ton:
                        inner = cb_rect.inflate(-4, -4)
                        pygame.draw.rect(surface, (160, 200, 240), inner, border_radius=1)
                    lab_surf = label_font.render(tlabel, True,
                        SIM_WIN_VALUE if ton else SIM_WIN_DIM)
                    surface.blit(lab_surf,
                        (cb_rect.right + 4,
                         cy + (SIM_WIN_ROW_H - lab_surf.get_height()) // 2))
                    cell_rect = pygame.Rect(tx, cy, half_w, SIM_WIN_ROW_H)
                    sim_window_rects.append((cell_rect,
                        {"action": "active_buff_boost", "idx": bidx,
                         "field": tkey, "value": not ton}))
                cy += SIM_WIN_ROW_H
        else:
            # roll: plus + level on this row, optimal toggle on next.
            cur_lv = int(entry.get("level", 11))
            l2 = label_font.render("  Lv", True, SIM_WIN_DIM)
            surface.blit(l2, (wx + SIM_WIN_PAD,
                              cy + (SIM_WIN_ROW_H - l2.get_height()) // 2))
            # Level +/- on left half, plus +/- on right half.
            half_x = wx + (ww // 3)
            lv_minus = pygame.Rect(half_x, cy + 2, 18, SIM_WIN_ROW_H - 4)
            lv_plus  = pygame.Rect(half_x + 50, cy + 2, 18, SIM_WIN_ROW_H - 4)
            lv_val   = pygame.Rect(lv_minus.right + 2, cy + 2,
                                   lv_plus.left - lv_minus.right - 4,
                                   SIM_WIN_ROW_H - 4)
            pygame.draw.rect(surface, SIM_WIN_BTN_BG, lv_minus, border_radius=2)
            pygame.draw.rect(surface, SIM_WIN_BTN_BG, lv_plus,  border_radius=2)
            pygame.draw.rect(surface, (32, 32, 40), lv_val, border_radius=2)
            lm = value_font.render("−", True, SIM_WIN_VALUE)
            lp = value_font.render("+", True, SIM_WIN_VALUE)
            lv = value_font.render(str(cur_lv), True, SIM_WIN_VALUE)
            surface.blit(lm, (lv_minus.x + (lv_minus.width - lm.get_width()) // 2,
                              lv_minus.y + (lv_minus.height - lm.get_height()) // 2 - 2))
            surface.blit(lp, (lv_plus.x + (lv_plus.width - lp.get_width()) // 2,
                              lv_plus.y + (lv_plus.height - lp.get_height()) // 2 - 2))
            surface.blit(lv, (lv_val.x + (lv_val.width - lv.get_width()) // 2,
                              lv_val.y + (lv_val.height - lv.get_height()) // 2))
            sim_window_rects.append((lv_minus,
                {"action": "active_buff_field", "idx": bidx,
                 "field": "level", "delta": -1, "min": 1, "max": 11}))
            sim_window_rects.append((lv_plus,
                {"action": "active_buff_field", "idx": bidx,
                 "field": "level", "delta": +1, "min": 1, "max": 11}))
            # Plus on the right.
            pl_label = label_font.render("Plus", True, SIM_WIN_DIM)
            surface.blit(pl_label, (lv_plus.right + 6,
                cy + (SIM_WIN_ROW_H - pl_label.get_height()) // 2))
            pp_minus = pygame.Rect(lv_plus.right + 38, cy + 2,
                                   18, SIM_WIN_ROW_H - 4)
            pp_plus  = pygame.Rect(wx + ww - SIM_WIN_PAD - 18, cy + 2,
                                   18, SIM_WIN_ROW_H - 4)
            pp_val   = pygame.Rect(pp_minus.right + 2, cy + 2,
                                   pp_plus.left - pp_minus.right - 4,
                                   SIM_WIN_ROW_H - 4)
            pygame.draw.rect(surface, SIM_WIN_BTN_BG, pp_minus, border_radius=2)
            pygame.draw.rect(surface, SIM_WIN_BTN_BG, pp_plus,  border_radius=2)
            pygame.draw.rect(surface, (32, 32, 40), pp_val, border_radius=2)
            pm = value_font.render("−", True, SIM_WIN_VALUE)
            pp = value_font.render("+", True, SIM_WIN_VALUE)
            pv = value_font.render(f"+{cur_plus}", True, SIM_WIN_VALUE)
            surface.blit(pm, (pp_minus.x + (pp_minus.width - pm.get_width()) // 2,
                              pp_minus.y + (pp_minus.height - pm.get_height()) // 2 - 2))
            surface.blit(pp, (pp_plus.x + (pp_plus.width - pp.get_width()) // 2,
                              pp_plus.y + (pp_plus.height - pp.get_height()) // 2 - 2))
            surface.blit(pv, (pp_val.x + (pp_val.width - pv.get_width()) // 2,
                              pp_val.y + (pp_val.height - pv.get_height()) // 2))
            sim_window_rects.append((pp_minus,
                {"action": "active_buff_field", "idx": bidx,
                 "field": "plus", "delta": -1, "min": 0, "max": 11}))
            sim_window_rects.append((pp_plus,
                {"action": "active_buff_field", "idx": bidx,
                 "field": "plus", "delta": +1, "min": 0, "max": 11}))
            cy += SIM_WIN_ROW_H
            # Row 3 (rolls): "C. Cards" and "Job present" as two
            # side-by-side checkboxes, mirroring the BRD song row's
            # Soul Voice / Marcato layout. Whole half-width is
            # clickable; the small box at the left of each cell is the
            # visual indicator. Compact labels keep them legible at
            # the sim window's narrow default width.
            cc_on  = bool(entry.get("boost_cc",      False))
            opt_on = bool(entry.get("optimal",       False))
            half_w = (ww - SIM_WIN_PAD * 2) // 2
            for ti, (tkey, tlabel, ton) in enumerate([
                ("boost_cc", "C. Cards",    cc_on),
                ("optimal",  "Job present", opt_on),
            ]):
                tx = wx + SIM_WIN_PAD + ti * half_w
                box_size = 11
                cb_rect = pygame.Rect(tx + 4,
                                      cy + (SIM_WIN_ROW_H - box_size) // 2,
                                      box_size, box_size)
                pygame.draw.rect(surface, (40, 50, 65) if ton else (24, 26, 34),
                                 cb_rect, border_radius=2)
                pygame.draw.rect(surface, (110, 130, 170), cb_rect, 1, border_radius=2)
                if ton:
                    inner = cb_rect.inflate(-4, -4)
                    pygame.draw.rect(surface, (160, 200, 240), inner, border_radius=1)
                lab_surf = label_font.render(tlabel, True,
                    SIM_WIN_VALUE if ton else SIM_WIN_DIM)
                surface.blit(lab_surf,
                    (cb_rect.right + 4,
                     cy + (SIM_WIN_ROW_H - lab_surf.get_height()) // 2))
                cell_rect = pygame.Rect(tx, cy, half_w, SIM_WIN_ROW_H)
                # "optimal" goes through its own action key (preserved
                # for backwards-compat with the lua handler); CC goes
                # through the generic boost handler.
                if tkey == "optimal":
                    sim_window_rects.append((cell_rect,
                        {"action": "active_buff_optimal", "idx": bidx,
                         "value": not ton}))
                else:
                    sim_window_rects.append((cell_rect,
                        {"action": "active_buff_boost", "idx": bidx,
                         "field": tkey, "value": not ton}))
            cy += SIM_WIN_ROW_H

    # Picker UI: Add button (closed) → job dropdown → buff dropdown.
    picker_stage = sim_buff_picker.get("stage") if sim_buff_picker else None
    if picker_stage is None:
        # Closed: render "Add Buff +" button.
        add_rect = pygame.Rect(wx + SIM_WIN_PAD, cy + 2,
                               ww - SIM_WIN_PAD * 2, SIM_WIN_ROW_H - 4)
        pygame.draw.rect(surface, (50, 70, 90), add_rect, border_radius=3)
        a_surf = value_font.render("Add Buff +", True, (220, 230, 240))
        surface.blit(a_surf,
            (add_rect.x + (add_rect.width - a_surf.get_width()) // 2,
             add_rect.y + (add_rect.height - a_surf.get_height()) // 2))
        sim_window_rects.append((add_rect, {"action": "buff_picker_open"}))
        cy += SIM_WIN_ROW_H
    elif picker_stage == "job":
        # Stage 1: pick a job. Render one row per job that has buffs.
        prompt = label_font.render("Pick job:", True, SIM_WIN_LABEL)
        surface.blit(prompt, (wx + SIM_WIN_PAD,
            cy + (SIM_WIN_ROW_H - prompt.get_height()) // 2))
        cy += SIM_WIN_ROW_H
        for job in SIM_BUFF_JOB_LIST:
            j_rect = pygame.Rect(wx + SIM_WIN_PAD, cy + 1,
                                 ww - SIM_WIN_PAD * 2, SIM_WIN_ROW_H - 2)
            pygame.draw.rect(surface, SIM_WIN_BTN_BG, j_rect, border_radius=3)
            j_surf = value_font.render(job, True, SIM_WIN_VALUE)
            surface.blit(j_surf,
                (j_rect.x + (j_rect.width - j_surf.get_width()) // 2,
                 j_rect.y + (j_rect.height - j_surf.get_height()) // 2))
            sim_window_rects.append((j_rect,
                {"action": "buff_picker_job", "job": job}))
            cy += SIM_WIN_ROW_H
        # Cancel button.
        c_rect = pygame.Rect(wx + SIM_WIN_PAD, cy + 1,
                             ww - SIM_WIN_PAD * 2, SIM_WIN_ROW_H - 2)
        pygame.draw.rect(surface, (60, 50, 50), c_rect, border_radius=3)
        c_surf = value_font.render("Cancel", True, (220, 200, 200))
        surface.blit(c_surf,
            (c_rect.x + (c_rect.width - c_surf.get_width()) // 2,
             c_rect.y + (c_rect.height - c_surf.get_height()) // 2))
        sim_window_rects.append((c_rect, {"action": "buff_picker_cancel"}))
        cy += SIM_WIN_ROW_H
    elif picker_stage == "buff":
        # Stage 2: pick a buff for the chosen job.
        chosen_job = sim_buff_picker.get("job", "")
        prompt = label_font.render(f"Pick {chosen_job} buff:",
                                   True, SIM_WIN_LABEL)
        surface.blit(prompt, (wx + SIM_WIN_PAD,
            cy + (SIM_WIN_ROW_H - prompt.get_height()) // 2))
        cy += SIM_WIN_ROW_H
        for bid, bname, bkind, _bpmax in SIM_BUFF_BY_JOB.get(chosen_job, []):
            b_rect = pygame.Rect(wx + SIM_WIN_PAD, cy + 1,
                                 ww - SIM_WIN_PAD * 2, SIM_WIN_ROW_H - 2)
            pygame.draw.rect(surface, SIM_WIN_BTN_BG, b_rect, border_radius=3)
            b_surf = value_font.render(bname, True, SIM_WIN_VALUE)
            surface.blit(b_surf,
                (b_rect.x + 8,
                 b_rect.y + (b_rect.height - b_surf.get_height()) // 2))
            sim_window_rects.append((b_rect,
                {"action": "buff_picker_choose", "id": bid}))
            cy += SIM_WIN_ROW_H
        # Cancel button.
        c_rect = pygame.Rect(wx + SIM_WIN_PAD, cy + 1,
                             ww - SIM_WIN_PAD * 2, SIM_WIN_ROW_H - 2)
        pygame.draw.rect(surface, (60, 50, 50), c_rect, border_radius=3)
        c_surf = value_font.render("Cancel", True, (220, 200, 200))
        surface.blit(c_surf,
            (c_rect.x + (c_rect.width - c_surf.get_width()) // 2,
             c_rect.y + (c_rect.height - c_surf.get_height()) // 2))
        sim_window_rects.append((c_rect, {"action": "buff_picker_cancel"}))
        cy += SIM_WIN_ROW_H

    cy += 4

    # Import Set button. Opens an in-overlay file browser (rooted at the
    # configured GearSwap data path) to pick a gear .lua file, then a typed
    # set-path field; Lua sandbox-resolves the set into the sim equipment.
    import_rect = pygame.Rect(wx + SIM_WIN_PAD, cy + 2,
                              ww - SIM_WIN_PAD * 2, SIM_WIN_ROW_H - 4)
    pygame.draw.rect(surface, (50, 80, 70), import_rect, border_radius=3)
    i_surf = value_font.render("IMPORT SET", True, (220, 245, 235))
    surface.blit(i_surf, (import_rect.x + (import_rect.width - i_surf.get_width()) // 2,
                          import_rect.y + (import_rect.height - i_surf.get_height()) // 2))
    sim_window_rects.append((import_rect, {"action": "import_open"}))
    cy += SIM_WIN_ROW_H

    # Export Set button. Writes the current sim equipment+food to a
    # GearSwap-style .lua file under simulation/export/. Lua handles
    # the file write (it has access to addon_path and to live item names
    # in resources). Disabled-looking when sim has no equipment set.
    export_rect = pygame.Rect(wx + SIM_WIN_PAD, cy + 2,
                              ww - SIM_WIN_PAD * 2, SIM_WIN_ROW_H - 4)
    has_eq = bool(sim_state.get("equipment"))
    btn_col = (50, 70, 90) if has_eq else (40, 40, 50)
    txt_col = (220, 230, 245) if has_eq else (110, 110, 130)
    pygame.draw.rect(surface, btn_col, export_rect, border_radius=3)
    e_surf = value_font.render("EXPORT SET", True, txt_col)
    surface.blit(e_surf, (export_rect.x + (export_rect.width - e_surf.get_width()) // 2,
                          export_rect.y + (export_rect.height - e_surf.get_height()) // 2))
    sim_window_rects.append((export_rect, {"action": "export_set"}))
    cy += SIM_WIN_ROW_H

    # Reset button at bottom.
    reset_rect = pygame.Rect(wx + SIM_WIN_PAD, cy + 2,
                             ww - SIM_WIN_PAD * 2, SIM_WIN_ROW_H - 4)
    pygame.draw.rect(surface, (80, 50, 50), reset_rect, border_radius=3)
    r_surf = value_font.render("RESET", True, (240, 220, 220))
    surface.blit(r_surf, (reset_rect.x + (reset_rect.width - r_surf.get_width()) // 2,
                          reset_rect.y + (reset_rect.height - r_surf.get_height()) // 2))
    sim_window_rects.append((reset_rect, {"action": "reset"}))
    cy += SIM_WIN_ROW_H

    # ── Restore clip + chrome (scrollbar, resize grip) ──────────────────────
    # Drawn AFTER restoring the previous clip so the chrome can sit on
    # top of the rounded border instead of being clipped at the body
    # edge.
    surface.set_clip(prev_clip)

    # Vertical scrollbar (only when there's overflow). Track on the
    # right inside edge; thumb sized proportional to visible/natural.
    if overflow > 0:
        sb_w = 4
        sb_x = wx + ww - sb_w - 2
        track_y = wy + SIM_WIN_HDR_H + 2
        track_h = wh - SIM_WIN_HDR_H - 4
        pygame.draw.rect(surface, (40, 40, 50),
                         (sb_x, track_y, sb_w, track_h), border_radius=2)
        thumb_h = max(20, int(track_h * body_h
                              / max(1, body_h + overflow)))
        thumb_y = track_y + int((track_h - thumb_h)
                                * sim_window_scroll / overflow)
        pygame.draw.rect(surface, (130, 130, 150),
                         (sb_x, thumb_y, sb_w, thumb_h), border_radius=2)

    # Resize grip in the bottom-right corner. Three diagonal lines —
    # standard "drag-to-resize" affordance. Hit area is a small square
    # that covers all three lines plus a generous border for easier
    # grabbing on small windows.
    grip_size = 14
    grip_rect = pygame.Rect(wx + ww - grip_size - 2,
                            wy + wh - grip_size - 2,
                            grip_size, grip_size)
    sim_window_resize_rect = grip_rect
    grip_col = (130, 130, 150)
    for i in range(3):
        off = 4 + i * 4
        pygame.draw.line(surface, grip_col,
                         (grip_rect.right - 2, grip_rect.bottom - off),
                         (grip_rect.right - off, grip_rect.bottom - 2), 1)

    # ── Augment-nickname editor overlay ──────────────────────────────
    # When right-clicking an item in an equipment dropdown, an editor
    # appears overlaying the sim window's center. Lets the user assign
    # a friendly nickname for that augment fingerprint. Enter saves,
    # Esc cancels (handled in the main key loop).
    if sim_nickname_editor is not None:
        ed = sim_nickname_editor
        # Modal panel: 80% of window width, centered, ~80px tall.
        ep_w = max(220, ww - 40)
        ep_h = 96
        ep_x = wx + (ww - ep_w) // 2
        ep_y = wy + (wh - ep_h) // 2
        # Backdrop dim
        backdrop = pygame.Surface((ww, wh), pygame.SRCALPHA)
        backdrop.fill((0, 0, 0, 140))
        surface.blit(backdrop, (wx, wy))
        # Panel
        pygame.draw.rect(surface, (32, 32, 42),
                         (ep_x, ep_y, ep_w, ep_h), border_radius=6)
        pygame.draw.rect(surface, (90, 100, 130),
                         (ep_x, ep_y, ep_w, ep_h), 1, border_radius=6)
        # Title
        t_surf = title_font.render("Nickname for this item", True, SIM_WIN_TITLE)
        surface.blit(t_surf, (ep_x + 10, ep_y + 8))
        # Hint line below title
        hint = "Enter to save · Esc to cancel · empty clears"
        h_surf = label_font.render(hint, True, SIM_WIN_DIM)
        surface.blit(h_surf, (ep_x + 10, ep_y + 26))
        # Input box
        box = pygame.Rect(ep_x + 10, ep_y + 50, ep_w - 20, 28)
        pygame.draw.rect(surface, (20, 20, 28), box, border_radius=3)
        pygame.draw.rect(surface, (110, 130, 170), box, 1, border_radius=3)
        # Text + blinking cursor
        txt = ed.get("text", "")
        # Cursor visibility toggles every ~530ms.
        show_cursor = (int((time.time() - ed.get("cursor_blink", 0)) * 1.9) % 2 == 0)
        rendered = txt + ("|" if show_cursor else "")
        i_surf = value_font.render(rendered, True, SIM_WIN_VALUE)
        # Vertically center the text
        surface.blit(i_surf, (box.x + 6,
                              box.y + (box.height - i_surf.get_height()) // 2))


def _sim_safe_text(s):
    """Strip null bytes and control chars that pygame's font renderer
    rejects (raises ValueError on any '\\x00'). Used for any dynamic text
    in the import modal (paths, filenames, user input)."""
    if not s:
        return ""
    s = str(s).replace("\x00", "")
    return "".join(c for c in s if c == " " or c == "\t" or ord(c) >= 32)


def _sim_import_list_dir(path):
    """Return (folders, lua_files) for a directory, sorted. Each is a list
    of (display_name, full_path). Returns ([],[]) on error."""
    folders, files = [], []
    try:
        for nm in sorted(os.listdir(path), key=str.lower):
            full = os.path.join(path, nm)
            if os.path.isdir(full):
                folders.append((nm, full))
            elif nm.lower().endswith(".lua"):
                files.append((nm, full))
    except Exception:
        pass
    return folders, files


def draw_sim_import_modal(surface):
    """In-overlay file browser for importing a gear set into the sim.
    Rooted at the configured GearSwap data path. Lists folders + .lua
    files, lets the user pick a file and type a set path, then sends
    SIM_IMPORT|<file>|<setpath> to Lua. Populates sim_import_rects."""
    global sim_import_rects
    sim_import_rects = []
    if not sim_import_open:
        return

    sw, sh = surface.get_size()
    mw = min(520, sw - 40)
    mh = min(200, sh - 40)
    mx = (sw - mw) // 2
    my = (sh - mh) // 2

    # Backdrop dim (also a click-catcher to close on outside click).
    backdrop = pygame.Surface((sw, sh), pygame.SRCALPHA)
    backdrop.fill((0, 0, 0, 150))
    surface.blit(backdrop, (0, 0))
    sim_import_rects.append((pygame.Rect(0, 0, sw, sh), {"action": "imp_backdrop"}))

    # Panel
    panel = pygame.Rect(mx, my, mw, mh)
    pygame.draw.rect(surface, (24, 28, 36), panel, border_radius=6)
    pygame.draw.rect(surface, (70, 110, 95), panel, 1, border_radius=6)

    title_font = _chat_get_font("body", 15) if "_chat_get_font" in globals() else pygame.font.SysFont("Arial", 15)
    lbl_font   = pygame.font.SysFont("Arial", 13)
    sm_font    = pygame.font.SysFont("Arial", 12)

    pad = 12
    cy = my + pad

    # Title + close
    t_surf = title_font.render("Import Gear Set", True, (220, 245, 235))
    surface.blit(t_surf, (mx + pad, cy))
    close_r = pygame.Rect(mx + mw - pad - 16, cy, 16, 16)
    pygame.draw.rect(surface, (80, 50, 50), close_r, border_radius=3)
    x_surf = lbl_font.render("X", True, (240, 220, 220))
    surface.blit(x_surf, (close_r.x + (16 - x_surf.get_width()) // 2,
                          close_r.y + (16 - x_surf.get_height()) // 2))
    sim_import_rects.append((close_r, {"action": "imp_close"}))
    cy += 26

    # Browse button — opens the native OS file picker (same mechanism as
    # the hotbar icon picker). Far simpler than an in-overlay browser and
    # lets the user reach any path on disk.
    browse_btn = pygame.Rect(mx + pad, cy, 100, 24)
    pygame.draw.rect(surface, (55, 80, 70), browse_btn, border_radius=3)
    surface.blit(lbl_font.render("Browse…", True, (220, 245, 235)),
                 (browse_btn.x + (100 - lbl_font.size("Browse…")[0]) // 2,
                  browse_btn.y + (24 - lbl_font.get_height()) // 2))
    sim_import_rects.append((browse_btn, {"action": "imp_browse"}))
    # Selected file (full name, wrapped/clipped) to the right of Browse.
    sel_name = os.path.basename(sim_import_file) if sim_import_file else "(no file selected)"
    sel_col = (190, 220, 205) if sim_import_file else (120, 125, 135)
    surface.blit(sm_font.render(_sim_safe_text(sel_name), True, sel_col),
                 (browse_btn.right + 10, cy + 5))
    cy += 32
    # Full path line (dim, clipped) so the user can confirm which file.
    if sim_import_file:
        clip_prev = surface.get_clip()
        path_clip = pygame.Rect(mx + pad, cy, mw - pad * 2, 16)
        surface.set_clip(path_clip)
        p_surf = sm_font.render(_sim_safe_text(sim_import_file), True, (110, 120, 130))
        pxp = path_clip.x
        if p_surf.get_width() > path_clip.width:
            pxp = path_clip.right - p_surf.get_width()
        surface.blit(p_surf, (pxp, cy))
        surface.set_clip(clip_prev)
    cy += 22
    surface.blit(sm_font.render("Set path:", True, (160, 175, 185)),
                 (mx + pad, cy))
    sp_box = pygame.Rect(mx + pad + 64, cy - 2, mw - pad * 2 - 64, 20)
    focused_sp = (sim_import_field == "setpath")
    pygame.draw.rect(surface, (16, 20, 26), sp_box, border_radius=3)
    pygame.draw.rect(surface, (90, 140, 120) if focused_sp else (60, 70, 80),
                     sp_box, 1, border_radius=3)
    sp_txt = sim_import_setpath or "sets.engaged.HighHaste"
    sp_txt = _sim_safe_text(sp_txt)
    sp_col = (220, 230, 240) if sim_import_setpath else (110, 115, 125)
    if focused_sp and sim_import_setpath:
        # Draw text with a caret at the cursor position. Clamp cursor to
        # the current text length (it can lag after external edits).
        cpos = max(0, min(sim_import_setpath_cursor, len(sim_import_setpath)))
        before = _sim_safe_text(sim_import_setpath[:cpos])
        blink = (int(time.time() * 1.9) % 2 == 0)
        shown = before + ("|" if blink else "") + _sim_safe_text(sim_import_setpath[cpos:])
        sp_surf = sm_font.render(shown, True, sp_col)
    else:
        sp_surf = sm_font.render(sp_txt + ("|" if focused_sp else ""), True, sp_col)
    surface.blit(sp_surf, (sp_box.x + 5, sp_box.y + (20 - sp_surf.get_height()) // 2))
    sim_import_rects.append((sp_box, {"action": "imp_focus", "field": "setpath"}))
    cy += 26

    # Import button + status.
    imp_btn = pygame.Rect(mx + pad, cy, 110, 22)
    can_import = bool(sim_import_file and sim_import_setpath)
    pygame.draw.rect(surface, (50, 95, 75) if can_import else (40, 50, 50),
                     imp_btn, border_radius=3)
    surface.blit(lbl_font.render("IMPORT", True,
                 (225, 245, 235) if can_import else (110, 120, 120)),
                 (imp_btn.x + (110 - lbl_font.size("IMPORT")[0]) // 2,
                  imp_btn.y + (22 - lbl_font.get_height()) // 2))
    if can_import:
        sim_import_rects.append((imp_btn, {"action": "imp_confirm"}))
    if sim_import_status:
        surface.blit(sm_font.render(_sim_safe_text(sim_import_status), True, (200, 190, 150)),
                     (imp_btn.right + 10, cy + 4))


def _draw_checkbox_check(surface, cb_rect, color=(140, 220, 140)):
    """Draw a ✓ inside a checkbox-style rect using pygame primitives.

    Used instead of `font.render("✓")` because the bundled Consolas
    SysFont doesn't reliably ship the Unicode checkmark glyph — on
    most Windows installs it renders as a blank-width fallback, so
    enabled checkboxes look empty. Two line segments forming a tick
    shape (short stroke down-right, long stroke up-right) reads as
    a clear check regardless of font availability.

    cb_rect is the checkbox rectangle (typically 14×14 px). The
    check is drawn 2px inside each edge so it visually fits without
    overlapping the box border.
    """
    inset = 2
    p1 = (cb_rect.x + inset,
          cb_rect.y + cb_rect.h // 2 + 1)
    p2 = (cb_rect.x + cb_rect.w // 2 - 1,
          cb_rect.bottom - inset - 1)
    p3 = (cb_rect.right - inset,
          cb_rect.y + inset + 1)
    pygame.draw.lines(surface, color, False, [p1, p2, p3], 2)


def draw_currency_settings_modal(surface):
    """Render the currency cycler subdialog if open. A small centered
    panel with six checkboxes (one per currency), a +/- spinner for
    the cycle interval, and a Close button. Refills
    currency_settings_modal_rects each frame with click targets.

    State is read straight from settings[] so toggling immediately
    affects the header cycler. Closing the modal commits nothing extra
    — settings already auto-persist via the standard save path.
    """
    global currency_settings_modal_rects
    currency_settings_modal_rects = []
    if not currency_settings_modal_open:
        return

    g = _menu_g()
    def _ms(v):
        return max(1, round(v * g))
    ctrl_h = _ms(22)
    sw, sh = surface.get_size()
    mw = min(_ms(420), sw - 40)
    # Compute height from the actual currency-row count instead of
    # hardcoding 280px. With 6 currencies the old 280 had headroom;
    # with 9 the modal bled off the bottom of the screen (Tokens and
    # Ichor were under the header strip / clipped). Breakdown:
    #   title_block   ≈ 50  (title + subtitle + gap)
    #   interval_row  ≈ 32  (spinner)
    #   divider       ≈ 8
    #   rows          = 22 * len(CURRENCY_CYCLE_KEYS)
    #   close_block   ≈ 50
    title_block_h = _ms(50)
    interval_h    = _ms(32)
    divider_h     = _ms(8)
    row_h         = _ms(22)
    close_block_h = _ms(50)
    rows_h = row_h * len(CURRENCY_CYCLE_KEYS)
    mh = (title_block_h + interval_h + divider_h + rows_h + close_block_h)
    # Floor at the original 280 so the modal can't look cramped on
    # the smallest installs (1-2 currencies enabled is still a 9-
    # row schema; future additions might also shrink the list).
    mh = max(mh, _ms(280))
    # Ceiling at screen height − 40 so even on tiny windows the
    # modal stays bordered top + bottom.
    mh = min(mh, sh - 40)
    mx = (sw - mw) // 2
    my = (sh - mh) // 2

    # Backdrop dim (also a click-catcher to close on outside click).
    # When transparent_background is ON, the LWA_COLORKEY compositor
    # filter relies on every "empty" pixel still being COL_BG. Filling
    # the screen with a (0,0,0,150) overlay paints those pixels with a
    # different color and the colorkey stops triggering — so the modal
    # looks fine but the surrounding window goes opaque. Skip the
    # visual dim in that case; the click target still registers below
    # so clicking outside the panel still dismisses.
    if not setting("transparent_background"):
        backdrop = pygame.Surface((sw, sh), pygame.SRCALPHA)
        backdrop.fill((0, 0, 0, 150))
        surface.blit(backdrop, (0, 0))
    currency_settings_modal_rects.append(
        (pygame.Rect(0, 0, sw, sh), {"action": "cur_backdrop"}))

    # Panel.
    panel = pygame.Rect(mx, my, mw, mh)
    pygame.draw.rect(surface, (24, 28, 36), panel, border_radius=6)
    pygame.draw.rect(surface, (110, 130, 170), panel, 1, border_radius=6)
    # Re-register the panel itself as a click-eater so panel-internal
    # clicks that miss a control don't fall through to the backdrop
    # and dismiss the modal accidentally.
    currency_settings_modal_rects.append(
        (panel, {"action": "cur_panel_bg"}))

    # Fonts.
    title_font = pygame.font.SysFont("Consolas", _ms(14), bold=True)
    label_font = pygame.font.SysFont("Consolas", _ms(12))
    small_font = pygame.font.SysFont("Consolas", _ms(10), italic=True)

    pad = _ms(14)
    cy_y = my + pad

    # Title.
    t_surf = title_font.render(
        "Currency Cycler", True, (220, 200, 150))
    surface.blit(t_surf, (mx + pad, cy_y))
    cy_y += t_surf.get_height() + _ms(2)
    # Subtitle/hint.
    sub_surf = small_font.render(
        "Pick which currencies appear in the header rotation.",
        True, (160, 160, 175))
    surface.blit(sub_surf, (mx + pad, cy_y))
    cy_y += sub_surf.get_height() + _ms(10)

    # Cycle interval spinner (− value + label).
    interval = setting("header_currency_cycle_seconds") or 5
    try:
        interval = int(interval)
    except (TypeError, ValueError):
        interval = 5
    iv_label = label_font.render(
        "Cycle interval:", True, (220, 220, 230))
    surface.blit(iv_label, (mx + pad, cy_y + _ms(4)))
    iv_lbl_w = iv_label.get_width()

    # Minus button.
    minus_rect = pygame.Rect(mx + pad + iv_lbl_w + _ms(12), cy_y, ctrl_h, ctrl_h)
    pygame.draw.rect(surface, (50, 50, 65), minus_rect, border_radius=3)
    pygame.draw.rect(surface, (110, 110, 130), minus_rect, 1,
                     border_radius=3)
    m_surf = label_font.render("−", True, (220, 220, 230))
    surface.blit(m_surf,
        (minus_rect.x + (ctrl_h - m_surf.get_width()) // 2,
         minus_rect.y + (ctrl_h - m_surf.get_height()) // 2))
    currency_settings_modal_rects.append(
        (minus_rect, {"action": "cur_interval", "delta": -1}))

    # Value display.
    val_surf = label_font.render(
        f"{interval}s", True, (220, 195, 90))
    val_x = minus_rect.right + _ms(8)
    surface.blit(val_surf,
        (val_x, cy_y + (ctrl_h - val_surf.get_height()) // 2))

    # Plus button.
    plus_rect = pygame.Rect(val_x + _ms(40), cy_y, ctrl_h, ctrl_h)
    pygame.draw.rect(surface, (50, 50, 65), plus_rect, border_radius=3)
    pygame.draw.rect(surface, (110, 110, 130), plus_rect, 1,
                     border_radius=3)
    p_surf = label_font.render("+", True, (220, 220, 230))
    surface.blit(p_surf,
        (plus_rect.x + (ctrl_h - p_surf.get_width()) // 2,
         plus_rect.y + (ctrl_h - p_surf.get_height()) // 2))
    currency_settings_modal_rects.append(
        (plus_rect, {"action": "cur_interval", "delta": 1}))

    # Range hint.
    range_surf = small_font.render(
        " (2-10s)", True, (140, 145, 160))
    surface.blit(range_surf,
        (plus_rect.right + _ms(8),
         cy_y + (ctrl_h - range_surf.get_height()) // 2))

    cy_y += _ms(32)

    # Divider.
    pygame.draw.line(surface, (60, 60, 75),
                     (mx + pad, cy_y),
                     (mx + mw - pad, cy_y), 1)
    cy_y += _ms(8)

    # Per-currency checkboxes.
    for key, name, setting_key in CURRENCY_CYCLE_KEYS:
        row_rect = pygame.Rect(mx + pad, cy_y, mw - 2 * pad, ctrl_h)
        # Hover highlight.
        if row_rect.collidepoint(pygame.mouse.get_pos()):
            pygame.draw.rect(surface, (40, 40, 52), row_rect,
                             border_radius=2)

        # Checkbox.
        cb_size = _ms(14)
        cb_rect = pygame.Rect(mx + pad + _ms(4),
                              cy_y + (ctrl_h - cb_size) // 2,
                              cb_size, cb_size)
        pygame.draw.rect(surface, (30, 30, 40), cb_rect,
                         border_radius=2)
        pygame.draw.rect(surface, (110, 130, 170), cb_rect, 1,
                         border_radius=2)
        is_on = bool(setting(setting_key))
        if is_on:
            _draw_checkbox_check(surface, cb_rect)

        # Label + current value preview.
        name_surf = label_font.render(name, True, (220, 220, 230))
        surface.blit(name_surf,
            (cb_rect.right + _ms(8),
             cy_y + (ctrl_h - name_surf.get_height()) // 2))
        # Show the current value as a faint suffix so the user can
        # confirm at a glance that data is actually flowing.
        cur_val = currency_state.get(key, 0)
        val_text = f"({cur_val:,})"
        val_s = small_font.render(val_text, True, (140, 145, 160))
        surface.blit(val_s,
            (mx + mw - pad - val_s.get_width(),
             cy_y + (ctrl_h - val_s.get_height()) // 2))

        currency_settings_modal_rects.append(
            (row_rect, {"action": "cur_toggle",
                        "key": setting_key}))
        cy_y += ctrl_h

    # Close button at bottom right.
    cy_y = my + mh - pad - _ms(24)
    close_rect = pygame.Rect(mx + mw - pad - _ms(70), cy_y, _ms(70), _ms(24))
    pygame.draw.rect(surface, (60, 70, 90), close_rect, border_radius=3)
    pygame.draw.rect(surface, (140, 160, 200), close_rect, 1,
                     border_radius=3)
    cl_surf = label_font.render("Close", True, (220, 220, 230))
    surface.blit(cl_surf,
        (close_rect.x + (close_rect.w - cl_surf.get_width()) // 2,
         close_rect.y + (close_rect.h - cl_surf.get_height()) // 2))
    currency_settings_modal_rects.append(
        (close_rect, {"action": "cur_close"}))


def dispatch_currency_settings_click(mx, my):
    """Resolve a click against the currency settings modal. Returns
    True if consumed. Walks the rects list in reverse so foreground
    controls (buttons, checkboxes) take priority over the panel
    background catcher and the backdrop."""
    global currency_settings_modal_open
    global currency_cycle_index, currency_cycle_last_advance
    global settings_menu_open
    if not currency_settings_modal_open:
        return False
    for rect, action in reversed(currency_settings_modal_rects):
        if not rect.collidepoint(mx, my):
            continue
        what = action.get("action")
        if what == "cur_backdrop":
            # Outside-click closes.
            currency_settings_modal_open = False
            settings_menu_open = True
            return True
        if what == "cur_panel_bg":
            # Click inside panel but not on a control — swallow so
            # the click doesn't fall through to the backdrop.
            return True
        if what == "cur_close":
            currency_settings_modal_open = False
            settings_menu_open = True
            return True
        if what == "cur_toggle":
            key = action["key"]
            cur = bool(setting(key))
            settings[key] = not cur
            apply_setting_side_effects(key, not cur)
            save_settings()
            # Reset cycle so the user lands on a sensible entry
            # rather than a now-disabled one.
            currency_cycle_index = 0
            currency_cycle_last_advance = time.time()
            return True
        if what == "cur_interval":
            delta = action.get("delta", 0)
            cur = setting("header_currency_cycle_seconds") or 5
            try:
                cur = int(cur)
            except (TypeError, ValueError):
                cur = 5
            new_val = max(2, min(10, cur + delta))
            if new_val != cur:
                settings["header_currency_cycle_seconds"] = new_val
                apply_setting_side_effects(
                    "header_currency_cycle_seconds", new_val)
                save_settings()
            return True
    return False


# ──────────────────────────────────────────────────────────────────────
# Party Panel settings modal — mirrors the currency modal's pattern:
# centered popup, backdrop dim, panel of controls, Close button.
# Holds the nine party settings that used to live inline in the
# settings dropdown. Each control reads/writes the underlying setting
# via setting() / settings[key] and triggers apply_setting_side_effects
# + save_settings on change.
# ──────────────────────────────────────────────────────────────────────

# Row definitions for the party modal. Tuple shape:
#   (setting_key, display_label, control_kind, help_optional)
#   control_kind: "bool" | "enum" | "button"
# Order is the render order in the modal — keep logically grouped
# (visibility toggles first, then column toggles, then formatting,
# then the blacklist editor).
_PARTY_MODAL_ROWS = [
    ("show_party",            "Show party panel",        "bool"),
    ("show_alliance",         "Show alliance",           "bool"),
    ("party_show_pets",       "Show pets",               "bool"),
    ("party_show_buffs",      "Show buffs",              "bool"),
    ("party_show_debuffs",    "Show debuffs",            "bool"),
    ("party_buff_font_size",  "Buff/debuff font size",   "enum"),
    ("party_buff_icon_grid",  "Compact icon grid",       "bool"),
    ("specific_buff_names",   "Specific buff names (self)", "bool"),
    ("edit_buff_blacklist",   "Edit buffs / debuffs",    "button"),
]


def draw_party_settings_modal(surface):
    """Render the Party Panel subdialog if open. Refills
    party_settings_modal_rects each frame with click targets.

    Control rendering:
      bool   — checkbox + label (full-row click toggle)
      enum   — checkbox-row layout but the right side shows the
               current option name in a small pill; click cycles
               through options
      button — checkbox-row layout but the right side shows an
               "Open..." pill; click triggers the registered action
               (in practice: edit_buff_blacklist → open the JSON
               in the user's default editor).
    """
    global party_settings_modal_rects
    party_settings_modal_rects = []
    if not party_settings_modal_open:
        return

    g = _menu_g()
    def _ms(v):
        return max(1, round(v * g))
    sw, sh = surface.get_size()
    # Generous width for label + control on the right.
    mw = min(_ms(500), sw - 40)
    # Height grows with row count: title block + N*row_h + close
    # button + padding. row_h = 26 keeps things readable without
    # feeling sparse.
    title_block_h = _ms(50)
    row_h         = _ms(26)
    close_block_h = _ms(50)
    pad           = _ms(14)
    mh = title_block_h + len(_PARTY_MODAL_ROWS) * row_h + close_block_h
    mh = min(mh, sh - 40)
    mx = (sw - mw) // 2
    my = (sh - mh) // 2

    # Backdrop dim — click closes. Skip the visual fill when
    # transparent_background is on (see currency modal note about
    # the LWA_COLORKEY interaction); click target still registers.
    if not setting("transparent_background"):
        backdrop = pygame.Surface((sw, sh), pygame.SRCALPHA)
        backdrop.fill((0, 0, 0, 150))
        surface.blit(backdrop, (0, 0))
    party_settings_modal_rects.append(
        (pygame.Rect(0, 0, sw, sh), {"action": "party_backdrop"}))

    # Panel.
    panel = pygame.Rect(mx, my, mw, mh)
    pygame.draw.rect(surface, (24, 28, 36), panel, border_radius=6)
    pygame.draw.rect(surface, (110, 130, 170), panel, 1, border_radius=6)
    # Swallow panel-internal misclicks so they don't dismiss the
    # modal via the backdrop catch.
    party_settings_modal_rects.append(
        (panel, {"action": "party_panel_bg"}))

    # Fonts (match the currency modal's font choices for visual
    # consistency).
    title_font = pygame.font.SysFont("Consolas", _ms(14), bold=True)
    label_font = pygame.font.SysFont("Consolas", _ms(12))
    small_font = pygame.font.SysFont("Consolas", _ms(10), italic=True)

    cy_y = my + pad

    # Title + subtitle.
    t_surf = title_font.render("Party Panel", True, (220, 200, 150))
    surface.blit(t_surf, (mx + pad, cy_y))
    cy_y += t_surf.get_height() + _ms(2)
    sub_surf = small_font.render(
        "Show/hide rows and configure buff & debuff columns.",
        True, (160, 160, 175))
    surface.blit(sub_surf, (mx + pad, cy_y))
    cy_y += sub_surf.get_height() + _ms(10)

    # Rows.
    for setting_key, display_label, kind in _PARTY_MODAL_ROWS:
        row_rect = pygame.Rect(mx + pad, cy_y, mw - 2 * pad, row_h - _ms(2))
        # Hover highlight (mirrors currency modal).
        if row_rect.collidepoint(pygame.mouse.get_pos()):
            pygame.draw.rect(surface, (40, 40, 52), row_rect,
                             border_radius=2)

        if kind == "bool":
            # Checkbox-style toggle.
            cb_size = _ms(14)
            cb_rect = pygame.Rect(mx + pad + _ms(4),
                                  cy_y + (row_h - cb_size) // 2 - 1,
                                  cb_size, cb_size)
            pygame.draw.rect(surface, (30, 30, 40), cb_rect,
                             border_radius=2)
            pygame.draw.rect(surface, (110, 130, 170), cb_rect, 1,
                             border_radius=2)
            is_on = bool(setting(setting_key))
            if is_on:
                _draw_checkbox_check(surface, cb_rect)
            # Label.
            name_surf = label_font.render(display_label, True,
                                           (220, 220, 230))
            surface.blit(name_surf,
                (cb_rect.right + _ms(8),
                 cy_y + (row_h - name_surf.get_height()) // 2 - 1))
            # Whole-row click toggles.
            party_settings_modal_rects.append(
                (row_rect, {"action": "party_toggle",
                            "key": setting_key}))

        elif kind == "enum":
            # Label on the left (no checkbox — this isn't a toggle).
            name_surf = label_font.render(display_label, True,
                                           (220, 220, 230))
            surface.blit(name_surf,
                (mx + pad + _ms(4),
                 cy_y + (row_h - name_surf.get_height()) // 2 - 1))
            # Current option pill on the right; click cycles forward.
            # Pull current value + the schema's option list to
            # determine the next value. Falls back to "medium" if
            # the schema entry is missing (shouldn't happen, but
            # defensive).
            schema = _setting_schema(setting_key)
            options       = (schema.get("options") if schema else None) or ["small", "medium", "large"]
            option_labels = (schema.get("option_labels") if schema
                             else None) or [s.title() for s in options]
            cur_val = setting(setting_key) or options[0]
            try:
                cur_idx = options.index(cur_val)
            except ValueError:
                cur_idx = 0
            cur_label = option_labels[cur_idx]
            pill_text = f"{cur_label}"
            pill_surf = label_font.render(pill_text, True, (220, 195, 90))
            pill_pad_x = _ms(10)
            pill_w = pill_surf.get_width() + pill_pad_x * 2
            pill_h = _ms(20)
            pill_rect = pygame.Rect(
                mx + mw - pad - pill_w,
                cy_y + (row_h - pill_h) // 2 - 1,
                pill_w, pill_h)
            pygame.draw.rect(surface, (50, 50, 65), pill_rect,
                             border_radius=3)
            pygame.draw.rect(surface, (110, 130, 170), pill_rect, 1,
                             border_radius=3)
            surface.blit(pill_surf,
                (pill_rect.x + pill_pad_x,
                 pill_rect.y + (pill_h - pill_surf.get_height()) // 2))
            party_settings_modal_rects.append(
                (pill_rect, {"action": "party_enum_cycle",
                             "key": setting_key,
                             "options": list(options)}))

        elif kind == "button":
            # Label on the left, action pill on the right.
            name_surf = label_font.render(display_label, True,
                                           (220, 220, 230))
            surface.blit(name_surf,
                (mx + pad + _ms(4),
                 cy_y + (row_h - name_surf.get_height()) // 2 - 1))
            btn_text = "Open..."
            btn_surf = label_font.render(btn_text, True, (220, 220, 230))
            btn_pad_x = _ms(10)
            btn_w = btn_surf.get_width() + btn_pad_x * 2
            btn_h = _ms(20)
            btn_rect = pygame.Rect(
                mx + mw - pad - btn_w,
                cy_y + (row_h - btn_h) // 2 - 1,
                btn_w, btn_h)
            pygame.draw.rect(surface, (60, 70, 90), btn_rect,
                             border_radius=3)
            pygame.draw.rect(surface, (140, 160, 200), btn_rect, 1,
                             border_radius=3)
            surface.blit(btn_surf,
                (btn_rect.x + btn_pad_x,
                 btn_rect.y + (btn_h - btn_surf.get_height()) // 2))
            # Look up the action key from the schema so dispatch can
            # invoke it via the action registry.
            schema = _setting_schema(setting_key)
            action_key = (schema or {}).get("action", "")
            party_settings_modal_rects.append(
                (btn_rect, {"action": "party_action",
                            "action_key": action_key}))

        cy_y += row_h

    # Close button at bottom right.
    close_y = my + mh - pad - _ms(24)
    close_rect = pygame.Rect(mx + mw - pad - _ms(70), close_y, _ms(70), _ms(24))
    pygame.draw.rect(surface, (60, 70, 90), close_rect, border_radius=3)
    pygame.draw.rect(surface, (140, 160, 200), close_rect, 1,
                     border_radius=3)
    cl_surf = label_font.render("Close", True, (220, 220, 230))
    surface.blit(cl_surf,
        (close_rect.x + (close_rect.w - cl_surf.get_width()) // 2,
         close_rect.y + (close_rect.h - cl_surf.get_height()) // 2))
    party_settings_modal_rects.append(
        (close_rect, {"action": "party_close"}))


def dispatch_party_settings_click(mx, my):
    """Resolve a click against the party panel modal. Returns True if
    consumed. Reverse-iterates rects so foreground controls beat the
    panel/backdrop catches."""
    global party_settings_modal_open
    global settings_menu_open
    if not party_settings_modal_open:
        return False
    for rect, action in reversed(party_settings_modal_rects):
        if not rect.collidepoint(mx, my):
            continue
        what = action.get("action")
        if what == "party_backdrop":
            party_settings_modal_open = False
            settings_menu_open = True
            return True
        if what == "party_panel_bg":
            return True
        if what == "party_close":
            party_settings_modal_open = False
            settings_menu_open = True
            return True
        if what == "party_toggle":
            key = action["key"]
            cur = bool(setting(key))
            settings[key] = not cur
            apply_setting_side_effects(key, not cur)
            save_settings()
            return True
        if what == "party_enum_cycle":
            key = action["key"]
            options = action.get("options", [])
            if not options:
                return True
            cur = setting(key) or options[0]
            try:
                cur_idx = options.index(cur)
            except ValueError:
                cur_idx = -1
            next_val = options[(cur_idx + 1) % len(options)]
            settings[key] = next_val
            apply_setting_side_effects(key, next_val)
            save_settings()
            return True
        if what == "party_action":
            action_key = action.get("action_key", "")
            handler = _SETTINGS_ACTIONS.get(action_key)
            if callable(handler):
                try:
                    handler()
                except Exception as e:
                    print(f"[OmniWatch] party action {action_key!r}: {e!r}")
            return True
    return False


def _setting_schema(key):
    """Look up a setting's schema entry from SETTINGS_SCHEMA by key.
    Returns the dict or None. Used by the party modal to read enum
    options + action mappings without duplicating that data inline.

    Special case: 'chat_main_char' has DYNAMIC options — the same
    characters shown in the header character dropdown (config-folder
    characters + the current logged-in one). We return a shallow copy of
    the schema with options/option_labels filled in live, so the picker
    always reflects the known characters without persisting a stale list."""
    for entry in SETTINGS_SCHEMA:
        if entry.get("key") == key:
            if key == "chat_main_char":
                names = _mb_known_chars()
                opts = list(names) if names else [""]
                labels = list(names) if names else ["(no characters yet)"]
                dyn = dict(entry)
                dyn["options"] = opts
                dyn["option_labels"] = labels
                return dyn
            return entry
    return None


# ──────────────────────────────────────────────────────────────────────
# Display settings modal — opacity, UI scale, transparent background,
# and a Hide display action. Mirrors the Party Panel modal's style
# but adds int/float spinner rows (minus / value / plus) for the
# numeric settings. The hide-display row is an action button that
# fires _toggle_display_hidden.
# ──────────────────────────────────────────────────────────────────────

# Row table. Tuple shape: (setting_key, display_label, control_kind)
# where control_kind is one of: "int" | "float" | "bool" | "action".
# "action" is special — instead of toggling a setting it fires an
# action handler from _SETTINGS_ACTIONS (the action key is read from
# the row's auxiliary fourth element, present only for action rows).
_DISPLAY_MODAL_ROWS = [
    ("window_opacity",         "Window opacity %",       "int"),
    ("global_ui_scale",        "Global UI scale",        "float"),
    ("transparent_background", "Transparent background", "bool"),
    # show_hide_nub controls whether the floating nub ("eye") renders
    # at all. Off = nub completely hidden; on = nub visible and can be
    # clicked to hide/show the panels. Defaults to on. The earlier
    # toggle here used an action that flipped display_hidden — which
    # hid the panels but left the eye visible, which was the opposite
    # of what was asked for. A direct bool toggle on show_hide_nub
    # makes the row do exactly what its label says.
    ("show_hide_nub",          "Show toggle nub (eye)",  "bool"),
]


def draw_display_settings_modal(surface):
    """Render the Display subdialog if open. Refills
    display_settings_modal_rects each frame with click targets.

    Control rendering:
      int    — label on left, [−] [value] [+] spinner on right.
               min/max/step come from the setting's schema.
      float  — same as int but value formatted as f"{v:.2f}".
      bool   — checkbox + label (whole-row click toggles).
      action — label + [Toggle] pill on right; click runs the action.
    """
    global display_settings_modal_rects
    display_settings_modal_rects = []
    if not display_settings_modal_open:
        return

    g = _menu_g()
    def _ms(v):
        return max(1, round(v * g))
    ctrl_h = _ms(22)
    sw, sh = surface.get_size()
    mw = min(_ms(520), sw - 40)
    title_block_h = _ms(50)
    row_h         = _ms(28)      # slightly taller than party (spinners need it)
    close_block_h = _ms(50)
    pad           = _ms(14)
    mh = title_block_h + len(_DISPLAY_MODAL_ROWS) * row_h + close_block_h
    mh = min(mh, sh - 40)
    mx = (sw - mw) // 2
    my = (sh - mh) // 2

    # Backdrop dim — click closes. Skip the visual fill when
    # transparent_background is on (see currency modal note);
    # click target still registers.
    if not setting("transparent_background"):
        backdrop = pygame.Surface((sw, sh), pygame.SRCALPHA)
        backdrop.fill((0, 0, 0, 150))
        surface.blit(backdrop, (0, 0))
    display_settings_modal_rects.append(
        (pygame.Rect(0, 0, sw, sh), {"action": "disp_backdrop"}))

    # Panel.
    panel = pygame.Rect(mx, my, mw, mh)
    pygame.draw.rect(surface, (24, 28, 36), panel, border_radius=6)
    pygame.draw.rect(surface, (110, 130, 170), panel, 1, border_radius=6)
    display_settings_modal_rects.append(
        (panel, {"action": "disp_panel_bg"}))

    title_font = pygame.font.SysFont("Consolas", _ms(14), bold=True)
    label_font = pygame.font.SysFont("Consolas", _ms(12))
    small_font = pygame.font.SysFont("Consolas", _ms(10), italic=True)

    cy_y = my + pad

    # Title + subtitle.
    t_surf = title_font.render("Display", True, (220, 200, 150))
    surface.blit(t_surf, (mx + pad, cy_y))
    cy_y += t_surf.get_height() + _ms(2)
    sub_surf = small_font.render(
        "Window appearance and visibility controls.",
        True, (160, 160, 175))
    surface.blit(sub_surf, (mx + pad, cy_y))
    cy_y += sub_surf.get_height() + _ms(10)

    for setting_key, display_label, kind in _DISPLAY_MODAL_ROWS:
        row_rect = pygame.Rect(mx + pad, cy_y, mw - 2 * pad, row_h - _ms(2))
        if row_rect.collidepoint(pygame.mouse.get_pos()):
            pygame.draw.rect(surface, (40, 40, 52), row_rect,
                             border_radius=2)

        # Label (always on the left).
        name_surf = label_font.render(display_label, True,
                                       (220, 220, 230))
        surface.blit(name_surf,
            (mx + pad + _ms(4),
             cy_y + (row_h - name_surf.get_height()) // 2 - 1))

        if kind == "bool":
            # Right-side checkbox (mirror Party modal but anchor to
            # the right so labels align with int/float rows above).
            cb_size = _ms(14)
            cb_rect = pygame.Rect(
                mx + mw - pad - cb_size - _ms(4),
                cy_y + (row_h - cb_size) // 2 - 1,
                cb_size, cb_size)
            pygame.draw.rect(surface, (30, 30, 40), cb_rect,
                             border_radius=2)
            pygame.draw.rect(surface, (110, 130, 170), cb_rect, 1,
                             border_radius=2)
            is_on = bool(setting(setting_key))
            if is_on:
                _draw_checkbox_check(surface, cb_rect)
            # Whole-row click toggles.
            display_settings_modal_rects.append(
                (row_rect, {"action": "disp_toggle",
                            "key": setting_key}))

        elif kind in ("int", "float"):
            schema = _setting_schema(setting_key) or {}
            cur = setting(setting_key)
            if cur is None:
                cur = schema.get("default", 0)
            try:
                cur = float(cur) if kind == "float" else int(cur)
            except (TypeError, ValueError):
                cur = float(schema.get("default", 0)) if kind == "float" else int(schema.get("default", 0))
            # Minus button.
            spinner_y = cy_y + (row_h - ctrl_h) // 2 - 1
            minus_w = _ms(22)
            plus_w  = _ms(22)
            # Compute value pill width based on formatted text.
            if kind == "float":
                val_text = f"{cur:.2f}"
            else:
                val_text = f"{cur}"
            val_surf = label_font.render(val_text, True, (220, 195, 90))
            val_pad_x = _ms(10)
            val_w = max(val_surf.get_width() + val_pad_x * 2, _ms(44))
            gap = _ms(4)
            total_spinner_w = minus_w + gap + val_w + gap + plus_w
            right_edge = mx + mw - pad - _ms(4)
            spinner_x  = right_edge - total_spinner_w
            # Render minus.
            minus_rect = pygame.Rect(spinner_x, spinner_y, minus_w, ctrl_h)
            pygame.draw.rect(surface, (50, 50, 65), minus_rect,
                             border_radius=3)
            pygame.draw.rect(surface, (110, 110, 130), minus_rect, 1,
                             border_radius=3)
            m_surf = label_font.render("−", True, (220, 220, 230))
            surface.blit(m_surf,
                (minus_rect.x + (minus_w - m_surf.get_width()) // 2,
                 minus_rect.y + (ctrl_h - m_surf.get_height()) // 2))
            display_settings_modal_rects.append(
                (minus_rect, {"action": "disp_spinner",
                              "key": setting_key,
                              "kind": kind,
                              "delta": -1}))
            # Value pill.
            val_rect = pygame.Rect(minus_rect.right + gap, spinner_y,
                                    val_w, ctrl_h)
            pygame.draw.rect(surface, (30, 30, 40), val_rect,
                             border_radius=3)
            pygame.draw.rect(surface, (110, 130, 170), val_rect, 1,
                             border_radius=3)
            surface.blit(val_surf,
                (val_rect.x + (val_w - val_surf.get_width()) // 2,
                 val_rect.y + (ctrl_h - val_surf.get_height()) // 2))
            # Plus button.
            plus_rect = pygame.Rect(val_rect.right + gap, spinner_y,
                                     plus_w, ctrl_h)
            pygame.draw.rect(surface, (50, 50, 65), plus_rect,
                             border_radius=3)
            pygame.draw.rect(surface, (110, 110, 130), plus_rect, 1,
                             border_radius=3)
            p_surf = label_font.render("+", True, (220, 220, 230))
            surface.blit(p_surf,
                (plus_rect.x + (plus_w - p_surf.get_width()) // 2,
                 plus_rect.y + (ctrl_h - p_surf.get_height()) // 2))
            display_settings_modal_rects.append(
                (plus_rect, {"action": "disp_spinner",
                             "key": setting_key,
                             "kind": kind,
                             "delta": 1}))

        elif kind == "action":
            # Hide display button.
            btn_text = "Toggle"
            btn_surf = label_font.render(btn_text, True, (220, 220, 230))
            btn_pad_x = _ms(12)
            btn_w = btn_surf.get_width() + btn_pad_x * 2
            btn_h = _ms(22)
            btn_rect = pygame.Rect(
                mx + mw - pad - btn_w - _ms(4),
                cy_y + (row_h - btn_h) // 2 - 1,
                btn_w, btn_h)
            pygame.draw.rect(surface, (60, 70, 90), btn_rect,
                             border_radius=3)
            pygame.draw.rect(surface, (140, 160, 200), btn_rect, 1,
                             border_radius=3)
            surface.blit(btn_surf,
                (btn_rect.x + btn_pad_x,
                 btn_rect.y + (btn_h - btn_surf.get_height()) // 2))
            display_settings_modal_rects.append(
                (btn_rect, {"action": "disp_action",
                            "action_key": setting_key}))

        cy_y += row_h

    # Close button.
    close_y = my + mh - pad - _ms(24)
    close_rect = pygame.Rect(mx + mw - pad - _ms(70), close_y, _ms(70), _ms(24))
    pygame.draw.rect(surface, (60, 70, 90), close_rect, border_radius=3)
    pygame.draw.rect(surface, (140, 160, 200), close_rect, 1,
                     border_radius=3)
    cl_surf = label_font.render("Close", True, (220, 220, 230))
    surface.blit(cl_surf,
        (close_rect.x + (close_rect.w - cl_surf.get_width()) // 2,
         close_rect.y + (close_rect.h - cl_surf.get_height()) // 2))
    display_settings_modal_rects.append(
        (close_rect, {"action": "disp_close"}))


def dispatch_display_settings_click(mx, my):
    """Resolve a click against the Display modal. Returns True if
    consumed. Reverse-iterates rects so foreground controls beat the
    panel/backdrop catches."""
    global display_settings_modal_open
    global settings_menu_open
    if not display_settings_modal_open:
        return False
    for rect, action in reversed(display_settings_modal_rects):
        if not rect.collidepoint(mx, my):
            continue
        what = action.get("action")
        if what == "disp_backdrop":
            display_settings_modal_open = False
            settings_menu_open = True
            return True
        if what == "disp_panel_bg":
            return True
        if what == "disp_close":
            display_settings_modal_open = False
            settings_menu_open = True
            return True
        if what == "disp_toggle":
            key = action["key"]
            cur = bool(setting(key))
            # Use set_setting() — the canonical path used by the old
            # settings dropdown. It coerces through the schema,
            # persists to disk, AND fires apply_setting_side_effects
            # in one step. Going manually (settings[key] = v + apply
            # + save) is functionally similar but skips coercion,
            # which can break side-effect handlers that expect the
            # post-coerce type. transparent_background not visually
            # responding was the symptom.
            set_setting(key, not cur)
            return True
        if what == "disp_spinner":
            key   = action["key"]
            kind  = action["kind"]
            delta = action["delta"]
            schema = _setting_schema(key) or {}
            cur = setting(key)
            if cur is None:
                cur = schema.get("default", 0)
            step  = schema.get("step", 1)
            lo    = schema.get("min", 0)
            hi    = schema.get("max", 100)
            try:
                if kind == "float":
                    cur_v = float(cur)
                    new_v = cur_v + float(step) * delta
                    new_v = max(float(lo), min(float(hi), new_v))
                    # Round to step precision so 1.0 + 0.25 doesn't
                    # turn into 1.2499999999 due to fp accumulation.
                    new_v = round(new_v / float(step)) * float(step)
                    new_v = round(new_v, 4)
                else:
                    cur_v = int(cur)
                    new_v = cur_v + int(step) * delta
                    new_v = max(int(lo), min(int(hi), new_v))
            except (TypeError, ValueError):
                return True
            if new_v != cur:
                set_setting(key, new_v)
            return True
        if what == "disp_action":
            action_key = action.get("action_key", "")
            handler = _SETTINGS_ACTIONS.get(action_key)
            if callable(handler):
                try:
                    handler()
                except Exception as e:
                    print(f"[OmniWatch] display action {action_key!r}: {e!r}")
            return True
    return False


def _draw_modal_row(surface, row_rect, kind, key, display_label,
                     mouse_pos, click_rects, label_font, action_prefix):
    """Generic Configure-modal row renderer. Supports bool, int,
    float, enum, action. Appends click targets to `click_rects` with
    payloads keyed off `action_prefix` so each modal's dispatcher can
    route them to its own state. Used by the Header and Inventory
    modals; older modals (Currency, Party, Display) inline their own
    row code and don't go through this helper.

    Layout: label on the left, control on the right. Hover
    highlight on the whole row. Schema (min/max/step, options,
    option_labels, button_text, action) is read from
    `_setting_schema(key)` so callers only need to specify the kind
    and the display label.
    """
    g = _menu_g()
    def _ms(v):
        return max(1, round(v * g))
    ctrl_h = _ms(22)
    # Hover highlight.
    if row_rect.collidepoint(mouse_pos):
        pygame.draw.rect(surface, (40, 40, 52), row_rect,
                         border_radius=2)
    # Label.
    name_surf = label_font.render(display_label, True, (220, 220, 230))
    surface.blit(name_surf,
        (row_rect.x + _ms(4),
         row_rect.y + (row_rect.h - name_surf.get_height()) // 2))

    schema = _setting_schema(key) or {}

    if kind == "bool":
        cb_size = _ms(14)
        cb_rect = pygame.Rect(
            row_rect.right - _ms(4) - cb_size,
            row_rect.y + (row_rect.h - cb_size) // 2,
            cb_size, cb_size)
        pygame.draw.rect(surface, (30, 30, 40), cb_rect,
                         border_radius=2)
        pygame.draw.rect(surface, (110, 130, 170), cb_rect, 1,
                         border_radius=2)
        if bool(setting(key)):
            _draw_checkbox_check(surface, cb_rect)
        click_rects.append((row_rect.copy(),
            {"action": f"{action_prefix}_toggle", "key": key}))

    elif kind in ("int", "float"):
        cur = setting(key)
        if cur is None:
            cur = schema.get("default", 0)
        try:
            cur_val = float(cur) if kind == "float" else int(cur)
        except (TypeError, ValueError):
            cur_val = float(schema.get("default", 0)) if kind == "float" else int(schema.get("default", 0))
        # Format the value text.
        if kind == "float":
            val_text = f"{cur_val:.2f}"
        else:
            val_text = f"{cur_val}"
        val_surf = label_font.render(val_text, True, (220, 195, 90))
        val_pad_x = _ms(10)
        val_w = max(val_surf.get_width() + val_pad_x * 2, _ms(56))
        minus_w = _ms(22)
        plus_w  = _ms(22)
        gap = _ms(4)
        total_w = minus_w + gap + val_w + gap + plus_w
        right_edge = row_rect.right - _ms(4)
        spinner_x = right_edge - total_w
        spinner_y = row_rect.y + (row_rect.h - ctrl_h) // 2
        # Minus.
        minus_rect = pygame.Rect(spinner_x, spinner_y, minus_w, ctrl_h)
        pygame.draw.rect(surface, (50, 50, 65), minus_rect,
                         border_radius=3)
        pygame.draw.rect(surface, (110, 110, 130), minus_rect, 1,
                         border_radius=3)
        m_surf = label_font.render("−", True, (220, 220, 230))
        surface.blit(m_surf,
            (minus_rect.x + (minus_w - m_surf.get_width()) // 2,
             minus_rect.y + (ctrl_h - m_surf.get_height()) // 2))
        click_rects.append((minus_rect,
            {"action": f"{action_prefix}_spinner", "key": key,
             "kind": kind, "delta": -1}))
        # Value pill.
        val_rect = pygame.Rect(minus_rect.right + gap, spinner_y,
                                val_w, ctrl_h)
        pygame.draw.rect(surface, (30, 30, 40), val_rect,
                         border_radius=3)
        pygame.draw.rect(surface, (110, 130, 170), val_rect, 1,
                         border_radius=3)
        surface.blit(val_surf,
            (val_rect.x + (val_w - val_surf.get_width()) // 2,
             val_rect.y + (ctrl_h - val_surf.get_height()) // 2))
        # Plus.
        plus_rect = pygame.Rect(val_rect.right + gap, spinner_y,
                                 plus_w, ctrl_h)
        pygame.draw.rect(surface, (50, 50, 65), plus_rect,
                         border_radius=3)
        pygame.draw.rect(surface, (110, 110, 130), plus_rect, 1,
                         border_radius=3)
        p_surf = label_font.render("+", True, (220, 220, 230))
        surface.blit(p_surf,
            (plus_rect.x + (plus_w - p_surf.get_width()) // 2,
             plus_rect.y + (ctrl_h - p_surf.get_height()) // 2))
        click_rects.append((plus_rect,
            {"action": f"{action_prefix}_spinner", "key": key,
             "kind": kind, "delta": 1}))

    elif kind == "enum":
        options       = schema.get("options") or []
        option_labels = schema.get("option_labels") or options
        cur = setting(key) or (options[0] if options else "")
        try:
            idx = options.index(cur)
        except (ValueError, TypeError):
            idx = 0
        cur_label = option_labels[idx] if idx < len(option_labels) else str(cur)
        # Layout: [<] [ value ] [>] right-aligned. The arrows are
        # symmetric to the spinner's − / + buttons (same dimensions
        # and styling) so enum rows visually align with int/float
        # rows above them.
        arrow_w  = _ms(22)
        gap      = _ms(4)
        pill_h   = _ms(22)
        pill_surf = label_font.render(cur_label, True, (220, 195, 90))
        pill_pad_x = _ms(10)
        pill_w = max(pill_surf.get_width() + pill_pad_x * 2, _ms(80))
        total_w  = arrow_w + gap + pill_w + gap + arrow_w
        right_edge = row_rect.right - _ms(4)
        ctl_x = right_edge - total_w
        ctl_y = row_rect.y + (row_rect.h - pill_h) // 2
        # Left arrow (prev).
        left_rect = pygame.Rect(ctl_x, ctl_y, arrow_w, pill_h)
        pygame.draw.rect(surface, (50, 50, 65), left_rect,
                         border_radius=3)
        pygame.draw.rect(surface, (110, 110, 130), left_rect, 1,
                         border_radius=3)
        lt_surf = label_font.render("<", True, (220, 220, 230))
        surface.blit(lt_surf,
            (left_rect.x + (arrow_w - lt_surf.get_width()) // 2,
             left_rect.y + (pill_h - lt_surf.get_height()) // 2))
        click_rects.append((left_rect,
            {"action": f"{action_prefix}_enum_cycle",
             "key": key, "options": list(options), "delta": -1}))
        # Value pill (center).
        pill_rect = pygame.Rect(left_rect.right + gap, ctl_y,
                                 pill_w, pill_h)
        pygame.draw.rect(surface, (30, 30, 40), pill_rect,
                         border_radius=3)
        pygame.draw.rect(surface, (110, 130, 170), pill_rect, 1,
                         border_radius=3)
        surface.blit(pill_surf,
            (pill_rect.x + (pill_w - pill_surf.get_width()) // 2,
             pill_rect.y + (pill_h - pill_surf.get_height()) // 2))
        # Right arrow (next).
        right_rect = pygame.Rect(pill_rect.right + gap, ctl_y,
                                  arrow_w, pill_h)
        pygame.draw.rect(surface, (50, 50, 65), right_rect,
                         border_radius=3)
        pygame.draw.rect(surface, (110, 110, 130), right_rect, 1,
                         border_radius=3)
        rt_surf = label_font.render(">", True, (220, 220, 230))
        surface.blit(rt_surf,
            (right_rect.x + (arrow_w - rt_surf.get_width()) // 2,
             right_rect.y + (pill_h - rt_surf.get_height()) // 2))
        click_rects.append((right_rect,
            {"action": f"{action_prefix}_enum_cycle",
             "key": key, "options": list(options), "delta": 1}))

    elif kind == "action":
        btn_text   = schema.get("button_text") or "Open..."
        action_key = schema.get("action", "")
        btn_surf = label_font.render(btn_text, True, (220, 220, 230))
        btn_pad_x = _ms(12)
        btn_w = btn_surf.get_width() + btn_pad_x * 2
        btn_h = _ms(22)
        btn_rect = pygame.Rect(
            row_rect.right - _ms(4) - btn_w,
            row_rect.y + (row_rect.h - btn_h) // 2,
            btn_w, btn_h)
        pygame.draw.rect(surface, (60, 70, 90), btn_rect,
                         border_radius=3)
        pygame.draw.rect(surface, (140, 160, 200), btn_rect, 1,
                         border_radius=3)
        surface.blit(btn_surf,
            (btn_rect.x + btn_pad_x,
             btn_rect.y + (btn_h - btn_surf.get_height()) // 2))
        click_rects.append((btn_rect,
            {"action": f"{action_prefix}_action",
             "action_key": action_key}))


def _dispatch_modal_row_action(payload, action_prefix):
    """Shared dispatcher for row actions. Returns True if the payload
    was consumed; the caller is still responsible for closing/backdrop
    actions (those vary per modal). Routes by the action suffix —
    `_toggle`, `_spinner`, `_enum_cycle`, `_action`.

    Called from each modal's dispatch fn after it's checked for its
    own backdrop/panel/close payloads."""
    what = payload.get("action", "")
    if not what.startswith(action_prefix + "_"):
        return False
    suffix = what[len(action_prefix) + 1:]
    if suffix == "toggle":
        key = payload["key"]
        cur = bool(setting(key))
        set_setting(key, not cur)
        return True
    if suffix == "spinner":
        key   = payload["key"]
        kind  = payload["kind"]
        delta = payload["delta"]
        schema = _setting_schema(key) or {}
        cur = setting(key)
        if cur is None:
            cur = schema.get("default", 0)
        step = schema.get("step", 1)
        lo   = schema.get("min", 0)
        hi   = schema.get("max", 100)
        try:
            if kind == "float":
                cur_v = float(cur)
                new_v = cur_v + float(step) * delta
                new_v = max(float(lo), min(float(hi), new_v))
                new_v = round(new_v / float(step)) * float(step)
                new_v = round(new_v, 4)
            else:
                cur_v = int(cur)
                new_v = cur_v + int(step) * delta
                new_v = max(int(lo), min(int(hi), new_v))
        except (TypeError, ValueError):
            return True
        if new_v != cur:
            set_setting(key, new_v)
        return True
    if suffix == "enum_cycle":
        key = payload["key"]
        options = payload.get("options", [])
        if not options:
            return True
        delta = int(payload.get("delta", 1))
        cur = setting(key) or options[0]
        try:
            idx = options.index(cur)
        except ValueError:
            idx = 0
        next_idx = (idx + delta) % len(options)
        set_setting(key, options[next_idx])
        return True
    if suffix == "action":
        action_key = payload.get("action_key", "")
        handler = _SETTINGS_ACTIONS.get(action_key)
        if callable(handler):
            try:
                handler()
            except Exception as e:
                print(f"[OmniWatch] modal action {action_key!r}: {e!r}")
        return True
    return False


# ──────────────────────────────────────────────────────────────────────
# Header settings modal — reset zone timer, Vana'diel time offset,
# server picker, points tracker on/off + type. Uses _draw_modal_row /
# _dispatch_modal_row_action so the body is mostly just the row
# definitions.
# ──────────────────────────────────────────────────────────────────────
_HEADER_MODAL_ROWS = [
    ("header_autohide",      "Auto-hide header",        "bool"),
    ("header_position",      "Header position",         "enum"),
    ("show_time",            "Show time",               "bool"),
    ("clock_cycle_enabled",  "Cycle VT / OS time",      "bool"),
    ("clock_cycle_sec",      "VT/OS cycle seconds",     "int"),
    ("vana_time_offset_min", "Adjust Vana'diel time",   "int"),
    ("show_weather",         "Show weather",            "bool"),
    ("show_events",          "Show events",             "bool"),
    ("show_location",        "Show location",           "bool"),
    ("show_clock_seconds",   "Show clock seconds",      "bool"),
    ("clock_timezone",       "OS clock time zone",      "enum"),
    ("chat_main_char",       "Chat main character",     "enum"),
    ("ffxi_server",          "Server",                  "enum"),
    ("show_header_points",   "Show points tracker",     "bool"),
    ("header_points_focus",  "Points type",             "enum"),
]


def draw_header_settings_modal(surface):
    """Render the Header subdialog if open."""
    global header_settings_modal_rects
    header_settings_modal_rects = []
    if not header_settings_modal_open:
        return

    g = _menu_g()
    def _ms(v):
        return max(1, round(v * g))
    sw, sh = surface.get_size()
    mw = min(_ms(520), sw - 40)
    title_block_h = _ms(50)
    row_h = _ms(28)
    close_block_h = _ms(50)
    pad = _ms(14)
    mh = title_block_h + len(_HEADER_MODAL_ROWS) * row_h + close_block_h
    mh = min(mh, sh - 40)
    mx = (sw - mw) // 2
    my = (sh - mh) // 2

    # Backdrop (skip visual fill when transparent_background is on
    # so the LWA_COLORKEY compositor filter still triggers).
    if not setting("transparent_background"):
        bd = pygame.Surface((sw, sh), pygame.SRCALPHA)
        bd.fill((0, 0, 0, 150))
        surface.blit(bd, (0, 0))
    header_settings_modal_rects.append(
        (pygame.Rect(0, 0, sw, sh), {"action": "head_backdrop"}))

    panel = pygame.Rect(mx, my, mw, mh)
    pygame.draw.rect(surface, (24, 28, 36), panel, border_radius=6)
    pygame.draw.rect(surface, (110, 130, 170), panel, 1, border_radius=6)
    header_settings_modal_rects.append(
        (panel, {"action": "head_panel_bg"}))

    title_font = pygame.font.SysFont("Consolas", _ms(14), bold=True)
    label_font = pygame.font.SysFont("Consolas", _ms(12))
    small_font = pygame.font.SysFont("Consolas", _ms(10), italic=True)

    cy_y = my + pad
    t_surf = title_font.render("Header", True, (220, 200, 150))
    surface.blit(t_surf, (mx + pad, cy_y))
    cy_y += t_surf.get_height() + _ms(2)
    sub_surf = small_font.render(
        "Header items: zone timer, Vana'diel clock, server, points.",
        True, (160, 160, 175))
    surface.blit(sub_surf, (mx + pad, cy_y))
    cy_y += sub_surf.get_height() + _ms(10)

    mouse_pos = pygame.mouse.get_pos()
    for key, label, kind in _HEADER_MODAL_ROWS:
        row_rect = pygame.Rect(mx + pad, cy_y, mw - 2 * pad, row_h - _ms(2))
        _draw_modal_row(surface, row_rect, kind, key, label,
                         mouse_pos, header_settings_modal_rects,
                         label_font, "head")
        cy_y += row_h

    # Close.
    close_y = my + mh - pad - _ms(24)
    close_rect = pygame.Rect(mx + mw - pad - _ms(70), close_y, _ms(70), _ms(24))
    pygame.draw.rect(surface, (60, 70, 90), close_rect, border_radius=3)
    pygame.draw.rect(surface, (140, 160, 200), close_rect, 1,
                     border_radius=3)
    cl_surf = label_font.render("Close", True, (220, 220, 230))
    surface.blit(cl_surf,
        (close_rect.x + (close_rect.w - cl_surf.get_width()) // 2,
         close_rect.y + (close_rect.h - cl_surf.get_height()) // 2))
    header_settings_modal_rects.append(
        (close_rect, {"action": "head_close"}))


def dispatch_header_settings_click(mx, my):
    global header_settings_modal_open
    global settings_menu_open
    if not header_settings_modal_open:
        return False
    for rect, action in reversed(header_settings_modal_rects):
        if not rect.collidepoint(mx, my):
            continue
        what = action.get("action", "")
        if what == "head_backdrop":
            header_settings_modal_open = False
            settings_menu_open = True
            return True
        if what == "head_panel_bg":
            return True
        if what == "head_close":
            header_settings_modal_open = False
            settings_menu_open = True
            return True
        if _dispatch_modal_row_action(action, "head"):
            return True
    return False


