# Per-subdialog UI state. Initialized once at module load. Each entry
# has open=False and rects=[]. The factory draws + dispatches against
# this dict.
_subdialog_states = {k: {"open": False, "rects": []}
                     for k in _SUBDIALOG_CONFIGS}


def _open_subdialog(state_key):
    """Open one of the generic Configure subdialogs by key. Closes the
    parent settings dropdown so the modal isn't visually competing."""
    if state_key not in _subdialog_states:
        return
    _subdialog_states[state_key]["open"] = True
    global settings_menu_open
    settings_menu_open = False


def _draw_subdialog(surface, state_key):
    """Render the named subdialog if its open flag is set. Mirrors
    the Statistics modal's structure (per-row optional helpers,
    transparent-bg-aware backdrop) so all factory modals share one
    layout style."""
    state = _subdialog_states.get(state_key)
    if state is None:
        return
    state["rects"] = []
    if not state["open"]:
        return
    cfg = _SUBDIALOG_CONFIGS[state_key]
    rows    = cfg["rows"]
    helpers = cfg.get("helpers", {}) or {}
    title   = cfg["title"]
    subtitle = cfg.get("subtitle", "")

    g = _menu_g()
    def _ms(v):
        return max(1, round(v * g))
    sw, sh = surface.get_size()
    mw = min(_ms(520), sw - 40)
    title_block_h = _ms(50)
    row_h         = _ms(28)
    helper_h      = _ms(16)
    close_block_h = _ms(50)
    pad           = _ms(14)
    rows_total_h = sum(
        row_h + (helper_h if helpers.get(key) else 0)
        for key, _, _ in rows)
    mh = title_block_h + rows_total_h + close_block_h
    mh = min(mh, sh - 40)
    mx = (sw - mw) // 2
    my = (sh - mh) // 2

    # Backdrop dim — skip fill when transparent_background is on.
    if not setting("transparent_background"):
        bd = pygame.Surface((sw, sh), pygame.SRCALPHA)
        bd.fill((0, 0, 0, 150))
        surface.blit(bd, (0, 0))
    state["rects"].append(
        (pygame.Rect(0, 0, sw, sh),
         {"action": f"{state_key}_backdrop"}))

    panel = pygame.Rect(mx, my, mw, mh)
    pygame.draw.rect(surface, (24, 28, 36), panel, border_radius=6)
    pygame.draw.rect(surface, (110, 130, 170), panel, 1, border_radius=6)
    state["rects"].append(
        (panel, {"action": f"{state_key}_panel_bg"}))

    title_font = pygame.font.SysFont("Consolas", _ms(14), bold=True)
    label_font = pygame.font.SysFont("Consolas", _ms(12))
    small_font = pygame.font.SysFont("Consolas", _ms(10), italic=True)

    cy_y = my + pad
    t_surf = title_font.render(title, True, (220, 200, 150))
    surface.blit(t_surf, (mx + pad, cy_y))
    cy_y += t_surf.get_height() + _ms(2)
    if subtitle:
        sub_surf = small_font.render(subtitle, True, (160, 160, 175))
        surface.blit(sub_surf, (mx + pad, cy_y))
        cy_y += sub_surf.get_height() + _ms(10)
    else:
        cy_y += _ms(10)

    mouse_pos = pygame.mouse.get_pos()
    for key, label, kind in rows:
        row_rect = pygame.Rect(mx + pad, cy_y, mw - 2 * pad, row_h - _ms(2))
        _draw_modal_row(surface, row_rect, kind, key, label,
                         mouse_pos, state["rects"],
                         label_font, state_key)
        cy_y += row_h
        helper_text = helpers.get(key)
        if helper_text:
            h_surf = small_font.render(helper_text, True,
                                        (150, 155, 170))
            surface.blit(h_surf, (mx + pad + _ms(8), cy_y))
            cy_y += helper_h

    close_y = my + mh - pad - _ms(24)
    close_rect = pygame.Rect(mx + mw - pad - _ms(70), close_y, _ms(70), _ms(24))
    pygame.draw.rect(surface, (60, 70, 90), close_rect, border_radius=3)
    pygame.draw.rect(surface, (140, 160, 200), close_rect, 1,
                     border_radius=3)
    cl_surf = label_font.render("Close", True, (220, 220, 230))
    surface.blit(cl_surf,
        (close_rect.x + (close_rect.w - cl_surf.get_width()) // 2,
         close_rect.y + (close_rect.h - cl_surf.get_height()) // 2))
    state["rects"].append(
        (close_rect, {"action": f"{state_key}_close"}))


def _dispatch_subdialog(state_key, mx, my):
    """Resolve a click against the named subdialog. Returns True if
    consumed. Mirrors the Statistics dispatcher's branch order:
    backdrop / panel_bg / close → then defer to the shared row
    dispatcher."""
    global settings_menu_open
    state = _subdialog_states.get(state_key)
    if state is None or not state["open"]:
        return False
    for rect, action in reversed(state["rects"]):
        if not rect.collidepoint(mx, my):
            continue
        what = action.get("action", "")
        if what == f"{state_key}_backdrop":
            state["open"] = False
            settings_menu_open = True
            return True
        if what == f"{state_key}_panel_bg":
            return True
        if what == f"{state_key}_close":
            state["open"] = False
            settings_menu_open = True
            return True
        if _dispatch_modal_row_action(action, state_key):
            return True
    return False


def draw_checklist_modal(surface):
    """Render the checklist modal popup if open. Layout:
      ┌────────────────────────────────────┐
      │ [Allies][Spells][Transport][Quests]│  tab bar
      ├────────────────────────────────────┤
      │  < Trusts        42 / 87       >   │  header (category cycler)
      ├────────────────────────────────────┤
      │  ✓  Apururu                        │  rows (scrollable)
      │  M  Babban Ny Mheillea             │
      │  ☐  Cherukiki                      │
      │  ...                                │
      └────────────────────────────────────┘
    Click the box to toggle manual check. Click the label to open
    BG-wiki for that row. Click outside the panel to close. Click
    arrows to cycle categories within the current tab. Click a tab
    to switch to its first category. Mouse wheel scrolls.

    Refills _checklist_click_rects each frame with hit-test targets.
    Each entry is (pygame.Rect, {"action": <kind>, ...payload}). Kinds:
      'cl_backdrop'  — outside-click close
      'cl_panel_bg'  — swallow misclicks inside panel
      'cl_tab'       — top-level tab button; payload has 'tab_idx'
      'cl_arrow'     — header arrow; payload has 'direction' ∈ {-1, +1}
      'cl_box'       — checkbox column; payload has 'item_key'
      'cl_label'     — row label (BG-wiki link); payload has 'url'
    """
    global _checklist_click_rects, _checklist_modal_rect
    _checklist_click_rects = []
    _checklist_modal_rect = None
    if not checklist_modal_open:
        return
    if not CHECKLIST_TABS:
        return
    cat = _checklist_active_category()
    if cat is None or not callable(cat.get("row_iter")):
        return
    rows = cat["row_iter"]()
    is_checked = cat["is_checked"]

    sw, sh = surface.get_size()
    mw = min(460, sw - 60)
    mh = min(520, sh - 60)
    mx = (sw - mw) // 2
    my = (sh - mh) // 2

    # Backdrop dim — also serves as the outside-click target.
    backdrop = pygame.Surface((sw, sh), pygame.SRCALPHA)
    backdrop.fill((0, 0, 0, 150))
    surface.blit(backdrop, (0, 0))
    _checklist_click_rects.append(
        (pygame.Rect(0, 0, sw, sh), {"action": "cl_backdrop"}))

    # Panel.
    panel = pygame.Rect(mx, my, mw, mh)
    _checklist_modal_rect = panel
    pygame.draw.rect(surface, (24, 28, 36), panel, border_radius=6)
    pygame.draw.rect(surface, (110, 130, 170), panel, 1, border_radius=6)
    # Swallow misclicks inside panel so they don't reach the backdrop.
    _checklist_click_rects.append(
        (panel, {"action": "cl_panel_bg"}))

    # Fonts.
    title_font = pygame.font.SysFont("Consolas", 16, bold=True)
    count_font = pygame.font.SysFont("Consolas", 13)
    row_font   = pygame.font.SysFont("Consolas", 13)
    small_font = pygame.font.SysFont("Consolas", 11, italic=True)

    pad = 14

    # ── Tab bar (top-level navigation) ─────────────────────────────────
    # Auto-sized tab buttons (width = label-text width + horizontal
    # padding) so labels like "Weapon Skills" and "Transportation"
    # never get squeezed. When the total width of all tabs exceeds the
    # modal's inner width, the strip becomes horizontally scrollable
    # with arrow buttons at each end — same pattern as the chat-panel
    # tab strip. Active tab is highlighted; clicking a tab switches the
    # active category set and resets the per-tab category index +
    # scroll.
    global checklist_tab_hscroll
    tab_h = 26
    tab_band_rect = pygame.Rect(mx, my, mw, tab_h)
    pygame.draw.rect(surface, (28, 32, 42), tab_band_rect,
                     border_radius=6)
    # Bottom edge separator.
    pygame.draw.line(surface, (60, 72, 92),
                     (mx, my + tab_h), (mx + mw, my + tab_h))
    tab_font = pygame.font.SysFont("Consolas", 12, bold=True)
    mpos_tabs = pygame.mouse.get_pos()

    # ── Measure every tab first ────────────────────────────────────
    # We need the total width up front to know whether the strip
    # overflows (and thus whether to show scroll arrows). Tab widths
    # are independent — each is sized to fit its own label.
    tab_pad_x = 14   # horizontal padding inside each tab button
    tab_gap   = 0    # tab buttons sit edge-to-edge (no inter-tab gap)
    tab_meta = []    # list of (ti, label, tab_w)
    for ti, tab in enumerate(CHECKLIST_TABS):
        name_w = tab_font.size(tab["label"])[0]
        t_w = name_w + tab_pad_x * 2
        tab_meta.append((ti, tab["label"], t_w))
    total_tabs_w = (sum(m[2] for m in tab_meta)
                    + tab_gap * max(0, len(tab_meta) - 1))

    # ── Reserve arrow zones / compute the scrollable strip ─────────
    arrow_w  = tab_h            # square arrow buttons sized to tab height
    overflow = total_tabs_w > mw

    # Always reserve space for the left/right arrows. They render
    # regardless of whether the tab strip overflows — when all tabs
    # fit, the arrows still act as a "previous tab / next tab"
    # navigator (handy on mobile-feeling clicks where the user wants
    # arrow keys rather than aiming at small tab buttons). When the
    # strip DOES overflow, the same arrows additionally drive
    # horizontal scroll-into-view via the auto-scroll logic below.
    inner_left  = mx + arrow_w
    inner_right = mx + mw - arrow_w
    inner_w     = inner_right - inner_left
    max_scroll  = max(0, total_tabs_w - inner_w) if overflow else 0
    if overflow:
        # Auto-scroll: if the currently active tab would land off-
        # screen, slide the strip so it's visible. Keeps the active
        # tab in view across tab switches without forcing the user to
        # hunt for it manually.
        if 0 <= checklist_current_tab < len(tab_meta):
            active_x0 = sum(m[2] + tab_gap for m in tab_meta[:checklist_current_tab])
            active_w  = tab_meta[checklist_current_tab][2]
            active_x1 = active_x0 + active_w
            if active_x0 < checklist_tab_hscroll:
                checklist_tab_hscroll = active_x0
            elif active_x1 > checklist_tab_hscroll + inner_w:
                checklist_tab_hscroll = active_x1 - inner_w
        # Clamp persisted hscroll into range.
        if checklist_tab_hscroll < 0:
            checklist_tab_hscroll = 0
        elif checklist_tab_hscroll > max_scroll:
            checklist_tab_hscroll = max_scroll
        clip_left, clip_w = inner_left, inner_w
        tab_x0 = inner_left - checklist_tab_hscroll
    else:
        # Strip fits — no horizontal scroll, just center the tabs
        # within the inner area (between the always-present arrows).
        checklist_tab_hscroll = 0
        clip_left, clip_w = inner_left, inner_w
        tab_x0 = inner_left + max(0, (inner_w - total_tabs_w) // 2)

    # ── Draw tabs (clipped to the visible inner strip) ─────────────
    prev_clip = surface.get_clip()
    surface.set_clip(pygame.Rect(clip_left, my, clip_w, tab_h))
    tx = tab_x0
    for (ti, label, t_w) in tab_meta:
        t_rect = pygame.Rect(tx, my, t_w, tab_h)
        is_active = (ti == checklist_current_tab)
        is_hover  = t_rect.collidepoint(mpos_tabs) and not is_active
        if is_active:
            bg_col = (52, 62, 82)
            fg_col = (235, 220, 160)
        elif is_hover:
            bg_col = (38, 44, 58)
            fg_col = (210, 215, 225)
        else:
            bg_col = (28, 32, 42)
            fg_col = (170, 180, 200)
        # Skip drawing tabs fully outside the visible strip — the clip
        # would hide them anyway, but the early-out also avoids needless
        # surface allocations for the off-screen ones.
        if tx + t_w >= clip_left and tx <= clip_left + clip_w:
            if is_active or is_hover:
                inner = t_rect.inflate(-2, -2)
                pygame.draw.rect(surface, bg_col, inner, border_radius=4)
            lbl = tab_font.render(label, True, fg_col)
            surface.blit(lbl,
                (t_rect.centerx - lbl.get_width() // 2,
                 t_rect.centery - lbl.get_height() // 2))
        # Hit-target: clamp to the visible portion so a half-scrolled
        # edge tab still clicks correctly AND clicks inside the arrow
        # zones don't fall through to an off-screen tab beneath them.
        vis_l = max(tx, clip_left)
        vis_r = min(tx + t_w, clip_left + clip_w)
        if vis_r > vis_l:
            _checklist_click_rects.append(
                (pygame.Rect(vis_l, my, vis_r - vis_l, tab_h),
                 {"action": "cl_tab", "tab_idx": ti}))
        tx += t_w + tab_gap
    surface.set_clip(prev_clip)

    # ── Tab-nav arrows (always rendered) ───────────────────────────
    # Click semantics: arrows step the ACTIVE TAB by ±1 (cycling at
    # the ends, see cl_tab_nav handler). When the strip overflows the
    # active-tab change naturally triggers scroll-into-view via the
    # block above. Arrow color fades when there's no neighboring tab
    # to step to.
    n_tabs = len(tab_meta)
    cur_ti = checklist_current_tab
    has_prev = (n_tabs > 1 and cur_ti > 0)
    has_next = (n_tabs > 1 and cur_ti < n_tabs - 1)
    # Left arrow.
    l_rect = pygame.Rect(mx, my, arrow_w, tab_h)
    pygame.draw.rect(surface, (28, 32, 42), l_rect)
    pygame.draw.line(surface, (60, 72, 92),
                     (l_rect.right, my), (l_rect.right, my + tab_h))
    l_col = (220, 230, 250) if has_prev else (90, 95, 105)
    pygame.draw.polygon(
        surface, l_col,
        [(l_rect.x + l_rect.w * 3 // 5, l_rect.y + 5),
         (l_rect.x + l_rect.w * 2 // 5, l_rect.centery),
         (l_rect.x + l_rect.w * 3 // 5, l_rect.bottom - 5)])
    _checklist_click_rects.append(
        (l_rect, {"action": "cl_tab_nav", "direction": -1}))
    # Right arrow.
    r_rect = pygame.Rect(mx + mw - arrow_w, my, arrow_w, tab_h)
    pygame.draw.rect(surface, (28, 32, 42), r_rect)
    pygame.draw.line(surface, (60, 72, 92),
                     (r_rect.x, my), (r_rect.x, my + tab_h))
    r_col = (220, 230, 250) if has_next else (90, 95, 105)
    pygame.draw.polygon(
        surface, r_col,
        [(r_rect.x + r_rect.w * 2 // 5, r_rect.y + 5),
         (r_rect.x + r_rect.w * 3 // 5, r_rect.centery),
         (r_rect.x + r_rect.w * 2 // 5, r_rect.bottom - 5)])
    _checklist_click_rects.append(
        (r_rect, {"action": "cl_tab_nav", "direction": +1}))

    # ── Header: < label    X / Y    > ──────────────────────────────────
    # Sits just below the tab bar; same band geometry as before but
    # offset by tab_h.
    header_h = 36
    header_rect = pygame.Rect(mx, my + tab_h, mw, header_h)
    # Subtle header background to separate from list.
    pygame.draw.rect(surface, (32, 38, 50),
                     header_rect)
    pygame.draw.line(surface, (60, 72, 92),
                     (mx, my + tab_h + header_h),
                     (mx + mw, my + tab_h + header_h))

    # Compute X / Y. X = union of auto and manual sets, intersected
    # with the master list so unknown stray names don't inflate the count.
    sets = checklist_known.get(cat["key"], {})
    auto = sets.get("auto", set())
    manual = sets.get("manual", set())
    known_keys = {k for k, _disp in rows}
    have = (auto | manual) & known_keys
    x_count = len(have)
    y_count = len(known_keys)

    # The header band's Y origin shifts down by the tab bar height so
    # arrows / title don't draw on top of the tab buttons.
    hdr_top = my + tab_h

    # Left arrow.
    arr_w = 28
    larrow_rect = pygame.Rect(mx + 6, hdr_top + 6, arr_w, header_h - 12)
    is_l_hover = larrow_rect.collidepoint(pygame.mouse.get_pos())
    arr_col = (220, 230, 250) if is_l_hover else (160, 180, 210)
    pygame.draw.polygon(
        surface, arr_col,
        [(larrow_rect.x + 18, larrow_rect.y + 4),
         (larrow_rect.x + 8,  larrow_rect.centery),
         (larrow_rect.x + 18, larrow_rect.bottom - 4)])
    _checklist_click_rects.append(
        (larrow_rect, {"action": "cl_arrow", "direction": -1}))

    # Right arrow.
    rarrow_rect = pygame.Rect(mx + mw - arr_w - 6, hdr_top + 6,
                              arr_w, header_h - 12)
    is_r_hover = rarrow_rect.collidepoint(pygame.mouse.get_pos())
    arr_col = (220, 230, 250) if is_r_hover else (160, 180, 210)
    pygame.draw.polygon(
        surface, arr_col,
        [(rarrow_rect.right - 18, rarrow_rect.y + 4),
         (rarrow_rect.right - 8,  rarrow_rect.centery),
         (rarrow_rect.right - 18, rarrow_rect.bottom - 4)])
    _checklist_click_rects.append(
        (rarrow_rect, {"action": "cl_arrow", "direction": +1}))

    # Title centered between arrows, with a leading marker that tells
    # the user at a glance whether the category is auto-detected
    # (green ●) or manual-only (red ●). Manual-only categories are
    # listed in CHECKLIST_MANUAL_ONLY; everything else gets the auto
    # marker. The two dots use the same glyph but different colors,
    # so the markers line up vertically across categories.
    is_manual = cat["key"] in CHECKLIST_MANUAL_ONLY
    marker_text = "●"
    marker_col  = (220, 110, 110) if is_manual else (140, 200, 150)
    marker_surf = title_font.render(marker_text, True, marker_col)
    title_surf = title_font.render(cat["label"], True, (235, 220, 160))
    count_surf = count_font.render(
        f"{x_count} / {y_count}", True, (180, 200, 220))
    # Layout: [marker] [Title]  [count]  centered as a group. The
    # marker sits 6px before the title text.
    marker_gap = 6
    group_w = (marker_surf.get_width() + marker_gap
               + title_surf.get_width() + 14 + count_surf.get_width())
    gx = mx + (mw - group_w) // 2
    gy_m = hdr_top + (header_h - marker_surf.get_height()) // 2
    gy_t = hdr_top + (header_h - title_surf.get_height()) // 2
    gy_c = hdr_top + (header_h - count_surf.get_height()) // 2
    surface.blit(marker_surf, (gx, gy_m))
    tx = gx + marker_surf.get_width() + marker_gap
    surface.blit(title_surf, (tx, gy_t))
    surface.blit(count_surf, (tx + title_surf.get_width() + 14, gy_c))

    # Reserved space below the header for the row list. No subtitle
    # is rendered any more — the manual / auto status is conveyed by
    # the title's red/green dot marker, and the legend at the footer
    # explains the symbols.
    sub_h = 0

    # ── List area (scrollable) ─────────────────────────────────────────
    list_top = hdr_top + header_h + sub_h
    list_bot = my + mh - pad - 14   # room for footer hint
    list_h = list_bot - list_top
    row_h = 22
    inner_x = mx + pad
    inner_w = mw - pad * 2
    # Small breathing-room gap before the first row. Without this,
    # row 0 renders flush against the header band's bottom edge,
    # making it look cramped (especially noticeable on tabs where
    # the first row's checkbox lines up with the header separator).
    # The gap is INSIDE the clipped area so when the user scrolls
    # down, content slides naturally underneath — only the very-top
    # frame gets the cushion.
    list_top_pad = 4

    # Clamp scroll.
    max_scroll = max(0, len(rows) * row_h + list_top_pad - list_h)
    global checklist_scroll
    if checklist_scroll < 0:
        checklist_scroll = 0
    if checklist_scroll > max_scroll:
        checklist_scroll = max_scroll

    # Clip subsurface so rows don't bleed outside the list area.
    list_clip = pygame.Rect(mx + 2, list_top, mw - 4, list_h)
    prev_clip = surface.get_clip()
    surface.set_clip(list_clip)

    # Draw each row.
    mpos = pygame.mouse.get_pos()
    for i, (item_key, disp) in enumerate(rows):
        ry = list_top + list_top_pad + i * row_h - checklist_scroll
        if ry + row_h < list_top - row_h:
            continue   # off-screen above (cheap skip)
        if ry > list_bot + row_h:
            break       # off-screen below — list is sorted by position
        rrect = pygame.Rect(inner_x, ry, inner_w, row_h - 2)

        # Hover highlight (only if cursor is in the visible list area).
        in_list = list_clip.collidepoint(mpos)
        if in_list and rrect.collidepoint(mpos):
            hl = pygame.Surface(rrect.size, pygame.SRCALPHA)
            hl.fill((255, 255, 255, 14))
            surface.blit(hl, rrect.topleft)

        # Check-state badge. Manual and auto render identically — once
        # a row is checked, the source doesn't matter visually; what
        # matters is "you have this." Auto stays live-derived from the
        # game state; manual is persisted user input. Both green ✓.
        state = is_checked(item_key)
        is_check_filled = state in ("auto", "manual")
        box_size = 14
        box = pygame.Rect(inner_x + 2,
                          ry + (row_h - box_size) // 2,
                          box_size, box_size)
        pygame.draw.rect(surface, (60, 70, 88), box, 1, border_radius=2)
        if is_check_filled:
            # Green checkmark — same glyph regardless of auto/manual.
            col = (130, 220, 140)
            pygame.draw.lines(surface, col, False, [
                (box.x + 3, box.centery),
                (box.x + 6, box.bottom - 3),
                (box.right - 2, box.y + 2),
            ], 2)

        # Determine whether the label is link-able (the category has a
        # url_builder AND it returns a non-empty URL for this row).
        # We resolve the URL once per draw so we can both color the
        # label correctly AND store it on the click rect payload.
        url = None
        url_builder = cat.get("url_builder") if cat else None
        if callable(url_builder):
            try:
                url = url_builder(item_key, disp)
            except Exception:
                url = None

        # Compute label rect FIRST (independent of color) so we can
        # check link-hover before deciding the final color. We pick
        # one color and render once — no double-render/flicker.
        lbl_x = inner_x + box_size + 10
        # Use a temp surface measurement only for sizing the click rect
        # (height is uniform across colors).
        _tmp_h = row_font.get_height()
        lbl_y_pre = ry + (row_h - _tmp_h) // 2
        # Label click rect spans from end-of-box to right edge of the
        # row. This gives a generous click target — anywhere right of
        # the checkbox is "the name."
        lbl_rect = pygame.Rect(
            lbl_x - 4, ry, rrect.right - (lbl_x - 4), row_h - 2)
        label_hovered = (in_list and url
                         and lbl_rect.collidepoint(mpos))

        # Label color: link-hover wins, otherwise check-state tint
        # (same mint-green for both auto and manual — see badge above),
        # otherwise neutral text gray.
        if label_hovered:
            label_col = (135, 195, 255)   # matches OW's other link cues
        elif is_check_filled:
            label_col = (210, 240, 215)
        else:
            label_col = (220, 225, 235)
        lbl_surf = row_font.render(disp, True, label_col)
        lbl_y = ry + (row_h - lbl_surf.get_height()) // 2
        surface.blit(lbl_surf, (lbl_x, lbl_y))
        # Underline on hover reinforces the link affordance.
        if label_hovered:
            underline_y = lbl_y + lbl_surf.get_height() - 1
            pygame.draw.line(surface, label_col,
                             (lbl_x, underline_y),
                             (lbl_x + lbl_surf.get_width(), underline_y),
                             1)

        # Register click targets — ONLY for rows fully inside the
        # visible list area, so scrolled-off rows don't poach clicks
        # from the header arrows or footer hint (this clamp prevents
        # an old bug where negative-Y row rects landed in the arrow
        # band and stole the click).
        #
        # Two separate targets per row:
        #   - The box: toggles the manual check (the original row
        #     action, narrowed to just the checkbox area).
        #   - The label: opens the BG-wiki link (when a URL exists).
        # The label rect is appended AFTER the box rect so that, in the
        # reverse-walk dispatch, the box still wins for clicks inside
        # the box area (its rect is a strict subset of the label band
        # would-be reach, but we draw the box first and use distinct
        # rects, so no overlap actually occurs).
        if (rrect.top >= list_top and rrect.bottom <= list_bot):
            # Slightly expand the box hit area for easier clicking —
            # the visible box is 14px but accept clicks within the
            # full row height column to the left of the label start.
            box_hit = pygame.Rect(
                inner_x, ry, (lbl_x - 4) - inner_x, row_h - 2)
            _checklist_click_rects.append(
                (box_hit, {"action": "cl_box", "item_key": item_key}))
            if url:
                _checklist_click_rects.append(
                    (lbl_rect, {"action": "cl_label", "url": url}))

    surface.set_clip(prev_clip)

    # Scrollbar (only when needed). Wider than a hairline so it can
    # actually be grabbed with the mouse; track + thumb rects + the
    # max_scroll value are captured for the click + drag handlers
    # in dispatch_checklist_modal_click and the MOUSEMOTION block.
    global _checklist_scrollbar_thumb_rect, _checklist_scrollbar_track_rect
    global _checklist_scrollbar_max_scroll
    _checklist_scrollbar_thumb_rect = None
    _checklist_scrollbar_track_rect = None
    _checklist_scrollbar_max_scroll = 0
    if max_scroll > 0:
        sb_w = 8
        bar_track_x = mx + mw - sb_w - 2
        bar_track_y = list_top
        bar_track_h = list_h
        track_rect = pygame.Rect(bar_track_x, bar_track_y, sb_w, bar_track_h)
        _checklist_scrollbar_track_rect = track_rect
        _checklist_scrollbar_max_scroll = max_scroll
        # Track background. The slightly muted color keeps it from
        # competing with row content at the right edge while still
        # being visible enough to find by eye.
        pygame.draw.rect(surface, (40, 46, 60),
                         track_rect, border_radius=3)
        # Thumb sized proportional to (visible / total). Floor at
        # 28px so it's always grabbable even on huge lists.
        natural_h = max(1, len(rows) * row_h)
        thumb_h = max(28, int(bar_track_h * list_h / natural_h))
        thumb_h = min(thumb_h, bar_track_h)
        thumb_y = bar_track_y + int(
            (bar_track_h - thumb_h) * checklist_scroll / max_scroll)
        thumb_rect = pygame.Rect(bar_track_x, thumb_y, sb_w, thumb_h)
        _checklist_scrollbar_thumb_rect = thumb_rect
        # Hover/drag affordance: lighter thumb color while engaged.
        is_dragging = _checklist_scroll_drag is not None
        mouse_p = pygame.mouse.get_pos()
        is_hover = thumb_rect.collidepoint(mouse_p)
        thumb_col = ((180, 200, 230) if (is_dragging or is_hover)
                     else (110, 130, 170))
        pygame.draw.rect(surface, thumb_col, thumb_rect, border_radius=3)

    # Footer hint: legend for the title's red/green dot plus the
    # close affordance. The dot in the legend renders in the same
    # red as the manual-category title marker, with the explanatory
    # text in the muted gray used by the rest of the modal chrome.
    hint_dot = small_font.render("●", True, (220, 110, 110))
    hint_text = small_font.render(
        " Denotes manual tab   ·   Click outside to close",
        True, (140, 150, 170))
    hint_total_w = hint_dot.get_width() + hint_text.get_width()
    hint_x = mx + (mw - hint_total_w) // 2
    hint_y = my + mh - 18
    surface.blit(hint_dot, (hint_x, hint_y))
    surface.blit(hint_text,
                 (hint_x + hint_dot.get_width(),
                  hint_y + (hint_dot.get_height() - hint_text.get_height()) // 2))


def draw_achievement_banner(surface):
    """If the easter-egg achievement banner is currently active, draw
    it as a flashing pass-through overlay across the middle of the
    screen. Banner duration is set by _achievement_banner_until_ts
    (a unix-seconds deadline); this fn no-ops once that deadline
    passes. Pass-through means clicks underneath still register —
    we don't push anything into _checklist_click_rects or the like.

    Flashing pattern: the background and border colors alternate
    every 200ms between two warm/celebratory palettes. Title text
    stays steady gold so it's always readable; the cycle is purely
    chrome."""
    now = time.time()
    if now >= _achievement_banner_until_ts:
        return
    sw, sh = surface.get_size()
    # Banner is a centered horizontal band. Width ≈ 90% of screen,
    # height ≈ 110px, two stacked text rows (title + subtitle).
    bw = min(sw - 40, 720)
    bh = 110
    bx = (sw - bw) // 2
    by = (sh - bh) // 2
    # Flash phase: cycle every ~200ms. Two palette frames.
    phase = int(now * 5) % 2
    if phase == 0:
        bg_col    = (60, 20, 80, 230)      # purple-magenta
        edge_col  = (255, 215, 100)        # bright gold
    else:
        bg_col    = (20, 30, 90, 230)      # deep blue
        edge_col  = (255, 130, 200)        # hot pink
    # Translucent fill drawn onto an SRCALPHA surface so the screen
    # underneath stays visible. The user CAN still see what's behind
    # the banner (which suits "pass-through" semantics — clicks work
    # AND vision works).
    panel = pygame.Surface((bw, bh), pygame.SRCALPHA)
    panel.fill(bg_col)
    surface.blit(panel, (bx, by))
    # Thick border in the flash color. Two passes (inner + outer)
    # give a chunky party-banner feel without needing a separate
    # asset.
    pygame.draw.rect(surface, edge_col, (bx, by, bw, bh), 4,
                     border_radius=10)
    pygame.draw.rect(surface, (255, 255, 255),
                     (bx + 4, by + 4, bw - 8, bh - 8), 1,
                     border_radius=8)
    # Title text. Steady gold so the message is readable through
    # the flashes. Use a larger, bolder font than the modal chrome.
    big_font   = get_font("Consolas", 28, bold=True)
    sub_font   = get_font("Consolas", 16, bold=True)
    title_txt  = "Congratulations!!"
    sub_txt    = "You beat Final Fantasy XI!"
    title_surf = big_font.render(title_txt, True, (255, 230, 130))
    sub_surf   = sub_font.render(sub_txt,   True, (255, 245, 200))
    # Stack the two lines, centered.
    total_h = title_surf.get_height() + 6 + sub_surf.get_height()
    ty = by + (bh - total_h) // 2
    surface.blit(title_surf,
                 (bx + (bw - title_surf.get_width()) // 2, ty))
    surface.blit(sub_surf,
                 (bx + (bw - sub_surf.get_width()) // 2,
                  ty + title_surf.get_height() + 6))


def _achievement_periodic_check():
    """Throttled wrapper around _checklist_check_achievement called
    from the main draw loop. Caps the check rate to roughly 1Hz so
    we don't spend a tiny but pointless amount of CPU re-walking
    every category on every frame. Early-exits once the achievement
    is unlocked so the runtime cost falls to a single timestamp
    comparison forever after."""
    global _achievement_last_check_ts
    if _achievement_unlocked:
        return
    now = time.time()
    if now - _achievement_last_check_ts < 1.0:
        return
    _achievement_last_check_ts = now
    _checklist_check_achievement()


def dispatch_checklist_modal_click(mx, my):
    """Resolve a click against the checklist modal. Returns True if
    the click was consumed (so the caller skips other handlers)."""
    global checklist_modal_open, checklist_current_category
    global checklist_current_tab, checklist_scroll
    global checklist_tab_hscroll
    global _checklist_scroll_drag
    if not checklist_modal_open:
        return False
    # Scrollbar hit-tests run FIRST so a click on the thumb wins over
    # the panel-bg catch-all that swallows in-panel non-control clicks.
    # Thumb click → start a drag (recorded in _checklist_scroll_drag,
    # consumed by the MOUSEMOTION handler). Track click outside the
    # thumb → page-jump in that direction by roughly one thumb-height.
    thumb_r = _checklist_scrollbar_thumb_rect
    track_r = _checklist_scrollbar_track_rect
    if thumb_r is not None and thumb_r.collidepoint(mx, my):
        _checklist_scroll_drag = {
            "origin_mouse_y": my,
            "origin_scroll":  checklist_scroll,
            "track_top":      track_r.top,
            "track_h":        track_r.h,
            "thumb_h":        thumb_r.h,
            "max_scroll":     _checklist_scrollbar_max_scroll,
        }
        return True
    if track_r is not None and track_r.collidepoint(mx, my):
        # Page jump in the direction of the click. Step ≈ one thumb-
        # height worth of content scroll, which approximates a
        # visible-window page. Clamp on the next frame's draw.
        step_pixels = max(40, int(thumb_r.h if thumb_r else 60))
        if thumb_r is not None and my < thumb_r.top:
            checklist_scroll = max(0, checklist_scroll - step_pixels)
        else:
            checklist_scroll += step_pixels
        return True
    # Walk rects in reverse so the more-specific overlays (rows, arrows)
    # match before the panel/backdrop catch-alls.
    for rect, payload in reversed(_checklist_click_rects):
        if not rect.collidepoint(mx, my):
            continue
        what = payload.get("action")
        if what == "cl_backdrop":
            checklist_modal_open = False
            return True
        if what == "cl_panel_bg":
            # Click inside panel but not on a control — swallow so it
            # doesn't fall through to the backdrop.
            return True
        if what == "cl_tab":
            # Switch to a different top-level tab. Reset the per-tab
            # category index + scroll so we land cleanly on the new
            # tab's first category. No-op if the user clicked the
            # already-active tab.
            new_tab = payload.get("tab_idx", 0)
            if 0 <= new_tab < len(CHECKLIST_TABS):
                if new_tab != checklist_current_tab:
                    checklist_current_tab = new_tab
                    checklist_current_category = 0
                    checklist_scroll = 0
            return True
        if what == "cl_tab_nav":
            # Step the active tab by ±1 (no wrap-around at the ends).
            # Mirrors the </> arrows under the strip but operates on
            # TABS rather than sub-categories. When the tab strip
            # overflows, the next-frame draw's scroll-into-view logic
            # will slide the newly-active tab into the visible band
            # automatically.
            d = payload.get("direction", 1)
            new_tab = checklist_current_tab + d
            if 0 <= new_tab < len(CHECKLIST_TABS):
                checklist_current_tab = new_tab
                checklist_current_category = 0
                checklist_scroll = 0
            return True
        if what == "cl_arrow":
            # Cycle within the CURRENT tab's category list, not the
            # full CHECKLIST_CATEGORIES. This lets each tab have its
            # own bounded loop without spilling into adjacent groups.
            keys = _checklist_active_category_keys()
            n = len(keys)
            if n > 0:
                d = payload.get("direction", 1)
                checklist_current_category = (
                    checklist_current_category + d) % n
                checklist_scroll = 0
            return True
        if what == "cl_box":
            # Click on the checkbox area — toggle the manual check.
            # This is the original row-click action, now narrowed to
            # just the box so the label can carry the BG-wiki link.
            item_key = payload.get("item_key")
            if item_key:
                _checklist_toggle_manual(item_key)
            return True
        if what == "cl_label":
            # Click on the row's label — open the BG-wiki URL in the
            # user's default browser. webbrowser.open is non-blocking
            # on every platform we run (it spawns and returns); the
            # try/except guards against the rare case where no browser
            # is registered (headless CI etc).
            url = payload.get("url")
            if url:
                try:
                    webbrowser.open(url, new=2, autoraise=True)
                except Exception as e:
                    print(f"[OmniWatch] could not open browser: {e!r}")
            return True
    return False


# ═════════════════════════════════════════════════════════════════════
# ── Campaigns Modal Render + Click Dispatch ─────────────────────────
# Simple scrollable list of cards. Each card shows:
#   • Title (bold, larger font)
#   • Date range "X → Y" (muted color)
#   • Summary blurb
#   • Bonus bullets (if parsed)
# Header has a Refresh button and an X close button.
# Click anywhere outside the panel closes it.
# ═════════════════════════════════════════════════════════════════════

def draw_campaigns_modal(surface):
    """Render the Current Campaigns modal popup if open. Layout:
      ┌───────────────────────────────────────┐
      │ Ongoing Events           [↻] [X]      │  header
      ├───────────────────────────────────────┤
      │ ╔═══════════════════════════════════╗ │
      │ ║ 24th Vana'versary Celebration    ║ │  card
      │ ║ Wed, May 13 → Tue, June 9         ║ │
      │ ║ A variety of bonuses including…  ║ │
      │ ║ • Sparks doubled                  ║ │
      │ ║ • Conquest tally bonus            ║ │
      │ ╚═══════════════════════════════════╝ │
      │ ╔═══════════════════════════════════╗ │
      │ ║ ...                               ║ │
      │ ╚═══════════════════════════════════╝ │
      └───────────────────────────────────────┘
    Mouse wheel scrolls. Click backdrop to close. Click ↻ to refresh
    from the live feed. Click a card to open its source URL in a browser.

    Refills _campaigns_click_rects each frame for the dispatcher."""
    global _campaigns_click_rects, _campaigns_modal_rect
    _campaigns_click_rects = []
    _campaigns_modal_rect = None
    if not campaigns_modal_open:
        return

    # While the modal is visible, keep the DI banner in sync with the
    # live whereisdi feed. _di_maybe_refresh self-throttles to one
    # actual network call per WHEREISDI_REFRESH_INTERVAL_SEC and is
    # safe to call every frame — it short-circuits if either throttle
    # gate hasn't elapsed. Without this, opening the modal once and
    # leaving it open during play would let the DI location go stale
    # against the website.
    _di_maybe_refresh()

    sw, sh = surface.get_size()
    mw = min(540, sw - 60)
    mh = min(640, sh - 60)
    mx = (sw - mw) // 2
    my = (sh - mh) // 2

    # Backdrop (semi-transparent, full-screen). A click on it closes.
    backdrop = pygame.Surface((sw, sh), pygame.SRCALPHA)
    backdrop.fill((0, 0, 0, 180))
    surface.blit(backdrop, (0, 0))
    _campaigns_click_rects.append(
        (pygame.Rect(0, 0, sw, sh), {"action": "cmp_backdrop"}))

    # Panel background — slightly translucent so the panel feels like
    # a real overlay rather than a flat rectangle.
    panel_rect = pygame.Rect(mx, my, mw, mh)
    _campaigns_modal_rect = panel_rect
    pygame.draw.rect(surface, (28, 28, 38), panel_rect, border_radius=8)
    pygame.draw.rect(surface, (90, 90, 120), panel_rect, 2, border_radius=8)
    # Swallow non-control clicks inside the panel so they don't fall
    # through to the backdrop close.
    _campaigns_click_rects.append(
        (panel_rect.copy(), {"action": "cmp_panel_bg"}))

    # ── Header bar ──
    title_font = pygame.font.SysFont("arial", 20, bold=True)
    body_font  = pygame.font.SysFont("arial", 14)
    small_font = pygame.font.SysFont("arial", 12)
    bonus_font = pygame.font.SysFont("arial", 12, italic=True)

    header_h = 38
    header_rect = pygame.Rect(mx, my, mw, header_h)
    pygame.draw.rect(surface, (40, 40, 55), header_rect,
                     border_top_left_radius=8, border_top_right_radius=8)
    title_surf = title_font.render("Ongoing Events", True, (235, 235, 245))
    surface.blit(title_surf, (mx + 14, my + 8))

    # Refresh button — uses a wider rect with plain text since the
    # ↻ unicode glyph isn't reliably available in pygame's default
    # SysFont (renders as a hollow placeholder box on Windows when
    # the active font lacks that codepoint).
    refresh_w = 64
    refresh_rect = pygame.Rect(mx + mw - 110, my + 7, refresh_w, 24)
    refresh_bg = (60, 90, 60) if not campaigns_fetch_in_flight else (90, 90, 50)
    pygame.draw.rect(surface, refresh_bg, refresh_rect, border_radius=4)
    pygame.draw.rect(surface, (130, 160, 130), refresh_rect, 1,
                     border_radius=4)
    refresh_label = "Refreshing" if campaigns_fetch_in_flight else "Refresh"
    refresh_surf = small_font.render(refresh_label, True, (235, 245, 235))
    surface.blit(refresh_surf,
                 (refresh_rect.x + (refresh_w - refresh_surf.get_width())//2,
                  refresh_rect.y + (24 - refresh_surf.get_height())//2))
    _campaigns_click_rects.append(
        (refresh_rect.copy(), {"action": "cmp_refresh"}))

    # Close button
    close_size = 24
    close_rect = pygame.Rect(mx + mw - 38, my + 7, close_size, close_size)
    pygame.draw.rect(surface, (90, 50, 50), close_rect, border_radius=4)
    pygame.draw.rect(surface, (160, 130, 130), close_rect, 1, border_radius=4)
    close_surf = title_font.render("X", True, (245, 235, 235))
    surface.blit(close_surf,
                 (close_rect.x + (close_size - close_surf.get_width())//2,
                  close_rect.y + (close_size - close_surf.get_height())//2 - 2))
    _campaigns_click_rects.append(
        (close_rect.copy(), {"action": "cmp_close"}))

    # ── Persistent info banners (above the scrollable content) ──
    # Two side-by-side boxes that stay fixed when the user scrolls
    # the campaigns list below. The "look at the top of the
    # modal first" pattern: the rotating RoE objective and the
    # current Domain Invasion location are the two pieces of info
    # he checks most often. Putting them in fixed boxes means he
    # doesn't have to scroll to the top to see them — useful when
    # he's deep in the campaigns list reading sub-campaign details
    # and just wants a quick glance at where DI is.
    banner_top    = my + header_h + 6
    banner_h      = 56
    banner_gap    = 8
    banner_outer_w = mw - 16          # leave 8px L/R margin like content
    box_w         = (banner_outer_w - banner_gap) // 2
    banner_label_font = pygame.font.SysFont("arial", 11, bold=True)
    banner_value_font = pygame.font.SysFont("arial", 14, bold=True)
    banner_meta_font  = pygame.font.SysFont("arial", 11, italic=True)

    # ── Box 1: Rotating RoE Objective ──
    # Limited-Time Records of Eminence objective for the current
    # 4-hour slot. Schedule is fixed (real-world clock, Pacific TZ),
    # so we compute it locally with no network round-trip — just a
    # table lookup keyed by (day_of_week, slot).
    roe_rect = pygame.Rect(mx + 8, banner_top, box_w, banner_h)
    pygame.draw.rect(surface, (45, 45, 65), roe_rect, border_radius=6)
    pygame.draw.rect(surface, (110, 110, 150), roe_rect, 1, border_radius=6)
    roe_label = banner_label_font.render("LIMITED-TIME ROE OBJECTIVE",
                                          True, (180, 180, 210))
    surface.blit(roe_label,
                 (roe_rect.x + 10,
                  roe_rect.y + 6))
    roe_lookup = _roe_current_objective()
    if roe_lookup is not None:
        roe_name, roe_seconds_left, roe_next_name = roe_lookup
        roe_value = banner_value_font.render(roe_name, True, (220, 200, 130))
        # Truncate if too wide for the box
        if roe_value.get_width() > box_w - 20:
            for i in range(len(roe_name) - 1, 0, -1):
                test = roe_name[:i] + "…"
                ts = banner_value_font.render(test, True, (220, 200, 130))
                if ts.get_width() <= box_w - 20:
                    roe_value = ts
                    break
        surface.blit(roe_value,
                     (roe_rect.x + 10,
                      roe_rect.y + 22))
        countdown = _roe_format_countdown(roe_seconds_left)
        if countdown and roe_next_name:
            # Show what's coming up next in the meta line. Format is
            # compact since the line is tight: "next: <name> in 2h 35m".
            # If the name overflows the box width, progressively
            # truncate it (keeping the time intact — that's the part
            # the user actually scans for).
            meta_text = f"next: {roe_next_name} in {countdown}"
            roe_meta = banner_meta_font.render(meta_text, True, (140, 140, 170))
            if roe_meta.get_width() > box_w - 20:
                # Truncate just the name portion, preserve "in N".
                suffix = f" in {countdown}"
                for i in range(len(roe_next_name) - 1, 0, -1):
                    test = f"next: {roe_next_name[:i]}…{suffix}"
                    ts = banner_meta_font.render(test, True, (140, 140, 170))
                    if ts.get_width() <= box_w - 20:
                        roe_meta = ts
                        break
            surface.blit(roe_meta,
                         (roe_rect.x + 10,
                          roe_rect.y + banner_h - 16))
    else:
        roe_value = banner_value_font.render(
            "(rotation lookup failed)", True, (200, 130, 130))
        surface.blit(roe_value,
                     (roe_rect.x + 10,
                      roe_rect.y + 22))

    # ── Box 2: Domain Invasion (whereisdi.com) ──
    di_rect = pygame.Rect(mx + 8 + box_w + banner_gap, banner_top,
                           box_w, banner_h)
    pygame.draw.rect(surface, (50, 55, 50), di_rect, border_radius=6)
    pygame.draw.rect(surface, (110, 150, 110), di_rect, 1, border_radius=6)
    di_server = di_state.get("server") or _di_current_server()
    if di_server:
        di_label_text = f"DOMAIN INVASION • {di_server.upper()}"
    else:
        di_label_text = "DOMAIN INVASION"
    di_label = banner_label_font.render(di_label_text, True, (180, 210, 180))
    surface.blit(di_label,
                 (di_rect.x + 10,
                  di_rect.y + 6))
    # Show location, freshness, or status text depending on state.
    if not di_server:
        # No server configured. Point the user at the new settings
        # entry rather than the Lua broadcast path — most users will
        # just pick their server from the dropdown.
        di_value_text = "(set your server in Settings)"
        di_value_col  = (220, 180, 130)
    elif di_state.get("location"):
        di_value_text = di_state["location"]
        di_value_col  = (220, 240, 180)
    elif di_fetch_in_flight:
        di_value_text = "fetching…"
        di_value_col  = (190, 190, 210)
    elif di_state.get("error"):
        di_value_text = "(fetch failed — try Refresh)"
        di_value_col  = (220, 180, 180)
    else:
        di_value_text = "(no data yet)"
        di_value_col  = (190, 190, 210)
    di_value = banner_value_font.render(di_value_text, True, di_value_col)
    # Truncate visually if too wide for the box (zone names are usually
    # short enough but just in case).
    if di_value.get_width() > box_w - 20:
        # Re-render truncated. Find longest prefix that fits.
        for i in range(len(di_value_text) - 1, 0, -1):
            test = di_value_text[:i] + "…"
            test_surf = banner_value_font.render(test, True, di_value_col)
            if test_surf.get_width() <= box_w - 20:
                di_value = test_surf
                break
    surface.blit(di_value,
                 (di_rect.x + 10,
                  di_rect.y + 22))
    # Freshness line (last updated) — or hint if server unknown
    if not di_server:
        di_meta = banner_meta_font.render(
            "Settings → Header → Server", True, (180, 150, 130))
        surface.blit(di_meta,
                     (di_rect.x + 10,
                      di_rect.y + banner_h - 16))
    else:
        fresh = _di_freshness_text()
        if fresh:
            di_meta = banner_meta_font.render(
                f"updated {fresh}", True, (150, 180, 150))
            surface.blit(di_meta,
                         (di_rect.x + 10,
                          di_rect.y + banner_h - 16))

    # ── Box 3 & 4: Transport schedules (Airship | Ferry) ──
    # Same dimensions / styling as the RoE/DI row above so the modal
    # reads as "two stacked rows of two boxes". Each shows ONE route
    # at a time; clicking the box cycles to the next route in the
    # respective list (8 airships, 6 directional ferries).
    tr_top = banner_top + banner_h + 6     # tight gap below RoE/DI
    tr_h   = banner_h                       # same height as row 1
    # Reset transport click rects each render — banner geometry can
    # shift if the modal width changes.
    _transport_click_rects.clear()

    # Auto-cycle tick: rotate to next route every
    # TRANSPORT_AUTO_CYCLE_SEC seconds. Stale timestamps (modal was
    # closed for a while) reset without advancing so a re-open
    # doesn't trigger an immediate cycle. Manual clicks also bump
    # the timestamp in dispatch_campaigns_modal_click, so a manual
    # cycle gives the user the full interval to read the new route
    # before another auto-tick fires.
    global transport_airship_idx, transport_airship_last_cycle_ts
    global transport_ferry_idx,   transport_ferry_last_cycle_ts
    _now_ts = time.time()
    # Airship auto-cycle
    if (transport_airship_last_cycle_ts == 0.0
            or _now_ts - transport_airship_last_cycle_ts
                > TRANSPORT_STALE_THRESHOLD_SEC):
        transport_airship_last_cycle_ts = _now_ts
    elif (_now_ts - transport_airship_last_cycle_ts
            >= TRANSPORT_AUTO_CYCLE_SEC):
        if TRANSPORT_AIRSHIPS:
            transport_airship_idx = ((transport_airship_idx + 1)
                                     % len(TRANSPORT_AIRSHIPS))
        transport_airship_last_cycle_ts = _now_ts
    # Ferry auto-cycle (same logic, independent timer)
    if (transport_ferry_last_cycle_ts == 0.0
            or _now_ts - transport_ferry_last_cycle_ts
                > TRANSPORT_STALE_THRESHOLD_SEC):
        transport_ferry_last_cycle_ts = _now_ts
    elif (_now_ts - transport_ferry_last_cycle_ts
            >= TRANSPORT_AUTO_CYCLE_SEC):
        if TRANSPORT_FERRIES:
            transport_ferry_idx = ((transport_ferry_idx + 1)
                                   % len(TRANSPORT_FERRIES))
        transport_ferry_last_cycle_ts = _now_ts

    # Helper that draws one transport box and returns its rect (we
    # collect the rect into _transport_click_rects below). Kept inline
    # so it captures all the font/color locals from the enclosing
    # scope without re-passing them.
    def _draw_transport_box(rect, label_text, routes, idx, mode_key,
                             border_col, fill_col, value_col):
        pygame.draw.rect(surface, fill_col, rect, border_radius=6)
        pygame.draw.rect(surface, border_col, rect, 1, border_radius=6)
        # Top label
        lbl = banner_label_font.render(label_text, True, border_col)
        surface.blit(lbl, (rect.x + 10, rect.y + 6))
        # Route name (large center line)
        if not routes:
            return
        idx = idx % len(routes)
        route_name, offset_vs, cycle_vs, board_vs = routes[idx]
        # Compute countdown for the currently-selected route
        ev = _next_transport_event(offset_vs, cycle_vs, board_vs)
        # Status flips the color a bit: amber when waiting, green
        # while actively boarding (a "now is the time" signal).
        if ev["status"] == "boarding":
            name_col = (170, 230, 170)
        else:
            name_col = value_col
        val = banner_value_font.render(route_name, True, name_col)
        # Truncate visually if too wide for the box
        if val.get_width() > rect.w - 20:
            for i in range(len(route_name) - 1, 0, -1):
                t = route_name[:i] + "…"
                ts = banner_value_font.render(t, True, name_col)
                if ts.get_width() <= rect.w - 20:
                    val = ts
                    break
        surface.blit(val, (rect.x + 10, rect.y + 22))
        # Meta line: countdown + next-event label + VD time of event.
        # Include the cycle index "(3/8)" so cycling-mode discoverability
        # is obvious — user can see they're 3 routes into a list of 8.
        countdown = _format_transport_countdown(ev["earth_secs"])
        meta_text = (f"{ev['event_label']} in {countdown} "
                     f"• VD {ev['vana_hhmm']} • ({idx+1}/{len(routes)})")
        meta = banner_meta_font.render(meta_text, True, (160, 170, 180))
        # Truncate meta from the right if too wide (drop the cycle
        # marker first since it's the least essential bit).
        if meta.get_width() > rect.w - 20:
            short = f"{ev['event_label']} in {countdown}"
            meta = banner_meta_font.render(short, True, (160, 170, 180))
        surface.blit(meta, (rect.x + 10, rect.y + tr_h - 16))
        # Whole-box click cycles to the next route. Recorded with
        # the mode_key so the dispatcher knows which list to advance.
        _transport_click_rects.append(
            (rect.copy(),
             {"action": "tr_cycle", "mode": mode_key,
              "list_len": len(routes)}))

    # Airship box (left half)
    air_rect = pygame.Rect(mx + 8, tr_top, box_w, tr_h)
    _draw_transport_box(
        air_rect, "AIRSHIP", TRANSPORT_AIRSHIPS,
        transport_airship_idx, "airship",
        border_col=(170, 140, 200),
        fill_col=(55, 50, 70),
        value_col=(210, 195, 240))
    # Ferry box (right half)
    ferry_rect = pygame.Rect(mx + 8 + box_w + banner_gap, tr_top,
                              box_w, tr_h)
    _draw_transport_box(
        ferry_rect, "FERRY", TRANSPORT_FERRIES,
        transport_ferry_idx, "ferry",
        border_col=(140, 180, 200),
        fill_col=(45, 60, 70),
        value_col=(190, 220, 240))

    # ── Content area (clipped, scrollable) ──
    content_top    = tr_top + tr_h + 8
    content_bottom = my + mh - 26  # leave room for footer
    content_rect   = pygame.Rect(mx + 8, content_top,
                                  mw - 16, content_bottom - content_top)
    prev_clip = surface.get_clip()
    surface.set_clip(content_rect)

    if not campaigns_entries:
        # Empty state. Different message for "loading" vs "tried and failed".
        if campaigns_fetch_in_flight or campaigns_last_fetched == 0:
            msg = "Loading events from PlayOnline…"
        elif campaigns_fetch_failed:
            msg = ("Could not reach the PlayOnline feed.\n"
                   "Click Refresh to retry, or check your connection.")
        else:
            msg = "No active events found."
        for i, line in enumerate(msg.split("\n")):
            surf = body_font.render(line, True, (200, 200, 210))
            surface.blit(surf,
                         (content_rect.x + (content_rect.w - surf.get_width())//2,
                          content_rect.y + 30 + i * 20))
        surface.set_clip(prev_clip)
        # Footer below
        _draw_campaigns_footer(surface, mx, my, mw, mh, small_font)
        return

    # ── Render cards, grouped by status (current / upcoming / past) ──
    # Each group gets a colored header band at the top so the user can
    # tell at a glance which campaigns are running NOW vs which are
    # upcoming. Within each group, individual event cards render as
    # before. This sectioned layout mirrors bg-wiki's
    # "Ongoing and Upcoming Events" widget convention.
    card_x = content_rect.x
    card_w = content_rect.w
    inner_pad_x = 12
    inner_pad_y = 10
    card_gap = 8
    group_header_h = 32          # height of the colored section band
    group_top_gap = 10           # space above each section header
    group_bottom_gap = 4         # space below header before first card

    # Build a flat list of "render items" interleaving group headers
    # with cards. Each item is a dict so we can dispatch on type during
    # the render pass. campaigns_entries is already sorted by the
    # _campaigns_sort_key (current group first, then upcoming by date
    # ascending), so iterating in order naturally groups same-status
    # entries together. We just inject a header whenever the group
    # changes.
    render_items = []  # list of dicts: {type:"header"|"card", ...}
    avail_text_w = card_w - 2 * inner_pad_x
    prev_group_key = None

    for entry in campaigns_entries:
        group_key, group_label = _campaigns_group_for(entry)
        if group_key != prev_group_key:
            # New group: inject a header item.
            render_items.append({
                "type":      "header",
                "label":     group_label,
                "color":     _campaigns_group_color(group_key),
                "group_key": group_key,
                "height":    group_header_h + group_top_gap + group_bottom_gap,
            })
            prev_group_key = group_key

        # Card layout (same as before; just packaged into a dict).
        title       = entry.get("title", "") or "(untitled)"
        period_s    = entry.get("period_start", "") or ""
        period_e    = entry.get("period_end", "") or ""
        summary     = entry.get("summary", "") or ""
        bonuses     = entry.get("bonuses", []) or []
        subcamps    = entry.get("subcampaigns", []) or []
        # Wrap title at the card width
        title_lines = _campaigns_wrap_text(title, body_font, avail_text_w)
        # Date line — shortened for display ("Friday, May 22" → "Fri May 22")
        date_str = _campaigns_format_period(period_s, period_e)

        # If we got rich sub-campaign data from the detail page, prefer
        # it: skip the generic summary blurb (which is just the
        # umbrella event's marketing copy) and skip the bullet list
        # (which would duplicate the sub-campaign content). The
        # sub-campaign cards carry all the actionable info.
        if subcamps:
            summary_lines = []
            bonus_lines = []
        else:
            # Wrap summary
            summary_lines = _campaigns_wrap_text(summary, small_font, avail_text_w)
            if len(summary_lines) > 4:
                # Truncate long summaries; full text is on the source page.
                summary_lines = summary_lines[:4]
                summary_lines[-1] = summary_lines[-1].rstrip() + "…"
            # Bonus lines — keep short, cap at 6
            bonus_lines = []
            for b in bonuses[:6]:
                wrapped = _campaigns_wrap_text("• " + b, bonus_font, avail_text_w)
                bonus_lines.extend(wrapped[:2])  # max 2 wrapped lines per bullet

        # Pre-wrap each sub-campaign's name + description for accurate
        # height measurement. The list interleaves two item types:
        #   {"type": "phase", "label": str, "label_lines": [str, ...]}
        #   {"type": "sc",    "name_lines": [...], "desc_lines": [...]}
        # When the parent campaign is in KNOWN_CAMPAIGN_PHASES, phase
        # headers are inserted between groups; otherwise sub-campaigns
        # render flat (the entire list is one implicit group).
        wrapped_subs = []
        parent_title_for_phase = entry.get("title", "")
        phase_groups = _campaigns_phase_groups(parent_title_for_phase,
                                                subcamps[:40])  # 40-cap
        # Track total sub-campaigns rendered across all phases. Caps
        # at 40 globally (the previous limit) so a misbehaving page
        # can't blow up the modal even if the mapping table grows.
        rendered_count = 0
        for phase_label, phase_subs in phase_groups:
            if rendered_count >= 40:
                break
            # Add a phase header row IF we have a label (None means
            # this event has no phase mapping, so we render a single
            # flat group with no header).
            if phase_label is not None:
                # Wrap the phase label so long labels still fit in
                # narrow modals. Phase labels are short (~30 chars)
                # so they rarely wrap, but cheap to support.
                label_lines = _campaigns_wrap_text(
                    phase_label, bonus_font, avail_text_w - 12)
                wrapped_subs.append({
                    "type":        "phase",
                    "label":       phase_label,
                    "label_lines": label_lines,
                })
            for sc in phase_subs:
                if rendered_count >= 40:
                    break
                n_lines = _campaigns_wrap_text(sc.get("name", ""),
                                                bonus_font, avail_text_w - 12)
                d_lines = _campaigns_wrap_text(sc.get("description", ""),
                                                small_font, avail_text_w - 12)
                if len(d_lines) > 4:
                    d_lines = d_lines[:4]
                    d_lines[-1] = d_lines[-1].rstrip() + "…"
                wrapped_subs.append({
                    "type":       "sc",
                    "name_lines": n_lines,
                    "desc_lines": d_lines,
                })
                rendered_count += 1

        title_h   = len(title_lines) * (body_font.get_linesize() + 2)
        date_h    = 18 if date_str else 0
        summary_h = len(summary_lines) * (small_font.get_linesize() + 1) if summary_lines else 0
        bonus_h   = len(bonus_lines)   * (bonus_font.get_linesize() + 1) if bonus_lines else 0
        # Sub-campaigns: each one is (name lines) + (desc lines) + a
        # small inter-block gap. Phase headers add a small fixed band
        # plus padding above/below to set them off visually.
        sub_h = 0
        for item in wrapped_subs:
            if item["type"] == "phase":
                # Phase header: top gap + label line(s) + bottom gap
                sub_h += 8  # space above header
                sub_h += (len(item["label_lines"])
                          * (bonus_font.get_linesize() + 1))
                sub_h += 4  # space below header
            else:
                sub_h += (len(item["name_lines"])
                          * (bonus_font.get_linesize() + 1))
                sub_h += (len(item["desc_lines"])
                          * (small_font.get_linesize() + 1))
                sub_h += 6  # gap between sub-campaigns
        if wrapped_subs:
            sub_h += 4  # extra space above first item
        spacer_h  = 4 if (summary_lines or bonus_lines or wrapped_subs) else 0
        total_h = (inner_pad_y * 2 + title_h + date_h + spacer_h
                   + summary_h + bonus_h + sub_h)
        render_items.append({
            "type":           "card",
            "entry":          entry,
            "title_lines":    title_lines,
            "date_str":       date_str,
            "summary_lines":  summary_lines,
            "bonus_lines":    bonus_lines,
            "wrapped_subs":   wrapped_subs,
            "height":         total_h,
        })

    # Compute total content height including all headers and inter-card
    # gaps. Headers already factor in their own top/bottom spacing in
    # their "height" field; cards need card_gap between consecutive
    # cards within the same group.
    total_content_h = 0
    last_was_card = False
    for itm in render_items:
        if itm["type"] == "card" and last_was_card:
            total_content_h += card_gap
        total_content_h += itm["height"]
        last_was_card = (itm["type"] == "card")
    max_scroll = max(0, total_content_h - content_rect.h)

    global campaigns_scroll
    campaigns_scroll = max(0, min(campaigns_scroll, max_scroll))

    y_cursor = content_top - campaigns_scroll
    last_was_card = False
    for itm in render_items:
        if itm["type"] == "header":
            # ── Group section header ──
            # A colored band stretching the full content width, with
            # the group label centered in it. Acts as a visual divider
            # between groups (Current / Starting <date> / Past).
            header_y = y_cursor + group_top_gap
            header_rect = pygame.Rect(card_x, header_y,
                                       card_w, group_header_h)
            # Cull if fully outside view
            if (header_rect.bottom < content_rect.top
                    or header_rect.top > content_rect.bottom):
                y_cursor += itm["height"]
                last_was_card = False
                continue
            pygame.draw.rect(surface, itm["color"], header_rect,
                             border_radius=6)
            # Subtle border for definition
            pygame.draw.rect(surface, (200, 220, 200),
                             header_rect, 1, border_radius=6)
            label_surf = title_font.render(itm["label"], True,
                                            (245, 245, 245))
            surface.blit(label_surf,
                         (header_rect.x
                          + (header_rect.w - label_surf.get_width()) // 2,
                          header_rect.y
                          + (header_rect.h - label_surf.get_height()) // 2))
            y_cursor += itm["height"]
            last_was_card = False
            continue

        # ── Event card ──
        entry        = itm["entry"]
        title_lines  = itm["title_lines"]
        date_str     = itm["date_str"]
        summary_lines = itm["summary_lines"]
        bonus_lines  = itm["bonus_lines"]
        wrapped_subs = itm["wrapped_subs"]
        total_h      = itm["height"]
        # Cards within the same group get a small gap between them; the
        # first card after a header has no extra gap (the header already
        # provides separation).
        if last_was_card:
            y_cursor += card_gap
        card_rect = pygame.Rect(card_x, y_cursor, card_w, total_h)
        last_was_card = True
        # Cull cards entirely outside the clipped content area to skip
        # paint work for items the user has scrolled past.
        if card_rect.bottom < content_rect.top or card_rect.top > content_rect.bottom:
            y_cursor += total_h
            continue

        # Card background
        pygame.draw.rect(surface, (45, 45, 58), card_rect, border_radius=6)
        pygame.draw.rect(surface, (75, 75, 95), card_rect, 1, border_radius=6)
        # Make the card itself clickable (opens source URL).
        # IMPORTANT: clip the click-target rect to the visible content
        # area. The card_rect may extend ABOVE content_rect.top (when
        # the user has scrolled and the top of this card is partially
        # off-screen) or below content_rect.bottom. Visually that's
        # fine — surface.set_clip(content_rect) above prevents drawing
        # outside the content area — but the click-test code below
        # doesn't see the visual clip; it just collides against the
        # raw rect. Without clipping the click rect, the scrolled-up
        # portion of a card would extend up under the header bar and
        # swallow clicks meant for the Refresh / Close buttons.
        link = entry.get("link", "")
        if link:
            click_rect = card_rect.clip(content_rect)
            if click_rect.width > 0 and click_rect.height > 0:
                _campaigns_click_rects.append(
                    (click_rect, {"action": "cmp_card", "url": link}))

        ty = card_rect.y + inner_pad_y
        # Title
        for ln in title_lines:
            surf = body_font.render(ln, True, (245, 230, 180))  # warm gold
            surface.blit(surf, (card_rect.x + inner_pad_x, ty))
            ty += body_font.get_linesize() + 2
        # Date range
        if date_str:
            surf = small_font.render(date_str, True, (180, 200, 240))
            surface.blit(surf, (card_rect.x + inner_pad_x, ty))
            ty += 18
        # Summary (only when we have no sub-campaigns to show — the
        # umbrella summary duplicates what the sub-campaign cards
        # already convey when we have detail-page data).
        for ln in summary_lines:
            surf = small_font.render(ln, True, (210, 210, 220))
            surface.blit(surf, (card_rect.x + inner_pad_x, ty))
            ty += small_font.get_linesize() + 1
        # Bonus bullets (only when no sub-campaigns parsed)
        for ln in bonus_lines:
            surf = bonus_font.render(ln, True, (170, 220, 170))
            surface.blit(surf, (card_rect.x + inner_pad_x, ty))
            ty += bonus_font.get_linesize() + 1

        # Sub-campaigns block: each item is either a phase header
        # (rendered as a small colored band with the phase label) or
        # a sub-campaign row (name in light green-italic above an
        # indented description).
        if wrapped_subs:
            ty += 4  # gap above first item
        for item in wrapped_subs:
            if item["type"] == "phase":
                # Phase header: a thin band that visually breaks
                # the sub-campaign stream into phase groups. Same
                # color treatment as the modal's top-level group
                # bands (warm muted blue) so it reads as "schedule
                # divider" rather than a card.
                ty += 8  # top padding
                band_x = card_rect.x + inner_pad_x + 2
                band_w = card_rect.w - (inner_pad_x * 2) - 4
                band_h = (len(item["label_lines"])
                          * (bonus_font.get_linesize() + 1)) + 2
                band_rect = pygame.Rect(band_x, ty - 1, band_w, band_h)
                pygame.draw.rect(surface, (55, 70, 95), band_rect,
                                  border_radius=4)
                pygame.draw.rect(surface, (90, 120, 160), band_rect, 1,
                                  border_radius=4)
                for ll in item["label_lines"]:
                    surf = bonus_font.render(ll, True, (200, 220, 245))
                    # Center the label horizontally in the band.
                    lw = surf.get_width()
                    lx = band_x + max(4, (band_w - lw) // 2)
                    surface.blit(surf, (lx, ty))
                    ty += bonus_font.get_linesize() + 1
                ty += 4  # bottom padding
                continue
            # Sub-campaign row.
            sub_x = card_rect.x + inner_pad_x + 4
            for nl in item["name_lines"]:
                surf = bonus_font.render(nl, True, (190, 230, 170))
                surface.blit(surf, (sub_x, ty))
                ty += bonus_font.get_linesize() + 1
            for dl in item["desc_lines"]:
                surf = small_font.render(dl, True, (210, 210, 220))
                surface.blit(surf, (sub_x + 8, ty))  # double-indent desc
                ty += small_font.get_linesize() + 1
            ty += 6  # gap between sub-campaigns

        y_cursor += total_h

    surface.set_clip(prev_clip)

    # Re-append the header button click rects AFTER all card rects.
    # The dispatcher iterates in reverse so later entries match first;
    # this guarantees Refresh and Close always win against any card
    # rect that might overlap their position (the card click rects
    # are already clipped to content_rect above, so this is a
    # belt-and-suspenders defense). Without this, scrolling could
    # cause a card rect to intercept clicks on the header buttons
    # despite the visual clip.
    _campaigns_click_rects.append(
        (refresh_rect.copy(), {"action": "cmp_refresh"}))
    _campaigns_click_rects.append(
        (close_rect.copy(), {"action": "cmp_close"}))

    # Scroll hint: draw a faint scrollbar on the right edge if content
    # overflows. Purely informational — not draggable in this modal.
    if max_scroll > 0:
        track_x = mx + mw - 6
        track_y = content_top
        track_h = content_rect.h
        thumb_h = max(20, int(track_h * (content_rect.h / total_content_h)))
        thumb_y = track_y + int((track_h - thumb_h)
                                 * (campaigns_scroll / max_scroll))
        pygame.draw.rect(surface, (60, 60, 75),
                         pygame.Rect(track_x, track_y, 4, track_h),
                         border_radius=2)
        pygame.draw.rect(surface, (130, 130, 160),
                         pygame.Rect(track_x, thumb_y, 4, thumb_h),
                         border_radius=2)

    # ── Footer ──
    _draw_campaigns_footer(surface, mx, my, mw, mh, small_font)


def _draw_campaigns_footer(surface, mx, my, mw, mh, font):
    """Render the small status line at the bottom of the campaigns
    modal — shows last-fetched time + a hint if we're stale/offline."""
    if campaigns_last_fetched:
        age = time.time() - campaigns_last_fetched
        if age < 90:
            stamp = "just now"
        elif age < 3600:
            stamp = f"{int(age // 60)} min ago"
        elif age < 86400:
            stamp = f"{int(age // 3600)} hr ago"
        else:
            stamp = f"{int(age // 86400)} d ago"
        msg = f"Last updated: {stamp}"
        if campaigns_fetch_failed:
            msg += "  •  (refresh failed)"
    elif campaigns_fetch_in_flight:
        msg = "Fetching…"
    else:
        msg = "No data fetched yet."
    surf = font.render(msg, True, (140, 140, 160))
    surface.blit(surf, (mx + 14, my + mh - 18))


def _campaigns_wrap_text(text, font, max_w):
    """Word-wrap a single line of text against a pygame font + pixel
    width budget. Returns a list of strings each fitting within max_w.
    Handles long unbreakable tokens by hard-cutting them so a single
    monster URL doesn't overflow the card."""
    if not text:
        return []
    lines = []
    for paragraph in text.split("\n"):
        if not paragraph.strip():
            continue
        words = paragraph.split()
        cur = ""
        for w in words:
            trial = (cur + " " + w).strip() if cur else w
            if font.size(trial)[0] <= max_w:
                cur = trial
            else:
                if cur:
                    lines.append(cur)
                # If single word is wider than max_w, hard-cut it.
                if font.size(w)[0] > max_w:
                    chunk = ""
                    for ch in w:
                        if font.size(chunk + ch)[0] <= max_w:
                            chunk += ch
                        else:
                            if chunk:
                                lines.append(chunk)
                            chunk = ch
                    cur = chunk
                else:
                    cur = w
        if cur:
            lines.append(cur)
    return lines


def _campaigns_format_period(start_str, end_str):
    """Compact the PlayOnline-style date strings for display.

    PlayOnline writes "Friday, May 22, 2026, at 1:00 a.m. (PDT)" which
    is too wide for our card. Reduce to "Fri May 22 → Mon Jun 1" while
    preserving the time + tz on hover if we ever add tooltips.
    Returns the formatted "A → B" string, or just A if B is empty."""
    def shorten(s):
        if not s:
            return ""
        # Try to extract "<Day-of-week>, <Month> <Day>" and shorten.
        m = re.match(
            r"\s*([A-Z][a-z]+),?\s+([A-Z][a-z]+)\s+(\d{1,2})"
            r"(?:,?\s+(\d{4}))?",
            s,
        )
        if not m:
            return s.strip()
        dow = m.group(1)[:3]
        mon = m.group(2)[:3]
        day = m.group(3)
        # Year is omitted unless it differs from the current real year.
        return f"{dow} {mon} {day}"
    a = shorten(start_str)
    b = shorten(end_str)
    if a and b:
        return f"{a}  →  {b}"
    return a or b


def dispatch_campaigns_modal_click(mx, my):
    """Resolve a click against the campaigns modal. Returns True if
    the click was consumed."""
    global campaigns_modal_open, campaigns_scroll
    global transport_airship_idx, transport_ferry_idx
    global transport_airship_last_cycle_ts, transport_ferry_last_cycle_ts
    if not campaigns_modal_open:
        return False
    # Transport boxes — check FIRST so their whole-box click target
    # isn't swallowed by any backdrop/panel catch-all sitting below.
    # Reverse-iterate for the same reason the campaigns dispatcher
    # does (later-added rects win on overlap).
    for rect, payload in reversed(_transport_click_rects):
        if not rect.collidepoint(mx, my):
            continue
        if payload.get("action") == "tr_cycle":
            mode = payload.get("mode", "")
            list_len = max(1, int(payload.get("list_len", 1)))
            # Bump the auto-cycle timestamp too — without this, an
            # auto-tick could fire 50ms after the user's manual click
            # and rotate again immediately, which would feel like the
            # click ate a route.
            _now = time.time()
            if mode == "airship":
                transport_airship_idx = (transport_airship_idx + 1) % list_len
                transport_airship_last_cycle_ts = _now
            elif mode == "ferry":
                transport_ferry_idx = (transport_ferry_idx + 1) % list_len
                transport_ferry_last_cycle_ts = _now
            return True
    # Walk in reverse so specific controls beat the panel/backdrop
    # catch-alls.
    for rect, payload in reversed(_campaigns_click_rects):
        if not rect.collidepoint(mx, my):
            continue
        what = payload.get("action")
        if what == "cmp_backdrop":
            campaigns_modal_open = False
            return True
        if what == "cmp_panel_bg":
            return True  # swallow stray panel clicks
        if what == "cmp_close":
            campaigns_modal_open = False
            return True
        if what == "cmp_refresh":
            # Refresh fires BOTH the campaigns list AND the DI banner.
            # The user expects "Refresh" to refresh everything visible
            # in the modal — they'd be (rightly) confused if the DI
            # banner kept showing stale data after clicking it just
            # because our cache TTL hadn't elapsed yet.
            _force_campaigns_refresh()
            _force_di_refresh()
            return True
        if what == "cmp_card":
            url = payload.get("url")
            if url:
                try:
                    webbrowser.open(url, new=2, autoraise=True)
                except Exception as e:
                    print(f"[OmniWatch] could not open browser: {e!r}")
            return True
    return False


def dispatch_sim_import_click(mx, my):
    """Resolve a click against the import modal. Returns True if consumed.
    Only active while sim_import_open."""
    global sim_import_open, sim_import_cwd, sim_import_file, sim_import_field
    global sim_import_scroll, sim_import_status, sim_import_root
    global sim_import_setpath_cursor
    if not sim_import_open:
        return False
    for rect, payload in reversed(sim_import_rects):
        if not rect.collidepoint(mx, my):
            continue
        act = payload.get("action")
        if act == "imp_close":
            sim_import_open = False
            sim_import_field = None
            return True
        if act == "imp_backdrop":
            # Click outside the panel content → close. (Panel rects are
            # later in the list and matched first via reversed().)
            sim_import_open = False
            sim_import_field = None
            return True
        if act == "imp_focus":
            sim_import_field = payload.get("field")
            if sim_import_field == "setpath":
                sim_import_setpath_cursor = len(sim_import_setpath)
            return True
        if act == "imp_browse":
            # Open the native OS file picker. Blocks until the user picks
            # or cancels (same as the icon picker). Store the chosen path.
            chosen = _browse_for_gear_file()
            if chosen:
                sim_import_file = chosen
                # Remember the folder as the next browse's starting point.
                try:
                    sim_import_root = os.path.dirname(chosen)
                    _sim_save_import_root()
                except Exception:
                    pass
                sim_import_status = ""
            return True
        if act == "imp_confirm":
            if sim_import_file and sim_import_setpath:
                _sim_send_import(sim_import_file, sim_import_setpath)
                sim_import_status = "sent — check sim panel"
            return True
    return True   # swallow clicks anywhere over the modal (it's on top)


def dispatch_sim_window_click(mx, my):
    """Resolve a click against sim_window_rects. Returns True if the
    click was handled (caller should not propagate to other handlers).
    Also updates sim_state and pushes the change to lua over UDP."""
    global sim_active_field, sim_state, sim_buff_picker
    if not sim_window_open:
        return False
    # Walk in reverse so dropdown options (added LAST) take priority over
    # the dropdown's parent row (added before them, smaller rect inside
    # the same vertical region).
    for rect, payload in reversed(sim_window_rects):
        if not rect.collidepoint(mx, my):
            continue
        action = payload.get("action")
        if action == "close":
            # Same as flipping sim_mode off — call set_setting so the
            # checkbox in Settings updates and side effects fire.
            try:
                set_setting("sim_mode", False)
            except Exception:
                pass
            return True
        if action == "open_dropdown":
            kind = payload.get("kind")
            slot = payload.get("slot")  # only for equip_slot
            # Toggle: clicking the same dropdown that's already open closes it.
            if (sim_active_field
                    and sim_active_field.get("kind") == kind
                    and sim_active_field.get("slot") == slot):
                sim_active_field = None
            else:
                sim_active_field = {"kind": kind}
                if slot is not None:
                    sim_active_field["slot"] = slot
            return True
        if action == "select":
            kind = payload.get("kind")
            value = payload.get("value")
            if kind == "equip_slot":
                # Sim equipment override. value can be:
                #   0 / None       → "explicitly empty"
                #   dict {id,bag,idx} → instance ref (preferred, for augments)
                #   int            → legacy id-only (fallback)
                slot = payload.get("slot")
                if slot:
                    eq = sim_state.setdefault("equipment", {})
                    if value == 0 or value is None:
                        eq[slot] = 0
                        _sim_send("equip", "0", sub=slot)
                    elif isinstance(value, dict):
                        # Store the dict as-is in sim_state so the rendering
                        # cell can match instance by exact (bag, idx).
                        eq[slot] = dict(value)
                        _sim_send("equip", _sim_format_equip_ref(value), sub=slot)
                    else:
                        eq[slot] = int(value)
                        _sim_send("equip", str(int(value)), sub=slot)
                sim_active_field = None
                return True
            if kind == "food":
                # value is None for "(none)" or an int food id.
                sim_state["food"] = value
                # Push to lua: SIM|food|<id|0>
                _sim_send("food", value if value is not None else 0)
                sim_active_field = None
                return True
            # main_job / sub_job dropdowns. Pure state writes — push to
            # lua via SIM|main_job|<v> / SIM|sub_job|<v>. The compute
            # path consumes these in the synthetic-stats pipeline (TBD
            # in the next phase).
            sim_state[kind] = value
            sim_active_field = None
            _sim_send(kind, value)
            return True
        if action == "export_set":
            # Tell lua to write the current sim equipment to disk.
            # Lua handles formatting + filename so the .lua file uses
            # correct item names from the resources lib.
            try:
                sock_cmd_out.sendto(b"SIM|export", CMD_OUT_ADDR)
            except Exception as e:
                print(f"[OmniWatch] sim export send failed: {e!r}")
            return True
        if action == "import_open":
            # Open the in-overlay file browser modal. Seed cwd from the
            # saved root (or wherever we last were).
            global sim_import_open, sim_import_cwd, sim_import_status
            sim_import_open = True
            sim_import_status = ""
            if not sim_import_cwd and sim_import_root:
                sim_import_cwd = sim_import_root
            return True
        if action == "jp_step":
            cur = int(sim_state.get("jp_spent", 0))
            new = max(0, min(SIM_JP_MAX, cur + int(payload.get("delta", 0))))
            sim_state["jp_spent"] = new
            _sim_send("jp", new)
            return True
        if action == "ml_step":
            cur = int(sim_state.get("master_level", 0))
            new = max(0, min(SIM_ML_MAX, cur + int(payload.get("delta", 0))))
            sim_state["master_level"] = new
            _sim_send("master_level", new)
            return True
        if action == "merit_step":
            key = payload.get("key")
            mx_ = int(payload.get("max", 5))
            cur = int(sim_state.get("merits", {}).get(key, 0))
            new = max(0, min(mx_, cur + int(payload.get("delta", 0))))
            sim_state.setdefault("merits", {})[key] = new
            # Sub field carries the merit name; value carries the count.
            _sim_send("merit", new, sub=key)
            return True
        if action == "active_buff_boost":
            # Per-buff boost toggle (Soul Voice / Marcato on songs;
            # Crooked Cards on rolls). field is the entry key
            # ('boost_sv' / 'boost_marcato' / 'boost_cc'); value is the
            # new bool. Pushed to lua via SIM|buff_update so the
            # buff-stat compute applies the multiplier on next tick.
            idx = int(payload.get("idx", -1))
            field = payload.get("field", "")
            new_val = bool(payload.get("value", False))
            buffs = sim_state.setdefault("active_buffs", [])
            if 0 <= idx < len(buffs) and field:
                buffs[idx][field] = new_val
                # Wire format reuses buff_update: "<idx>:<field>:<value>"
                # Lua-side parser already routes any 'true'/'false' tail
                # to a bool via existing optimal handling logic.
                wire = f"{idx + 1}:{field}:{'true' if new_val else 'false'}"
                _sim_send("buff_update", wire)
            return True
        if action == "buff_picker_open":
            # Open stage 1: pick a job.
            sim_buff_picker = {"stage": "job"}
            return True
        if action == "buff_picker_cancel":
            sim_buff_picker = None
            return True
        if action == "buff_picker_job":
            # Stage 1 → stage 2.
            sim_buff_picker = {"stage": "buff", "job": payload.get("job", "")}
            return True
        if action == "buff_picker_choose":
            # Stage 2 → add to active list, close picker, notify lua.
            bid = payload.get("id", "")
            catalog_entry = next(
                (c for c in SIM_BUFF_CATALOG if c[0] == bid), None)
            if catalog_entry is not None:
                # Catalog tuple is (id, job, name, kind, plus_max).
                # Slice in case a future entry omits the trailing
                # plus_max (4-tuple back-compat).
                _, _, _, kind = catalog_entry[:4]
                # Build the local mirror entry. Defaults match lua's
                # buff_add behavior (rolls start at level 11, songs at +0).
                new_entry = {"id": bid, "plus": 0}
                if kind == "roll":
                    new_entry["level"] = 11
                    new_entry["optimal"] = False
                sim_state.setdefault("active_buffs", []).append(new_entry)
                _sim_send("buff_add", bid)
            sim_buff_picker = None
            return True
        if action == "buff_remove":
            idx = int(payload.get("idx", -1))
            buffs = sim_state.get("active_buffs", [])
            if 0 <= idx < len(buffs):
                del buffs[idx]
                # Lua list is 1-indexed; convert.
                _sim_send("buff_remove", idx + 1)
            return True
        if action == "active_buff_field":
            # ±1 to a numeric field (plus or level) on an active buff.
            idx = int(payload.get("idx", -1))
            field = payload.get("field", "")
            buffs = sim_state.get("active_buffs", [])
            if 0 <= idx < len(buffs):
                cur = int(buffs[idx].get(field, 0))
                lo = int(payload.get("min", 0))
                hi = int(payload.get("max", 0))
                new = max(lo, min(hi, cur + int(payload.get("delta", 0))))
                buffs[idx][field] = new
                # Lua wire format: SIM|buff_update|<idx>:<field>:<value>
                _sim_send("buff_update",
                          f"{idx + 1}:{field}:{new}")
            return True
        if action == "active_buff_optimal":
            # Toggle the optimal-job-present flag on a roll.
            idx = int(payload.get("idx", -1))
            new_val = bool(payload.get("value", False))
            buffs = sim_state.get("active_buffs", [])
            if 0 <= idx < len(buffs):
                buffs[idx]["optimal"] = new_val
                _sim_send("buff_update",
                          f"{idx + 1}:optimal:{'true' if new_val else 'false'}")
            return True
        if action == "reset":
            sim_state = {
                "main_job": "", "sub_job": "",
                "merits": {}, "jp_spent": 0, "gifts": {},
                "buffs":  {}, "active_buffs": [], "master_level": 0, "equipment": {}, "food": None,
            }
            sim_buff_picker = None
            sim_active_field = None
            _sim_send_reset()
            return True
    # Click was inside the window envelope but not on any control →
    # close the dropdown (if open) but otherwise no-op. Read actual
    # rendered size from sim_window_size (with auto-fit fallback to
    # natural height) so a resized window's hit-test stays accurate.
    nat_h = _sim_compute_height()
    eww = max(220, int(sim_window_size[0]))
    user_h = int(sim_window_size[1])
    ewh = user_h if user_h > 0 else nat_h
    env = pygame.Rect(sim_window_pos[0], sim_window_pos[1], eww, ewh)
    if env.collidepoint(mx, my):
        sim_active_field = None
        return True
    return False


def draw_settings_menu(surface):
    """If settings_menu_open is true, render the dropdown panel below the
    gear button in the header. Populates settings_menu_rects so click
    dispatch can find which control was hit."""
    global settings_menu_rects, settings_menu_scroll, settings_menu_panel_rect
    settings_menu_rects = []
    settings_menu_panel_rect = None
    if not settings_menu_open:
        return

    g = _menu_g()
    w, h_natural = settings_menu_size()
    # Anchor x: just inside the left edge, under the gear.
    mx = 6
    # The dropdown only opens via the gear, and the header is force-
    # revealed while the menu is open, so the bar is always present at
    # its edge here. Anchor to the bar itself (header_y()/header_h())
    # rather than layout_top(), which reserves no space in auto-hide
    # mode and would let the menu overlap the bar.
    #   • top header    → open downward from just below the bar.
    #   • bottom header  → gear is at the bottom, so open UPWARD: pin the
    #     dropdown's bottom just above the bar and grow toward the top.
    if not header_at_top():
        bottom_edge = header_y() - 2
        available_h = max(80, bottom_edge - 4)
        h = min(h_natural, available_h)
        my = bottom_edge - h
    else:
        my = header_h() + 2
        available_h = max(80, HEIGHT - my - 4)
        h = min(h_natural, available_h)
    # Clamp x to screen (also covers the bottom-header branch above).
    if mx + w > WIDTH:
        mx = max(0, WIDTH - w)
    overflow = max(0, h_natural - h)
    # Clamp scroll to valid range. Clamping here (rather than in the
    # scroll handler) keeps things consistent if `overflow` shrinks
    # because the user collapsed something or resized the window.
    if settings_menu_scroll < 0:
        settings_menu_scroll = 0
    if settings_menu_scroll > overflow:
        settings_menu_scroll = overflow

    # Background panel.
    pygame.draw.rect(surface, (28, 28, 36), (mx, my, w, h),
                     border_radius=4)
    pygame.draw.rect(surface, (140, 140, 160), (mx, my, w, h), 1,
                     border_radius=4)
    settings_menu_panel_rect = pygame.Rect(mx, my, w, h)

    pad   = round(8 * g)
    row_h = round(24 * g)
    sec_h = round(22 * g)
    placeholder_h = round(18 * g)
    label_font = pygame.font.SysFont("Consolas", max(1, round(12 * g)))
    title_font = pygame.font.SysFont("Consolas", max(1, round(13 * g)), bold=True)
    value_font = pygame.font.SysFont("Consolas", max(1, round(12 * g)), bold=True)
    placeholder_font = pygame.font.SysFont("Consolas", max(1, round(11 * g)), italic=True)
    # Inner control geometry, scaled once here so every row branch and
    # the rects it stores share the same factor (clicks follow the
    # drawn rects, so this also keeps hit-testing aligned).
    inset       = round(4 * g)   # label inset / control right-inset
    ctrl_h      = round(16 * g)  # pill / spinner / button height
    spin_w      = round(18 * g)  # +/- and </> button width
    spin_gap    = round(6 * g)   # gap between spinner value and buttons
    pill_pad    = round(12 * g)  # horizontal padding inside ON/OFF pill
    pill_min_w  = round(38 * g)  # minimum ON/OFF pill width
    btn_pad     = round(14 * g)  # horizontal padding inside action button
    btn_min_w   = round(46 * g)  # minimum action button width
    radius_pill = max(2, round(8 * g))
    ph_inset    = round(8 * g)   # placeholder text extra inset

    # Clip drawing to the panel interior so scrolled-off rows don't
    # bleed past the rounded border. Save/restore the previous clip so
    # we don't wreck whatever the rest of the frame had set.
    prev_clip = surface.get_clip()
    surface.set_clip(pygame.Rect(mx + 1, my + 1, w - 2, h - 2))

    # Group by section so we can render each section in canonical order
    # (regardless of where its entries appear in the schema list) and
    # know which sections are empty.
    grouped = {sec: [] for sec in SETTINGS_SECTIONS}
    for s in SETTINGS_SCHEMA:
        sec = s.get("section")
        # The "Update available" button only appears when the
        # startup update check found a newer release.
        if s.get("key") == "open_update" and not _update_available:
            continue
        if sec in grouped:
            grouped[sec].append(s)

    # Subtract scroll from the starting y. Rows whose y+h is < my get
    # clipped at the top automatically; same for bottom. Click rects
    # added below use these (already-scrolled) coords so hit-testing
    # stays correct.
    cy = my + pad - settings_menu_scroll
    mouse_pos = pygame.mouse.get_pos()

    for section in SETTINGS_SECTIONS:
        # Sections whose name begins with an underscore render an
        # UNNAMED header strip — the underline divider draws but
        # the section name doesn't. Visually separates the loose
        # group from the section above without giving it a label.
        # Empty unnamed sections render nothing at all (no divider,
        # no placeholder) — there'd be nothing to separate from.
        is_loose = section.startswith("_")
        section_entries_check = grouped[section]
        if is_loose and not section_entries_check:
            continue

        if is_loose:
            # Divider only, no name text. Same Y position as a normal
            # header's underline so the visual rhythm matches.
            pygame.draw.line(surface, (90, 90, 110),
                             (mx + pad, cy + sec_h - 2),
                             (mx + w - pad, cy + sec_h - 2))
            cy += sec_h
        else:
            # Section header strip.
            sec_surf = title_font.render(section.upper(), True, (200, 180, 130))
            surface.blit(sec_surf, (mx + pad, cy + 2))
            # Underline running across the row.
            pygame.draw.line(surface, (90, 90, 110),
                             (mx + pad, cy + sec_h - 2),
                             (mx + w - pad, cy + sec_h - 2))
            cy += sec_h

        section_entries = grouped[section]
        if not section_entries:
            # Empty named section: show a subtle placeholder so the user
            # sees the section exists but has nothing to configure
            # yet. (Empty loose sections were already skipped above.)
            ph_surf = placeholder_font.render(
                "(no settings yet)", True, (110, 110, 130))
            surface.blit(ph_surf,
                         (mx + pad + ph_inset,
                          cy + (placeholder_h - ph_surf.get_height()) // 2))
            cy += placeholder_h
            continue

        for schema in section_entries:
            row_rect = pygame.Rect(mx + pad, cy, w - pad * 2, row_h)
            # Hover background.
            is_hover = row_rect.collidepoint(*mouse_pos)
            if is_hover:
                pygame.draw.rect(surface, (44, 44, 56), row_rect,
                                 border_radius=2)

            # Label on the left.
            lab_surf = label_font.render(schema["label"], True,
                                          (210, 210, 220))
            surface.blit(lab_surf,
                         (row_rect.x + inset,
                          row_rect.y + (row_h - lab_surf.get_height()) // 2))

            # Control on the right. Each control's hit rects are added
            # to settings_menu_rects with action dicts the click handler
            # uses to dispatch. We don't read cur_val up-front because
            # button-kind entries don't have values — those go straight
            # to the action-render branch below.
            kind = schema["kind"]
            ctrl_x_right = row_rect.x + row_rect.width - inset

            if kind == "bool":
                # If schema has a live_key, read from the live module
                # global of that name (not from the persistent settings
                # dict). Used for things like setup_mode that shouldn't
                # auto-restore on next launch.
                live_key = schema.get("live_key")
                if live_key:
                    cur_val = bool(globals().get(live_key, False))
                else:
                    cur_val = setting(schema["key"])
                # [ ON / OFF ] toggle as a single pill.
                pill_text = "ON" if cur_val else "OFF"
                pill_surf = value_font.render(pill_text, True,
                                              (40, 40, 50))
                pill_w = max(pill_min_w, pill_surf.get_width() + pill_pad)
                pill_h = ctrl_h
                pill_rect = pygame.Rect(
                    ctrl_x_right - pill_w,
                    row_rect.y + (row_h - pill_h) // 2,
                    pill_w, pill_h)
                pill_color = (140, 200, 140) if cur_val else (160, 100, 100)
                pygame.draw.rect(surface, pill_color, pill_rect,
                                 border_radius=radius_pill)
                surface.blit(pill_surf,
                             (pill_rect.x + (pill_w - pill_surf.get_width()) // 2,
                              pill_rect.y + (pill_h - pill_surf.get_height()) // 2))
                settings_menu_rects.append((pill_rect, {
                    "kind": "toggle", "key": schema["key"],
                    "live_key": live_key,    # propagate so click handler knows
                }))
            elif kind in ("int", "float"):
                cur_val = setting(schema["key"])
                # [-] value [+]
                step = schema.get("step", 1)
                val_text = (f"{cur_val:.1f}" if kind == "float"
                            else str(cur_val))
                val_surf = value_font.render(val_text, True,
                                             (220, 220, 230))
                btn_w = spin_w
                plus_rect = pygame.Rect(
                    ctrl_x_right - btn_w,
                    row_rect.y + (row_h - ctrl_h) // 2, btn_w, ctrl_h)
                val_rect_x = plus_rect.x - spin_gap - val_surf.get_width()
                minus_rect = pygame.Rect(
                    val_rect_x - spin_gap - btn_w,
                    row_rect.y + (row_h - ctrl_h) // 2, btn_w, ctrl_h)
                pygame.draw.rect(surface, (60, 60, 75), minus_rect,
                                 border_radius=2)
                pygame.draw.rect(surface, (60, 60, 75), plus_rect,
                                 border_radius=2)
                ms = value_font.render("-", True, (220, 220, 230))
                ps = value_font.render("+", True, (220, 220, 230))
                surface.blit(ms, (minus_rect.x +
                                  (minus_rect.w - ms.get_width()) // 2,
                                  minus_rect.y +
                                  (minus_rect.h - ms.get_height()) // 2))
                surface.blit(ps, (plus_rect.x +
                                  (plus_rect.w - ps.get_width()) // 2,
                                  plus_rect.y +
                                  (plus_rect.h - ps.get_height()) // 2))
                surface.blit(val_surf,
                             (val_rect_x,
                              row_rect.y + (row_h - val_surf.get_height()) // 2))
                settings_menu_rects.append((minus_rect, {
                    "kind": "step", "key": schema["key"],
                    "delta": -step,
                }))
                settings_menu_rects.append((plus_rect, {
                    "kind": "step", "key": schema["key"],
                    "delta": step,
                }))
            elif kind == "enum":
                cur_val = setting(schema["key"])
                # [<] value [>]
                options = schema.get("options", [])
                # If the schema provides display labels, show those
                # while the underlying stored value stays in `options`.
                # Lets us store ints (e.g. 300 seconds) but display
                # human-friendly labels ("5 min").
                option_labels = schema.get("option_labels")
                if option_labels and len(option_labels) == len(options):
                    try:
                        val_text = str(option_labels[options.index(cur_val)])
                    except ValueError:
                        val_text = str(cur_val)
                else:
                    val_text = str(cur_val)
                val_surf = value_font.render(val_text, True,
                                             (220, 220, 230))
                btn_w = spin_w
                next_rect = pygame.Rect(
                    ctrl_x_right - btn_w,
                    row_rect.y + (row_h - ctrl_h) // 2, btn_w, ctrl_h)
                val_rect_x = next_rect.x - spin_gap - val_surf.get_width()
                prev_rect = pygame.Rect(
                    val_rect_x - spin_gap - btn_w,
                    row_rect.y + (row_h - ctrl_h) // 2, btn_w, ctrl_h)
                pygame.draw.rect(surface, (60, 60, 75), prev_rect,
                                 border_radius=2)
                pygame.draw.rect(surface, (60, 60, 75), next_rect,
                                 border_radius=2)
                ls = value_font.render("<", True, (220, 220, 230))
                rs = value_font.render(">", True, (220, 220, 230))
                surface.blit(ls, (prev_rect.x +
                                  (prev_rect.w - ls.get_width()) // 2,
                                  prev_rect.y +
                                  (prev_rect.h - ls.get_height()) // 2))
                surface.blit(rs, (next_rect.x +
                                  (next_rect.w - rs.get_width()) // 2,
                                  next_rect.y +
                                  (next_rect.h - rs.get_height()) // 2))
                surface.blit(val_surf,
                             (val_rect_x,
                              row_rect.y + (row_h - val_surf.get_height()) // 2))
                settings_menu_rects.append((prev_rect, {
                    "kind": "enum_step", "key": schema["key"],
                    "delta": -1, "options": options,
                }))
                settings_menu_rects.append((next_rect, {
                    "kind": "enum_step", "key": schema["key"],
                    "delta": 1, "options": options,
                }))
            elif kind == "string":
                # Read-only string display. Settings of this kind are
                # set indirectly (via a button that runs a folder-picker
                # or similar) — there's no inline text editor in the
                # menu. Show a truncated value, right-aligned in a dim
                # color so it visually reads as "informational" rather
                # than "click here to edit".
                cur_val = setting(schema["key"])
                disp = str(cur_val) if cur_val else "(not set)"
                # Truncate to keep the row tidy. We don't need to be
                # precise about character count vs pixel width — the
                # menu width is fixed and the help text shows the full
                # value if needed.
                if len(disp) > 32:
                    disp = "…" + disp[-31:]
                col = (170, 170, 185) if cur_val else (110, 110, 130)
                disp_surf = value_font.render(disp, True, col)
                surface.blit(disp_surf,
                    (ctrl_x_right - disp_surf.get_width(),
                     row_rect.y + (row_h - disp_surf.get_height()) // 2))
            elif kind == "button":
                # An action trigger, not a value. Render as a small
                # rectangular button on the right side of the row;
                # click invokes the registered handler. Schema can
                # override the default "OPEN" label via "button_text"
                # — used by entries where "open" doesn't fit (e.g.
                # "Restart overlay" feels more like GO than OPEN).
                btn_text = schema.get("button_text", "OPEN")
                btn_surf = value_font.render(btn_text, True, (40, 40, 50))
                btn_w = max(btn_min_w, btn_surf.get_width() + btn_pad)
                btn_h = ctrl_h
                btn_rect = pygame.Rect(
                    ctrl_x_right - btn_w,
                    row_rect.y + (row_h - btn_h) // 2,
                    btn_w, btn_h)
                # Hover-lift like the toggle pills.
                is_btn_hover = btn_rect.collidepoint(*mouse_pos)
                # CONFIGURE buttons get a light-blue tint so they
                # visually distinguish themselves from the action
                # buttons (OPEN / RESET / EDIT / PICK) — they do
                # something fundamentally different (open a
                # subdialog) so deserve a distinct color. EXIT is
                # red to mark it as a destructive / one-way action
                # — clicking it ends the session. The "Open log
                # folder" button gets a light-purple tint as a
                # one-off — it does its own thing (spawns an
                # explorer window on the log dir) and the color
                # makes it easy to spot when reporting bugs.
                if btn_text == "CONFIGURE":
                    btn_color = ((170, 210, 240) if is_btn_hover
                                  else (140, 185, 220))
                elif btn_text == "EXIT":
                    btn_color = ((230, 110, 110) if is_btn_hover
                                  else (200, 80, 80))
                elif btn_text == "UPDATE":
                    # Green to read as a positive, available action —
                    # distinct from the red EXIT directly below it.
                    btn_color = ((120, 210, 130) if is_btn_hover
                                  else (90, 180, 105))
                elif schema.get("key") == "open_crash_log":
                    btn_color = ((195, 175, 225) if is_btn_hover
                                  else (170, 145, 205))
                else:
                    btn_color = ((200, 180, 130) if is_btn_hover
                                  else (180, 160, 110))
                pygame.draw.rect(surface, btn_color, btn_rect,
                                 border_radius=radius_pill)
                surface.blit(btn_surf,
                             (btn_rect.x + (btn_w - btn_surf.get_width()) // 2,
                              btn_rect.y + (btn_h - btn_surf.get_height()) // 2))
                settings_menu_rects.append((btn_rect, {
                    "kind": "action", "key": schema["key"],
                }))
            cy += row_h

    # Restore the clip rect we changed at the top of the function. If
    # we don't, subsequent draws (settings menu is one of many things
    # rendered each frame) get clipped to the menu interior — bug.
    surface.set_clip(prev_clip)

    # Scrollbar: only when content overflows. Drawn AFTER clip restore
    # so it sits on top of the rounded border instead of getting
    # clipped at the panel edge.
    if overflow > 0:
        sb_w = max(2, round(4 * g))
        sb_x = mx + w - sb_w - round(2 * g)
        # Track (full available height, dim).
        track_y = my + round(2 * g)
        track_h = h - round(4 * g)
        pygame.draw.rect(surface, (40, 40, 50),
                         (sb_x, track_y, sb_w, track_h),
                         border_radius=2)
        # Thumb size proportional to visible/natural ratio.
        thumb_h = max(round(20 * g), int(track_h * h / max(1, h_natural)))
        thumb_y = track_y + int((track_h - thumb_h)
                                * settings_menu_scroll / overflow)
        pygame.draw.rect(surface, (130, 130, 150),
                         (sb_x, thumb_y, sb_w, thumb_h),
                         border_radius=2)


def dispatch_settings_menu_click(mx, my):
    """Resolve a click at (mx, my) against settings_menu_rects. Returns
    True if the click hit a control (and was dispatched), False if the
    menu didn't claim the click. The click handler closes the menu when
    a click lands OUTSIDE both the menu and the gear button."""
    for rect, action in settings_menu_rects:
        if rect.collidepoint(mx, my):
            akind = action["kind"]
            if akind == "toggle":
                # Live-bound toggles (currently just setup_mode) read
                # from a module global, not the settings dict. We
                # toggle by firing the same SETUP|toggle packet that
                # the //ow setup slash command uses, so the canonical
                # state-flipping logic (lock, anchor re-assertion,
                # setup banner) all runs through one path. The live
                # global will be flipped on the next prerender frame.
                live_key = action.get("live_key")
                if live_key == "setup_mode":
                    try:
                        _s = socket.socket(socket.AF_INET,
                                           socket.SOCK_DGRAM)
                        try:
                            _s.sendto(b"SETUP|toggle",
                                      ("127.0.0.1", 5005))
                        finally:
                            _s.close()
                    except Exception as e:
                        print(f"[OmniWatch] setup toggle (settings) "
                              f"failed: {e!r}")
                else:
                    cur = setting(action["key"])
                    set_setting(action["key"], not cur)
            elif akind == "step":
                cur = setting(action["key"])
                schema = SETTINGS_BY_KEY[action["key"]]
                new = cur + action["delta"]
                set_setting(action["key"], new)   # _coerce clamps
                _ = schema   # silence linter
            elif akind == "enum_step":
                cur = setting(action["key"])
                opts = action["options"]
                if opts:
                    try:
                        idx = opts.index(cur)
                    except ValueError:
                        idx = 0
                    new_idx = (idx + action["delta"]) % len(opts)
                    set_setting(action["key"], opts[new_idx])
            elif akind == "action":
                dispatch_setting_action(action["key"])
            return True
    return False


# ── DPS panel ─────────────────────────────────────────────────────────────
# Combat metrics panel populated from UDP port 5010. Shows rolling 5-min
# totals: per-source damage, accuracy/crit/evasion percentages, top WS
# breakdown, recent mobs hit. Toggleable visibility via //ow dps.
DPS_PANEL_PAD       = 8
DPS_PANEL_W         = 290
DPS_PANEL_LINE_H    = 14    # tight rows
DPS_PANEL_HEAD_H    = 18    # section heading row


def _format_dmg(n):
    """Compact damage formatter: 1234 → '1.2k', 1234567 → '1.23M'."""
    if not n:
        return "0"
    if n < 1000:
        return f"{int(n)}"
    if n < 1_000_000:
        return f"{n/1000:.1f}k"
    return f"{n/1_000_000:.2f}M"


def _format_dps_num(dps):
    """DPS number with one decimal up to 999.9, then compact."""
    if dps < 1000:
        return f"{dps:.1f}"
    if dps < 1_000_000:
        return f"{dps/1000:.2f}k"
    return f"{dps/1_000_000:.3f}M"


def scaled_dps_dims(scale):
    """Per-scale font + size dictionary for the DPS panel."""
    scale = _eff(scale)
    pad     = max(4, int(DPS_PANEL_PAD * scale))
    line_h  = max(11, int(DPS_PANEL_LINE_H * scale))
    head_h  = max(14, int(DPS_PANEL_HEAD_H * scale))
    panel_w = max(180, int(DPS_PANEL_W * scale))
    f_label = pygame.font.SysFont("Consolas", max(9, int(11 * scale)), bold=False)
    f_value = pygame.font.SysFont("Consolas", max(9, int(11 * scale)), bold=True)
    f_total = pygame.font.SysFont("Consolas", max(14, int(22 * scale)), bold=True)
    f_head  = pygame.font.SysFont("Consolas", max(10, int(12 * scale)), bold=True)
    return {
        "pad": pad, "line_h": line_h, "head_h": head_h,
        "panel_w": panel_w,
        "f_label": f_label, "f_value": f_value,
        "f_total": f_total, "f_head": f_head,
    }


def dps_panel_size(scale):
    """Estimate (w, h) for the DPS panel given the current dps_state.

    Sections:
      title strip                      (head_h)
      big DPS number                   (f_total height + small pad)
      stats grid                       (4-5 lines; +1 when SC is active)
      WS subhead + WS rows             (variable)
      Mob subhead + mob rows           (variable)
      Party rows                       (variable)
    """
    d = scaled_dps_dims(scale)
    pad   = d["pad"]
    line_h= d["line_h"]
    head_h= d["head_h"]
    w     = d["panel_w"]
    # Use 'me' bucket for sizing when available; else minimum.
    me = dps_state.get("me") or {}
    h = pad + head_h                       # title
    h += d["f_total"].get_height() + 2     # big DPS number
    # Stats grid is 5 rows by default (White/Ranged, WS/Magic, Hits/Crit,
    # Acc/Mag, Evd alone). A 6th SC row appends when there's been any
    # skillchain activity. Must match the conditional row push in
    # draw_dps_panel().
    grid_rows = 5
    if me.get("sc", 0) > 0 or me.get("skillchains", 0) > 0:
        grid_rows = 6
    h += line_h * grid_rows
    if me or any(dps_ws_state.get(s) for s in dps_state):
        ws_for_me = dps_ws_state.get("me", {})
        if ws_for_me:
            h += head_h + line_h * min(4, len(ws_for_me))
    if me:
        mob_for_me = dps_mob_state.get("me", {})
        if mob_for_me:
            h += head_h + line_h * min(4, len(mob_for_me))
    # Party rows (just a single line per non-me source, brief).
    extra_sources = [s for s in dps_state if s != "me"]
    if extra_sources:
        h += head_h + line_h * len(extra_sources)
    h += pad
    if h < 80:
        h = 80
    return w, h


def draw_cfgwiz(surface):
    """Render the config wizard modal overlay if cfgwiz_visible.

    Layout:
      ┌──────────────────────────────────────────────┐
      │  Configure Song+ / Phantom Roll+ Gear        │  title bar
      ├──────────────────────────────────────────────┤
      │  Enter the +N counts from your typical cast  │  description
      │  set. all_songs sums Gjall (4), Whistle (2), │
      │  etc. Per-family fields sum the matching     │
      │  pieces (Mousai Gages NQ=carol+1, +1=carol+2).│
      ├──────────────────────────────────────────────┤
      │  Unity Rank (1=highest, 11=lowest):          │  section header
      │      [-] 1 [+]                               │  numeric field, 1..11
      ├──────────────────────────────────────────────┤
      │  Bards (you):                                │  section header
      │  [-] all_songs 4 [+]   [-] minuet 1 [+]   ...│  6 fields x 2 rows
      │  [-] minne 0 [+]       [-] mambo 0 [+]    ...│
      │                                              │
      │  Corsairs (you):                             │  section header
      │  [-] phantom_roll 0 [+]                      │
      ├──────────────────────────────────────────────┤
      │  Tip: ally bards/cors via //ow config <name> │  hint
      ├──────────────────────────────────────────────┤
      │            [ Save ] [ Skip ] [ Cancel ]      │  buttons
      └──────────────────────────────────────────────┘

    Populates cfgwiz_hit_rects so dispatch_cfgwiz_click can find which
    +/- or button was hit. Each entry is (rect, action, *extra) where
    action is "inc"/"dec" with extra=field_key, or "save"/"skip"/"cancel"
    with no extra.
    """
    global cfgwiz_hit_rects
    cfgwiz_hit_rects = []
    if not cfgwiz_visible:
        return

    win_w, win_h = surface.get_size()
    mw = CFGWIZ_MODAL_W

    # Compute height dynamically. Base layout (title + desc + bards
    # 2-row + cors 1-row + add-ally button + save/skip/cancel) is
    # ~CFGWIZ_MODAL_H. Each ally row adds ~46px, and the dropdown
    # form adds ~94px when open. Cap at 92% of window height so the
    # modal can't overflow the screen on small windows.
    bard_ally_count = len({
        k.split(".")[1] for k in cfgwiz_state
        if k.startswith("bards.") and not k.startswith("bards.self.")
    })
    cor_ally_count = len({
        k.split(".")[1] for k in cfgwiz_state
        if k.startswith("corsairs.")
        and not k.startswith("corsairs.self.")
    })
    extra_h = (bard_ally_count + cor_ally_count) * 46
    if bard_ally_count or cor_ally_count:
        extra_h += 25   # "Allies:" header
    if cfgwiz_dropdown_open:
        extra_h += 94
    desired_h = CFGWIZ_MODAL_H + extra_h
    mh = min(desired_h, int(win_h * 0.92))
    mx = (win_w - mw) // 2
    my = (win_h - mh) // 2

    # Dim the entire window behind the modal so the user knows it's
    # modal and clicks outside the modal go to "cancel".
    dim = pygame.Surface((win_w, win_h), pygame.SRCALPHA)
    dim.fill((0, 0, 0, 160))
    surface.blit(dim, (0, 0))

    # Modal background.
    pygame.draw.rect(surface, (28, 28, 36), (mx, my, mw, mh),
                     border_radius=6)
    pygame.draw.rect(surface, (140, 140, 170), (mx, my, mw, mh), 1,
                     border_radius=6)

    pad = 16
    f_title = get_font("default", 20, bold=True)
    f_text  = get_font("default", 14)
    f_label = get_font("default", 13, bold=True)
    f_value = get_font("default", 17, bold=True)
    f_btn   = get_font("default", 15, bold=True)

    # Title bar.
    tsurf = f_title.render("Configure Song+ / Phantom Roll+ Gear",
                           True, (230, 230, 240))
    surface.blit(tsurf, (mx + pad, my + pad))
    title_h = tsurf.get_height()
    cy = my + pad + title_h + 6

    # Separator under title.
    pygame.draw.line(surface, (90, 90, 110),
                     (mx + pad, cy), (mx + mw - pad, cy), 1)
    cy += 8

    # Description (3 lines wrap).
    desc_lines = [
        "Enter the +N counts from your typical cast set. Sum all gear",
        "pieces in that set. Examples: Gjallarhorn=All Songs+4,",
        "Mousai Gages=Carol+1 (NQ) or Carol+2 (+1).",
    ]
    for line in desc_lines:
        ds = f_text.render(line, True, (190, 190, 200))
        surface.blit(ds, (mx + pad, cy))
        cy += ds.get_height() + 1
    cy += 8

    # Helper to render one numeric field. Layout per cell:
    #
    #          LABEL                (centered above)
    #     VALUE  [+][-]             (value left, buttons grouped right)
    def _field(fx, fy, fw, label, key):
        btn_w = 24
        btn_h = 24
        btn_gap = 2

        # Label row (centered above).
        cell_cx = fx + fw // 2
        ls = f_label.render(label, True, (170, 170, 180))
        surface.blit(ls, (cell_cx - ls.get_width() // 2, fy))

        # Value + buttons row.
        row_y = fy + ls.get_height() + 4

        # Both buttons grouped against the right edge of the cell.
        # Order on screen: [+] then [-] (matches "+ -" in user request).
        minus_rect = pygame.Rect(fx + fw - btn_w, row_y, btn_w, btn_h)
        plus_rect  = pygame.Rect(minus_rect.x - btn_gap - btn_w,
                                 row_y, btn_w, btn_h)

        pygame.draw.rect(surface, (60, 60, 72), plus_rect,
                         border_radius=4)
        pygame.draw.rect(surface, (130, 130, 150), plus_rect, 1,
                         border_radius=4)
        ps = f_btn.render("+", True, (220, 220, 230))
        surface.blit(ps, (plus_rect.centerx - ps.get_width() // 2,
                          plus_rect.centery - ps.get_height() // 2))
        cfgwiz_hit_rects.append((plus_rect, "inc", key))

        pygame.draw.rect(surface, (60, 60, 72), minus_rect,
                         border_radius=4)
        pygame.draw.rect(surface, (130, 130, 150), minus_rect, 1,
                         border_radius=4)
        ms = f_btn.render("-", True, (220, 220, 230))
        surface.blit(ms, (minus_rect.centerx - ms.get_width() // 2,
                          minus_rect.centery - ms.get_height() // 2))
        cfgwiz_hit_rects.append((minus_rect, "dec", key))

        # Value: centered in the space LEFT of the button group.
        v = cfgwiz_state.get(key, 0)
        vs = f_value.render(str(v), True, (230, 230, 240))
        value_area_left  = fx
        value_area_right = plus_rect.x - btn_gap
        value_area_cx    = (value_area_left + value_area_right) // 2
        surface.blit(vs, (value_area_cx - vs.get_width() // 2,
                          row_y + (btn_h - vs.get_height()) // 2))

    # ── Unity Rank row ─────────────────────────────────────────────
    # Single numeric field, 1..11. Stored under "player.unity_rank".
    # GearInfo's Calculator scales Unity-augmented gear by this rank
    # (1 = highest tier of the player's Unity Concord, 11 = lowest).
    # We render it ABOVE the bard/cor rows so it reads as the most
    # prominent setting in the dialog.
    ur_hdr = f_label.render(
        "Unity Rank (1=highest, 11=lowest):", True, (200, 200, 220))
    surface.blit(ur_hdr, (mx + pad, cy))
    cy += ur_hdr.get_height() + 6
    # Use the same _field helper as Bards/Cors but pass a fixed slot
    # width so the field doesn't stretch across the modal. The dispatch
    # handler is special-cased for this key (clamp 1..11 instead of >=0).
    ur_field_w = (mw - 2 * pad) // 6   # one cell wide, like a bard family
    _field(mx + pad, cy, ur_field_w,
           "unity_rank", "player.unity_rank")
    cy += 56
    cy += 8

    # Bards section header.
    bs = f_label.render("Bards (you):", True, (200, 200, 220))
    surface.blit(bs, (mx + pad, cy))
    cy += bs.get_height() + 6

    # Two rows of 6 fields each.
    inner_w = mw - 2 * pad
    field_w = inner_w // 6
    for i, fk in enumerate(CFGWIZ_BARD_FAMILIES_ROW1):
        fx = mx + pad + i * field_w
        _field(fx, cy, field_w, fk, f"bards.self.{fk}")
    cy += 56
    for i, fk in enumerate(CFGWIZ_BARD_FAMILIES_ROW2):
        fx = mx + pad + i * field_w
        _field(fx, cy, field_w, fk, f"bards.self.{fk}")
    cy += 56

    cy += 8

    # Corsairs section header.
    cs = f_label.render("Corsairs (you):", True, (200, 200, 220))
    surface.blit(cs, (mx + pad, cy))
    cy += cs.get_height() + 6

    # Single field for phantom_roll. Use the same field layout but
    # wider so the longer label fits.
    cor_field_w = field_w * 2
    _field(mx + pad, cy, cor_field_w,
           "phantom_roll", "corsairs.self.phantom_roll")
    cy += 56

    cy += 8

    # Geomancers section header. Five fields in a single row, mirroring
    # the bard layout but narrower (5 instead of 6 per row).
    #   indi+    — gear boosting Indi-spell potency
    #   geo+     — gear boosting Geo-spell (Luopan) potency
    #   bolster+ — gear boosting Bolster strength
    #   handbell+— Handbell skill bonus above 900 (scales base potency)
    #   all+     — generic +all geomancy gear bucket (rare)
    gs = f_label.render("Geomancers (you):", True, (200, 200, 220))
    surface.blit(gs, (mx + pad, cy))
    cy += gs.get_height() + 6

    geo_field_w = inner_w // 5
    for i, fk in enumerate(CFGWIZ_GEO_FAMILIES):
        fx = mx + pad + i * geo_field_w
        _field(fx, cy, geo_field_w, fk, f"geomancers.self.{fk}")
    cy += 56

    cy += 8

    # ── Allies section ─────────────────────────────────────────────
    # Discover ally entries from cfgwiz_state. Bards have keys
    # "bards.<name>.<fam>"; cors have "corsairs.<name>.phantom_roll";
    # geomancers have "geomancers.<name>.<field>". Self entries excluded.
    bard_allies = sorted({
        k.split(".")[1] for k in cfgwiz_state
        if k.startswith("bards.") and not k.startswith("bards.self.")
    })
    cor_allies = sorted({
        k.split(".")[1] for k in cfgwiz_state
        if k.startswith("corsairs.")
        and not k.startswith("corsairs.self.")
    })
    geo_allies = sorted({
        k.split(".")[1] for k in cfgwiz_state
        if k.startswith("geomancers.")
        and not k.startswith("geomancers.self.")
    })

    if bard_allies or cor_allies or geo_allies:
        as_h = f_label.render("Allies:", True, (200, 200, 220))
        surface.blit(as_h, (mx + pad, cy))
        cy += as_h.get_height() + 6

    abbreviations = {
        "all_songs": "all", "minuet": "min", "march": "mar",
        "madrigal": "mad", "paeon": "pae", "ballad": "bal",
        "minne": "mne", "mambo": "mam", "prelude": "pre",
        "carol": "car", "etude": "etu", "scherzo": "sch",
        # Geomancer field abbreviations (5-letter cap matching bard style)
        "indi": "ind", "geo": "geo", "bolster": "bol",
        "handbell": "hb",  "all": "all",
    }
    fams_ordered = (CFGWIZ_BARD_FAMILIES_ROW1
                    + CFGWIZ_BARD_FAMILIES_ROW2)

    # Compact field: small [-] N [+] with a tiny label below.
    f_small = get_font("default", 11, bold=True)
    f_smval = get_font("default", 13, bold=True)

    def _compact_field(fx, fy, fw, abbrev, key):
        # Layout: VALUE  [+][-] on top row, abbrev label below.
        btn_w = 16
        btn_h = 16
        btn_gap = 1

        # Both buttons grouped on the right.
        minus_rect = pygame.Rect(fx + fw - btn_w, fy, btn_w, btn_h)
        plus_rect  = pygame.Rect(minus_rect.x - btn_gap - btn_w,
                                 fy, btn_w, btn_h)

        pygame.draw.rect(surface, (60, 60, 72), plus_rect,
                         border_radius=3)
        ps = f_smval.render("+", True, (220, 220, 230))
        surface.blit(ps, (plus_rect.centerx - ps.get_width() // 2,
                          plus_rect.centery - ps.get_height() // 2))
        cfgwiz_hit_rects.append((plus_rect, "inc", key))

        pygame.draw.rect(surface, (60, 60, 72), minus_rect,
                         border_radius=3)
        ms = f_smval.render("-", True, (220, 220, 230))
        surface.blit(ms, (minus_rect.centerx - ms.get_width() // 2,
                          minus_rect.centery - ms.get_height() // 2))
        cfgwiz_hit_rects.append((minus_rect, "dec", key))

        # Value centered in the area left of the buttons.
        v = cfgwiz_state.get(key, 0)
        vs = f_smval.render(str(v), True, (230, 230, 240))
        value_cx = (fx + plus_rect.x - btn_gap) // 2
        surface.blit(vs, (value_cx - vs.get_width() // 2,
                          fy + (btn_h - vs.get_height()) // 2))

        # Abbrev label below.
        ls = f_small.render(abbrev, True, (140, 140, 155))
        surface.blit(ls, (fx + (fw - ls.get_width()) // 2,
                          fy + btn_h + 1))

    inner_w = mw - 2 * pad
    name_w = 110
    rm_w = 26

    for ally in bard_allies:
        row_h = 42
        nl = f_label.render(f"{ally} (bard)", True, (210, 210, 220))
        surface.blit(nl, (mx + pad,
                          cy + (row_h - nl.get_height()) // 2))
        fields_x_start = mx + pad + name_w
        fields_avail_w = inner_w - name_w - rm_w - 8
        cf_w = max(28, fields_avail_w // 12)
        for fi, fk in enumerate(fams_ordered):
            _compact_field(
                fields_x_start + fi * cf_w, cy + 4, cf_w,
                abbreviations.get(fk, fk),
                f"bards.{ally}.{fk}")
        rx = mx + mw - pad - rm_w
        rm_rect = pygame.Rect(rx, cy + 8, rm_w, 22)
        pygame.draw.rect(surface, (110, 70, 80), rm_rect,
                         border_radius=3)
        rm_t = f_btn.render("X", True, (240, 240, 245))
        surface.blit(rm_t, (rm_rect.centerx - rm_t.get_width() // 2,
                            rm_rect.centery - rm_t.get_height() // 2))
        cfgwiz_hit_rects.append((rm_rect, "remove_ally", "bards", ally))
        cy += row_h

    for ally in cor_allies:
        row_h = 42
        nl = f_label.render(f"{ally} (cor)", True, (210, 210, 220))
        surface.blit(nl, (mx + pad,
                          cy + (row_h - nl.get_height()) // 2))
        fields_x_start = mx + pad + name_w
        _compact_field(fields_x_start, cy + 4, 80, "pr",
                       f"corsairs.{ally}.phantom_roll")
        rx = mx + mw - pad - rm_w
        rm_rect = pygame.Rect(rx, cy + 8, rm_w, 22)
        pygame.draw.rect(surface, (110, 70, 80), rm_rect,
                         border_radius=3)
        rm_t = f_btn.render("X", True, (240, 240, 245))
        surface.blit(rm_t, (rm_rect.centerx - rm_t.get_width() // 2,
                            rm_rect.centery - rm_t.get_height() // 2))
        cfgwiz_hit_rects.append((rm_rect, "remove_ally", "corsairs", ally))
        cy += row_h

    for ally in geo_allies:
        row_h = 42
        nl = f_label.render(f"{ally} (geo)", True, (210, 210, 220))
        surface.blit(nl, (mx + pad,
                          cy + (row_h - nl.get_height()) // 2))
        fields_x_start = mx + pad + name_w
        fields_avail_w = inner_w - name_w - rm_w - 8
        # 5 fields share the available width; min field width 36.
        cf_w = max(36, fields_avail_w // 5)
        for fi, fk in enumerate(CFGWIZ_GEO_FAMILIES):
            _compact_field(
                fields_x_start + fi * cf_w, cy + 4, cf_w,
                abbreviations.get(fk, fk),
                f"geomancers.{ally}.{fk}")
        rx = mx + mw - pad - rm_w
        rm_rect = pygame.Rect(rx, cy + 8, rm_w, 22)
        pygame.draw.rect(surface, (110, 70, 80), rm_rect,
                         border_radius=3)
        rm_t = f_btn.render("X", True, (240, 240, 245))
        surface.blit(rm_t, (rm_rect.centerx - rm_t.get_width() // 2,
                            rm_rect.centery - rm_t.get_height() // 2))
        cfgwiz_hit_rects.append((rm_rect, "remove_ally", "geomancers", ally))
        cy += row_h

    cy += 4

    # "+ Add Ally" button (centered). When clicked, the inline drop-
    # down expands directly below it with a name field + bard/cor
    # toggle + Confirm button.
    add_btn_w = 200
    add_btn_h = 30
    add_btn_x = mx + (mw - add_btn_w) // 2
    add_rect = pygame.Rect(add_btn_x, cy, add_btn_w, add_btn_h)
    pygame.draw.rect(surface, (45, 70, 90), add_rect,
                     border_radius=4)
    pygame.draw.rect(surface, (140, 160, 190), add_rect, 1,
                     border_radius=4)
    add_lbl = ("− Cancel Add Ally" if cfgwiz_dropdown_open
               else "+ Add Ally")
    abs2 = f_btn.render(add_lbl, True, (220, 230, 240))
    surface.blit(abs2, (add_rect.centerx - abs2.get_width() // 2,
                        add_rect.centery - abs2.get_height() // 2))
    cfgwiz_hit_rects.append(
        (add_rect,
         "add_ally_cancel" if cfgwiz_dropdown_open else "add_ally_open"))
    cy += add_btn_h + 6

    # Inline dropdown for the new-ally form.
    if cfgwiz_dropdown_open:
        # Background frame so it visually groups together.
        dd_pad_inner = 10
        dd_h = 88
        dd_rect = pygame.Rect(mx + pad, cy,
                              mw - 2 * pad, dd_h)
        pygame.draw.rect(surface, (38, 42, 52), dd_rect,
                         border_radius=4)
        pygame.draw.rect(surface, (120, 130, 150), dd_rect, 1,
                         border_radius=4)

        dx = dd_rect.x + dd_pad_inner
        dy = dd_rect.y + dd_pad_inner

        # Label.
        lbl = f_label.render("Name:", True, (200, 200, 215))
        surface.blit(lbl, (dx, dy + 6))

        # Text input field.
        ib_x = dx + 60
        ib_w = 200
        ib_h = 28
        ib_rect = pygame.Rect(ib_x, dy, ib_w, ib_h)
        pygame.draw.rect(surface, (50, 52, 62), ib_rect,
                         border_radius=4)
        pygame.draw.rect(surface, (180, 180, 200), ib_rect, 2,
                         border_radius=4)
        # Caret blinks at ~2 Hz so the field looks active.
        caret_on = (int(time.time() * 2) % 2 == 0)
        caret_str = "|" if caret_on else " "
        txt = f_value.render(cfgwiz_input_buffer + caret_str,
                             True, (230, 230, 240))
        surface.blit(txt, (ib_rect.x + 6,
                           ib_rect.centery - txt.get_height() // 2))
        # No hit_rect for the field — keystrokes go to it via keyboard
        # handler whenever the dropdown is open.

        # Bard / Cor / Geo radio toggle.
        radio_x = ib_rect.right + 16
        bard_rect = pygame.Rect(radio_x,         dy, 56, ib_h)
        cor_rect  = pygame.Rect(radio_x + 60,    dy, 56, ib_h)
        geo_rect  = pygame.Rect(radio_x + 120,   dy, 56, ib_h)
        bard_active = (cfgwiz_input_kind == "bard")
        cor_active  = (cfgwiz_input_kind == "cor")
        geo_active  = (cfgwiz_input_kind == "geo")
        for rect, label, active, action in [
            (bard_rect, "Bard", bard_active, "kind_bard"),
            (cor_rect,  "COR",  cor_active,  "kind_cor"),
            (geo_rect,  "Geo",  geo_active,  "kind_geo"),
        ]:
            fill = (60, 110, 80) if active else (60, 60, 72)
            pygame.draw.rect(surface, fill, rect, border_radius=4)
            pygame.draw.rect(surface, (180, 180, 200), rect, 1,
                             border_radius=4)
            ts = f_btn.render(label, True, (230, 230, 240))
            surface.blit(ts, (rect.centerx - ts.get_width() // 2,
                              rect.centery - ts.get_height() // 2))
            cfgwiz_hit_rects.append((rect, action))

        # Confirm button on second row.
        conf_rect = pygame.Rect(dx, dy + ib_h + 8,
                                100, 28)
        pygame.draw.rect(surface, (60, 110, 80), conf_rect,
                         border_radius=4)
        pygame.draw.rect(surface, (180, 180, 200), conf_rect, 1,
                         border_radius=4)
        cs2 = f_btn.render("Confirm", True, (240, 240, 245))
        surface.blit(cs2, (conf_rect.centerx - cs2.get_width() // 2,
                           conf_rect.centery - cs2.get_height() // 2))
        cfgwiz_hit_rects.append((conf_rect, "add_ally_confirm"))

        # Hint text inline.
        hint = f_text.render(
            "Enter to confirm, Esc to cancel. Name is lowercased.",
            True, (160, 160, 175))
        surface.blit(hint,
                     (conf_rect.right + 14,
                      conf_rect.centery - hint.get_height() // 2))

        cy += dd_h + 6

    # Buttons at the bottom.
    btn_y = my + mh - 36
    btn_w = 90
    btn_h = 26
    btn_gap = 10
    # Compute button bar centered.
    total_w = btn_w * 3 + btn_gap * 2
    bar_x = mx + (mw - total_w) // 2

    for i, (label, action, fill) in enumerate([
        ("Save",   "save",   (60, 110, 80)),
        ("Skip",   "skip",   (90, 90, 100)),
        ("Cancel", "cancel", (110, 70, 80)),
    ]):
        bx = bar_x + i * (btn_w + btn_gap)
        rect = pygame.Rect(bx, btn_y, btn_w, btn_h)
        pygame.draw.rect(surface, fill, rect, border_radius=4)
        pygame.draw.rect(surface, (180, 180, 200), rect, 1,
                         border_radius=4)
        ts = f_btn.render(label, True, (240, 240, 245))
        surface.blit(ts, (rect.centerx - ts.get_width() // 2,
                          rect.centery - ts.get_height() // 2))
        cfgwiz_hit_rects.append((rect, action))

    # Modal panel rect for click-out detection. Stored as a sentinel
    # last entry with action "modal_bounds" — dispatch checks for
    # collisions against this LAST so click-out (no inside hit) becomes
    # cancel.
    modal_rect = pygame.Rect(mx, my, mw, mh)
    cfgwiz_hit_rects.append((modal_rect, "modal_bounds"))


def dispatch_cfgwiz_click(mx, my):
    """Handle a left-click during cfgwiz modal. Returns True if the click
    was consumed (modal is up and click was inside the modal or on a
    control). Click-out (modal up, click outside) sends CFGWIZ|cancel
    and returns True too — modal eats the click either way."""
    global cfgwiz_visible, cfgwiz_input_kind
    if not cfgwiz_visible:
        return False
    # Walk hit rects. Buttons and +/- come BEFORE modal_bounds in the
    # list, so we'll find them first if the click is on one.
    inside_modal = False
    for entry in cfgwiz_hit_rects:
        rect = entry[0]
        action = entry[1]
        if action == "modal_bounds":
            if rect.collidepoint(mx, my):
                inside_modal = True
            continue
        if not rect.collidepoint(mx, my):
            continue
        if action == "inc":
            key = entry[2]
            if key == "player.unity_rank":
                # Unity Rank is 1..11, default 1.
                cur = int(cfgwiz_state.get(key, 1)) or 1
                cfgwiz_state[key] = min(11, cur + 1)
            else:
                cfgwiz_state[key] = max(0, int(cfgwiz_state.get(key, 0)) + 1)
            return True
        if action == "dec":
            key = entry[2]
            if key == "player.unity_rank":
                cur = int(cfgwiz_state.get(key, 1)) or 1
                cfgwiz_state[key] = max(1, cur - 1)
            else:
                cfgwiz_state[key] = max(0, int(cfgwiz_state.get(key, 0)) - 1)
            return True
        if action == "save":
            _cfgwiz_send_save()
            _cfgwiz_close()
            return True
        if action == "skip":
            _cfgwiz_send("CFGWIZ|skip")
            _cfgwiz_close()
            return True
        if action == "cancel":
            _cfgwiz_send("CFGWIZ|cancel")
            _cfgwiz_close()
            return True
        if action == "add_ally_open":
            _cfgwiz_dropdown_set(True)
            return True
        if action == "add_ally_cancel":
            _cfgwiz_dropdown_set(False)
            return True
        if action == "add_ally_confirm":
            _cfgwiz_commit_ally()
            return True
        if action == "kind_bard":
            cfgwiz_input_kind = "bard"
            return True
        if action == "kind_cor":
            cfgwiz_input_kind = "cor"
            return True
        if action == "kind_geo":
            cfgwiz_input_kind = "geo"
            return True
        if action == "remove_ally":
            _cfgwiz_remove_ally(entry[2], entry[3])  # kind, name
            return True
    # Click was outside any control. If it was outside the modal too,
    # treat as cancel.
    if not inside_modal:
        _cfgwiz_send("CFGWIZ|cancel")
        _cfgwiz_close()
        return True
    # Click inside modal but on dead space — eat it, do nothing.
    return True


def _cfgwiz_close():
    """Close the wizard and reset all related state so the next open
    starts clean."""
    global cfgwiz_visible
    global cfgwiz_dropdown_open, cfgwiz_input_buffer, cfgwiz_input_kind
    cfgwiz_visible = False
    cfgwiz_dropdown_open = False
    cfgwiz_input_buffer = ""
    cfgwiz_input_kind = "bard"


def _cfgwiz_dropdown_set(open_state):
    """Toggle the inline Add-Ally dropdown. Resets the input buffer
    on every open so stale text from a previous attempt doesn't carry
    over."""
    global cfgwiz_dropdown_open, cfgwiz_input_buffer, cfgwiz_input_kind
    cfgwiz_dropdown_open = bool(open_state)
    if open_state:
        cfgwiz_input_buffer = ""
        cfgwiz_input_kind = "bard"


def _cfgwiz_commit_ally():
    """Commit the dropdown's name + kind into cfgwiz_state. No-op if
    the name is empty or 'self' (reserved). Lowercases the name to
    match Buff_Processing's settings.Bards key convention."""
    global cfgwiz_dropdown_open
    name = cfgwiz_input_buffer.strip().lower()
    if not name or name == "self":
        return
    if cfgwiz_input_kind == "bard":
        # Initialize all 12 family fields at 0 so the row renders.
        for fk in (CFGWIZ_BARD_FAMILIES_ROW1
                   + CFGWIZ_BARD_FAMILIES_ROW2):
            cfgwiz_state.setdefault(f"bards.{name}.{fk}", 0)
    elif cfgwiz_input_kind == "geo":
        # Initialize all 5 geomancer fields at 0 so the row renders.
        for fk in CFGWIZ_GEO_FAMILIES:
            cfgwiz_state.setdefault(f"geomancers.{name}.{fk}", 0)
    else:  # "cor"
        cfgwiz_state.setdefault(f"corsairs.{name}.phantom_roll", 0)
    _cfgwiz_dropdown_set(False)


def _cfgwiz_remove_ally(kind, name):
    """Remove all cfgwiz_state keys belonging to the given ally."""
    prefix = f"{kind}.{name}."
    for k in list(cfgwiz_state.keys()):
        if k.startswith(prefix):
            del cfgwiz_state[k]


def _cfgwiz_send(packet_str):
    """Send a CFGWIZ packet to Lua via the inbound command socket."""
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as _s:
            _s.sendto(packet_str.encode("utf-8"),
                      ("127.0.0.1", 5011))
    except Exception as e:
        print(f"[OmniWatch] cfgwiz send failed: {e}")


def _cfgwiz_send_save():
    """Serialize cfgwiz_state into a CFGWIZ|save|<flat-fields> packet
    and send to Lua. Only sends fields whose key starts with bards.,
    corsairs., geomancers., or player. — anything else in cfgwiz_state
    is junk."""
    pairs = []
    for k in sorted(cfgwiz_state.keys()):
        if not (k.startswith("bards.")
                or k.startswith("corsairs.")
                or k.startswith("geomancers.")
                or k.startswith("player.")):
            continue
        pairs.append(f"{k}={int(cfgwiz_state[k])}")
    payload = "CFGWIZ|save|" + ",".join(pairs)
    _cfgwiz_send(payload)


def draw_dps_panel(surface, x, y, scale=1.0, locked=False):
    """Render the DPS panel at (x, y). Returns (w, h)."""
    d = scaled_dps_dims(scale)
    pad    = d["pad"]
    line_h = d["line_h"]
    head_h = d["head_h"]
    pw, ph = dps_panel_size(scale)

    pygame.draw.rect(surface, COL_PANEL,  (x, y, pw, ph), border_radius=4)
    pygame.draw.rect(surface, COL_BORDER, (x, y, pw, ph), 1, border_radius=4)
    draw_accent_stripe(surface, x, y, ph, ACCENT_DPS)

    cy = y + pad
    me = dps_state.get("me")

    # Title strip. Prefer the live `me["window"]` (what the lua just
    # used to bucket the displayed DPS) so the title matches the
    # number. When there's no combat data yet (common when fiddling
    # with settings), fall back to the configured setting so the
    # title reflects the user's current pick — not a hardcoded 5 min
    # placeholder that ignored the setting entirely.
    # Use `is not None` everywhere instead of truthiness — encounter
    # mode is window=0, which is falsy but still a valid window value
    # we want the title to honor.
    if me and me.get("window") is not None:
        win_secs = me["window"]
        scope_lbl = "all" if me.get("scope") == "all" else "me"
    else:
        cfg = setting("dps_window_seconds")
        win_secs = cfg if cfg is not None else 300
        scope_lbl = "me"
    if win_secs == 0:
        # Sentinel: encounter mode (per-fight tracking).
        title = f"DPS · Encounter · {scope_lbl}"
    else:
        win_min = win_secs / 60.0
        # Show one decimal for sub-minute windows, integer otherwise.
        if win_min < 1:
            title = f"DPS · {win_secs}s · {scope_lbl}"
        else:
            title = f"DPS · {win_min:.0f}min · {scope_lbl}"
    t_surf = d["f_head"].render(title, True, COL_LABEL_DIM)
    surface.blit(t_surf, (x + pad, cy))
    cy += head_h

    if not me:
        # Empty state: show a hint and stop.
        hint = d["f_label"].render("(no recent combat)", True, COL_LABEL_DIM)
        surface.blit(hint, (x + pad, cy))
        return pw, ph

    # ── DPS sparkline (renders BEHIND the headline number) ──────────────
    # Trend line of the last DPS_SPARK_WINDOW seconds of 'me' DPS values,
    # scaled vertically to fit the headline strip. Drawn first so the
    # number renders on top of it. Uses the panel's accent color, dimmed,
    # so it ties visually to the panel's identity strip.
    # Toggleable via the "Show sparkline" setting (Settings → Display).
    if setting("dps_sparkline") and len(dps_history) >= 2:
        now = time.time()
        cutoff = now - DPS_SPARK_WINDOW
        # Collect points in window
        pts = [(t, v) for (t, v) in dps_history if t >= cutoff]
        if len(pts) >= 2:
            # NOTE: deliberately do NOT name this local 'line_h' — that
            # would shadow the outer d["line_h"] used by the stats grid
            # and section rows, causing the rest of the panel to
            # mis-space and bleed off the bottom. Use spark_h directly.
            spark_x = x + pad
            spark_y = cy
            spark_w = pw - pad * 2
            spark_h = d["f_total"].get_height()
            # Map (timestamp, dps) → (x, y). Time spans the full window
            # so the line sweeps right as new samples arrive.
            t_min = pts[0][0]
            t_max = pts[-1][0]
            t_range = max(0.5, t_max - t_min)
            v_max = max(v for _, v in pts) or 1.0
            # Slight ceiling so the peak doesn't kiss the top edge.
            v_max *= 1.10
            poly = []
            for (t, v) in pts:
                px_x = spark_x + int((t - t_min) / t_range * spark_w)
                # Invert Y so higher DPS is higher on screen.
                px_y = spark_y + spark_h - int((v / v_max) * spark_h)
                poly.append((px_x, px_y))
            # Dimmed crimson, blends with the DPS accent without fighting
            # the foreground number.
            spark_col = (90, 40, 35)
            try:
                pygame.draw.lines(surface, spark_col, False, poly, 1)
            except ValueError:
                # Fewer than 2 distinct points — draw nothing this frame.
                pass

    # Big total-DPS number.
    dps_str = _format_dps_num(me.get("dps", 0.0))
    dps_surf = d["f_total"].render(dps_str, True, (240, 230, 180))
    surface.blit(dps_surf, (x + pad, cy))
    # "DPS" label to the right of the number.
    lab = d["f_head"].render("DPS", True, COL_LABEL_DIM)
    surface.blit(lab, (x + pad + dps_surf.get_width() + 6,
                        cy + dps_surf.get_height() - lab.get_height() - 2))
    # Total damage and longest hit on the right side.
    tot_str = f"{_format_dmg(me.get('total', 0))} dmg"
    tot_surf = d["f_value"].render(tot_str, True, (200, 200, 230))
    surface.blit(tot_surf, (x + pw - tot_surf.get_width() - pad, cy))
    long_str = f"longest: {_format_dmg(me.get('longest', 0))}"
    long_surf = d["f_label"].render(long_str, True, COL_LABEL_DIM)
    surface.blit(long_surf,
                 (x + pw - long_surf.get_width() - pad,
                  cy + tot_surf.get_height() + 1))
    cy += dps_surf.get_height() + 2

    # Stats grid: 2 columns × 5 rows by default. Rows 1-2 are damage
    # breakdown (white/ranged auto-attacks, then WS/magic active damage).
    # Rows 3-4 are combat-quality stats. Row 5 is evasion (right column
    # intentionally empty — too few stats remain for a full pair, and
    # leaving an isolated value reads cleaner than padding with a
    # contrived metric). The skillchain row is added only when there's
    # been a skillchain in the window.
    col_w = (pw - pad * 3) // 2
    rows = [
        ("White",  _format_dmg(me.get("white", 0)),
         "Ranged", _format_dmg(me.get("ranged", 0))),
        ("WS",     _format_dmg(me.get("ws", 0)),
         "Magic",  _format_dmg(me.get("magic", 0))),
        ("Hits",   f"{me.get('hits', 0)}/{me.get('hits',0)+me.get('misses',0)}",
         "Crit%",  f"{me.get('crit_pct', 0):.1f}"),
        ("Acc%",   f"{me.get('melee_acc', 0):.1f}",
         "Mag%",   f"{me.get('magic_acc', 0):.1f}"),
        ("Evd%",   f"{me.get('evasion', 0):.1f}",
         "",       ""),
    ]
    if me.get("sc", 0) > 0 or me.get("skillchains", 0) > 0:
        rows.append((
            "SC",  _format_dmg(me.get("sc", 0)),
            "SC#", f"{me.get('skillchains', 0)}",
        ))
    for left_lab, left_val, right_lab, right_val in rows:
        # Left column.
        l_lab = d["f_label"].render(left_lab, True, COL_LABEL_DIM)
        l_val = d["f_value"].render(left_val, True, (220, 220, 230))
        surface.blit(l_lab, (x + pad, cy))
        surface.blit(l_val,
                     (x + pad + col_w - l_val.get_width(), cy))
        # Right column.
        r_lab = d["f_label"].render(right_lab, True, COL_LABEL_DIM)
        r_val = d["f_value"].render(right_val, True, (220, 220, 230))
        surface.blit(r_lab, (x + pad * 2 + col_w, cy))
        surface.blit(r_val,
                     (x + pw - pad - r_val.get_width(), cy))
        cy += line_h

    # WS breakdown.
    ws_for_me = dps_ws_state.get("me", {})
    if ws_for_me:
        h_surf = d["f_head"].render("Weapon Skills", True, COL_LABEL_DIM)
        surface.blit(h_surf, (x + pad, cy))
        cy += head_h
        # Sort by total damage descending; show top 4.
        sorted_ws = sorted(ws_for_me.items(),
                           key=lambda kv: kv[1].get("total", 0),
                           reverse=True)[:4]
        for ws_name, w in sorted_ws:
            count = w.get("count", 0)
            total = w.get("total", 0)
            best  = w.get("best", 0)
            avg   = total // count if count else 0
            left = f"{ws_name}  ×{count}"
            right = f"{_format_dmg(total)}  (avg {_format_dmg(avg)}, best {_format_dmg(best)})"
            l_surf = d["f_label"].render(left, True, (210, 200, 230))
            r_surf = d["f_label"].render(right, True, (180, 180, 200))
            surface.blit(l_surf, (x + pad, cy))
            surface.blit(r_surf,
                         (x + pw - pad - r_surf.get_width(), cy))
            cy += line_h

    # Mob breakdown.
    mob_for_me = dps_mob_state.get("me", {})
    if mob_for_me:
        h_surf = d["f_head"].render("Mobs Hit", True, COL_LABEL_DIM)
        surface.blit(h_surf, (x + pad, cy))
        cy += head_h
        sorted_mobs = sorted(mob_for_me.items(),
                             key=lambda kv: kv[1].get("total", 0),
                             reverse=True)[:4]
        for mob_name, m in sorted_mobs:
            total = m.get("total", 0)
            since = m.get("since", 0.0)
            since_lbl = f"{int(since)}s ago" if since >= 1 else "now"
            left = f"{mob_name}"
            right = f"{_format_dmg(total)}  ({since_lbl})"
            l_surf = d["f_label"].render(left, True, (220, 210, 200))
            r_surf = d["f_label"].render(right, True, COL_LABEL_DIM)
            # Truncate name if it would collide with the right side.
            avail_w = pw - pad * 2 - r_surf.get_width() - 6
            if l_surf.get_width() > avail_w:
                # Crude character truncation.
                approx_chars = max(4, int(avail_w / 6))
                left = mob_name[:approx_chars - 1] + "…"
                l_surf = d["f_label"].render(left, True, (220, 210, 200))
            surface.blit(l_surf, (x + pad, cy))
            surface.blit(r_surf,
                         (x + pw - pad - r_surf.get_width(), cy))
            cy += line_h

    # Party / pet rows (anything in dps_state that isn't 'me').
    others = [(s, b) for s, b in dps_state.items() if s != "me"]
    if others:
        h_surf = d["f_head"].render("Others", True, COL_LABEL_DIM)
        surface.blit(h_surf, (x + pad, cy))
        cy += head_h
        for src, b in others:
            left = src
            right = f"{_format_dps_num(b.get('dps', 0))} dps · {_format_dmg(b.get('total', 0))}"
            l_surf = d["f_label"].render(left, True, (200, 220, 200))
            r_surf = d["f_label"].render(right, True, COL_LABEL_DIM)
            surface.blit(l_surf, (x + pad, cy))
            surface.blit(r_surf,
                         (x + pw - pad - r_surf.get_width(), cy))
            cy += line_h

    return pw, ph


# ── Chat panel ────────────────────────────────────────────────────────────
# Scrolling chat log floating panel. Auto-scrolls to bottom; mouse wheel
# scrolls up and pauses auto-scroll; "↓ N new" indicator appears at
# bottom-right when new events arrive while scrolled up, click to jump.
# Resize via corner grip changes pixel size directly (not text scale).
#
# Rendering strategy:
#   1. Compute the visible-line window from chat_scroll_offset.
#   2. Walk chat_events from newest backward, wrap each event, count
#      lines until we've covered the visible window + scroll offset.
#   3. Render those wrapped lines into the visible area, bottom-up.
#   4. Overlay the "jump to bottom" badge if applicable.
#
# Performance: at 60fps with ~12 visible events, ~720 line-renders/sec
# worst case. Wrap is cached per (event, panel_width); font.size() is
# fast. No issues observed in profiling but watch perf if cache misses
# spike (e.g. during rapid resize).

def chat_panel_size(scale=1.0):
    """Return current chat panel (w, h) in pixels.

    Width and height come from chat_panel_dims which the user
    controls via the corner-grip drag handler. Scale is currently
    a no-op for the panel envelope — text size is fixed by font
    selection. Reserved for future per-panel font scaling.
    """
    w = max(CHAT_PANEL_MIN_W, int(chat_panel_dims[0]))
    h = max(CHAT_PANEL_MIN_H, int(chat_panel_dims[1]))
    return w, h


def _chat_format_timestamp(ts):
    """HH:MM format from a unix-seconds float. Used dim/prefix only."""
    return time.strftime("%H:%M", time.localtime(ts))


# Cached fonts. Created lazily on first draw to avoid pygame init order
# issues. Keys: ("body"|"meta"|"badge", size).
_chat_fonts = {}

def _chat_get_font(kind, size):
    # Apply the global UI scale so chat text tracks the same multiplier
    # as every other panel (4K/high-DPI legibility). Fixed call-site
    # sizes get scaled here; the cache key uses the scaled size so
    # different global scales don't collide in the font cache.
    size = max(7, int(round(_eff(size))))
    key = (kind, size)
    f = _chat_fonts.get(key)
    if f is None:
        # The body font uses the global font helper so it picks up the
        # same monospaced face the rest of the UI uses (Consolas with
        # SysFont fallback). meta is slightly smaller; badge slightly
        # bolder.
        f = get_font("Consolas", size, bold=(kind == "badge"))
        _chat_fonts[key] = f
    return f


def _chat_get_cjk_font(size):
    """Return a font with CJK glyph coverage at the requested size.

    Consolas can't render hiragana/katakana/kanji — it shows tofu
    boxes. For chat lines containing Japanese characters (or other
    non-ASCII content like accented player names), we fall back to
    a font with full coverage.

    Strategy (in order):
      1. The bundled Noto Sans JP at chat/fonts/NotoSansJP-Regular.ttf
         — this is the reliable path. Ships with OmniWatch under the
         SIL OFL license. Covers all kana, JIS first+second level
         kanji, and Latin/punctuation. Works regardless of which
         system fonts the user has installed.
      2. System CJK fonts if the bundled file isn't found (e.g. user
         moved it or extraction was incomplete). Tries Yu Gothic UI,
         Meiryo, MS Gothic — all bundled with modern Windows.
      3. pygame's default font — last resort. Lacks CJK coverage so
         Japanese characters will show as tofu boxes, but the panel
         won't crash.

    The first lookup at each size is logged so users can confirm
    Japanese rendering will work without launching FFXI.
    """
    # Match the global UI scale applied in _chat_get_font so CJK and
    # Latin chat text stay the same size.
    size = max(7, int(round(_eff(size))))
    key = ("cjk", size)
    f = _chat_fonts.get(key)
    if f is not None:
        return f

    # Try bundled font first. Path resolution mirrors the icon-loading
    # convention earlier in this file — when frozen (PyInstaller .exe),
    # we look in the .exe's directory + walking up; when running from
    # source, relative to __file__.
    chosen_name = None
    if getattr(sys, "frozen", False):
        _self_dir = os.path.dirname(os.path.abspath(sys.executable))
    else:
        _self_dir = os.path.dirname(os.path.abspath(__file__))
    # Search the .py/exe folder and one level up (PyInstaller dumps
    # the exe into <addon>/dist/ while chat/ lives at <addon>/chat/).
    for _base in [_self_dir, os.path.dirname(_self_dir)]:
        if not _base or not os.path.isdir(_base):
            continue
        for _rel in ("chat/fonts/NotoSansJP-Regular.ttf",
                     "chat/fonts/NotoSansJP-Regular.otf"):
            _path = os.path.join(_base, _rel.replace("/", os.sep))
            if os.path.isfile(_path):
                try:
                    f = pygame.font.Font(_path, size)
                    chosen_name = f"bundled ({_rel})"
                    break
                except (pygame.error, OSError) as _e:
                    print(f"[OmniWatch] Bundled font load failed "
                          f"({_path}): {_e!r}")
        if f is not None:
            break

    # Fallback to system fonts.
    if f is None:
        system_candidates = [
            "Yu Gothic UI", "Yu Gothic",
            "Meiryo UI",    "Meiryo",
            "MS UI Gothic", "MS Gothic",
            "Noto Sans CJK JP", "Noto Sans JP",
            "MS Mincho",
        ]
        for name in system_candidates:
            path = pygame.font.match_font(name)
            if path:
                try:
                    f = pygame.font.Font(path, size)
                    chosen_name = f"system ({name})"
                    break
                except (pygame.error, OSError):
                    continue

    # Last resort: pygame default. No CJK glyphs — tofu boxes ahead.
    if f is None:
        f = pygame.font.SysFont(None, size)
        chosen_name = "<pygame default — NO CJK SUPPORT>"

    # Log selection once per size. If users see "<pygame default>"
    # in their console output they know to install / drop in the
    # bundled font file.
    if size not in _chat_cjk_logged:
        print(f"[OmniWatch] Chat CJK font @ {size}px: {chosen_name}")
        _chat_cjk_logged.add(size)

    _chat_fonts[key] = f
    return f


# Tracks which sizes we've already logged CJK font selection for, so
# repeated calls don't spam the console.
_chat_cjk_logged = set()


def _chat_is_cjk_char(c):
    """Should this character use the CJK fallback font?

    Heuristic: ASCII (codepoint < 0x80) → Consolas. Anything above
    → fallback. This errs on the side of using the fallback font
    for accented Latin too (é, ü, ñ), which Yu Gothic UI renders
    fine; the alternative (per-codepoint coverage check) is much
    more code for marginal visual benefit.
    """
    return ord(c) >= 0x80


def _chat_split_runs(text):
    """Split text into runs of consistent script (ASCII vs CJK/non-ASCII).

    Returns a list of (chunk_str, is_cjk) tuples. Adjacent characters
    of the same script class are grouped into one chunk — fewer runs
    means fewer font.render() calls per line. ASCII-only or pure-CJK
    lines return a single run.
    """
    if not text:
        return []
    runs = []
    cur_chunk = ""
    cur_is_cjk = None
    for c in text:
        is_cjk = _chat_is_cjk_char(c)
        if cur_is_cjk is None:
            cur_is_cjk = is_cjk
        if is_cjk != cur_is_cjk:
            runs.append((cur_chunk, cur_is_cjk))
            cur_chunk = ""
            cur_is_cjk = is_cjk
        cur_chunk += c
    if cur_chunk:
        runs.append((cur_chunk, cur_is_cjk))
    return runs


def _chat_strip_unrenderable(text):
    """Remove codepoints that pygame fonts can't render as readable
    glyphs. Specifically:

      - C0 controls (0x00-0x1F) except tab and newline. These should
        already be stripped on the lua side, but defense in depth.
      - C1 controls (0x80-0x9F). FFXI's autotranslate sometimes
        survives the SJIS decode as bytes in this range.
      - Private Use Area (U+E000-U+F8FF). The Shift-JIS user-defined
        area maps into the PUA, and autotranslate phrase wrappers
        commonly land here when the decoder doesn't know what to do
        with the bytes. Pygame's fallback font renders these as empty
        boxes which look like garbage to the user.
      - Specials (U+FFF0-U+FFFF) including the replacement character
        U+FFFD when it appears as decoder residue (we keep U+FFFD
        only in segments that came in pre-segmented, since those have
        already been decoded once on the lua side — but at the render
        level we treat all of these as unrenderable).
      - Variation selectors and zero-width joiner residue
        (U+FE00-U+FE0F, U+200B-U+200F).

    The result is what the user actually sees. Original text in
    chat_events is unchanged so diagnostics still show the raw bytes.
    """
    if not text:
        return text
    out = []
    for ch in text:
        cp = ord(ch)
        if cp == 0x09 or cp == 0x0A:
            out.append(ch)
            continue
        if cp < 0x20:
            continue          # C0 control
        if 0x7F <= cp <= 0x9F:
            continue          # DEL + C1 controls
        if 0xE000 <= cp <= 0xF8FF:
            continue          # Private Use Area
        if 0xFE00 <= cp <= 0xFE0F:
            continue          # Variation selectors
        if 0x200B <= cp <= 0x200F:
            continue          # ZWJ / direction marks
        if 0xFFF0 <= cp <= 0xFFFF:
            continue          # Specials block (incl. U+FFFD)
        out.append(ch)
    return "".join(out)


def _chat_render_mixed(text, body_font, cjk_font, color):
    """Render a line that may contain mixed ASCII and CJK/non-ASCII.

    Splits the text into script runs, renders each with the
    appropriate font, then composes a single surface. ASCII-only
    text falls through to a single body_font.render() — same cost
    as the non-fallback path.

    Returns a pygame.Surface (caller blits at the desired position).
    """
    if not text:
        return body_font.render("", True, color)
    # Strip codepoints pygame can't render as glyphs — FFXI auto-
    # translate residue, control bytes, PUA junk. Done at the render
    # funnel so every chat path benefits without changes upstream.
    text = _chat_strip_unrenderable(text)
    if not text:
        return body_font.render("", True, color)
    runs = _chat_split_runs(text)

    # Diagnostic: dump up to 5 different non-ASCII texts that arrive at
    # the renderer. The earlier one-shot version showed U+0702 (Syriac)
    # from an unidentified source, so we want broader visibility. We
    # also dump the full UTF-8 byte encoding of each chunk to identify
    # whether the bytes look like valid Japanese (E3 8x xx, E4-E9 xx
    # xx) or something else entirely.
    global _chat_render_diag_count
    if _chat_render_diag_count < 5:
        for chunk, is_cjk in runs:
            if is_cjk and chunk:
                cps = [f"U+{ord(c):04X}" for c in chunk[:12]]
                tail = "..." if len(chunk) > 12 else ""
                bytes_hex = chunk.encode("utf-8", errors="replace").hex(" ")
                # Truncate to first 60 bytes for log readability.
                if len(bytes_hex) > 180:
                    bytes_hex = bytes_hex[:180] + " ..."
                print(f"[OmniWatch] CJK render #{_chat_render_diag_count + 1}: "
                      f"text={chunk!r} "
                      f"codepoints=[{', '.join(cps)}{tail}] "
                      f"utf8_hex=[{bytes_hex}]")
                # Also log the surrounding FULL text so we can see what
                # came in as a whole and identify which chat line / UI
                # element produced this.
                full_cps = [f"U+{ord(c):04X}" for c in text[:30]]
                print(f"[OmniWatch] CJK render #{_chat_render_diag_count + 1} "
                      f"full text={text!r} (first 30 codepoints: "
                      f"{', '.join(full_cps)})")
                _chat_render_diag_count += 1
                break

    # Fast path: single run — render directly, no compositing.
    if len(runs) == 1:
        chunk, is_cjk = runs[0]
        font = cjk_font if is_cjk else body_font
        return font.render(chunk, True, color)
    # Mixed: render each run, compose horizontally.
    surfs = []
    for chunk, is_cjk in runs:
        font = cjk_font if is_cjk else body_font
        surfs.append(font.render(chunk, True, color))
    total_w = sum(s.get_width() for s in surfs)
    max_h = max(s.get_height() for s in surfs)
    composed = pygame.Surface((max(1, total_w), max(1, max_h)),
                              pygame.SRCALPHA)
    cur_x = 0
    for s in surfs:
        # Top-align (not baseline-align) for simplicity. The two
        # fonts have similar metrics at the same size; tiny vertical
        # mismatch is acceptable. If users complain about wobble, we
        # can compute baselines per font and align by that.
        composed.blit(s, (cur_x, 0))
        cur_x += s.get_width()
    return composed


# Module-level counter for the CJK render diagnostic. Allows up to 5
# different non-ASCII texts to be logged per session — enough to spot
# patterns without flooding the console. Reset by reloading OmniWatch.
_chat_render_diag_count = 0


def _chat_measure_mixed(text, body_font, cjk_font):
    """Measure pixel width of mixed-script text without rendering.

    Used by the wrap routine. Walks runs the same way _chat_render_mixed
    does, sums per-run widths. font.size(s)[0] is O(n) in n bytes; this
    is fine for wrap measurement (called against trial strings during
    word fit-checking).
    """
    if not text:
        return 0
    runs = _chat_split_runs(text)
    w = 0
    for chunk, is_cjk in runs:
        font = cjk_font if is_cjk else body_font
        w += font.size(chunk)[0]
    return w


def _chat_font_sizes():
    """Return current body/meta/tab font sizes based on chat_font_size setting.

    Setting is "small", "medium", or "large" — anything else falls back
    to medium. Sizes are looked up in CHAT_FONT_SIZE_MAP. Reading the
    setting once per draw keeps the panel responsive to setting changes
    without needing render-side cache invalidation.
    """
    pref = setting("chat_font_size") if "chat_font_size" in SETTINGS_BY_KEY else "medium"
    return CHAT_FONT_SIZE_MAP.get(pref, CHAT_FONT_SIZE_MAP["medium"])


def _chat_composer_send():
    """Format and dispatch the current composer text as a slash command.

    Format depends on:
      * Active channel (say/tell/reply/shout/yell/ls1/ls2)
      * Whether the message starts with '/' (raw command escape: any
        text starting with / is sent as-is, bypassing channel prefix
        — works on ALL channels per design)
      * For tell: requires a non-empty target name in the tell-target
        field, otherwise refuses to send

    Dispatch is the same UDP rail that hotbar button commands use:
      socket.sendto("input <slash command>", ("127.0.0.1", 5011))
    The lua side translates "input ..." into windower.send_command,
    which feeds FFXI's chat system. We use SETTING|... or other prefix
    schemes for non-FFXI ones; for chat we pass "input <cmd>" directly.

    On success, clears the input field but preserves channel selection
    (the user is likely to send another message on the same channel).
    """
    global chat_composer_text, chat_composer_cursor

    text = chat_composer_text.strip()
    if not text:
        return

    ch_idx = chat_composer_channel % len(CHAT_COMPOSER_CHANNELS)
    _ch_key, _ch_label, ch_prefix = CHAT_COMPOSER_CHANNELS[ch_idx]

    # Slash-command escape: any input starting with '/' is sent as a
    # raw FFXI command on every channel. Bypasses the channel prefix.
    # Useful for /lockstyle, /follow, /target, etc. without leaving
    # the chat input.
    if text.startswith("/"):
        payload = "input " + text
    elif _ch_key == "tell":
        target = chat_composer_tell_to.strip()
        if not target:
            # Silent fail — the empty target field will visually nag
            # the user. Could pop a transient message later.
            return
        payload = "input /t " + target + " " + text
    else:
        # Standard channel: prefix + message.
        payload = "input " + ch_prefix + text

    # Dispatch via the same UDP socket buttons use.
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.sendto(payload.encode("utf-8"), ("127.0.0.1", 5011))
        s.close()
    except Exception as e:
        print(f"[OmniWatch] chat send failed: {e}")
        return

    # Clear input on successful dispatch. Keep tell-target so the user
    # can fire follow-up tells to the same person without retyping.
    chat_composer_text = ""
    chat_composer_cursor = 0


# ── Click-on-sender-name actions ─────────────────────────────────────────
# Mouse interactions on rendered sender names in the chat panel. The
# rendering side records per-frame hit-test rects into
# _chat_clickable_senders (entries: {"rect", "name", "actor_class"}).
# These helpers are called from the main MOUSEBUTTONDOWN handler when
# a click hits one of those rects.
#
# Left-click → populate the chat composer with a tell to that name. We
# deliberately do NOT fire the /tell immediately: the user almost always
# wants to type a message first. Switching the composer channel to
# "tell" + filling the tell-target field + focusing the message input
# is the natural setup for that.
#
# Right-click → open a context menu next to the rect with "Send Tell"
# and "Invite to Party". "Send Tell" reuses the left-click setup;
# "Invite to Party" fires `/pcmd add <name>` directly via the same UDP
# rail the hotbar buttons use.

def _chat_compose_tell_to(name):
    """Set up the composer to send a tell to `name`.

    Switches the composer to the "tell" channel (index 1 in
    CHAT_COMPOSER_CHANNELS), populates the tell-target field, focuses
    the message body input (so the user can immediately start typing
    without an extra click), and shows the composer if hidden. The
    user still has to type a message and hit send / Enter — we never
    fire a /tell automatically from a click, since that would make
    accidental clicks send empty tells.

    Safe to call with an empty `name` (no-op).
    """
    if not name:
        return
    global chat_composer_channel, chat_composer_tell_to
    global chat_composer_tell_to_cursor
    global chat_composer_focused, chat_composer_tell_to_focused
    global chat_composer_visible
    # Find the "tell" channel index by key, in case the channels list
    # is reordered later (safer than hard-coding 1).
    tell_idx = 1
    for i, (key, _label, _prefix) in enumerate(CHAT_COMPOSER_CHANNELS):
        if key == "tell":
            tell_idx = i
            break
    chat_composer_channel = tell_idx
    chat_composer_tell_to = name
    chat_composer_tell_to_cursor = len(name)
    # Focus the MESSAGE body, not the tell-target, since the target is
    # now filled in. The user wants to start typing the message.
    chat_composer_focused = True
    chat_composer_tell_to_focused = False
    if not chat_composer_visible:
        chat_composer_visible = True


def _chat_invite_to_party(name):
    """Send /pcmd add <name> via the UDP command rail.

    Same dispatch path used by hotbar windower-kind buttons and the
    composer send helper. If the target is already in your party, or
    you're not the party leader, FFXI will reject the invite with its
    own error message — we don't try to validate client-side. The
    in-game error feedback is more informative than anything we'd
    invent.

    No-op for empty name.
    """
    if not name:
        return
    try:
        payload = ("input /pcmd add " + name).encode("utf-8")
        sock_cmd_out.sendto(payload, CMD_OUT_ADDR)
        print(f"[OmniWatch] invite -> {name}")
    except Exception as e:
        print(f"[OmniWatch] invite failed: {e!r}")


def _chat_blacklist_add(name):
    """Add `name` to the OmniWatch routing-config blacklist.

    Writes to _meta.blacklist in omniwatch_chat_routing.json (same
    field the routing GUI's footer manages — the "Mytoy ×" chip row
    you see in the GUI). NOT to FFXI's server-side /blist: OmniWatch
    chat is a local overlay concern, separate from the in-game
    blacklist by design. Blacklisting in the overlay should NOT
    affect what FFXI itself sees, only what the OW chat panel shows.

    Two-step update for instant effect with no reload required:
      1. Add to _chat_blacklist live set so the very next filter pass
         hides messages from this sender (chat panel updates on the
         next frame).
      2. Append to _meta.blacklist in the JSON file so the entry
         survives an addon reload / restart.

    The live set is compared case-insensitively (lowercase strings);
    the JSON stores the original-case name to match the GUI display
    convention ("Mytoy" not "mytoy"). De-duplicates on both sides.

    Known race: if the routing GUI is open at the same time, its
    Save will rewrite the whole file with its in-memory blacklist
    snapshot — possibly clobbering our addition. The GUI footer text
    already tells users to "Reload OmniWatch to apply", so collision
    in practice is rare and self-recovering (re-add and don't reopen
    the GUI mid-session).

    No-op for empty name.
    """
    if not name:
        return
    name_clean = name.strip()
    if not name_clean:
        return

    global _chat_blacklist
    # Live set update first. Filter takes effect on the next frame's
    # _chat_classify_for_routing call — chat panel immediately hides
    # messages from this sender without a reload.
    _chat_blacklist = set(_chat_blacklist) if _chat_blacklist else set()
    _chat_blacklist.add(name_clean.lower())

    # Persist to JSON. Pull current file, splice our entry into
    # _meta.blacklist, rewrite. We do this manually rather than
    # routing through the GUI's save_config helper because that helper
    # rewrites the WHOLE config (stripping empty actor sections, etc.);
    # we only want to touch _meta.blacklist, leaving everything else
    # byte-for-byte intact in case the user has hand-edited the rest.
    try:
        path = os.path.join(SETTINGS_DIR, "omniwatch_chat_routing.json")
    except Exception as e:
        print(f"[OmniWatch] blacklist add: bad path: {e!r}")
        return
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if not isinstance(data, dict):
                data = {}
        else:
            data = {}
        meta = data.get("_meta")
        if not isinstance(meta, dict):
            meta = {}
            data["_meta"] = meta
        # Existing list (or empty if missing / wrong type).
        cur = meta.get("blacklist")
        if not isinstance(cur, list):
            cur = []
        # De-dupe case-insensitively against existing entries while
        # preserving original casing where present. If the name is
        # already there in any case, skip the write — live set update
        # above is still beneficial (it normalizes to lowercase) but
        # we don't need to touch the file.
        cur_lower = {s.strip().lower() for s in cur
                     if isinstance(s, str) and s.strip()}
        if name_clean.lower() in cur_lower:
            print(f"[OmniWatch] blacklist add: {name_clean!r} already "
                  "in routing config (live set refreshed)")
            return
        cur.append(name_clean)
        # Sort for stable file diffs — matches the GUI's save behavior.
        meta["blacklist"] = sorted(cur, key=str.lower)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
        print(f"[OmniWatch] blacklist add: {name_clean} → "
              "omniwatch_chat_routing.json")
    except Exception as e:
        print(f"[OmniWatch] blacklist add failed for {name_clean!r}: {e!r}")


def _chat_open_name_context_menu(name, actor_class, anchor_pos):
    """Open the right-click context menu for a chat sender name.

    Stores the menu state in _chat_name_context_menu; the actual
    rendering happens in draw_chat_panel (which positions the menu
    near anchor_pos and records per-item rects for hit-testing).

    All names get the same three items (Send Tell, Invite to Party,
    Blacklist) regardless of actor_class — even self/party. Per the
    design call: party/self click is harmless (tell to a party member
    works fine, invite is silently rejected by FFXI for already-in-party
    targets, blacklist on a self/party name is the user's call).

    The Blacklist item carries a `gap_before` flag that the menu
    renderer uses to insert extra vertical space + a separator line
    above it. Misclick safety: blacklist is a one-way action in FFXI
    (no undo confirmation), so the visual gap keeps it from sitting
    directly under Invite where an off-by-one click might land.
    """
    global _chat_name_context_menu
    _chat_name_context_menu = {
        "name":        name,
        "actor_class": actor_class or "other",
        "anchor":      anchor_pos,    # (x, y) where the menu opens
        "items": [
            {"label": "Send Tell",       "action": "tell",      "rect": None},
            {"label": "Invite to Party", "action": "invite",    "rect": None},
            {"label": "Blacklist Add",   "action": "blacklist", "rect": None,
             "gap_before": True},
        ],
    }


def _chat_close_name_context_menu():
    """Dismiss the context menu, if open."""
    global _chat_name_context_menu
    _chat_name_context_menu = None


def _chat_handle_name_context_action(action, name):
    """Dispatch a context-menu item's action.

    Called when the user clicks one of the menu items in
    _chat_name_context_menu. Closes the menu unconditionally after
    dispatch so the menu doesn't linger after the action fires.
    """
    if action == "tell":
        _chat_compose_tell_to(name)
    elif action == "invite":
        _chat_invite_to_party(name)
    elif action == "blacklist":
        _chat_blacklist_add(name)
    _chat_close_name_context_menu()


def _chat_update_name_hover(mx, my):
    """Update _chat_name_hover based on current mouse position.

    Walks _chat_clickable_senders and sets the hover state to the
    sender name whose rect contains (mx, my), or None if no rect
    matches. Cheap — typically <50 entries, single collidepoint per.
    Called from MOUSEMOTION; the next draw paints accordingly.
    """
    global _chat_name_hover
    hit = None
    for entry in _chat_clickable_senders:
        try:
            if entry["rect"].collidepoint(mx, my):
                hit = entry["name"]
                break
        except Exception:
            continue
    _chat_name_hover = hit


def _chat_handle_name_click(button, mx, my):
    """Check if (mx, my) hit a clickable sender name and act on it.

    Returns True if a name was hit and the click was consumed.
    `button` is the pygame mouse button index (1 = left, 3 = right).
    Should be called BEFORE more generic chat-panel click handlers so
    a click on a name doesn't fall through to e.g. tab switching.
    """
    for entry in _chat_clickable_senders:
        try:
            if not entry["rect"].collidepoint(mx, my):
                continue
        except Exception:
            continue
        name = entry.get("name") or ""
        actor_class = entry.get("actor_class") or "other"
        if not name:
            return False
        if button == 1:
            _chat_compose_tell_to(name)
            return True
        if button == 3:
            _chat_open_name_context_menu(name, actor_class, (mx, my))
            return True
        return False
    return False


def _chat_handle_name_context_click(button, mx, my):
    """Hit-test the open context menu, if any.

    Returns True if the click was consumed (either by selecting an
    item or by clicking outside the menu, which dismisses it).
    """
    if _chat_name_context_menu is None:
        return False
    # Any click while the menu is open consumes the event — either as
    # an item selection or as a dismiss. This is standard menu UX:
    # the menu has modal focus until resolved.
    for item in _chat_name_context_menu.get("items", []):
        r = item.get("rect")
        if r is not None and r.collidepoint(mx, my):
            # Left-click selects; right-click on a menu item also
            # selects (slightly forgiving — user already opened the
            # menu, they probably meant to click).
            if button in (1, 3):
                action = item.get("action")
                name = _chat_name_context_menu.get("name") or ""
                _chat_handle_name_context_action(action, name)
                return True
    # Click was inside the menu's overall rect but not on any item?
    # Still consume to prevent accidental fall-through. Otherwise it's
    # outside the menu → dismiss.
    menu_rect = _chat_name_context_menu.get("rect")
    if menu_rect is not None and menu_rect.collidepoint(mx, my):
        return True
    _chat_close_name_context_menu()
    return True


def _chat_draw_name_context_menu(surface):
    """Render the open context menu, if any, and record item rects.

    Called from draw_chat_panel after all other chat rendering so the
    menu sits ON TOP of everything else in the panel. Sets each item's
    rect for hit-testing on the next click.

    Layout:
      ┌────────────────────────┐
      │ <Name>                 │   ← header row (non-clickable label)
      ├────────────────────────┤
      │ Send Tell              │   ← item row
      │ Invite to Party        │   ← item row
      └────────────────────────┘

    Width is sized to fit the longest item label + name. Anchored at
    the click position; if it would clip off the right/bottom edge of
    the surface, shift it left/up to stay on-screen.
    """
    if _chat_name_context_menu is None:
        return
    menu = _chat_name_context_menu
    name = menu.get("name") or ""
    items = menu.get("items", [])
    if not items:
        return

    # Font + sizing.
    font = _chat_get_font("meta", 12)
    pad_x = 10
    pad_y = 5
    row_h = font.get_linesize() + 2
    # Extra vertical space inserted above any item that carries the
    # `gap_before` flag (currently only Blacklist). Acts as a visual
    # "section break" so a misclick from the row above doesn't slide
    # into a destructive action.
    gap_h = 6     # blank pixels above the gapped item
    sep_h = 1     # separator line drawn inside the gap
    header_text = font.render(name, True, CHAT_YELL_ZONE_COLOR)
    item_surfs = []
    for it in items:
        item_surfs.append(font.render(it.get("label") or "",
                                      True, (230, 230, 230)))
    max_w = header_text.get_width()
    for s in item_surfs:
        if s.get_width() > max_w:
            max_w = s.get_width()
    menu_w = max_w + pad_x * 2
    # Sum extra height from any gap_before items so the backdrop is
    # tall enough to contain them. Counting it once here keeps the
    # menu_h / menu_rect / clamping math in one place.
    gap_total = 0
    for it in items:
        if it.get("gap_before"):
            gap_total += gap_h
    # Header row + separator + items rows + gaps.
    menu_h = row_h + 1 + row_h * len(items) + gap_total + pad_y * 2

    # Anchor; clamp to surface bounds.
    ax, ay = menu.get("anchor", (0, 0))
    sw, sh = surface.get_size()
    mx = min(ax, sw - menu_w - 2)
    my = min(ay, sh - menu_h - 2)
    if mx < 0:
        mx = 0
    if my < 0:
        my = 0
    menu_rect = pygame.Rect(mx, my, menu_w, menu_h)
    menu["rect"] = menu_rect

    # Backdrop.
    bg = pygame.Surface((menu_w, menu_h), pygame.SRCALPHA)
    bg.fill((24, 28, 36, 240))
    surface.blit(bg, menu_rect.topleft)
    pygame.draw.rect(surface, (100, 110, 130), menu_rect, 1)

    # Header label (the name in pale yellow, non-clickable).
    cy = my + pad_y
    surface.blit(header_text, (mx + pad_x, cy))
    cy += row_h
    # Separator line.
    pygame.draw.line(surface, (60, 70, 85),
                     (mx + 4, cy), (mx + menu_w - 4, cy), 1)
    cy += 1

    # Item rows. Record each row's rect for hit-testing. Hover
    # highlight uses the live mouse position. Items flagged
    # `gap_before` get extra vertical space plus a thin separator
    # line inserted above them — the misclick-safety affordance for
    # destructive actions like Blacklist.
    mouse_pos = pygame.mouse.get_pos()
    for i, it in enumerate(items):
        if it.get("gap_before"):
            # Inject the gap, with a separator centered vertically
            # within it. The separator runs the full menu width
            # (minus a small inset) so it visually belongs to the
            # menu rather than to either neighboring item.
            sep_y = cy + (gap_h // 2)
            pygame.draw.line(surface, (60, 70, 85),
                             (mx + 4, sep_y), (mx + menu_w - 4, sep_y),
                             sep_h)
            cy += gap_h
        item_rect = pygame.Rect(mx + 1, cy, menu_w - 2, row_h)
        it["rect"] = item_rect
        if item_rect.collidepoint(mouse_pos):
            hov_bg = pygame.Surface((item_rect.width, item_rect.height),
                                    pygame.SRCALPHA)
            hov_bg.fill((60, 80, 110, 220))
            surface.blit(hov_bg, item_rect.topleft)
        surface.blit(item_surfs[i], (mx + pad_x, cy + 1))
        cy += row_h


def _chat_composer_handle_keydown(event):
    """Process a pygame KEYDOWN event for the composer.

    Returns True if the event was consumed, False if it should fall
    through to other handlers. Routes based on which composer field
    is focused (main message vs tell-target).
    """
    global chat_composer_text, chat_composer_cursor
    global chat_composer_tell_to, chat_composer_tell_to_cursor
    global chat_composer_focused, chat_composer_tell_to_focused

    key = event.key

    # Enter on any focused field → send.
    if key in (pygame.K_RETURN, pygame.K_KP_ENTER):
        _chat_composer_send()
        return True

    # Escape clears the focused field's content AND unfocuses.
    # Matches the design: "Enter sends, Escape clears + unfocuses."
    if key == pygame.K_ESCAPE:
        if chat_composer_tell_to_focused:
            chat_composer_tell_to = ""
            chat_composer_tell_to_cursor = 0
            chat_composer_tell_to_focused = False
        if chat_composer_focused:
            chat_composer_text = ""
            chat_composer_cursor = 0
            chat_composer_focused = False
        return True

    # Tab: switch focus between main and tell-target when on tell
    # channel. Doesn't apply otherwise — fall through (allowing tab
    # to be consumed by other handlers if any).
    if key == pygame.K_TAB:
        ch_idx = chat_composer_channel % len(CHAT_COMPOSER_CHANNELS)
        is_tell = CHAT_COMPOSER_CHANNELS[ch_idx][0] == "tell"
        if is_tell:
            chat_composer_focused, chat_composer_tell_to_focused = (
                chat_composer_tell_to_focused, chat_composer_focused)
            return True
        return False

    # The rest operates on whichever field is focused.
    if chat_composer_tell_to_focused:
        # Edit the tell-target buffer.
        if key == pygame.K_BACKSPACE:
            if chat_composer_tell_to_cursor > 0:
                cur = chat_composer_tell_to_cursor
                chat_composer_tell_to = (
                    chat_composer_tell_to[:cur - 1]
                    + chat_composer_tell_to[cur:])
                chat_composer_tell_to_cursor -= 1
            return True
        if key == pygame.K_DELETE:
            cur = chat_composer_tell_to_cursor
            chat_composer_tell_to = (
                chat_composer_tell_to[:cur]
                + chat_composer_tell_to[cur + 1:])
            return True
        if key == pygame.K_LEFT:
            chat_composer_tell_to_cursor = max(
                0, chat_composer_tell_to_cursor - 1)
            return True
        if key == pygame.K_RIGHT:
            chat_composer_tell_to_cursor = min(
                len(chat_composer_tell_to),
                chat_composer_tell_to_cursor + 1)
            return True
        if key == pygame.K_HOME:
            chat_composer_tell_to_cursor = 0
            return True
        if key == pygame.K_END:
            chat_composer_tell_to_cursor = len(chat_composer_tell_to)
            return True
        # Other keys fall through — TEXTINPUT will handle character
        # insertion for typed letters.
        return False

    if chat_composer_focused:
        # Edit the main message buffer. Same operations as above but
        # against chat_composer_text + chat_composer_cursor.
        if key == pygame.K_BACKSPACE:
            if chat_composer_cursor > 0:
                cur = chat_composer_cursor
                chat_composer_text = (chat_composer_text[:cur - 1]
                                      + chat_composer_text[cur:])
                chat_composer_cursor -= 1
            return True
        if key == pygame.K_DELETE:
            cur = chat_composer_cursor
            chat_composer_text = (chat_composer_text[:cur]
                                  + chat_composer_text[cur + 1:])
            return True
        if key == pygame.K_LEFT:
            chat_composer_cursor = max(0, chat_composer_cursor - 1)
            return True
        if key == pygame.K_RIGHT:
            chat_composer_cursor = min(
                len(chat_composer_text), chat_composer_cursor + 1)
            return True
        if key == pygame.K_HOME:
            chat_composer_cursor = 0
            return True
        if key == pygame.K_END:
            chat_composer_cursor = len(chat_composer_text)
            return True
        return False

    return False


def _chat_composer_handle_textinput(text):
    """Insert typed text at the cursor of the focused composer field.

    pygame's TEXTINPUT event fires for committed Unicode input,
    including IME-composed sequences. `text` is the string to insert
    (one character normally, but can be multi-char for IME results).
    Inserts at the focused field's cursor position.
    """
    global chat_composer_text, chat_composer_cursor
    global chat_composer_tell_to, chat_composer_tell_to_cursor

    if not text:
        return

    if chat_composer_tell_to_focused:
        # Tell-target field — FFXI names are letters only. Strip any
        # non-alpha characters from the typed text (paste-protection).
        # Cap at 16 chars (longest FFXI name is 15).
        filtered = "".join(c for c in text if c.isalpha())
        if not filtered:
            return
        room = max(0, 16 - len(chat_composer_tell_to))
        if room == 0:
            return
        filtered = filtered[:room]
        cur = chat_composer_tell_to_cursor
        chat_composer_tell_to = (chat_composer_tell_to[:cur]
                                 + filtered
                                 + chat_composer_tell_to[cur:])
        chat_composer_tell_to_cursor += len(filtered)
        return

    if chat_composer_focused:
        # Main message field — accept anything. FFXI chat messages
        # can be quite long; cap at 500 to avoid runaway input
        # (FFXI's own limit is around 256 bytes after encoding).
        room = max(0, 500 - len(chat_composer_text))
        if room == 0:
            return
        insert = text[:room]
        cur = chat_composer_cursor
        chat_composer_text = (chat_composer_text[:cur]
                              + insert
                              + chat_composer_text[cur:])
        chat_composer_cursor += len(insert)


# ── NPC dialog "continue" arrow (ported from OmniChat) ────────────────
# Each client's OmniWatch.lua reports CSSTATE over the chat stream
# (pre-gate, so alts count) whenever it enters/leaves FFXI's Event
# status — i.e. while an NPC dialog or cutscene is waiting on the
# player. While the pinned character is in that state, the chat panel
# draws a small pulsing ▼ at the end of the last line, mirroring the
# game's own blinking continue cursor: more to read — hit Enter in
# the game to advance.
_cs_state = {}              # char -> [in_event(bool), last_seen_ts]
CS_FRESH = 6.0              # seconds a CSSTATE report stays trusted


def _dialog_chars():
    """Characters currently reported in Event status (fresh)."""
    now = time.time()
    return sorted(c for c, (on, ts) in _cs_state.items()
                  if on and (now - ts) <= CS_FRESH)


def _chat_continue_arrow_active():
    """True when the character whose chat the panel shows is sitting
    in an NPC dialog/cutscene. Falls back to 'anyone' before a pin
    target exists."""
    chars = _dialog_chars()
    if not chars:
        return False
    target = _mb_chat_lock_target() or ""
    return (target in chars) if target else True


def _chat_composer_height():
    """Pixel height of the composer row. Constant — same height
    whether or not the tell target field is showing (the target
    field is inline-left, not stacked)."""
    return 30


def _draw_chat_composer(surface, x, y, w, body_font, meta_font, cjk_font):
    """Render the composer row (channel selector + input field + send).

    Layout (left to right):
        [< say >]                          channel selector — arrow,
                                           channel name, arrow
        [target]   (only when tell)        tell-target field
        [............message field..............]   main input
        [send]                             send button

    Click targets are stashed in the _chat_composer_rect_* globals
    so the mousedown handler can hit-test them without recomputing
    geometry.
    """
    global _chat_composer_rect_arrow_l, _chat_composer_rect_arrow_r
    global _chat_composer_rect_channel, _chat_composer_rect_input
    global _chat_composer_rect_tell_to, _chat_composer_rect_send
    global chat_composer_last_blink

    h = _chat_composer_height()
    pad_inner = 4

    # Composer background fills the full width of the panel and
    # leaves room for borders on left/right that the panel itself
    # draws elsewhere.
    bg = pygame.Surface((w, h), pygame.SRCALPHA)
    bg.fill(CHAT_COMPOSER_BG)
    surface.blit(bg, (x, y))
    # Thin top border separating composer from scrollback above.
    pygame.draw.line(surface, CHAT_BORDER_COLOR, (x, y), (x + w, y), 1)

    # Get current channel info.
    ch_idx = chat_composer_channel % len(CHAT_COMPOSER_CHANNELS)
    _ch_key, ch_label, _ch_prefix = CHAT_COMPOSER_CHANNELS[ch_idx]
    is_tell = (_ch_key == "tell")

    # ── Channel selector: [<] channel-name [>] ──────────────────
    # Compute widths so the components line up consistently regardless
    # of channel name length. We allocate a fixed channel-name width
    # based on the widest channel name in the list — keeps the input
    # field's left edge from jumping when channels change.
    arrow_font = body_font     # arrows are bigger and easier to click
    name_font  = body_font
    widest = max(name_font.size(label)[0]
                 for _k, label, _p in CHAT_COMPOSER_CHANNELS)
    arrow_w   = arrow_font.size("<")[0] + 8
    chname_w  = widest + 6     # +6 for small horizontal padding
    cx = x + 4
    cy = y + (h - 18) // 2
    # Left arrow
    arr_l = pygame.Rect(cx, y + 2, arrow_w, h - 4)
    _chat_composer_rect_arrow_l = arr_l
    al_surf = arrow_font.render("<", True, CHAT_COMPOSER_ARROW_FG)
    surface.blit(al_surf,
                 (arr_l.x + (arr_l.w - al_surf.get_width()) // 2,
                  arr_l.y + (arr_l.h - al_surf.get_height()) // 2))
    cx += arrow_w
    # Channel name (clickable — same as right arrow)
    ch_rect = pygame.Rect(cx, y + 2, chname_w, h - 4)
    _chat_composer_rect_channel = ch_rect
    # Tint the label to match the channel's chat color (party teal, unity
    # gold, ls1 green, etc.) so the selector reads at a glance. Falls back
    # to the neutral foreground for any unmapped key.
    _ch_color_class = CHAT_COMPOSER_CHANNEL_COLOR_CLASS.get(_ch_key)
    _ch_name_color = (CHAT_SEGMENT_COLORS.get(_ch_color_class,
                                              CHAT_COMPOSER_CHANNEL_FG)
                      if _ch_color_class else CHAT_COMPOSER_CHANNEL_FG)
    ch_surf = name_font.render(ch_label, True, _ch_name_color)
    surface.blit(ch_surf,
                 (ch_rect.x + (ch_rect.w - ch_surf.get_width()) // 2,
                  ch_rect.y + (ch_rect.h - ch_surf.get_height()) // 2))
    cx += chname_w
    # Right arrow
    arr_r = pygame.Rect(cx, y + 2, arrow_w, h - 4)
    _chat_composer_rect_arrow_r = arr_r
    ar_surf = arrow_font.render(">", True, CHAT_COMPOSER_ARROW_FG)
    surface.blit(ar_surf,
                 (arr_r.x + (arr_r.w - ar_surf.get_width()) // 2,
                  arr_r.y + (arr_r.h - ar_surf.get_height()) // 2))
    cx += arrow_w + 4

    # ── Send button (right-aligned, reserved width) ────────────
    send_label = "send"
    send_w = body_font.size(send_label)[0] + 16
    send_rect = pygame.Rect(x + w - send_w - 4, y + 3,
                            send_w, h - 6)
    _chat_composer_rect_send = send_rect
    send_bg = pygame.Surface((send_rect.w, send_rect.h), pygame.SRCALPHA)
    send_bg.fill((*CHAT_COMPOSER_SEND_BG, 235))
    surface.blit(send_bg, send_rect.topleft)
    pygame.draw.rect(surface, CHAT_COMPOSER_FIELD_BDR, send_rect, 1)
    s_surf = body_font.render(send_label, True, CHAT_COMPOSER_SEND_FG)
    surface.blit(s_surf,
                 (send_rect.x + (send_rect.w - s_surf.get_width()) // 2,
                  send_rect.y + (send_rect.h - s_surf.get_height()) // 2))

    # ── Tell-target field (only when channel == tell) ──────────
    # Placed inline-left of the message field. Width is fixed at
    # ~100px which fits "Wormfood" comfortably and is short enough
    # not to crowd the main field.
    available_w = (send_rect.x - 4) - cx       # space between selector
                                               # and send button
    if is_tell:
        tt_w = 110
        tt_rect = pygame.Rect(cx, y + 3, tt_w, h - 6)
        _chat_composer_rect_tell_to = tt_rect
        # Background — focused vs unfocused
        focused = chat_composer_tell_to_focused
        tt_bg = pygame.Surface((tt_rect.w, tt_rect.h), pygame.SRCALPHA)
        tt_bg.fill(CHAT_COMPOSER_FIELD_FOCUS if focused
                   else CHAT_COMPOSER_FIELD_BG)
        surface.blit(tt_bg, tt_rect.topleft)
        bdr = (CHAT_COMPOSER_FIELD_BDR_F if focused
               else CHAT_COMPOSER_FIELD_BDR)
        pygame.draw.rect(surface, bdr, tt_rect, 1)
        # Render text or placeholder
        tt_text = chat_composer_tell_to
        if tt_text:
            tt_surf = _chat_render_mixed(tt_text, body_font,
                                         cjk_font, CHAT_COMPOSER_TEXT)
        else:
            tt_surf = body_font.render("to:", True, CHAT_COMPOSER_PLACEHOLDER)
        surface.blit(tt_surf,
                     (tt_rect.x + 6,
                      tt_rect.y + (tt_rect.h - tt_surf.get_height()) // 2))
        # Cursor for tell-target field (only when focused)
        if focused:
            now = time.time()
            blink_on = (int(now * 2) % 2) == 0
            if blink_on:
                cursor_x = tt_rect.x + 6
                if tt_text:
                    pre = tt_text[:chat_composer_tell_to_cursor]
                    cursor_x += _chat_measure_mixed(pre, body_font, cjk_font)
                cy_top = tt_rect.y + 4
                cy_bot = tt_rect.bottom - 4
                pygame.draw.line(surface, CHAT_COMPOSER_TEXT,
                                 (cursor_x, cy_top), (cursor_x, cy_bot), 1)
        cx += tt_w + 4
    else:
        _chat_composer_rect_tell_to = None

    # ── Main message field ─────────────────────────────────────
    field_w = (send_rect.x - 4) - cx
    if field_w < 40:
        # Panel too narrow — clip the field but still draw something.
        field_w = max(40, field_w)
    field_rect = pygame.Rect(cx, y + 3, field_w, h - 6)
    _chat_composer_rect_input = field_rect
    focused = chat_composer_focused
    field_bg = pygame.Surface((field_rect.w, field_rect.h), pygame.SRCALPHA)
    field_bg.fill(CHAT_COMPOSER_FIELD_FOCUS if focused
                  else CHAT_COMPOSER_FIELD_BG)
    surface.blit(field_bg, field_rect.topleft)
    bdr = (CHAT_COMPOSER_FIELD_BDR_F if focused
           else CHAT_COMPOSER_FIELD_BDR)
    pygame.draw.rect(surface, bdr, field_rect, 1)

    # Render text or placeholder. For horizontal scrolling within
    # the field: compute the cursor pixel offset; if it would land
    # past the visible field width, shift the view left so the
    # cursor stays in view.
    inner_x = field_rect.x + 6
    inner_max_x = field_rect.right - 6
    inner_w = inner_max_x - inner_x
    cursor_px_in_text = _chat_measure_mixed(
        chat_composer_text[:chat_composer_cursor], body_font, cjk_font)
    # Scroll offset within the text: we want cursor_px_in_text to
    # fall in [0, inner_w). If it would exceed inner_w, shift right.
    scroll_off = max(0, cursor_px_in_text - inner_w + 4)

    # Clip rendering to the field's interior so long text doesn't
    # bleed over the send button.
    prev_clip = surface.get_clip()
    surface.set_clip(pygame.Rect(inner_x, field_rect.y + 1,
                                 inner_w, field_rect.h - 2))
    if chat_composer_text:
        text_surf = _chat_render_mixed(chat_composer_text, body_font,
                                       cjk_font, CHAT_COMPOSER_TEXT)
        surface.blit(text_surf,
                     (inner_x - scroll_off,
                      field_rect.y + (field_rect.h - text_surf.get_height()) // 2))
    else:
        ph = body_font.render(
            "Click to type, Enter to send, Esc to cancel",
            True, CHAT_COMPOSER_PLACEHOLDER)
        surface.blit(ph,
                     (inner_x,
                      field_rect.y + (field_rect.h - ph.get_height()) // 2))

    # Cursor (only when main field focused)
    if focused:
        now = time.time()
        blink_on = (int(now * 2) % 2) == 0
        if blink_on:
            cursor_x = inner_x + cursor_px_in_text - scroll_off
            cy_top = field_rect.y + 4
            cy_bot = field_rect.bottom - 4
            pygame.draw.line(surface, CHAT_COMPOSER_TEXT,
                             (cursor_x, cy_top), (cursor_x, cy_bot), 1)
    surface.set_clip(prev_clip)


def scaled_skillchain_dims(scale):
    """Sizing constants for the skillchain panel. Mirrors the shape of
    scaled_recast_dims and scaled_buff_dims so the panel reads as part
    of the same family.

    Returns a dict with row heights, bar dims, pad, and pre-built fonts
    at the requested scale.
    """
    s = _eff(scale)
    return {
        "s":            s,
        "panel_w":      max(240, int(300 * s)),
        "head_h":       max(14,  int(18 * s)),
        "row_h":        max(14,  int(17 * s)),
        "bar_h":        max(8,   int(10 * s)),
        "pad":          max(4,   int(6 * s)),
        "f_head":       get_font("Consolas", max(10, int(13 * s)), bold=True),
        "f_label":      get_font("Consolas", max(8,  int(11 * s))),
        "f_prop":       get_font("Consolas", max(9,  int(12 * s)), bold=True),
        "f_sugg_name":  get_font("Consolas", max(8,  int(11 * s))),
        "f_sugg_lvl":   get_font("Consolas", max(8,  int(11 * s)), bold=True),
    }


def skillchain_panel_size(scale):
    """Estimate (w, h) for the skillchain panel given the current
    state and active settings. Variable height because the suggestion
    list can be 0-30 entries.

    Sizing layout (when all rows enabled, with active resonating state):
      header                    head_h + pad
      props row                 row_h
      timer bar                 bar_h + small pad
      step row                  row_h (if show_step)
      magic burst row           row_h (if track_magic_burst and active)
      sep line                  2px
      suggestions               N * row_h (capped at MAX_SUGG_ROWS)
    """
    d = scaled_skillchain_dims(scale)
    pad = d["pad"]; rh = d["row_h"]
    w = d["panel_w"]

    cs = skillchain_settings
    # Empty/placeholder panel still needs to be discoverable in setup
    # mode, so we keep a minimum height of header + 1 row.
    if (skillchain_state is None
            and not (skillchain_suggestions or False)):
        return (w, pad + d["head_h"] + rh + pad)

    h = pad + d["head_h"] + 2
    # Props row (counts when track_sc and show_props are on AND we have props).
    if cs.get("track_sc") and cs.get("show_props") and skillchain_state:
        h += rh
    # Timer bar (counts when track_sc and show_timer).
    if cs.get("track_sc") and cs.get("show_timer") and skillchain_state:
        h += d["bar_h"] + pad // 2 + 2
    # Step row.
    if cs.get("track_sc") and cs.get("show_step") and skillchain_state:
        h += rh
    # Magic burst row — only displays after a chain closes AND track_magic_burst.
    if cs.get("track_magic_burst") and skillchain_state \
            and skillchain_state.get("closed"):
        h += rh
    # Suggestions list. Cap rows so a SAM with 20+ matching WS doesn't
    # produce a 600-pixel-tall panel.
    MAX_SUGG_ROWS = 12
    n_sugg = min(len(skillchain_suggestions), MAX_SUGG_ROWS)
    if n_sugg > 0 and skillchain_state:
        # Separator line + N rows.
        h += 4 + n_sugg * rh
    h += pad
    return (w, h)


def _sc_format_timer_text_and_color(state, now):
    """Return (text, color, fill_ratio) for the timer bar based on
    the current SC state and wall-clock time.

    Phases (left-to-right in lua's wire):
      delay_ts        wait period — bar fills, red color, "Wait Ns"
      window_ts       SC window open — green, "Go! Ns"
      after window_ts magic burst window (~5s after close) — blue,
                      "Burst Ns" (only when closed=1)
      otherwise       expired — caller hides the row
    """
    delay  = state["delay_ts"]
    window = state["window_ts"]
    closed = state["closed"]
    if now < delay:
        # Pre-SC-window wait phase. Bar fills from 0 → 1 over the
        # delay period.
        total = max(0.1, delay - state.get("received", now - 1))
        rem   = delay - now
        ratio = 1.0 - (rem / total)
        return (f"Wait {rem:.1f}s", (230, 90, 80), max(0.0, min(1.0, ratio)))
    elif now < window:
        # SC window is open.
        total = max(0.1, window - delay)
        rem   = window - now
        ratio = rem / total
        return (f"Go! {rem:.1f}s", (110, 220, 130), max(0.0, min(1.0, ratio)))
    elif closed and now < window + 10:
        # Magic burst window (only if chain closed).
        burst_total = 10.0
        burst_rem   = (window + 10) - now
        ratio = burst_rem / burst_total
        return (f"Burst {burst_rem:.1f}s", (110, 170, 250),
                max(0.0, min(1.0, ratio)))
    else:
        return (None, None, 0.0)


def draw_skillchain_panel(surface, x, y, scale=1.0, locked=False):
    """Render the skillchain panel at (x, y). Returns (w, h).

    Reads global state: skillchain_state, skillchain_suggestions,
    skillchain_settings, skillchain_main_job. The panel auto-hides
    its rows based on the settings booleans — track_sc gates the
    props / timer / step rows, track_magic_burst gates the burst
    row, and the show_* per-info booleans gate individual rows
    inside track_sc.
    """
    d = scaled_skillchain_dims(scale)
    pad = d["pad"]; rh = d["row_h"]
    pw, ph = skillchain_panel_size(scale)

    pygame.draw.rect(surface, COL_PANEL,  (x, y, pw, ph), border_radius=4)
    pygame.draw.rect(surface, COL_BORDER, (x, y, pw, ph), 1, border_radius=4)

    # Header strip — matches stats/equipment panel style: a darker
    # filled rect across the top with neutral title text, plus a 1px
    # separator line below it. The accent color is reserved for the
    # left-edge stripe so the panel is identifiable at a glance
    # without making the title text itself read as a color.
    title_h = d["head_h"] + pad // 2 + 2
    pygame.draw.rect(surface, COL_EV_HEADER,
                     (x + 1, y + 1, pw - 2, title_h - 1),
                     border_radius=3)
    draw_accent_stripe(surface, x, y, ph, ACCENT_SC)
    pygame.draw.line(surface, COL_BORDER,
                     (x + 1, y + title_h),
                     (x + pw - 2, y + title_h))

    head_label = "SKILLCHAIN"
    if skillchain_state and skillchain_state.get("bound"):
        head_label = f"SKILLCHAIN · CHAINBOUND LV.{skillchain_state['bound']}"
    head_surf = d["f_head"].render(head_label, True, COL_EV_TITLE)
    surface.blit(head_surf,
        (x + pad + 3,
         y + (title_h - head_surf.get_height()) // 2))

    # Idle / placeholder state.
    if skillchain_state is None and not skillchain_suggestions:
        msg_surf = d["f_label"].render(
            "no active chain", True, COL_LABEL_DIM)
        surface.blit(msg_surf,
            (x + pad + 3, y + pad + d["head_h"] + 2))
        return (pw, ph)

    cs = skillchain_settings
    cur_y = y + pad + d["head_h"] + 2
    now = time.time()

    # Props row — colored chunks per element.
    if (cs.get("track_sc") and cs.get("show_props")
            and skillchain_state):
        props = skillchain_state.get("props") or []
        prefix_surf = d["f_label"].render("Prop: ", True, COL_LABEL_DIM)
        surface.blit(prefix_surf,
            (x + pad + 3, cur_y + (rh - prefix_surf.get_height()) // 2))
        cx = x + pad + 3 + prefix_surf.get_width()
        for i, prop in enumerate(props):
            if i > 0:
                sep_surf = d["f_prop"].render(" · ", True, COL_LABEL_DIM)
                surface.blit(sep_surf,
                    (cx, cur_y + (rh - sep_surf.get_height()) // 2))
                cx += sep_surf.get_width()
            color = SC_PROPERTY_COLORS.get(prop, (220, 220, 220))
            prop_surf = d["f_prop"].render(prop, True, color)
            surface.blit(prop_surf,
                (cx, cur_y + (rh - prop_surf.get_height()) // 2))
            cx += prop_surf.get_width()
        cur_y += rh

    # Timer bar.
    if (cs.get("track_sc") and cs.get("show_timer")
            and skillchain_state):
        text, color, ratio = _sc_format_timer_text_and_color(
            skillchain_state, now)
        if text is not None:
            bar_w = pw - 2 * (pad + 3) - 70
            bar_x = x + pad + 3
            bar_y = cur_y + 2
            # Bar background.
            pygame.draw.rect(surface, (40, 40, 50),
                (bar_x, bar_y, bar_w, d["bar_h"]),
                border_radius=2)
            # Bar fill.
            fill_w = max(0, int(bar_w * ratio))
            if fill_w > 0:
                pygame.draw.rect(surface, color,
                    (bar_x, bar_y, fill_w, d["bar_h"]),
                    border_radius=2)
            # Border on top.
            pygame.draw.rect(surface, (60, 60, 70),
                (bar_x, bar_y, bar_w, d["bar_h"]),
                1, border_radius=2)
            # Right-aligned text.
            txt_surf = d["f_label"].render(text, True, color)
            surface.blit(txt_surf,
                (x + pw - pad - 3 - txt_surf.get_width(),
                 bar_y + (d["bar_h"] - txt_surf.get_height()) // 2))
            cur_y += d["bar_h"] + pad // 2 + 2

    # Step row.
    if (cs.get("track_sc") and cs.get("show_step")
            and skillchain_state):
        step = skillchain_state.get("step", 0)
        # Action that triggered this state — useful for parties to see
        # what WS opened/closed. resource determines the lookup table
        # but we don't have a resource→name table on the python side
        # right now, so just show the step number and closed status.
        step_text = f"Step: Lv.{step}"
        if skillchain_state.get("closed"):
            step_text += " (CLOSED)"
        elif skillchain_state.get("bound"):
            step_text += " (Chainbound)"
        step_surf = d["f_label"].render(step_text, True, (220, 220, 230))
        surface.blit(step_surf,
            (x + pad + 3, cur_y + (rh - step_surf.get_height()) // 2))
        cur_y += rh

    # Magic burst row — only when the chain has closed.
    if (cs.get("track_magic_burst") and skillchain_state
            and skillchain_state.get("closed")):
        # Expand the closing SC's properties into the FULL set of
        # burstable elements. A Light close bursts Fire/Wind/Lightning/
        # Light, a Darkness close bursts Ice/Earth/Water/Dark, Lv.3
        # props cover two elements each, etc. We dedupe across multiple
        # closing props while preserving canonical element order.
        props = skillchain_state.get("props") or []
        _ELEM_ORDER = ["Fire", "Ice", "Wind", "Earth",
                       "Lightning", "Water", "Light", "Dark"]
        burst_elems = set()
        for prop in props:
            for el in SC_PROPERTY_BURST_ELEMENTS.get(prop, [prop]):
                burst_elems.add(el)
        # Render in canonical order; unknown tokens (shouldn't occur)
        # appended after.
        ordered = [e for e in _ELEM_ORDER if e in burst_elems]
        ordered += [e for e in burst_elems if e not in _ELEM_ORDER]

        burst_prefix = d["f_label"].render("Burst: ", True, (130, 170, 240))
        surface.blit(burst_prefix,
            (x + pad + 3, cur_y + (rh - burst_prefix.get_height()) // 2))
        cx = x + pad + 3 + burst_prefix.get_width()
        for i, el in enumerate(ordered):
            if i > 0:
                sep_surf = d["f_label"].render("/", True, COL_LABEL_DIM)
                surface.blit(sep_surf,
                    (cx, cur_y + (rh - sep_surf.get_height()) // 2))
                cx += sep_surf.get_width()
            color = SC_ELEMENT_COLORS.get(el, (220, 220, 220))
            ps = d["f_label"].render(el, True, color)
            surface.blit(ps,
                (cx, cur_y + (rh - ps.get_height()) // 2))
            cx += ps.get_width()
        cur_y += rh

    # Suggestions list (capped). Grouped by descending level. Lua
    # already sends them in the right order so we just render top-down.
    MAX_SUGG_ROWS = 12
    if skillchain_suggestions and skillchain_state:
        # Separator line.
        pygame.draw.line(surface, COL_BORDER,
            (x + pad + 3, cur_y), (x + pw - pad - 3, cur_y), 1)
        cur_y += 4
        # Track the last level rendered so we can lightly group them
        # visually (small vertical gap between Lv.4 block and Lv.3
        # block, etc. — but only if there's room). Simple version: no
        # extra gap; the level number itself differentiates them.
        for i, (name, lvl, prop) in enumerate(
                skillchain_suggestions[:MAX_SUGG_ROWS]):
            # Left: WS / spell / ability name, truncated to fit.
            name_surf = d["f_sugg_name"].render(name, True, (200, 200, 210))
            surface.blit(name_surf,
                (x + pad + 3, cur_y + (rh - name_surf.get_height()) // 2))
            # Right: "Lv.N PropName" with the prop colored.
            color = SC_PROPERTY_COLORS.get(prop, (220, 220, 220))
            right_text = f"Lv.{lvl}  "
            right_surf = d["f_sugg_lvl"].render(right_text, True, (180, 180, 190))
            prop_surf  = d["f_sugg_lvl"].render(prop, True, color)
            rx = x + pw - pad - 3 - prop_surf.get_width()
            surface.blit(prop_surf,
                (rx, cur_y + (rh - prop_surf.get_height()) // 2))
            surface.blit(right_surf,
                (rx - right_surf.get_width(),
                 cur_y + (rh - right_surf.get_height()) // 2))
            cur_y += rh
        # If we truncated, show "..." in dim text on the last row.
        if len(skillchain_suggestions) > MAX_SUGG_ROWS:
            more_n = len(skillchain_suggestions) - MAX_SUGG_ROWS
            more_surf = d["f_label"].render(
                f"... +{more_n} more", True, COL_LABEL_DIM)
            surface.blit(more_surf,
                (x + pad + 3, cur_y - rh + 1))

    return (pw, ph)


def draw_chat_tab_rclick_popup(surface):
    """Render the right-click tab popup if one is open.

    A small floating menu anchored at the right-click position with
    one button: 'Hide tab'. Click that button to add the tab's
    index to the hidden_chat_tabs setting (causing it to vanish
    from the tab strip). Click anywhere else to dismiss the popup
    without changes.

    Drawn AFTER the chat panel so it floats above the tab strip.
    Per-frame click rects are written to _chat_tab_rclick_rects for
    the main left-click handler to consume.
    """
    global _chat_tab_rclick_rects
    _chat_tab_rclick_rects = []
    if _chat_tab_rclick_tab is None or _chat_tab_rclick_anchor is None:
        return
    if not (0 <= _chat_tab_rclick_tab < len(chat_tab_names)):
        return   # defensive — stale index after tab list change

    ax, ay = _chat_tab_rclick_anchor
    tab_label = chat_tab_names[_chat_tab_rclick_tab][0]
    title_font = _chat_get_font("meta", 11)
    # Two text rows: a small header showing which tab the popup
    # targets, and the actionable button below.
    hdr_text  = f"Tab: {tab_label}"
    btn_text  = "Hide tab"
    hdr_w     = title_font.size(hdr_text)[0]
    btn_w     = title_font.size(btn_text)[0]
    pad       = 8
    row_h     = 20
    panel_w   = max(hdr_w, btn_w) + pad * 2 + 6
    panel_h   = row_h * 2 + pad
    # Keep the popup on-screen — clamp to surface bounds.
    sw, sh = surface.get_size()
    px = min(max(0, ax), sw - panel_w)
    py = min(max(0, ay), sh - panel_h)

    # Backdrop with a 1px border so it visually pops above chat.
    panel_rect = pygame.Rect(px, py, panel_w, panel_h)
    pygame.draw.rect(surface, (30, 34, 42), panel_rect, border_radius=3)
    pygame.draw.rect(surface, (140, 160, 200), panel_rect, 1,
                     border_radius=3)
    # Eat clicks on the panel background so they don't dismiss the
    # popup (a click on the panel chrome is still inside the popup).
    _chat_tab_rclick_rects.append(
        (panel_rect, {"action": "rclick_panel_bg"}))

    # Header label.
    hdr_surf = title_font.render(hdr_text, True, (180, 190, 200))
    surface.blit(hdr_surf, (px + pad, py + pad // 2))

    # "Hide tab" button.
    btn_rect = pygame.Rect(px + pad - 2, py + row_h + 2,
                            panel_w - (pad - 2) * 2, row_h - 2)
    mouse_pos = pygame.mouse.get_pos()
    is_hov   = btn_rect.collidepoint(mouse_pos)
    bg = (90, 50, 60) if is_hov else (55, 40, 48)
    pygame.draw.rect(surface, bg, btn_rect, border_radius=2)
    pygame.draw.rect(surface, (180, 120, 140), btn_rect, 1,
                     border_radius=2)
    btn_surf = title_font.render(btn_text, True,
        (255, 220, 220) if is_hov else (220, 200, 205))
    surface.blit(btn_surf,
        (btn_rect.x + (btn_rect.w - btn_surf.get_width()) // 2,
         btn_rect.y + (btn_rect.h - btn_surf.get_height()) // 2))
    _chat_tab_rclick_rects.append(
        (btn_rect, {"action": "rclick_hide_tab"}))


def dispatch_chat_tab_rclick_popup_click(mx, my, button=1):
    """Handle a left-click while the tab right-click popup is open.

    Returns True if the click was consumed (either by the Hide
    button or by clicking the panel background). Returns False if
    the click missed the popup entirely — in that case the caller
    should also dismiss the popup AND let the click fall through
    to whatever it would normally hit.
    """
    global _chat_tab_rclick_tab, _chat_tab_rclick_anchor
    global chat_active_tab
    if _chat_tab_rclick_tab is None:
        return False
    target_tab = _chat_tab_rclick_tab
    # Iterate in REVERSE order so the most-specific (innermost) rect
    # wins over outer ones. The panel-background rect is added first
    # but contains the Hide button rect added after — without
    # reversed(), a click on the button would hit the background
    # first and return early as "click on chrome", missing the hide.
    for rect, action in reversed(_chat_tab_rclick_rects):
        if not rect.collidepoint(mx, my):
            continue
        what = action.get("action", "")
        if what == "rclick_panel_bg":
            # Click on the popup chrome but not a button — eat it
            # but keep the popup open so the user can still click
            # the Hide button. Same UX as a desktop context menu.
            return True
        if what == "rclick_hide_tab":
            _current = list(settings.get("hidden_chat_tabs") or [])
            if target_tab not in _current:
                _current.append(target_tab)
                set_setting("hidden_chat_tabs", _current)
            # If we just hid the active tab, bump to the first
            # visible remaining tab.
            if chat_active_tab == target_tab:
                for i in range(len(chat_tab_names)):
                    if i not in _current:
                        chat_active_tab = i
                        chat_tab_unread[i] = 0
                        break
            print(f"[chat-tab] hid tab {target_tab} "
                  f"({chat_tab_names[target_tab][0]!r}) via "
                  f"right-click popup; hidden list now {_current}")
            _chat_tab_rclick_tab    = None
            _chat_tab_rclick_anchor = None
            return True
    # Click landed outside the popup — dismiss without changes.
    # Returning False lets the click also fall through to the
    # normal handler so the user can do whatever they intended.
    _chat_tab_rclick_tab    = None
    _chat_tab_rclick_anchor = None
    return False


def draw_chat_panel(surface, x, y, locked=False):
    """Render the chat panel at (x, y).

    Reads chat_events (newest-last deque), the active tab's filter and
    scroll position, and chat_panel_dims. Sets _chat_jump_badge_rect and
    chat_tab_rects each frame for the mousedown handler to consume.
    """
    global _chat_jump_badge_rect, chat_tab_rects
    global _chat_clickable_senders

    pw, ph = chat_panel_size()

    # Reset per-frame clickable-sender hit-test list. Populated inside
    # the message-rendering loop below whenever a sender name is blitted
    # (left-click → /tell composer, right-click → context menu). Reset
    # here so a hidden chat panel or a re-layout can't leak stale
    # rectangles into the next frame's hit-tests.
    _chat_clickable_senders = []

    # Background
    bg_surf = pygame.Surface((pw, ph), pygame.SRCALPHA)
    bg_surf.fill(CHAT_BG_COLOR)
    surface.blit(bg_surf, (x, y))

    # Header strip
    hdr_h = 18
    hdr_surf = pygame.Surface((pw, hdr_h), pygame.SRCALPHA)
    hdr_surf.fill(CHAT_HEADER_COLOR)
    surface.blit(hdr_surf, (x, y))
    title_font = _chat_get_font("meta", 11)
    title = title_font.render(
        f"Chat  ({chat_recv_text + chat_recv_battle} events)",
        True, (200, 210, 220))
    surface.blit(title, (x + 8, y + 3))

    # Routing-config gear button at the right edge of the header.
    # Clicking launches omniwatch_routing_gui.exe (or the .py fallback
    # if exe isn't built yet). Hit-testing is done in the click
    # handler via the rect stored in _chat_settings_button_rect.
    global _chat_settings_button_rect
    global _chat_clear_tab_button_rect, _chat_clear_all_button_rect
    mouse_pos = pygame.mouse.get_pos()

    gear_w = 56
    gear_h = hdr_h - 2
    gear_rect = pygame.Rect(x + pw - gear_w - 4, y + 1, gear_w, gear_h)
    _chat_settings_button_rect = gear_rect
    gear_hovered = gear_rect.collidepoint(mouse_pos)
    gear_bg = (60, 70, 90, 220) if gear_hovered else (40, 46, 56, 200)
    gear_surf = pygame.Surface((gear_rect.width, gear_rect.height),
                                pygame.SRCALPHA)
    gear_surf.fill(gear_bg)
    surface.blit(gear_surf, gear_rect.topleft)
    gear_text = title_font.render("Filters ⚙",
                                   True,
                                   (240, 240, 240) if gear_hovered
                                   else (180, 190, 200))
    gtx = gear_rect.x + (gear_rect.width - gear_text.get_width()) // 2
    gty = gear_rect.y + (gear_rect.height - gear_text.get_height()) // 2
    surface.blit(gear_text, (gtx, gty))

    # Two clear buttons just AFTER the title text, on the LEFT side —
    # deliberately far from the Filters button so they're not hit by
    # accident.
    #   "Clear Tab"  — removes only events visible in the active tab.
    #   "Clear All"  — wipes the entire chat buffer (every tab).
    def _draw_hdr_button(label, left_edge, width):
        r = pygame.Rect(left_edge, y + 1, width, gear_h)
        hov = r.collidepoint(mouse_pos)
        bg = (70, 55, 55, 220) if hov else (40, 46, 56, 200)
        s = pygame.Surface((r.width, r.height), pygame.SRCALPHA)
        s.fill(bg)
        surface.blit(s, r.topleft)
        t = title_font.render(label, True,
                              (240, 240, 240) if hov else (180, 190, 200))
        surface.blit(t, (r.x + (r.width - t.get_width()) // 2,
                         r.y + (r.height - t.get_height()) // 2))
        return r

    _gap = 4
    _clr_tab_w = 60
    _clr_all_w = 58
    _clr_left = x + 8 + title.get_width() + 12   # just past the title text
    _chat_clear_tab_button_rect = _draw_hdr_button(
        "Clear Tab", _clr_left, _clr_tab_w)
    _chat_clear_all_button_rect = _draw_hdr_button(
        "Clear All", _chat_clear_tab_button_rect.right + _gap, _clr_all_w)

    # "Show all tabs" — anchored to the right side of the header,
    # just LEFT of the Filters gear button (which is right-edge
    # anchored). Renders only when at least one tab is hidden so
    # there's something to unhide. Putting it on the right keeps
    # the left-side cluster (Clear Tab / Clear All) tight and
    # avoids hit-confusion with the destructive Clear buttons.
    global _chat_show_all_button_rect
    _chat_show_all_button_rect = None
    _hidden_now = settings.get("hidden_chat_tabs") or []
    if _hidden_now:
        _sa_label = f"Show all tabs ({len(_hidden_now)})"
        _sa_w     = max(110, title_font.size(_sa_label)[0] + 16)
        # Position: right of Filters minus gap minus our width.
        _sa_x = gear_rect.x - _gap - _sa_w
        _sa_r = pygame.Rect(_sa_x, y + 1, _sa_w, gear_h)
        _sa_hov = _sa_r.collidepoint(mouse_pos)
        _sa_bg  = (60, 80, 70, 220) if _sa_hov else (40, 46, 56, 200)
        _sa_surf = pygame.Surface((_sa_r.width, _sa_r.height),
                                   pygame.SRCALPHA)
        _sa_surf.fill(_sa_bg)
        surface.blit(_sa_surf, _sa_r.topleft)
        _sa_t = title_font.render(_sa_label, True,
            (240, 240, 240) if _sa_hov else (180, 200, 190))
        surface.blit(_sa_t,
            (_sa_r.x + (_sa_r.width  - _sa_t.get_width())  // 2,
             _sa_r.y + (_sa_r.height - _sa_t.get_height()) // 2))
        _chat_show_all_button_rect = _sa_r

    # Read font sizes once per draw based on chat_font_size setting.
    # Tab strip height scales with tab font so the strip doesn't look
    # cramped on Large or oversized on Small.
    fs = _chat_font_sizes()
    body_font_size = fs["body"]
    meta_font_size = fs["meta"]
    tab_font_size  = fs["tab"]

    # ── Tab strip ───────────────────────────────────────────────
    # Renders below the header bar. Each tab is sized to fit its
    # full name + unread badge (if any). Rendered left-to-right;
    # if total width exceeds the panel, later tabs are clipped.
    # Default panel width is 800 to accommodate all 10 tabs at
    # medium font size; users on Small can fit at narrower widths,
    # Large may need 900+.
    tab_h = max(20, tab_font_size + 10)
    tab_font = _chat_get_font("body", tab_font_size)
    tab_pad_x = 10                          # horizontal padding inside each tab
    tab_gap   = 2                           # gap between tabs
    tab_y = y + hdr_h
    # Rebuild click-target list for this frame.
    chat_tab_rects = []
    badge_h = max(12, tab_font_size + 2)

    # ── Measure every tab first ─────────────────────────────────
    # We need the total width up front to know whether the strip
    # overflows (and thus whether to show scroll arrows). Names are
    # never abbreviated — overflow is handled by sideways scrolling.
    global _chat_tab_hscroll, _chat_tab_arrow_rects
    tab_meta = []   # list of (tab_idx, full, tab_w, badge_text, badge_w, name_w)
    # Per-tab hide state lives in settings as a list of indices the
    # user has hidden via right-click. The set is populated lazily
    # from the persisted list each frame (cheap — typically <14
    # entries). When all tabs are visible the set is empty.
    hidden_tabs = set(settings.get("hidden_chat_tabs") or [])
    for tab_idx, (_short, full) in enumerate(chat_tab_names):
        if tab_idx in hidden_tabs:
            continue   # user hid this tab via right-click
        active = (tab_idx == chat_active_tab)
        unread = chat_tab_unread.get(tab_idx, 0) if not active else 0
        name_w = tab_font.size(full)[0]
        badge_w = 0
        badge_text = None
        if unread > 0:
            badge_text = str(unread) if unread < 1000 else "999+"
            badge_w = tab_font.size(badge_text)[0] + 8
        tab_w = tab_pad_x * 2 + name_w + (4 + badge_w if badge_w else 0)
        tab_meta.append((tab_idx, full, tab_w, badge_text, badge_w, name_w))
    total_tabs_w = sum(m[2] for m in tab_meta) + tab_gap * max(0, len(tab_meta) - 1)

    # ── Reserve arrow zones / compute the scrollable strip ──────
    # Strip spans from just inside the left edge to just inside the
    # right edge. If the tabs overflow, we carve out an arrow button
    # at each end and scroll the middle.
    strip_left  = x + 2
    strip_right = x + pw - 2
    strip_w     = strip_right - strip_left
    arrow_w     = tab_h        # square-ish arrow buttons
    overflow    = total_tabs_w > strip_w

    _chat_tab_arrow_rects = {"left": None, "right": None}
    if overflow:
        # Inner area between the two arrows.
        inner_left  = strip_left + arrow_w
        inner_right = strip_right - arrow_w
        inner_w     = inner_right - inner_left
        max_scroll  = max(0, total_tabs_w - inner_w)
        # Clamp the persisted scroll into range.
        if _chat_tab_hscroll < 0:
            _chat_tab_hscroll = 0
        elif _chat_tab_hscroll > max_scroll:
            _chat_tab_hscroll = max_scroll
        clip_left, clip_w = inner_left, inner_w
        tab_x0 = inner_left - _chat_tab_hscroll
    else:
        # Everything fits — no arrows, no scroll.
        _chat_tab_hscroll = 0
        max_scroll = 0
        clip_left, clip_w = strip_left, strip_w
        tab_x0 = strip_left

    # ── Draw tabs (clipped to the inner strip) ──────────────────
    prev_clip = surface.get_clip()
    surface.set_clip(pygame.Rect(clip_left, tab_y, clip_w, tab_h))
    tab_x = tab_x0
    for (tab_idx, full, tab_w, badge_text, badge_w, name_w) in tab_meta:
        active = (tab_idx == chat_active_tab)
        theme = (CHAT_TAB_PALETTE[tab_idx]
                 if tab_idx < len(CHAT_TAB_PALETTE)
                 else {"active":   CHAT_TAB_FG_ACTIVE,
                       "inactive": CHAT_TAB_FG_INACTIVE})
        # Skip drawing tabs fully outside the visible strip (perf + the
        # clip already hides them, but this avoids needless blits).
        if tab_x + tab_w < clip_left or tab_x > clip_left + clip_w:
            tab_x += tab_w + tab_gap
            continue
        # Draw tab background.
        bg = CHAT_TAB_BG_ACTIVE if active else CHAT_TAB_BG_INACTIVE
        tab_bg = pygame.Surface((tab_w, tab_h), pygame.SRCALPHA)
        tab_bg.fill(bg)
        surface.blit(tab_bg, (tab_x, tab_y))
        if active:
            pygame.draw.line(surface, theme["active"],
                             (tab_x, tab_y + tab_h - 1),
                             (tab_x + tab_w - 1, tab_y + tab_h - 1), 2)
        fg = theme["active"] if active else theme["inactive"]
        # Focus-phrase tab pulse: an inactive tab holding an unseen
        # focus hit blinks its label toward the highlight amber until
        # the user visits it (visit clears the marker).
        if active:
            _chat_tab_focus_pulse.pop(tab_idx, None)
        elif tab_idx in _chat_tab_focus_pulse:
            _pt = math.sin(time.time() * 5.0) * 0.5 + 0.5   # 0..1
            fg = tuple(
                int(fg[i] + (CHAT_FOCUS_HL[i] - fg[i]) * (0.35 + 0.65 * _pt))
                for i in range(3))
        name_surf = tab_font.render(full, True, fg)
        surface.blit(name_surf,
                     (tab_x + tab_pad_x,
                      tab_y + (tab_h - name_surf.get_height()) // 2))
        if badge_text:
            bx_text = tab_x + tab_pad_x + name_w + 4
            by_text = tab_y + (tab_h - badge_h) // 2
            badge_surf = pygame.Surface((badge_w, badge_h), pygame.SRCALPHA)
            badge_surf.fill((*CHAT_TAB_UNREAD_BG, 240))
            surface.blit(badge_surf, (bx_text, by_text))
            badge_surf2 = tab_font.render(badge_text, True, CHAT_TAB_UNREAD_FG)
            surface.blit(badge_surf2,
                         (bx_text + (badge_w - badge_surf2.get_width()) // 2,
                          by_text + (badge_h - badge_surf2.get_height()) // 2 - 1))
        # Record hit-target only for the portion within the strip. Clamp
        # the rect to the visible area so a click on a half-scrolled tab
        # at the edge still maps correctly (and clicks in the arrow zone
        # don't fall through to a tab underneath).
        vis_l = max(tab_x, clip_left)
        vis_r = min(tab_x + tab_w, clip_left + clip_w)
        if vis_r > vis_l:
            chat_tab_rects.append(
                (pygame.Rect(vis_l, tab_y, vis_r - vis_l, tab_h), tab_idx))
        tab_x += tab_w + tab_gap
    surface.set_clip(prev_clip)

    # ── Scroll arrows (only when overflowing) ───────────────────
    if overflow:
        arrow_mid_y = tab_y + tab_h // 2
        # Left arrow — enabled only if scrolled right of start.
        l_active = _chat_tab_hscroll > 0
        l_rect = pygame.Rect(strip_left, tab_y, arrow_w, tab_h)
        l_bg = pygame.Surface((arrow_w, tab_h), pygame.SRCALPHA)
        l_bg.fill(CHAT_TAB_BG_INACTIVE)
        surface.blit(l_bg, (l_rect.x, l_rect.y))
        l_col = (CHAT_TAB_FG_ACTIVE if l_active else (90, 95, 105))
        _ax = l_rect.centerx
        pygame.draw.polygon(surface, l_col, [
            (_ax + 3, arrow_mid_y - 5),
            (_ax + 3, arrow_mid_y + 5),
            (_ax - 4, arrow_mid_y)])
        _chat_tab_arrow_rects["left"] = l_rect if l_active else None
        # Right arrow — enabled only if more tabs lie past the right edge.
        r_active = _chat_tab_hscroll < max_scroll
        r_rect = pygame.Rect(strip_right - arrow_w, tab_y, arrow_w, tab_h)
        r_bg = pygame.Surface((arrow_w, tab_h), pygame.SRCALPHA)
        r_bg.fill(CHAT_TAB_BG_INACTIVE)
        surface.blit(r_bg, (r_rect.x, r_rect.y))
        r_col = (CHAT_TAB_FG_ACTIVE if r_active else (90, 95, 105))
        _bx = r_rect.centerx
        pygame.draw.polygon(surface, r_col, [
            (_bx - 3, arrow_mid_y - 5),
            (_bx - 3, arrow_mid_y + 5),
            (_bx + 4, arrow_mid_y)])
        _chat_tab_arrow_rects["right"] = r_rect if r_active else None

    # Border (1px outline around whole panel)
    pygame.draw.rect(surface, CHAT_BORDER_COLOR, (x, y, pw, ph), 1)
    # Mint accent stripe down the left edge — matches the per-panel
    # accent convention used by every other OmniWatch panel.
    draw_accent_stripe(surface, x, y, ph, ACCENT_CHAT)
    # Line under the tab strip to separate from content
    pygame.draw.line(surface, CHAT_BORDER_COLOR,
                     (x, y + hdr_h + tab_h),
                     (x + pw, y + hdr_h + tab_h), 1)

    # ── Content area (filtered by active tab) ───────────────────
    # Reserve space at the bottom for the composer row if visible.
    composer_h = _chat_composer_height() if chat_composer_visible else 0
    content_x = x + 6
    content_y = y + hdr_h + tab_h + 4
    content_w = pw - 12
    content_h = ph - hdr_h - tab_h - 8 - composer_h

    body_font = _chat_get_font("body", body_font_size)
    meta_font = _chat_get_font("meta", meta_font_size)
    cjk_font  = _chat_get_cjk_font(body_font_size)

    line_h = body_font.get_linesize()
    if line_h <= 0:
        line_h = body_font_size + 2

    visible_lines = max(1, content_h // line_h)

    # Reserve horizontal space for the timestamp prefix.
    ts_text = "00:00 "
    ts_w = meta_font.size(ts_text)[0]
    text_x = content_x + ts_w + 4
    text_max_w = content_w - ts_w - 4

    # Apply the active tab's filter as we walk events. The All tab's
    # filter trivially accepts everything; specialized tabs evaluate
    # a mode set lookup. Filter call cost is negligible (set lookup).
    active_filter = chat_tab_filters[chat_active_tab]
    active_scroll = chat_tab_scroll.get(chat_active_tab, 0)

    # Walk events newest -> oldest, applying filter, wrap each, until
    # we have visible_lines + scroll covered.
    events = list(chat_events)

    # Total physical lines across the FULL filtered+wrapped chat —
    # not just what we rendered. Used for two things:
    #   1. Scroll anchoring (below): keep the user's view stable when
    #      new events arrive while scrolled up.
    #   2. Scrollbar thumb sizing: without this, the rendering loop's
    #      early-break (it stops once it has enough lines to cover
    #      the visible window + a 10-line buffer) would make
    #      physical_lines_total grow as the user scrolls UP and
    #      shrink as they scroll DOWN — and thus make the thumb
    #      visibly resize. With true_total in hand the thumb size
    #      stays anchored to the real chat depth, only changing
    #      when actual messages arrive or filter changes.
    # Cost is one extra full-history walk per chat-panel frame. For
    # typical chat sizes (sub-1000 events) this is cheap (~100µs).
    true_total = 0
    for ev in events:
        try:
            if not active_filter(ev):
                continue
        except Exception:
            continue
        w = _chat_wrap_cached(ev, body_font, cjk_font, text_max_w)
        true_total += len(w) if w else 1

    # Scroll anchoring: when the user has scrolled UP, new events arriving
    # at the bottom must NOT slide their view. active_scroll is measured
    # in visible-lines-from-bottom, so if N new physical lines were
    # appended since last frame while scrolled up, bump active_scroll by N
    # to keep the same messages in view. At the bottom (active_scroll==0)
    # we leave it 0 so autoscroll keeps showing the newest line. Done
    # BEFORE the walk so `needed` below accounts for the bumped offset.
    if active_scroll > 0:
        prev_total = _chat_tab_line_total.get(chat_active_tab)
        if prev_total is not None and true_total > prev_total:
            active_scroll = active_scroll + (true_total - prev_total)
            chat_tab_scroll[chat_active_tab] = active_scroll
        _chat_tab_line_total[chat_active_tab] = true_total
    else:
        _chat_tab_line_total[chat_active_tab] = None

    physical_lines_total = 0
    rendered_segments = []
    needed = visible_lines + max(0, active_scroll)
    for ev in reversed(events):
        try:
            if not active_filter(ev):
                continue
        except Exception:
            continue
        wrapped = _chat_wrap_cached(ev, body_font, cjk_font, text_max_w)
        mode = ev.get("mode", 0)
        ts_str = _chat_format_timestamp(ev.get("ts", 0))

        # Detect wrap shape: list[str] = plain text wrap, list[list]
        # = segmented (colored spans) wrap. Drives the rendering path
        # for this event.
        is_segmented = (wrapped
                        and isinstance(wrapped[0], list))

        # For splittable chat modes (say/tell/shout/yell), use the
        # per-mode message color and the sender-orange split. For
        # everything else (battle, system, unknown), use the regular
        # palette color and no split. Segmented events bypass both
        # paths since per-segment colors override.
        sender_text, _msg_text_full = (None, None)
        if not is_segmented:
            sender_text, _msg_text_full = _chat_split_sender_cached(ev)
        # GearSwap output (macro-set echoes + "X is now Y" state lines)
        # arrives on mode 1, so the mode-based color below would tint it
        # /say-white. Detect it the same way the classifier routes it and
        # force gold to match the Gearswap tab theme.
        _ev_text = ev.get("text") or ""
        _is_gearswap_line = (
            any(_ev_text.startswith(p) for p in _GEARSWAP_TEXT_PREFIXES_R)
            or _GEARSWAP_STATE_PATTERN_R.match(_ev_text) is not None
        )
        if _is_gearswap_line:
            body_color = CHAT_GEARSWAP_BODY_COLOR
            sender_text = None      # no sender/orange split for addon output
        elif sender_text is not None:
            body_color = CHAT_MSG_COLOR_BY_MODE.get(mode, CHAT_COLOR_DEFAULT)
        else:
            # Pass the full event (not just mode) so source-based color
            # routing applies to synthetic buff/debuff events.
            body_color = _chat_color_for_mode(ev)

        # wrapped[0] is the FIRST physical line. Sender (if any) only
        # appears on that first line. Subsequent wrapped lines are
        # all message body, rendered in body_color uniformly.
        first_physical = wrapped[0] if wrapped else ""
        for i, ln in enumerate(reversed(wrapped)):
            is_top_of_event = (i == len(wrapped) - 1)
            # `is_top_of_event` here means "first physical line of the
            # event" (we walked the wrapped list in reverse to render
            # bottom-up, so the LAST element in our reversed iteration
            # is the original wrapped[0]).
            seg = {
                "color":  body_color,
                "text":   ln,
                "ts":     ts_str if is_top_of_event else "",
                "spans":  ln if is_segmented else None,
            }
            if ev.get("focus_hit"):
                seg["focus_ts"] = ev.get("focus_ts") or ev.get("ts") or 0
                # Character ranges of each matched word within THIS
                # physical line (a phrase split across a wrap boundary
                # simply doesn't highlight). Plain text is the
                # span-concat for segmented lines, the line otherwise.
                _fp = (ln if not is_segmented
                       else "".join(t for t, _ in ln))
                _fl = _fp.lower()
                _ranges = []
                for _w in (ev.get("focus_words") or []):
                    _i = 0
                    while True:
                        _i = _fl.find(_w, _i)
                        if _i < 0:
                            break
                        _ranges.append((_i, _i + len(_w)))
                        _i += len(_w)
                if _ranges:
                    seg["focus_plain"]  = _fp
                    seg["focus_ranges"] = _ranges
            # Mark the first-physical-line of a splittable event with
            # the sender region info so the renderer can do two-color
            # blit. We compute the sender pixel-width here (once per
            # event per width change, since wrap+split are cached).
            if (not is_segmented) and is_top_of_event \
                    and sender_text is not None \
                    and ln == first_physical:
                # Edge case: extremely narrow panel could wrap the
                # sender text itself. Only enable split rendering if
                # the sender text is fully contained in this first
                # wrapped line. Otherwise fall back to single color.
                if ln.startswith(sender_text):
                    seg["sender_text"] = sender_text
                    # Color the sender's name. Default is orange
                    # (CHAT_SENDER_COLOR), but if this is the player
                    # talking (sender text contains their character
                    # name), use the fixed self-identity blue so the
                    # player's own name reads consistently across
                    # every chat type — see CHAT_SELF_NAME_COLOR.
                    if (player_self_name
                            and player_self_name in sender_text):
                        seg["sender_color"] = CHAT_SELF_NAME_COLOR
                    else:
                        seg["sender_color"] = CHAT_SENDER_COLOR
                    seg["msg_offset"] = len(sender_text)
            rendered_segments.append(seg)
            physical_lines_total += 1
            if physical_lines_total >= needed + 10:
                break
        if physical_lines_total >= needed + 10:
            break

    # Clamp scroll to available filtered history.
    max_scroll = max(0, physical_lines_total - visible_lines)
    if active_scroll > max_scroll:
        active_scroll = max_scroll
        chat_tab_scroll[chat_active_tab] = active_scroll
    if active_scroll < 0:
        active_scroll = 0
        chat_tab_scroll[chat_active_tab] = 0

    # Slice the visible window. rendered_segments is newest-first.
    start_idx = active_scroll
    end_idx   = min(physical_lines_total, start_idx + visible_lines)
    window = rendered_segments[start_idx:end_idx]

    # Render bottom-up. window[0] goes at bottom, window[-1] at top.
    bottom_y = content_y + content_h - line_h
    _focus_now_t = time.time()
    for offset, seg in enumerate(window):
        ly = bottom_y - offset * line_h
        if ly < content_y:
            break
        # Focus-word highlight: a pulsing amber shade behind JUST the
        # matched word(s). Word pixel positions come from measuring
        # the text before/inside each match with the same body font
        # the line renders in. Pulses (sine on alpha) for
        # FOCUS_PULSE_SECS after the hit, then settles to a steady
        # faint shade so older hits stay findable.
        _fts = seg.get("focus_ts")
        _frs = seg.get("focus_ranges")
        if _fts and _frs:
            _age = _focus_now_t - _fts
            if _age < FOCUS_PULSE_SECS:
                _fa = int(95 + 70 * math.sin(_age * 6.0))
            else:
                _fa = 48
            _fa = max(0, min(255, _fa))
            _fp = seg.get("focus_plain") or ""
            for _a, _b in _frs:
                try:
                    _pre_w  = body_font.size(_fp[:_a])[0]
                    _word_w = body_font.size(_fp[_a:_b])[0]
                except Exception:
                    continue
                _wx = text_x + _pre_w - 2
                _ww = _word_w + 4
                _patch = pygame.Surface((max(1, _ww), line_h),
                                        pygame.SRCALPHA)
                _patch.fill(CHAT_FOCUS_HL[:3] + (_fa,))
                surface.blit(_patch, (_wx, ly))
        if seg["ts"]:
            ts_surf = meta_font.render(seg["ts"], True, CHAT_TIMESTAMP_COLOR)
            surface.blit(ts_surf,
                         (content_x,
                          ly + (line_h - ts_surf.get_height()) // 2))
        # Three render paths:
        #   1. Segmented: walk per-span and blit each in its own color.
        #   2. Splittable sender (say/tell): two-color blit with orange
        #      sender + body color message.
        #   3. Plain single-color body.
        spans = seg.get("spans")
        sender_marker = seg.get("sender_text")
        if spans is not None:
            # Walk spans left-to-right. Each span gets its own color
            # via _chat_render_mixed (which also handles CJK fallback).
            #
            # Two color overrides on top of the static class→color
            # lookup: (1) "default"-class spans on a player-chat mode
            # get the per-mode body color instead of gray, so message
            # bodies pick up the channel tint (purple tells, pink
            # yells, light-yellow shouts, etc.) even when lua emits
            # the line as pre-segmented spans rather than as a single
            # splittable string. (2) ch_*-class spans that contain
            # the player's own character name render in a fixed blue
            # so the player's name reads as one consistent identity
            # color regardless of channel — other senders keep their
            # channel-themed ch_* colors so channels remain visually
            # distinct at a glance.
            cur_x = text_x
            # Track outgoing-tell context: once we see a sender region
            # that ends with '>>' (the unique outgoing-tell wire marker)
            # and contains the player's name, treat following default
            # spans as the tell body even if the mode field disagrees.
            # Source path differences (text-event vs 0x017 packet) can
            # land an outgoing tell at mode 0, 4, or 12 depending on
            # the addon load order and Windower version; this content-
            # based detection works regardless.
            _saw_outgoing_tell_marker = False
            # Event-level actor_class for per-segment clickable rects.
            # Used by the right-click context menu (some actions could
            # gate on class later — invite to a self/party row is a
            # silent no-op, but we don't suppress the menu).
            _ev_actor_class_seg = ev.get("actor_class") or "other"
            for span_text, span_color_class in spans:
                if not span_text:
                    continue
                color = CHAT_SEGMENT_COLORS.get(span_color_class,
                                                CHAT_COLOR_DEFAULT)
                # Detect outgoing-tell marker BEFORE the color decision
                # so a default-class span that contains the '>>' marker
                # gets colored as the tell body, not as gray default.
                # The lua chat module commonly emits outgoing tells as
                # 'Wormfood' (sender span) + '>> y' (default body span
                # containing the marker AND the body text in one span),
                # so the marker check has to happen first to catch it.
                if span_text and ">>" in span_text:
                    _saw_outgoing_tell_marker = True
                # Override 1: default-class span on a chat mode → body color.
                if (span_color_class == "default"
                        and mode in CHAT_MSG_COLOR_BY_MODE):
                    color = CHAT_MSG_COLOR_BY_MODE[mode]
                # Override 1b: default-class span on an outgoing-tell
                # line → mode 12 (tell-sent) body color. Catches both
                # the case where '>>' is in this span itself and the
                # case where '>>' was in an earlier span and the body
                # follows in a separate default span. Either way the
                # marker is True by now.
                elif (span_color_class == "default"
                        and _saw_outgoing_tell_marker
                        and 12 in CHAT_MSG_COLOR_BY_MODE):
                    color = CHAT_MSG_COLOR_BY_MODE[12]
                # Override 2: ch_*-class sender span containing player's
                # own name → fixed self-identity blue. Substring check
                # so it works for both incoming and outgoing tell
                # formats ("Wormfood : ", ">>Wormfood : ", "Wormfood>> ").
                elif (span_color_class is not None
                        and isinstance(span_color_class, str)
                        and span_color_class.startswith("ch_")
                        and player_self_name
                        and player_self_name in span_text):
                    color = CHAT_SELF_NAME_COLOR
                # Override 3 (hover): ch_*-class sender span whose text
                # matches the current mouse-hover name → brighten to
                # CHAT_NAME_HOVER_COLOR. Applied AFTER the self-name
                # override so the hover wins even on your own name —
                # consistent visual feedback that the cell is clickable.
                # Note: span_text for chat_packets-emitted sender spans
                # is the bare name (no delimiter), so direct equality
                # against _chat_name_hover is correct.
                _is_sender_span = (
                    isinstance(span_color_class, str)
                    and span_color_class.startswith("ch_")
                    and span_color_class != "ch_other"
                    and span_color_class != "ch_system"
                )
                if (_is_sender_span and _chat_name_hover
                        and _chat_name_hover == span_text):
                    color = CHAT_NAME_HOVER_COLOR
                span_surf = _chat_render_mixed(span_text, body_font,
                                                cjk_font, color)
                surface.blit(span_surf, (cur_x, ly))
                # Record sender-span rect for click-handler hit-tests.
                # Excludes ch_other and ch_system because those are
                # generic catch-alls (NPC dialog, system messages) where
                # the "sender" isn't a real player you can tell/invite.
                if _is_sender_span and span_text:
                    _chat_clickable_senders.append({
                        "rect": pygame.Rect(cur_x, ly,
                                            span_surf.get_width(),
                                            span_surf.get_height()),
                        "name": span_text,
                        "actor_class": _ev_actor_class_seg,
                    })
                cur_x += span_surf.get_width()
        elif sender_marker:
            # Pass 1: sender in orange.
            #
            # Special-case /yell (mode 11): FFXI yells arrive shaped
            # "Sender[ZoneName]: msg" — the originator's zone is embedded
            # in brackets right after the name. Rendering that entire
            # region in CHAT_SENDER_COLOR makes the zone tag fight the
            # speaker name for visual weight. Split the sender_marker
            # into name + bracket portions and paint the bracket in a
            # paler yellow so the eye reads "name first, zone second".
            #
            # Detection is conservative: only fires when mode==11 AND a
            # '[' appears in the sender_marker AND a matching ']' appears
            # before the trailing ': ' delimiter. If the shape doesn't
            # match (yell without zone tag, or some other channel that
            # happens to contain brackets), fall through to the unified
            # single-color render below.
            #
            # In both sub-branches, we extract the bare sender NAME
            # (no brackets, no trailing colon/space, no '>>') and record
            # its blit rect into _chat_clickable_senders so the mouse
            # handler can left-click → /tell composer or right-click →
            # context menu. The name color also switches to the hover
            # tint when the mouse is currently over this name.
            _ev_actor_class = ev.get("actor_class") or "other"
            _split_rendered = False
            _clickable_name = None
            _clickable_rect = None
            if mode == 11 and "[" in sender_marker and "]" in sender_marker:
                _lb = sender_marker.find("[")
                _rb = sender_marker.find("]", _lb)
                # Ensure both brackets land BEFORE the sender-region
                # boundary (msg_offset). _lb > 0 guarantees we don't
                # color a name that starts with '[' (degenerate case).
                if 0 < _lb < _rb < seg["msg_offset"]:
                    name_part   = sender_marker[:_lb]
                    zone_part   = sender_marker[_lb:_rb + 1]   # includes [ ]
                    tail_part   = sender_marker[_rb + 1:]       # the " : " suffix
                    # Hover state: brighten the name color when this is
                    # the sender under the mouse.
                    _name_clean = name_part.rstrip()
                    _name_color = (CHAT_NAME_HOVER_COLOR
                                   if _chat_name_hover == _name_clean
                                   else seg["sender_color"])
                    name_surf = _chat_render_mixed(name_part, body_font,
                                                   cjk_font, _name_color)
                    zone_surf = _chat_render_mixed(zone_part, body_font,
                                                   cjk_font, CHAT_YELL_ZONE_COLOR)
                    tail_surf = _chat_render_mixed(tail_part, body_font,
                                                   cjk_font, seg["sender_color"])
                    _cx = text_x
                    surface.blit(name_surf, (_cx, ly))
                    # Record the name rect for hit-testing BEFORE we
                    # advance past it. Use the rstripped name (not the
                    # raw name_part which may have trailing whitespace).
                    if _name_clean:
                        _clickable_name = _name_clean
                        _clickable_rect = pygame.Rect(_cx, ly,
                                                      name_surf.get_width(),
                                                      name_surf.get_height())
                    _cx += name_surf.get_width()
                    surface.blit(zone_surf, (_cx, ly)); _cx += zone_surf.get_width()
                    surface.blit(tail_surf, (_cx, ly)); _cx += tail_surf.get_width()
                    _sender_width = _cx - text_x
                    _split_rendered = True
            if not _split_rendered:
                # Unsplit sender: blit the whole sender_marker as one
                # surface (orange) but extract the bare name for the
                # hit-test rect. The name portion is sender_marker
                # minus the trailing delimiter (": ", ">> ", or ") ").
                # We approximate by finding the FIRST occurrence of any
                # of those delimiters and slicing off everything from
                # there. If no delimiter found, the whole marker is the
                # name (defensive — shouldn't happen for properly-split
                # senders, but doesn't break if it does).
                _name_clean = sender_marker
                for _delim in (" : ", ">> ", ") ", "] ", "> "):
                    _di = sender_marker.find(_delim)
                    if _di >= 0:
                        _name_clean = sender_marker[:_di]
                        break
                # '>>' prefix on incoming tells — drop it from the clean
                # name so right-click on ">>Wormfood : " gives just
                # "Wormfood".
                if _name_clean.startswith(">>"):
                    _name_clean = _name_clean[2:]
                # Build the rendered sender surface, switching to hover
                # color if this name is currently hovered. The HOVER
                # paints the WHOLE sender_marker region (including the
                # delimiter) for simplicity — looks fine and lets us
                # reuse the single-surface code path.
                _name_color = (CHAT_NAME_HOVER_COLOR
                               if (_name_clean
                                   and _chat_name_hover == _name_clean)
                               else seg["sender_color"])
                sender_surf = _chat_render_mixed(sender_marker, body_font,
                                                 cjk_font, _name_color)
                surface.blit(sender_surf, (text_x, ly))
                _sender_width = sender_surf.get_width()
                # Hit-test rect covers only the NAME portion of the
                # blitted surface. We compute the name's pixel width
                # by measuring the clean-name string with the same
                # mixed-font measurer used during wrap, so the rect
                # doesn't include the trailing colon/space/etc.
                if _name_clean:
                    _name_w = _chat_measure_mixed(_name_clean,
                                                  body_font, cjk_font)
                    if _name_w > 0:
                        # If we stripped a '>>' prefix, the rect should
                        # start after the '>>' glyph too. Measure that
                        # explicitly so the hit area aligns visually.
                        _prefix_offset = 0
                        if sender_marker.startswith(">>"):
                            _prefix_offset = _chat_measure_mixed(
                                ">>", body_font, cjk_font)
                        _clickable_name = _name_clean
                        _clickable_rect = pygame.Rect(
                            text_x + _prefix_offset, ly,
                            _name_w, sender_surf.get_height())
            if _clickable_name and _clickable_rect is not None:
                _chat_clickable_senders.append({
                    "rect": _clickable_rect,
                    "name": _clickable_name,
                    "actor_class": _ev_actor_class,
                })
            # Pass 2: message body in mode color, positioned right
            # after the sender region. Slice the segment text using
            # msg_offset so we render only the post-sender portion.
            msg_part = seg["text"][seg["msg_offset"]:]
            if msg_part:
                msg_surf = _chat_render_mixed(msg_part, body_font,
                                              cjk_font, seg["color"])
                surface.blit(msg_surf,
                             (text_x + _sender_width, ly))
        else:
            body_surf = _chat_render_mixed(seg["text"], body_font,
                                           cjk_font, seg["color"])
            surface.blit(body_surf, (text_x, ly))

    # NPC-dialog continue arrow: a small pulsing ▼ at the end of the
    # last line while the pinned character is in a dialog/cutscene —
    # the panel's version of the game's blinking continue cursor.
    # Only at the live bottom (scrolled up = reading history).
    if active_scroll == 0 and window and _chat_continue_arrow_active():
        _bot = window[0]
        _bplain = _bot.get("spans")
        _bplain = ("".join(t for t, _ in _bplain) if _bplain
                   else (_bot.get("text") or ""))
        try:
            _aend = text_x + body_font.size(_bplain)[0] + 7
        except Exception:
            _aend = text_x
        _aend = min(_aend, content_x + content_w - 14)
        _pulse = (math.sin(time.time() * 5.0) + 1.0) * 0.5   # 0..1
        _aalpha = int(90 + 165 * _pulse)
        _asurf = meta_font.render("\u25bc", True, (245, 205, 120))
        _asurf.set_alpha(_aalpha)
        surface.blit(_asurf, (_aend, bottom_y + (line_h
                              - _asurf.get_height()) // 2))

    # Jump-to-bottom badge: shown when active tab is scrolled up.
    _chat_jump_badge_rect = None
    if active_scroll > 0:
        badge_text = f"  ↓ scrolled up {active_scroll} lines  "
        badge_font = _chat_get_font("badge", 11)
        bw, bh = badge_font.size(badge_text)
        bw += 12
        bh += 6
        bx = x + pw - bw - 8
        # Badge sits just above the composer row (or above the panel
        # bottom edge when composer is hidden). Without this offset the
        # badge would overlap the composer's send button.
        by = y + ph - bh - 6 - (composer_h if chat_composer_visible else 0)
        badge_surf = pygame.Surface((bw, bh), pygame.SRCALPHA)
        badge_surf.fill((*CHAT_BADGE_BG, 235))
        surface.blit(badge_surf, (bx, by))
        pygame.draw.rect(surface, CHAT_BORDER_COLOR, (bx, by, bw, bh), 1)
        text_surf = badge_font.render(badge_text, True, CHAT_BADGE_FG)
        surface.blit(text_surf,
                     (bx + (bw - text_surf.get_width()) // 2,
                      by + (bh - text_surf.get_height()) // 2))
        _chat_jump_badge_rect = pygame.Rect(bx, by, bw, bh)

    # ── Scrollbar (right edge of content area) ──────────────────
    # Only renders when there's overflow (more filtered lines than fit
    # in the visible window). Track + thumb rects + max_scroll are
    # captured each frame for the click + drag handlers in the main
    # event loop. Sized to match the checklist scrollbar (8px wide,
    # 28px min thumb) so the two feel like the same widget.
    #
    # IMPORTANT: thumb size and scrollbar max_scroll are computed
    # against `true_total` (the unbounded full-history line count),
    # NOT against `physical_lines_total` (which only counts what we
    # actually rendered before the early-break optimization kicked
    # in). Using physical_lines_total would make the thumb visibly
    # grow as the user scrolls toward the newest message — because
    # less of the buffer needs rendering when near the bottom — and
    # shrink as they scroll up. true_total stays anchored to real
    # chat depth so thumb size only changes when new messages
    # actually arrive.
    global _chat_scrollbar_thumb_rect, _chat_scrollbar_track_rect
    global _chat_scrollbar_max_scroll
    _chat_scrollbar_thumb_rect = None
    _chat_scrollbar_track_rect = None
    _chat_scrollbar_max_scroll = 0
    sb_max_scroll = max(0, true_total - visible_lines)
    if sb_max_scroll > 0 and true_total > visible_lines:
        cb_w = 8
        cb_x = x + pw - cb_w - 4
        # Track spans the message content area, not the full panel —
        # avoids overlapping the header strip or composer row.
        cb_track_y = content_y
        cb_track_h = content_h
        cb_track = pygame.Rect(cb_x, cb_track_y, cb_w, cb_track_h)
        _chat_scrollbar_track_rect = cb_track
        _chat_scrollbar_max_scroll = sb_max_scroll
        pygame.draw.rect(surface, (40, 46, 60),
                         cb_track, border_radius=3)
        # Thumb: proportion of visible / total filtered lines. Uses
        # true_total so size stays stable as the user scrolls (only
        # actual chat growth shrinks it).
        thumb_h = max(28, int(cb_track_h * visible_lines
                              / max(1, true_total)))
        thumb_h = min(thumb_h, cb_track_h)
        # Position: active_scroll=0 → thumb at BOTTOM (newest), so the
        # vertical mapping is inverted relative to checklist. At
        # sb_max_scroll the thumb sits at the top of the track.
        avail = cb_track_h - thumb_h
        # scroll_fraction: 0 at newest (bottom), 1 at oldest (top).
        scroll_frac = (active_scroll / sb_max_scroll) if sb_max_scroll > 0 else 0
        scroll_frac = max(0.0, min(1.0, scroll_frac))
        thumb_y = cb_track_y + int(avail * (1 - scroll_frac))
        cb_thumb = pygame.Rect(cb_x, thumb_y, cb_w, thumb_h)
        _chat_scrollbar_thumb_rect = cb_thumb
        # Hover/drag affordance.
        is_dragging = _chat_scroll_drag is not None
        mouse_p = pygame.mouse.get_pos()
        is_hover = cb_thumb.collidepoint(mouse_p)
        thumb_col = ((180, 200, 230) if (is_dragging or is_hover)
                     else (110, 130, 170))
        pygame.draw.rect(surface, thumb_col, cb_thumb, border_radius=3)

    # ── Composer row (bottom of panel) ──────────────────────────
    # Renders last so it sits above the scrollback's last line in
    # z-order (the scrollback is clipped to content_h which excludes
    # the composer band, so there's no actual overlap, but rendering
    # order keeps things tidy).
    if chat_composer_visible:
        comp_y = y + ph - composer_h
        _draw_chat_composer(surface, x, comp_y, pw,
                            body_font, meta_font, cjk_font)

    # ── Sender-name context menu (right-click popup) ──────────────
    # Drawn LAST so it sits on top of every other panel element —
    # composer, badge, content, header. Skips draw when no menu is
    # open (the common case). Records each menu item's rect into the
    # menu state dict so the next mousedown can hit-test them.
    _chat_draw_name_context_menu(surface)


# ── Button panel ─────────────────────────────────────────────────────────
# 6 wide × 2 tall grid of user-configurable buttons. Each button runs the
# command in buttons_config[idx] when clicked. Layout: BTN_W per button,
# BTN_H per row, BTN_GAP between, BTN_PAD on the outer edge.
BTN_COLS    = 13
BTN_ROWS    = 2
BTN_W       = 56
BTN_H       = 36
BTN_GAP     = 4
BTN_PAD     = 6
BTN_ICON_SZ = 22
BTN_HDR_H   = 18      # header row above the button grid (page name + arrows)

def buttons_panel_size(scale=1.0):
    """Total panel size at `scale`. Returns (w, h)."""
    s = max(0.5, min(2.5, float(_eff(scale))))
    cell_w = max(28, int(BTN_W * s))
    cell_h = max(20, int(BTN_H * s))
    gap    = max(2, int(BTN_GAP * s))
    pad    = max(3, int(BTN_PAD * s))
    hdr_h  = max(14, int(BTN_HDR_H * s))
    pw = pad * 2 + cell_w * BTN_COLS + gap * (BTN_COLS - 1)
    ph = pad * 2 + hdr_h + cell_h * BTN_ROWS + gap * BTN_ROWS
    return pw, ph

def draw_buttons_panel(surface, x, y, scale=1.0, locked=False,
                       panel_idx=0):
    """Render the 6×2 button panel at (x, y). Populates buttons_rects /
    buttons_panel_rects[panel_idx] so the click handler can resolve hits.
    Returns (w, h).

    panel_idx: which panel slot this is (0 = original primary panel,
        1..N-1 = additional multi-mode panels). Used to:
        - look up the panel's current content page in hotbar_panel_pages
        - route hit-test results to buttons_panel_rects[panel_idx] (for
          panel_idx > 0) or buttons_rects (for panel_idx == 0).
    """
    global buttons_rects, buttons_panel_rects
    s = max(0.5, min(2.5, float(_eff(scale))))
    cell_w = max(28, int(BTN_W * s))
    cell_h = max(20, int(BTN_H * s))
    gap    = max(2, int(BTN_GAP * s))
    pad    = max(3, int(BTN_PAD * s))
    icon_sz= max(14, int(BTN_ICON_SZ * s))
    hdr_h  = max(14, int(BTN_HDR_H * s))
    pw, ph = buttons_panel_size(scale)

    # Resolve which content page this panel is currently showing. Panel 0
    # defaults to hotbar_current_page (legacy single-mode behaviour); all
    # other panels track their own current page in hotbar_panel_pages.
    if panel_idx == 0:
        eff_page_idx = hotbar_panel_pages.get(0, hotbar_current_page)
    else:
        eff_page_idx = hotbar_panel_pages.get(panel_idx, panel_idx)
    # Clamp into valid range (config edits or page-count changes can
    # leave a stale higher index).
    n_pages_local = max(1, len(hotbar_pages))
    if eff_page_idx < 0 or eff_page_idx >= n_pages_local:
        eff_page_idx = 0
        hotbar_panel_pages[panel_idx] = 0
    # Self-healing page sync (panel 0 only): the page this panel
    # DISPLAYS is the single source of truth, so keep the legacy
    # globals (hotbar_current_page + buttons_config) pointed at it.
    # Without this, any path that writes hotbar_panel_pages[0] without
    # going through _hotbar_panel_set_page — the layout-file restore at
    # startup was the live case, and the stale-page clamp above is
    # another — left the EDITOR and drag-swap reading page 1 while the
    # panel displayed the restored page ("clicked slot edits a button
    # from another page"). Render happens before click handling every
    # frame, so this invariant guarantees the two can never disagree.
    if panel_idx == 0 and eff_page_idx != hotbar_current_page:
        _hotbar_set_page(eff_page_idx)

    # Per-panel rects collection. Panel 0 uses the legacy buttons_rects
    # (consumed by all the existing click-handler loops without changes);
    # panels 1..N-1 stash into buttons_panel_rects[panel_idx], iterated
    # by the multi-mode hit-testing in the event handlers.
    if panel_idx == 0:
        buttons_rects = []
        local_rects = buttons_rects
    else:
        local_rects = []
        buttons_panel_rects[panel_idx] = local_rects

    # Resolve buttons list for the page being rendered.
    if hotbar_pages and 0 <= eff_page_idx < len(hotbar_pages):
        page_buttons = hotbar_pages[eff_page_idx].get("buttons", [])
        page_dict    = hotbar_pages[eff_page_idx]
    else:
        page_buttons = []
        page_dict    = None

    # Outer frame, matching DPS / buff panels.
    pygame.draw.rect(surface, COL_PANEL,  (x, y, pw, ph), border_radius=4)
    pygame.draw.rect(surface, COL_BORDER, (x, y, pw, ph), 1, border_radius=4)
    draw_accent_stripe(surface, x, y, ph, ACCENT_BUTTONS)

    mx, my = pygame.mouse.get_pos()

    # font_moon is ~12px which fits BTN_H=36 nicely with single-line labels.
    label_font = font_moon

    # ── Header row: page name (left) + page arrows + page indicator (right) ──
    # The page name is editable via the hotbar editor (treated as a 21st
    # field after the button slots — see hotbar_edit_slot conventions).
    # Arrows wrap (left from page 0 → last page).
    #
    # Per-panel scoping: in multi-hotbar mode each panel has its own current
    # page. The action tuples we emit into local_rects encode which panel
    # owns the click, e.g. ("__page_prev__", panel_idx). Panel 0 still emits
    # the legacy bare-string action so existing handlers keep working
    # (single-mode is the most common case; we don't churn its hot path).
    hdr_y = y + pad
    page_name = (page_dict and page_dict.get("name")) or f"Page {eff_page_idx + 1}"
    # Page name on the LEFT. Truncate so it doesn't overflow the arrows.
    name_max_w = pw - pad * 2 - 80   # reserve right edge for nav (≈80px)
    name_surf  = label_font.render(page_name, True, (220, 220, 230))
    if name_surf.get_width() > name_max_w:
        cut = page_name
        while cut and label_font.render(cut + "…", True, (220, 220, 230)).get_width() > name_max_w:
            cut = cut[:-1]
        name_surf = label_font.render((cut + "…") if cut else page_name[:1],
                                       True, (220, 220, 230))
    name_x = x + pad
    surface.blit(name_surf, (name_x,
                             hdr_y + (hdr_h - name_surf.get_height()) // 2))
    # Whole left half of header is a click-target for editing the name.
    name_rect = pygame.Rect(x + pad, hdr_y, name_max_w, hdr_h)
    if panel_idx == 0:
        local_rects.append((name_rect, "__page_name__"))
    else:
        local_rects.append((name_rect, ("__page_name__", panel_idx)))

    # Right side: < N/T >. Always shown so each panel cycles independently.
    arrow_w = max(14, int(14 * s))
    nav_y   = hdr_y
    right_arrow = pygame.Rect(x + pw - pad - arrow_w, nav_y,
                              arrow_w, hdr_h)
    # Indicator string between arrows.
    n_pages = max(1, len(hotbar_pages))
    indicator = f"{eff_page_idx + 1}/{n_pages}"
    ind_surf  = label_font.render(indicator, True, (200, 200, 215))
    ind_w     = ind_surf.get_width() + 6
    left_arrow = pygame.Rect(right_arrow.x - ind_w - arrow_w, nav_y,
                             arrow_w, hdr_h)
    ind_x = left_arrow.right
    # Hover styling for arrows.
    for arr_rect, label_text, action_name in (
        (left_arrow,  "<", "__page_prev__"),
        (right_arrow, ">", "__page_next__"),
    ):
        is_hov = arr_rect.collidepoint(mx, my) and not locked
        pygame.draw.rect(surface,
            (62, 62, 78) if is_hov else (40, 40, 50),
            arr_rect, border_radius=2)
        pygame.draw.rect(surface,
            (180, 180, 200) if is_hov else (90, 90, 105),
            arr_rect, 1, border_radius=2)
        a_surf = label_font.render(label_text, True, (220, 220, 230))
        surface.blit(a_surf,
            (arr_rect.x + (arr_rect.width  - a_surf.get_width())  // 2,
             arr_rect.y + (arr_rect.height - a_surf.get_height()) // 2))
        if panel_idx == 0:
            local_rects.append((arr_rect, action_name))
        else:
            local_rects.append((arr_rect, (action_name, panel_idx)))
    # Indicator text between arrows.
    surface.blit(ind_surf, (ind_x + 3,
                            nav_y + (hdr_h - ind_surf.get_height()) // 2))

    for row in range(BTN_ROWS):
        for col in range(BTN_COLS):
            idx = row * BTN_COLS + col
            entry = page_buttons[idx] if idx < len(page_buttons) else None
            bx = x + pad + col * (cell_w + gap)
            by = y + pad + hdr_h + gap + row * (cell_h + gap)
            rect = pygame.Rect(bx, by, cell_w, cell_h)
            # Panel 0: legacy (rect, idx) shape so existing handlers work.
            # Other panels: (rect, (idx, panel_idx)) so we can route the
            # click to the right panel's content page.
            if panel_idx == 0:
                local_rects.append((rect, idx))
            else:
                local_rects.append((rect, (idx, panel_idx)))

            is_inert = (entry is None
                        or entry["kind"] == "none"
                        or not entry["command"])
            is_hover = (rect.collidepoint(mx, my) and not is_inert
                        and not locked)

            # Cell background. Inert buttons are dimmer so users can see
            # which slots are unconfigured at a glance.
            if is_inert:
                cell_bg    = (28, 28, 36)
                border_col = (60, 60, 70)
            elif is_hover:
                cell_bg    = (62, 62, 78)
                border_col = (180, 180, 200)
            else:
                cell_bg    = (44, 44, 54)
                border_col = (100, 100, 115)
            pygame.draw.rect(surface, cell_bg, rect, border_radius=3)
            pygame.draw.rect(surface, border_col, rect, 1, border_radius=3)

            if entry is None:
                continue

            label = entry["label"]
            icon  = entry["icon"]
            icon_surf = get_ui_icon_scaled(icon, icon_sz) if icon else None
            text_color = (160, 160, 170) if is_inert else (220, 220, 230)

            # Layout: icon-only | label-only | icon+label (icon left).
            if icon_surf and label:
                ix = bx + 4
                iy = by + (cell_h - icon_sz) // 2
                surface.blit(icon_surf, (ix, iy))
                lab_surf = label_font.render(label, True, text_color)
                avail_w = cell_w - icon_sz - 10
                if lab_surf.get_width() > avail_w:
                    short = label
                    while short and label_font.size(short + "…")[0] > avail_w:
                        short = short[:-1]
                    lab_surf = label_font.render(short + "…", True, text_color)
                lx = ix + icon_sz + 4
                ly = by + (cell_h - lab_surf.get_height()) // 2
                surface.blit(lab_surf, (lx, ly))
            elif icon_surf:
                ix = bx + (cell_w - icon_sz) // 2
                iy = by + (cell_h - icon_sz) // 2
                surface.blit(icon_surf, (ix, iy))
            elif label:
                lab_surf = label_font.render(label, True, text_color)
                avail_w = cell_w - 6
                if lab_surf.get_width() > avail_w:
                    short = label
                    while short and label_font.size(short + "…")[0] > avail_w:
                        short = short[:-1]
                    lab_surf = label_font.render(short + "…", True, text_color)
                lx = bx + (cell_w - lab_surf.get_width()) // 2
                ly = by + (cell_h - lab_surf.get_height()) // 2
                surface.blit(lab_surf, (lx, ly))
            # else: empty slot, just the dim cell.

    return pw, ph


# ── Hotbar editor ────────────────────────────────────────────────────────
# In-app editor for the hotbar slots. Triggered by Settings → HotBar
# → "Edit hotbar" which sets hotbar_edit_mode = True. While editing, the
# normal hotbar still renders (slot clicks SELECT for editing instead of
# running commands), and an inline form panel appears below the hotbar
# with fields for the currently-selected slot.
#
# Click flow:
#   1. User clicks slot N in the hotbar      → hotbar_edit_slot = N,
#                                               draft = copy of buttons_config[N]
#   2. User clicks Label / Command field     → hotbar_focused_field set, cursor at end
#   3. User types                            → KEYDOWN events dispatch to focused field
#   4. User clicks [<] / [>] on Kind         → cycles kinds
#   5. User clicks "Pick icon"               → opens icon picker grid
#   6. User clicks an icon thumbnail         → draft["icon"] = filename, picker closes
#   7. User clicks Save                      → buttons_config[slot] = draft, save_buttons_config()
#   8. User clicks Cancel / "Done editing"   → exits edit mode without saving in-progress draft

HOTBAR_EDIT_FORM_H   = 200   # height of the inline form panel
HOTBAR_EDIT_FIELD_H  = 22
HOTBAR_KINDS         = ["windower", "shell", "url", "file", "none"]


def _hotbar_editor_get_focused_text():
    """Return the text currently in the focused field (or empty string)."""
    if hotbar_edit_draft is None or hotbar_focused_field is None:
        return ""
    return hotbar_edit_draft.get(hotbar_focused_field, "") or ""


def _hotbar_editor_set_focused_text(new_text):
    """Write back into the focused field of the draft."""
    if hotbar_edit_draft is None or hotbar_focused_field is None:
        return
    hotbar_edit_draft[hotbar_focused_field] = new_text


def hotbar_editor_handle_keydown(event):
    """Apply a pygame KEYDOWN to the focused text field. Called from the
    main event loop when hotbar_edit_mode is on AND a field is focused.
    Supports backspace, delete, left/right arrows, home/end, and printable
    characters via event.unicode.

    Returns True if the event was consumed (so other handlers skip it)."""
    global hotbar_text_cursor, hotbar_text_blink_t0, hotbar_focused_field
    if hotbar_edit_draft is None or hotbar_focused_field is None:
        return False
    text = _hotbar_editor_get_focused_text()
    cursor = max(0, min(hotbar_text_cursor, len(text)))

    if event.key == pygame.K_BACKSPACE:
        if cursor > 0:
            text = text[:cursor - 1] + text[cursor:]
            cursor -= 1
    elif event.key == pygame.K_DELETE:
        if cursor < len(text):
            text = text[:cursor] + text[cursor + 1:]
    elif event.key == pygame.K_LEFT:
        cursor = max(0, cursor - 1)
    elif event.key == pygame.K_RIGHT:
        cursor = min(len(text), cursor + 1)
    elif event.key == pygame.K_HOME:
        cursor = 0
    elif event.key == pygame.K_END:
        cursor = len(text)
    elif event.key in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_TAB):
        # Move focus: label → command → label.
        hotbar_focused_field = (
            "command" if hotbar_focused_field == "label" else "label")
        new_text = _hotbar_editor_get_focused_text()
        cursor = len(new_text)
        text = new_text
    elif event.key == pygame.K_ESCAPE:
        # Defocus.
        hotbar_focused_field = None
    else:
        # Printable character. event.unicode is already the right
        # character including shift / dead keys / etc.
        ch = event.unicode
        if ch and ch.isprintable():
            text = text[:cursor] + ch + text[cursor:]
            cursor += len(ch)
        else:
            return False  # not consumed

    _hotbar_editor_set_focused_text(text)
    hotbar_text_cursor = cursor
    hotbar_text_blink_t0 = time.time()  # reset blink so cursor stays solid
    return True


def _list_ui_icons():
    """Scan the icons/ui/ folder and return a sorted list of filenames
    that pygame can load. Cached for the duration of edit mode (rebuild
    on each entry into edit mode by clearing the module-level cache)."""
    global _ui_icons_listing_cache
    try:
        _ui_icons_listing_cache
    except NameError:
        _ui_icons_listing_cache = None
    if _ui_icons_listing_cache is not None:
        return _ui_icons_listing_cache
    out = []
    if UI_ICONS_DIR and os.path.isdir(UI_ICONS_DIR):
        try:
            for fn in os.listdir(UI_ICONS_DIR):
                low = fn.lower()
                if low.endswith((".png", ".bmp", ".jpg", ".jpeg")):
                    out.append(fn)
        except Exception as e:
            print(f"[OmniWatch] could not list icons/ui/: {e!r}")
    out.sort(key=str.lower)
    _ui_icons_listing_cache = out
    return out


def _refresh_ui_icon_listing():
    """Force a rescan of icons/ui/. Called when entering edit mode so
    icons added since startup show up."""
    global _ui_icons_listing_cache
    _ui_icons_listing_cache = None


def _browse_for_gear_file():
    """Open a native OS file picker to choose a GearSwap gear .lua file.
    Returns the absolute path, or "" if cancelled. Modeled on
    _browse_for_icon_file (tkinter filedialog — stdlib, works in the
    frozen exe). Returns "" on any failure rather than raising."""
    try:
        import tkinter as tk
        from tkinter import filedialog
        root = tk.Tk()
        root.withdraw()
        try:
            root.attributes("-topmost", True)
        except Exception:
            pass
        # Seed the dialog at the last-used folder if we have one.
        initial = ""
        try:
            if sim_import_file and os.path.isfile(sim_import_file):
                initial = os.path.dirname(sim_import_file)
            elif sim_import_root and os.path.isdir(sim_import_root):
                initial = sim_import_root
        except Exception:
            initial = ""
        path = filedialog.askopenfilename(
            parent=root,
            title="Select a GearSwap gear file",
            initialdir=initial or None,
            filetypes=[
                ("Lua files", "*.lua"),
                ("All files", "*.*"),
            ],
        )
        try:
            root.destroy()
        except Exception:
            pass
        return path or ""
    except Exception as e:
        print(f"[OmniWatch] gear file picker failed: {e!r}")
        return ""


def _browse_for_icon_file():
    """Open a native OS file picker and return the absolute path the
    user chose, or "" if they cancelled. Uses tkinter's filedialog —
    stdlib, works in PyInstaller frozen exes. The dialog's hidden Tk
    root is destroyed before returning so it doesn't leak windows.

    Returns "" on any failure (no Tk available, dialog crash, etc.)
    rather than raising, so the editor stays alive."""
    try:
        import tkinter as tk
        from tkinter import filedialog
        root = tk.Tk()
        root.withdraw()      # don't show the empty Tk root window
        try:
            # On Windows, lift to TOPMOST briefly so the dialog appears
            # above the always-on-top OmniWatch overlay. Without this
            # the file picker can pop up BEHIND OmniWatch and look like
            # the click did nothing.
            root.attributes("-topmost", True)
        except Exception:
            pass
        path = filedialog.askopenfilename(
            parent=root,
            title="Pick an icon for this hotbar slot",
            filetypes=[
                ("Image files", "*.png *.bmp *.jpg *.jpeg *.gif"),
                ("PNG", "*.png"),
                ("BMP", "*.bmp"),
                ("All files", "*.*"),
            ],
        )
        try:
            root.destroy()
        except Exception:
            pass
        return path or ""
    except Exception as e:
        print(f"[OmniWatch] file picker failed: {e!r}")
        return ""


def _import_icon_into_ui_dir(src_path):
    """Copy `src_path` into UI_ICONS_DIR (icons/ui/) and return just
    the basename — that's what gets stored in the button entry's
    "icon" field. Keeps the JSON portable (no absolute paths) and
    means the file is bundled with the addon for future reference.

    If a file with the same name already exists in icons/ui/, we
    append a numeric suffix (foo.png → foo_1.png) so we don't
    overwrite an existing icon."""
    if not src_path or not os.path.isfile(src_path):
        print(f"[OmniWatch] icon import: source missing: {src_path!r}")
        return ""
    if not UI_ICONS_DIR:
        print("[OmniWatch] icon import: UI_ICONS_DIR not set")
        return ""
    try:
        os.makedirs(UI_ICONS_DIR, exist_ok=True)
    except Exception as e:
        print(f"[OmniWatch] icon import: cannot create {UI_ICONS_DIR}: {e!r}")
        return ""

    base = os.path.basename(src_path)
    stem, ext = os.path.splitext(base)
    target = os.path.join(UI_ICONS_DIR, base)
    n = 1
    # Don't overwrite an existing icon — append _1, _2, ... until we
    # find a free slot. Ten attempts is plenty; bail with a warning
    # rather than infinite-loop if something pathological happens.
    while os.path.exists(target) and n < 100:
        target = os.path.join(UI_ICONS_DIR, f"{stem}_{n}{ext}")
        n += 1
    if os.path.exists(target):
        print(f"[OmniWatch] icon import: too many name collisions for "
              f"{base}; aborting")
        return ""
    try:
        import shutil
        shutil.copy2(src_path, target)
        print(f"[OmniWatch] imported icon: {src_path} → {target}")
        return os.path.basename(target)
    except Exception as e:
        print(f"[OmniWatch] icon import failed: {e!r}")
        return ""


def draw_hotbar_editor(surface, hotbar_x, hotbar_y, hotbar_w, hotbar_h):
    """Render the inline editor form below the hotbar. Populates
    hotbar_editor_rects with click targets. Returns the total
    height consumed by the editor (form panel + optional icon picker)."""
    global hotbar_editor_rects
    hotbar_editor_rects = []
    if not hotbar_edit_mode:
        return 0

    pad   = 8
    fy    = hotbar_y + hotbar_h + 4
    form_w = hotbar_w
    form_h = HOTBAR_EDIT_FORM_H
    form_rect = pygame.Rect(hotbar_x, fy, form_w, form_h)

    # Background panel matching the dropdown style.
    pygame.draw.rect(surface, (28, 28, 36), form_rect, border_radius=4)
    pygame.draw.rect(surface, (140, 140, 160), form_rect, 1, border_radius=4)

    title_font = pygame.font.SysFont("Consolas", 13, bold=True)
    label_font = font_label
    field_font = pygame.font.SysFont("Consolas", 12)
    btn_font   = pygame.font.SysFont("Consolas", 11, bold=True)

    # Determine title + whether a draft is active. hotbar_edit_slot is
    # -1 (nothing selected), an int 0..19 (a button slot), or the
    # special string "__page_name__" (editing the current page name).
    is_page_name_mode = (hotbar_edit_slot == "__page_name__")
    is_slot_mode = (isinstance(hotbar_edit_slot, int)
                    and hotbar_edit_slot >= 0)
    has_draft = (is_page_name_mode or is_slot_mode) and (hotbar_edit_draft is not None)

    # Title strip + Done button on the right.
    if is_page_name_mode:
        title_text = f"Editing page {hotbar_current_page + 1} name"
    elif is_slot_mode:
        title_text = f"Editing slot {hotbar_edit_slot + 1}"
    else:
        title_text = "Hotbar editor — click a slot above to edit"
    t_surf = title_font.render(title_text, True, (220, 200, 150))
    surface.blit(t_surf, (form_rect.x + pad, form_rect.y + pad))

    done_w, done_h = 90, 18
    done_rect = pygame.Rect(form_rect.right - done_w - pad,
                            form_rect.y + pad,
                            done_w, done_h)
    pygame.draw.rect(surface, (180, 160, 110), done_rect, border_radius=8)
    done_surf = btn_font.render("DONE EDITING", True, (40, 40, 50))
    surface.blit(done_surf,
                 (done_rect.x + (done_w - done_surf.get_width()) // 2,
                  done_rect.y + (done_h - done_surf.get_height()) // 2))
    hotbar_editor_rects.append((done_rect, {"kind": "done"}))

    if not has_draft:
        # No slot picked yet — just show the title bar and Done button.
        return form_h + 4

    # ── Form fields ─────────────────────────────────────────────────────
    # Layout: 4 rows of (label : control) pairs. Label column on left,
    # control on right. Label/command get text-input widgets; kind gets
    # an enum-style cycler; icon gets a button + small preview.
    cy = form_rect.y + pad + 24
    label_col_w = 70
    control_x   = form_rect.x + pad + label_col_w
    control_w   = form_rect.right - pad - control_x

    def _draw_field_label(text, y):
        s = label_font.render(text, True, (180, 180, 200))
        surface.blit(s, (form_rect.x + pad, y + (HOTBAR_EDIT_FIELD_H - s.get_height()) // 2))

    def _draw_text_input(field_name, y):
        """Render a text input box for hotbar_edit_draft[field_name]."""
        rect = pygame.Rect(control_x, y, control_w, HOTBAR_EDIT_FIELD_H)
        is_focused = hotbar_focused_field == field_name
        bg = (44, 44, 56) if is_focused else (36, 36, 46)
        bdr = (200, 180, 130) if is_focused else (90, 90, 110)
        pygame.draw.rect(surface, bg, rect, border_radius=2)
        pygame.draw.rect(surface, bdr, rect, 1, border_radius=2)
        text = hotbar_edit_draft.get(field_name, "") or ""
        ts = field_font.render(text, True, (230, 230, 240))
        # Clip text to box.
        text_y = rect.y + (rect.h - ts.get_height()) // 2
        surface.blit(ts, (rect.x + 4, text_y),
                     pygame.Rect(0, 0, rect.w - 8, rect.h))

        # Cursor: blink at 2 Hz, drawn after the n-th character where
        # n = hotbar_text_cursor. Only when this field is focused.
        if is_focused:
            blink_phase = ((time.time() - hotbar_text_blink_t0) % 1.0) < 0.5
            if blink_phase:
                cursor_idx = max(0, min(hotbar_text_cursor, len(text)))
                prefix = text[:cursor_idx]
                px = rect.x + 4 + field_font.size(prefix)[0]
                pygame.draw.line(surface, (220, 220, 240),
                                 (px, rect.y + 3),
                                 (px, rect.y + rect.h - 3), 1)
        hotbar_editor_rects.append(
            (rect, {"kind": "focus", "field": field_name}))

    # Row 1: Label (or Page Name when in name-edit mode).
    _draw_field_label("Page Name" if is_page_name_mode else "Label", cy)
    _draw_text_input("label", cy)
    cy += HOTBAR_EDIT_FIELD_H + 6

    # Rows 2-4 only apply to button-slot edits. Skip them entirely when
    # editing a page name — the only field there is the name itself.
    if not is_page_name_mode:
        # Row 2: Kind (enum cycler [<] kind [>])
        _draw_field_label("Kind", cy)
        kind_val = hotbar_edit_draft.get("kind", "none")
        kind_text = kind_val
        kind_surf = field_font.render(kind_text, True, (220, 220, 230))
        btn_w = 18
        next_rect = pygame.Rect(control_x + control_w - btn_w,
                                cy + (HOTBAR_EDIT_FIELD_H - 16) // 2,
                                btn_w, 16)
        val_x = next_rect.x - 6 - kind_surf.get_width()
        prev_rect = pygame.Rect(val_x - 6 - btn_w,
                                cy + (HOTBAR_EDIT_FIELD_H - 16) // 2,
                                btn_w, 16)
        pygame.draw.rect(surface, (60, 60, 75), prev_rect, border_radius=2)
        pygame.draw.rect(surface, (60, 60, 75), next_rect, border_radius=2)
        ls = field_font.render("<", True, (220, 220, 230))
        rs = field_font.render(">", True, (220, 220, 230))
        surface.blit(ls, (prev_rect.x + (prev_rect.w - ls.get_width()) // 2,
                          prev_rect.y + (prev_rect.h - ls.get_height()) // 2))
        surface.blit(rs, (next_rect.x + (next_rect.w - rs.get_width()) // 2,
                          next_rect.y + (next_rect.h - rs.get_height()) // 2))
        surface.blit(kind_surf, (val_x,
                                 cy + (HOTBAR_EDIT_FIELD_H - kind_surf.get_height()) // 2))
        hotbar_editor_rects.append((prev_rect, {"kind": "kind_step", "delta": -1}))
        hotbar_editor_rects.append((next_rect, {"kind": "kind_step", "delta": 1}))
        cy += HOTBAR_EDIT_FIELD_H + 6

        # Row 3: Command
        _draw_field_label("Command", cy)
        _draw_text_input("command", cy)
        cy += HOTBAR_EDIT_FIELD_H + 6

        # Row 4: Icon — small thumb preview + "Pick…" button + clear.
        _draw_field_label("Icon", cy)
        icon_filename = hotbar_edit_draft.get("icon", "") or ""
        thumb_size = HOTBAR_EDIT_FIELD_H - 4
        thumb_rect = pygame.Rect(control_x, cy + 2, thumb_size, thumb_size)
        pygame.draw.rect(surface, (36, 36, 46), thumb_rect, border_radius=2)
        pygame.draw.rect(surface, (90, 90, 110), thumb_rect, 1, border_radius=2)
        if icon_filename:
            thumb = get_ui_icon_scaled(icon_filename, thumb_size - 4)
            if thumb is not None:
                surface.blit(thumb, (thumb_rect.x + 2, thumb_rect.y + 2))

        # Filename text after the thumb.
        fn_text = icon_filename if icon_filename else "(none)"
        fn_surf = field_font.render(fn_text, True, (180, 180, 200))
        surface.blit(fn_surf, (thumb_rect.right + 6,
                               cy + (HOTBAR_EDIT_FIELD_H - fn_surf.get_height()) // 2))

        # Pick / Clear buttons on the right.
        pick_w = 48
        pick_rect = pygame.Rect(control_x + control_w - pick_w * 2 - 4,
                                cy + (HOTBAR_EDIT_FIELD_H - 16) // 2,
                                pick_w, 16)
        clear_rect = pygame.Rect(control_x + control_w - pick_w,
                                 cy + (HOTBAR_EDIT_FIELD_H - 16) // 2,
                                 pick_w, 16)
        pygame.draw.rect(surface, (180, 160, 110), pick_rect, border_radius=8)
        pygame.draw.rect(surface, (160, 100, 100), clear_rect, border_radius=8)
        ps = btn_font.render("PICK", True, (40, 40, 50))
        cs = btn_font.render("CLEAR", True, (40, 40, 50))
        surface.blit(ps, (pick_rect.x + (pick_w - ps.get_width()) // 2,
                          pick_rect.y + (pick_rect.h - ps.get_height()) // 2))
        surface.blit(cs, (clear_rect.x + (pick_w - cs.get_width()) // 2,
                          clear_rect.y + (clear_rect.h - cs.get_height()) // 2))
        hotbar_editor_rects.append((pick_rect, {"kind": "pick_icon"}))
        hotbar_editor_rects.append((clear_rect, {"kind": "clear_icon"}))
        cy += HOTBAR_EDIT_FIELD_H + 8

    # Save button (commits draft → buttons_config[slot] + writes file).
    save_w, save_h = 80, 22
    save_rect = pygame.Rect(form_rect.x + pad,
                            form_rect.bottom - save_h - pad,
                            save_w, save_h)
    pygame.draw.rect(surface, (140, 200, 140), save_rect, border_radius=8)
    ss = btn_font.render("SAVE", True, (30, 50, 30))
    surface.blit(ss, (save_rect.x + (save_w - ss.get_width()) // 2,
                      save_rect.y + (save_h - ss.get_height()) // 2))
    hotbar_editor_rects.append((save_rect, {"kind": "save"}))

    # Cancel button (discards draft, leaves slot selection alone).
    cancel_rect = pygame.Rect(save_rect.right + 6,
                              save_rect.y, save_w, save_h)
    pygame.draw.rect(surface, (160, 100, 100), cancel_rect, border_radius=8)
    cs = btn_font.render("CANCEL", True, (40, 30, 30))
    surface.blit(cs, (cancel_rect.x + (save_w - cs.get_width()) // 2,
                      cancel_rect.y + (save_h - cs.get_height()) // 2))
    hotbar_editor_rects.append((cancel_rect, {"kind": "cancel"}))

    # Copy / Paste buttons. Copy snapshots the current draft into the
    # module-level _hotbar_clipboard. Paste replaces the draft with the
    # clipboard contents (you still have to SAVE to commit). Paste is
    # dimmed when the clipboard is empty. Skipped in page-name mode
    # since there's nothing meaningful to copy from a name-only draft.
    if not is_page_name_mode:
        cp_w = 64
        copy_rect = pygame.Rect(cancel_rect.right + 12,
                                save_rect.y, cp_w, save_h)
        paste_rect = pygame.Rect(copy_rect.right + 6,
                                 save_rect.y, cp_w, save_h)
        # Copy: always enabled (any draft can be copied).
        pygame.draw.rect(surface, (110, 130, 170), copy_rect, border_radius=8)
        cps = btn_font.render("COPY", True, (30, 30, 50))
        surface.blit(cps, (copy_rect.x + (cp_w - cps.get_width()) // 2,
                           copy_rect.y + (save_h - cps.get_height()) // 2))
        hotbar_editor_rects.append((copy_rect, {"kind": "copy_slot"}))
        # Paste: enabled only when clipboard has content.
        has_clip = (_hotbar_clipboard is not None)
        paste_bg = (110, 170, 130) if has_clip else (60, 70, 65)
        paste_fg = (30, 50, 35)    if has_clip else (110, 120, 115)
        pygame.draw.rect(surface, paste_bg, paste_rect, border_radius=8)
        pst = btn_font.render("PASTE", True, paste_fg)
        surface.blit(pst, (paste_rect.x + (cp_w - pst.get_width()) // 2,
                           paste_rect.y + (save_h - pst.get_height()) // 2))
        # Always register the rect — the click handler just no-ops when
        # clipboard is empty. Cleaner than a conditional rect that
        # disappears, which would cause hover layout to jitter.
        hotbar_editor_rects.append((paste_rect, {"kind": "paste_slot"}))
        # Delete: empties the SAVED slot immediately (no Save needed) —
        # the one-click way to remove a button. Danger-styled and set
        # apart from Paste so it isn't fat-fingered. COPY first if you
        # want an undo path (copy → delete → paste elsewhere).
        # Right-aligned at the form edge when there's room (keeps the
        # destructive action visually apart from Paste); falls back to
        # inline placement on very narrow/low-scale hotbars.
        del_rect = pygame.Rect(max(paste_rect.right + 12,
                                   form_rect.right - pad - cp_w),
                               save_rect.y, cp_w, save_h)
        pygame.draw.rect(surface, (190, 80, 80), del_rect, border_radius=8)
        dls = btn_font.render("DELETE", True, (50, 20, 20))
        surface.blit(dls, (del_rect.x + (cp_w - dls.get_width()) // 2,
                           del_rect.y + (save_h - dls.get_height()) // 2))
        hotbar_editor_rects.append((del_rect, {"kind": "delete_slot"}))

    total_h = form_h + 4

    # ── Icon picker ────────────────────────────────────────────────────
    # Renders below the form when open. Grid of icon thumbnails; click
    # one to set the draft's icon and close the picker.
    if hotbar_icon_picker_open:
        py = form_rect.bottom + 4
        picker_w = form_w
        picker_h = 220
        picker_rect = pygame.Rect(form_rect.x, py, picker_w, picker_h)
        pygame.draw.rect(surface, (28, 28, 36), picker_rect, border_radius=4)
        pygame.draw.rect(surface, (140, 140, 160), picker_rect, 1, border_radius=4)

        # Header strip with Browse button on the right.
        hdr_surf = title_font.render(
            "Choose an icon (click thumb, or Browse… for any file)",
            True, (220, 200, 150))
        surface.blit(hdr_surf, (picker_rect.x + pad, picker_rect.y + pad))

        # Browse button: opens a native OS file picker so the user can
        # grab an icon from anywhere on disk. Selected file gets copied
        # into icons/ui/ and auto-applied to the current draft.
        browse_w, browse_h = 80, 18
        browse_rect = pygame.Rect(
            picker_rect.right - browse_w - pad - 52,  # leave room for ▲▼
            picker_rect.y + 4, browse_w, browse_h)
        pygame.draw.rect(surface, (180, 160, 110), browse_rect, border_radius=8)
        bs = btn_font.render("BROWSE…", True, (40, 40, 50))
        surface.blit(bs, (browse_rect.x + (browse_w - bs.get_width()) // 2,
                          browse_rect.y + (browse_h - bs.get_height()) // 2))
        hotbar_editor_rects.append((browse_rect, {"kind": "browse_icon"}))

        # Grid layout: thumbnails of fixed size, wrap to fit.
        thumb = 32
        cell  = thumb + 8
        margin_top = 28
        cells_per_row = max(1, (picker_w - pad * 2) // cell)
        icons_listing = _list_ui_icons()
        # Scroll: integer row offset.
        max_rows = max(1, (picker_h - margin_top - pad) // cell)
        total_rows = (len(icons_listing) + cells_per_row - 1) // cells_per_row
        scroll_max = max(0, total_rows - max_rows)
        scroll = max(0, min(hotbar_icon_picker_scroll, scroll_max))
        first_idx = scroll * cells_per_row
        last_idx  = min(len(icons_listing), first_idx + cells_per_row * max_rows)

        # Empty-state: show a hint that points at icons/ui/ and the
        # Browse button. This is the case user hit — fresh install,
        # no icons in icons/ui/ yet.
        if not icons_listing:
            empty_lines = [
                "No icons found in icons/ui/.",
                "Click BROWSE… to pick any image file (it'll be",
                "copied into icons/ui/ for you), or drop .png/.bmp",
                "files into that folder directly.",
            ]
            ey = picker_rect.y + margin_top + 6
            for line in empty_lines:
                ls = field_font.render(line, True, (170, 170, 190))
                surface.blit(ls, (picker_rect.x + pad + 4, ey))
                ey += ls.get_height() + 2
        else:
            # Track visible icon thumbnail rects for click handling.
            for i in range(first_idx, last_idx):
                local = i - first_idx
                r = local // cells_per_row
                c = local % cells_per_row
                tx = picker_rect.x + pad + c * cell
                ty = picker_rect.y + margin_top + r * cell
                tr = pygame.Rect(tx, ty, thumb, thumb)
                pygame.draw.rect(surface, (40, 40, 52), tr, border_radius=2)
                pygame.draw.rect(surface, (80, 80, 100), tr, 1, border_radius=2)
                fn = icons_listing[i]
                ts = get_ui_icon_scaled(fn, thumb - 4)
                if ts is not None:
                    surface.blit(ts, (tr.x + 2, tr.y + 2))
                hotbar_editor_rects.append(
                    (tr, {"kind": "select_icon", "filename": fn}))

        # Scroll buttons in the top-right of the picker.
        if total_rows > max_rows:
            up_rect = pygame.Rect(picker_rect.right - 24 - 24,
                                  picker_rect.y + 4, 22, 18)
            dn_rect = pygame.Rect(picker_rect.right - 24,
                                  picker_rect.y + 4, 22, 18)
            for r, t in ((up_rect, "▲"), (dn_rect, "▼")):
                pygame.draw.rect(surface, (60, 60, 75), r, border_radius=2)
                ts = btn_font.render(t, True, (220, 220, 230))
                if ts.get_width() < 4:
                    ts = btn_font.render("^" if t == "▲" else "v",
                                         True, (220, 220, 230))
                surface.blit(ts, (r.x + (r.w - ts.get_width()) // 2,
                                  r.y + (r.h - ts.get_height()) // 2))
            hotbar_editor_rects.append(
                (up_rect, {"kind": "picker_scroll", "delta": -1}))
            hotbar_editor_rects.append(
                (dn_rect, {"kind": "picker_scroll", "delta": 1}))

        total_h += picker_h + 4

    return total_h


def dispatch_hotbar_editor_click(mx, my):
    """Resolve a click against hotbar_editor_rects. Returns True if the
    click hit something (and was consumed), False otherwise. The
    overall click handler still falls through to slot-select behavior
    if this returns False AND we're in edit mode.
    """
    global hotbar_edit_mode, hotbar_edit_slot, hotbar_edit_draft
    global hotbar_focused_field, hotbar_text_cursor, hotbar_text_blink_t0
    global hotbar_icon_picker_open, hotbar_icon_picker_scroll
    global _hotbar_clipboard
    for rect, action in hotbar_editor_rects:
        if not rect.collidepoint(mx, my):
            continue
        kind = action["kind"]
        if kind == "done":
            # Exit edit mode entirely. Doesn't auto-save the draft —
            # user has to hit Save first if they want to persist.
            hotbar_edit_mode = False
            hotbar_edit_slot = -1
            hotbar_edit_draft = None
            hotbar_focused_field = None
            hotbar_icon_picker_open = False
            print("[OmniWatch] hotbar editor closed")
        elif kind == "focus":
            hotbar_focused_field = action["field"]
            text = (hotbar_edit_draft.get(action["field"], "")
                    if hotbar_edit_draft else "")
            hotbar_text_cursor = len(text)
            hotbar_text_blink_t0 = time.time()
        elif kind == "kind_step":
            if hotbar_edit_draft is not None:
                cur = hotbar_edit_draft.get("kind", "none")
                try:
                    idx = HOTBAR_KINDS.index(cur)
                except ValueError:
                    idx = 0
                idx = (idx + action["delta"]) % len(HOTBAR_KINDS)
                hotbar_edit_draft["kind"] = HOTBAR_KINDS[idx]
        elif kind == "pick_icon":
            _refresh_ui_icon_listing()
            hotbar_icon_picker_open = True
            hotbar_icon_picker_scroll = 0
        elif kind == "clear_icon":
            if hotbar_edit_draft is not None:
                hotbar_edit_draft["icon"] = ""
        elif kind == "select_icon":
            if hotbar_edit_draft is not None:
                hotbar_edit_draft["icon"] = action["filename"]
            hotbar_icon_picker_open = False
        elif kind == "browse_icon":
            # Open a native OS file picker. The chosen file gets copied
            # into icons/ui/ (so the JSON stays portable, just stores
            # the filename) and is auto-selected for the current draft.
            picked = _browse_for_icon_file()
            if picked:
                copied_filename = _import_icon_into_ui_dir(picked)
                if copied_filename and hotbar_edit_draft is not None:
                    hotbar_edit_draft["icon"] = copied_filename
                    hotbar_icon_picker_open = False
                    _refresh_ui_icon_listing()
        elif kind == "picker_scroll":
            hotbar_icon_picker_scroll = max(
                0, hotbar_icon_picker_scroll + action["delta"])
        elif kind == "save":
            # Commit draft → buttons_config[slot] (or page name) and
            # write to disk. After saving, deselect the slot so the
            # user gets clear visual feedback. They can click another
            # slot to keep editing.
            if hotbar_edit_draft is not None:
                if hotbar_edit_slot == "__page_name__":
                    # Page name save: trim, fall back to "Page N" on empty.
                    new_name = (hotbar_edit_draft.get("label", "") or "").strip()
                    if not new_name:
                        new_name = f"Page {hotbar_current_page + 1}"
                    if hotbar_pages:
                        hotbar_pages[hotbar_current_page]["name"] = new_name
                    save_buttons_config()
                    print(f"[OmniWatch] saved page name: {new_name!r}")
                elif (isinstance(hotbar_edit_slot, int)
                        and 0 <= hotbar_edit_slot < len(buttons_config)):
                    buttons_config[hotbar_edit_slot] = _normalize_button_entry(
                        hotbar_edit_draft)
                    save_buttons_config()
                    print(f"[OmniWatch] saved slot "
                          f"{hotbar_edit_slot + 1}: "
                          f"{buttons_config[hotbar_edit_slot]}")
            hotbar_edit_slot = -1
            hotbar_edit_draft = None
            hotbar_focused_field = None
            hotbar_icon_picker_open = False
        elif kind == "cancel":
            # Discard the in-progress draft AND deselect this slot, so
            # the form returns to "click a slot to edit" state. Keeps
            # the user in edit mode (use Done Editing to leave entirely).
            hotbar_edit_slot = -1
            hotbar_edit_draft = None
            hotbar_focused_field = None
            hotbar_icon_picker_open = False
            print("[OmniWatch] hotbar slot edit cancelled")
        elif kind == "copy_slot":
            # Snapshot the current draft into the module clipboard.
            # Normalized so weird in-progress values (unknown kind, etc.)
            # don't get pasted back as-is. Page-name drafts can't be
            # copied (the COPY button isn't rendered in that mode), but
            # we guard here too in case the rect leaks through.
            if (hotbar_edit_draft is not None
                    and hotbar_edit_slot != "__page_name__"):
                _hotbar_clipboard = _normalize_button_entry(hotbar_edit_draft)
                print(f"[OmniWatch] hotbar copy: "
                      f"{_hotbar_clipboard.get('label') or '(no label)'!r}")
        elif kind == "paste_slot":
            # Replace the draft with the clipboard contents. SAVE still
            # has to be clicked to commit. No-op when the clipboard is
            # empty or when in page-name mode.
            if (_hotbar_clipboard is not None
                    and hotbar_edit_draft is not None
                    and hotbar_edit_slot != "__page_name__"):
                hotbar_edit_draft = dict(_hotbar_clipboard)
                hotbar_focused_field = None
                hotbar_icon_picker_open = False
                print(f"[OmniWatch] hotbar paste -> draft: "
                      f"{_hotbar_clipboard.get('label') or '(no label)'!r}")
        elif kind == "delete_slot":
            # Empty the slot NOW: clears the saved entry and persists,
            # then resets the draft to the empty entry so the form
            # immediately reflects it. The slot stays selected so the
            # user can type a new button straight in. No-op in
            # page-name mode or with no valid slot.
            if (isinstance(hotbar_edit_slot, int)
                    and 0 <= hotbar_edit_slot < len(buttons_config)):
                _empty = {"label": "", "icon": "",
                          "kind": "none", "command": ""}
                buttons_config[hotbar_edit_slot] = \
                    _normalize_button_entry(dict(_empty))
                save_buttons_config()
                hotbar_edit_draft = dict(
                    buttons_config[hotbar_edit_slot])
                hotbar_focused_field = None
                hotbar_icon_picker_open = False
                print(f"[OmniWatch] hotbar slot "
                      f"{hotbar_edit_slot + 1} deleted (emptied)")
        return True
    return False


def hotbar_select_slot(slot_idx):
    """Switch the editor's focus to a different slot, copying the
    current saved state into the draft. Called from the hotbar
    panel's click handler when in edit mode.

    `slot_idx` is normally an integer 0..19 (button slot). The special
    value "__page_name__" puts the editor into page-name editing mode:
    a single editable field that mirrors hotbar_pages[current]["name"].
    """
    global hotbar_edit_slot, hotbar_edit_draft, hotbar_focused_field
    global hotbar_icon_picker_open
    if slot_idx == "__page_name__":
        hotbar_edit_slot = "__page_name__"
        cur_page = hotbar_pages[hotbar_current_page] if hotbar_pages else None
        cur_name = (cur_page and cur_page.get("name")) or ""
        # Reuse the same draft shape; only "label" gets used for the name.
        hotbar_edit_draft = {
            "label": cur_name, "icon": "", "kind": "none", "command": "",
        }
        hotbar_focused_field = "label"   # auto-focus so user can type
        hotbar_icon_picker_open = False
        print(f"[OmniWatch] hotbar editor: editing page name "
              f"(page {hotbar_current_page + 1})")
        return
    if 0 <= slot_idx < len(buttons_config):
        hotbar_edit_slot = slot_idx
        hotbar_edit_draft = dict(buttons_config[slot_idx])
        hotbar_focused_field = None
        hotbar_icon_picker_open = False
        print(f"[OmniWatch] hotbar editor: now editing slot "
              f"{slot_idx + 1}")


def _hotbar_slot_at_pos(mx, my):
    """Returns the slot index under (mx, my) on the PRIMARY hotbar panel
    if any, else None. Used by the drag-and-drop handler to decide
    where a drop landed. Only numeric slot indices are returned —
    page navigation chrome (prev/next/name) returns None because you
    can't drop a button onto a navigation target.

    Reads from `buttons_rects` (the primary panel's per-frame rect
    list). Multi-mode panels are intentionally excluded; the editor
    only operates on the primary panel."""
    for rect, payload in buttons_rects:
        # `buttons_rects` payloads can be a bare int (primary slot),
        # a string (nav target), or a (kind, panel) tuple. We only
        # care about bare ints.
        if isinstance(payload, int) and rect.collidepoint(mx, my):
            return payload
    return None


def _hotbar_nav_arrow_at_pos(mx, my):
    """Returns 'prev' or 'next' if (mx, my) is over the primary panel's
    page-navigation arrow, else None. Used by the drag handler so
    hovering over an arrow mid-drag can flip the page (after a dwell
    delay) and let the user drop the button on a different page.

    Only the primary panel's arrows count, matching the editor's
    scope. Multi-panel arrows are ignored."""
    for rect, payload in buttons_rects:
        if not rect.collidepoint(mx, my):
            continue
        if payload == "__page_prev__":
            return "prev"
        if payload == "__page_next__":
            return "next"
    return None


def _hotbar_swap_slots(src, dst, src_page=None, dst_page=None):
    """Swap two slots — optionally across different pages — and persist.

    src/dst:           slot indices 0..19 within their respective pages.
    src_page/dst_page: 0-indexed page numbers; defaults to the
        currently-displayed page when omitted (the same-page case used
        by intra-page drag-and-drop).

    The active editor draft follows the moved button so the form keeps
    pointing at the same logical button after the swap. Cross-page
    follow works too: if the editor was on slot N of page A and we
    move that button to slot M of page B, the editor switches to
    showing page B and selects slot M.

    No-op if the resolved (page, slot) pair is identical for src and
    dst (drag-and-drop onto the same slot), or if any index is out
    of range."""
    global hotbar_edit_slot, hotbar_edit_draft, hotbar_current_page

    if src_page is None: src_page = hotbar_current_page
    if dst_page is None: dst_page = hotbar_current_page

    # Validate pages.
    if not (0 <= src_page < len(hotbar_pages)
            and 0 <= dst_page < len(hotbar_pages)):
        return
    src_buttons = hotbar_pages[src_page]["buttons"]
    dst_buttons = hotbar_pages[dst_page]["buttons"]
    # Validate slot indices and identity.
    if not (0 <= src < len(src_buttons)
            and 0 <= dst < len(dst_buttons)):
        return
    if src_page == dst_page and src == dst:
        return

    # Swap. For same-page swaps, both refs point to the same list so
    # the two-line tuple swap is correct as-is. For cross-page swaps,
    # we're moving items between two distinct lists.
    if src_page == dst_page:
        src_buttons[src], src_buttons[dst] = (
            src_buttons[dst], src_buttons[src])
    else:
        src_buttons[src], dst_buttons[dst] = (
            dst_buttons[dst], src_buttons[src])

    # Keep the active page's buttons_config view in sync. buttons_config
    # is the live reference used by render/click for the CURRENT page.
    # If the active page is one of the affected ones, refresh it.
    global buttons_config
    if hotbar_current_page == src_page:
        buttons_config = hotbar_pages[hotbar_current_page]["buttons"]
    elif hotbar_current_page == dst_page:
        buttons_config = hotbar_pages[hotbar_current_page]["buttons"]

    # Follow the moved button if the editor was on it. Cross-page
    # follow: switch the editor's active page to the destination
    # so the user sees their button where they dropped it.
    if isinstance(hotbar_edit_slot, int):
        # The editor's "slot" is implicitly scoped to hotbar_current_page,
        # because select_slot reads from buttons_config. If the editor
        # was tracking the source, follow it to the destination.
        if (hotbar_current_page == src_page
                and hotbar_edit_slot == src):
            if dst_page != hotbar_current_page:
                hotbar_current_page = dst_page
                buttons_config = hotbar_pages[hotbar_current_page]["buttons"]
            hotbar_edit_slot = dst
            hotbar_edit_draft = dict(buttons_config[dst])
        elif (hotbar_current_page == dst_page
                and hotbar_edit_slot == dst):
            if src_page != hotbar_current_page:
                hotbar_current_page = src_page
                buttons_config = hotbar_pages[hotbar_current_page]["buttons"]
            hotbar_edit_slot = src
            hotbar_edit_draft = dict(buttons_config[src])

    save_buttons_config()
    if src_page == dst_page:
        print(f"[OmniWatch] hotbar editor: swapped slot {src + 1} ↔ "
              f"slot {dst + 1} on page {src_page + 1}")
    else:
        print(f"[OmniWatch] hotbar editor: swapped "
              f"page {src_page + 1} slot {src + 1} ↔ "
              f"page {dst_page + 1} slot {dst + 1}")


def draw_hotbar_drag_overlay(surface):
    """Render the in-flight drag preview: dim the source slot, draw a
    ghost of the dragged button at the cursor, and highlight the slot
    under the cursor (if any) as a drop target.

    Strategy: snapshot the source slot's pixels from the just-drawn
    panel BEFORE applying any drag visualization, then re-use that
    snapshot every frame as the ghost. The source slot itself gets
    a dim overlay AFTER we've snapshotted, so the ghost stays clean.

    No-op unless a drag is in progress AND past the movement threshold.
    Pre-threshold the source button is still in its slot looking
    normal, so showing a ghost would be jarring."""
    if hotbar_drag is None or not hotbar_drag.get("active"):
        return
    src_rect = hotbar_drag.get("src_rect")
    if src_rect is None:
        return

    # Defensive: clip src_rect to the screen so subsurface() doesn't
    # blow up on a partially off-screen slot. This shouldn't happen
    # in practice but pygame raises ValueError on out-of-bounds rects.
    screen_rect = surface.get_rect()
    clipped = src_rect.clip(screen_rect)
    if clipped.width <= 0 or clipped.height <= 0:
        return

    # 1. Capture a snapshot of the source slot if we haven't yet. This
    #    runs once per drag, before any visualization touches the
    #    surface, so the ghost is a pristine copy of the button.
    if hotbar_drag.get("snapshot") is None:
        try:
            hotbar_drag["snapshot"] = surface.subsurface(clipped).copy()
        except (ValueError, pygame.error):
            return
    snapshot = hotbar_drag["snapshot"]

    # 2. Dim the source slot — but only when we're still on the page
    #    where the button lives. If a mid-drag page-flip moved us
    #    elsewhere, the source slot isn't on screen and dimming its
    #    coordinates would just darken whatever slot now happens to
    #    occupy that screen position.
    on_source_page = (hotbar_drag.get("src_page", hotbar_current_page)
                      == hotbar_current_page)
    if on_source_page:
        dim = pygame.Surface((clipped.width, clipped.height),
                             pygame.SRCALPHA)
        dim.fill((10, 10, 14, 170))
        surface.blit(dim, (clipped.x, clipped.y))

    mx, my = pygame.mouse.get_pos()

    # 3. Page-flip dwell: if the cursor is over a nav arrow, start a
    #    dwell timer. When the timer crosses HOTBAR_DRAG_DWELL_SEC,
    #    flip pages and reset the dwell (forcing the user to leave
    #    and re-enter the arrow to flip again — without this you'd
    #    cycle through pages every 600ms while parked over the arrow).
    arrow = _hotbar_nav_arrow_at_pos(mx, my)
    now_t = time.time()
    if arrow is None:
        # Left the arrow. Cancel dwell so a future hover starts fresh.
        hotbar_drag["hover_arrow"] = None
        hotbar_drag["hover_start"] = 0.0
    else:
        if hotbar_drag.get("hover_arrow") != arrow:
            # Either a fresh hover or moved between arrows. Reset.
            hotbar_drag["hover_arrow"] = arrow
            hotbar_drag["hover_start"] = now_t
        elif (now_t - hotbar_drag.get("hover_start", now_t)
              ) >= HOTBAR_DRAG_DWELL_SEC:
            # Dwell met — flip the page. Pages wrap (mirroring the
            # behavior of the actual < > arrows when clicked).
            n_pages = max(1, len(hotbar_pages))
            delta = -1 if arrow == "prev" else 1
            new_page = (hotbar_current_page + delta) % n_pages
            # Use the existing page-set helper so all the side-effects
            # (panel page mapping, etc.) are correct.
            _hotbar_panel_set_page(0, new_page)
            # Reset dwell so the same arrow won't fire again until
            # the cursor leaves and re-enters.
            hotbar_drag["hover_start"] = float('inf')

        # Draw a progress ring on the arrow to show dwell timing.
        # Gives clear visual feedback so the flip doesn't feel
        # mysterious. Skipped when hover_start is infinity (just
        # flipped — no progress to show).
        hs = hotbar_drag.get("hover_start", 0.0)
        if hs != float('inf'):
            for rect, payload in buttons_rects:
                if not rect.collidepoint(mx, my):
                    continue
                if payload not in ("__page_prev__", "__page_next__"):
                    continue
                progress = min(1.0,
                    (now_t - hs) / HOTBAR_DRAG_DWELL_SEC)
                # Background tint to draw attention.
                hi = pygame.Surface((rect.width, rect.height),
                                    pygame.SRCALPHA)
                hi.fill((90, 160, 230, 60))
                surface.blit(hi, (rect.x, rect.y))
                # Outline thickness scales with progress.
                pygame.draw.rect(surface, (160, 200, 255),
                                 rect, max(1, int(progress * 3) + 1),
                                 border_radius=2)
                break

    # 4. Highlight the drop-target slot under the cursor (if any).
    dst_idx = _hotbar_slot_at_pos(mx, my)
    if dst_idx is not None and not (
            on_source_page and dst_idx == hotbar_drag["src_slot"]):
        for rect, payload in buttons_rects:
            if isinstance(payload, int) and payload == dst_idx:
                hi = pygame.Surface((rect.width, rect.height),
                                    pygame.SRCALPHA)
                hi.fill((90, 200, 130, 60))
                surface.blit(hi, (rect.x, rect.y))
                pygame.draw.rect(surface, (140, 230, 170),
                                 rect, 2, border_radius=3)
                break

    # 5. Ghost of the dragged button at the cursor. Centered on the
    #    cursor so the user "carries" the button as they drag.
    gx = mx - snapshot.get_width() // 2
    gy = my - snapshot.get_height() // 2
    snapshot_alpha = snapshot.copy()
    snapshot_alpha.set_alpha(190)
    surface.blit(snapshot_alpha, (gx, gy))


# ── Target card ─────────────────────────────────────────────────────────────
# Base dimensions at scale 1.0. Height grows with ability list, capped so the
# card never dominates the screen. Widths calibrated for readable text.
TC_WIDTH      = 220   # mob-info column width (tall-not-wide shape)
TC_TITLE_H    = 16    # "TARGET  12.4y" title strip above the name header
TC_HEADER_H   = 34    # name + hex id strip at the top
TC_ICON_H     = 48    # family-icon strip
TC_HP_H       = 16    # HP bar
TC_SECTION_H  = 15    # one-line text sections (strengths, weaknesses)
TC_ABILITY_H  = 13    # per-ability-line
TC_PAD        = 5
TC_MAX_ABIL   = 8     # cap on visible ability lines (before "+N more")
TC_FADE_SEC   = 3.0   # seconds to fully fade after target lost

COL_TC_BG       = (22, 22, 30)
COL_TC_BORDER   = (65, 65, 85)
COL_TC_HEADER   = (32, 32, 45)
COL_TC_NAME     = (230, 230, 245)
COL_TC_HEX      = (130, 130, 160)
COL_TC_STRONG   = (120, 220, 120)
COL_TC_WEAK     = (230, 110, 110)
COL_TC_LABEL    = (140, 140, 170)
COL_TC_ABILITY  = (200, 200, 215)

# Family → icon draw function. Each takes (surface, cx, cy, radius, color).
def _icon_dragon(surf, cx, cy, r, color):
    # Diamond head with an "eye" dot.
    pts = [(cx, cy - r), (cx + r, cy), (cx, cy + r), (cx - r, cy)]
    pygame.draw.polygon(surf, color, pts, 2)
    pygame.draw.circle(surf, color, (int(cx + r * 0.3), int(cy)), max(1, r // 6))

def _icon_beastman(surf, cx, cy, r, color):
    # Stylized helmet: circle with two horn triangles.
    pygame.draw.circle(surf, color, (cx, cy), r, 2)
    pygame.draw.polygon(surf, color, [(cx - r, cy - r // 2),
                                      (cx - r - r // 3, cy - r - r // 3),
                                      (cx - r // 2, cy - r)], 2)
    pygame.draw.polygon(surf, color, [(cx + r, cy - r // 2),
                                      (cx + r + r // 3, cy - r - r // 3),
                                      (cx + r // 2, cy - r)], 2)

def _icon_undead(surf, cx, cy, r, color):
    # Skull: circle with two eye dots and a mouth line.
    pygame.draw.circle(surf, color, (cx, cy - r // 4), r, 2)
    eye = max(2, r // 4)
    pygame.draw.circle(surf, color, (cx - r // 2, cy - r // 4), eye)
    pygame.draw.circle(surf, color, (cx + r // 2, cy - r // 4), eye)
    pygame.draw.line(surf, color, (cx - r // 2, cy + r // 2),
                                  (cx + r // 2, cy + r // 2), 2)

def _icon_arcana(surf, cx, cy, r, color):
    # Six-pointed star.
    import math as _m
    pts = []
    for i in range(12):
        ang = _m.pi / 6 * i - _m.pi / 2
        rr  = r if i % 2 == 0 else r // 2
        pts.append((cx + int(rr * _m.cos(ang)), cy + int(rr * _m.sin(ang))))
    pygame.draw.polygon(surf, color, pts, 2)

def _icon_demon(surf, cx, cy, r, color):
    # Triangle pointing down with inner V (horns).
    pygame.draw.polygon(surf, color, [(cx - r, cy - r),
                                      (cx + r, cy - r),
                                      (cx, cy + r)], 2)
    pygame.draw.line(surf, color, (cx - r // 2, cy - r),
                                  (cx,          cy - r // 4), 2)
    pygame.draw.line(surf, color, (cx + r // 2, cy - r),
                                  (cx,          cy - r // 4), 2)

def _icon_aquan(surf, cx, cy, r, color):
    # Wavy horizontal lines.
    for i, dy in enumerate((-r // 2, 0, r // 2)):
        import math as _m
        pts = []
        for j in range(9):
            px = cx - r + j * (r // 4)
            py = cy + dy + int(_m.sin(j * 1.2 + i) * (r // 6))
            pts.append((px, py))
        if len(pts) >= 2:
            pygame.draw.lines(surf, color, False, pts, 2)

def _icon_bird(surf, cx, cy, r, color):
    # Chevron (wings).
    pygame.draw.lines(surf, color, False,
                      [(cx - r, cy + r // 2),
                       (cx - r // 2, cy - r // 2),
                       (cx, cy),
                       (cx + r // 2, cy - r // 2),
                       (cx + r, cy + r // 2)], 2)

def _icon_plantoid(surf, cx, cy, r, color):
    # Leaf shape (two arcs).
    rect = pygame.Rect(cx - r, cy - r, 2 * r, 2 * r)
    import math as _m
    pygame.draw.arc(surf, color, rect, _m.pi * 0.25, _m.pi * 1.25, 2)
    pygame.draw.line(surf, color, (cx - r // 2, cy + r // 2),
                                  (cx + r // 2, cy - r // 2), 2)

def _icon_vermin(surf, cx, cy, r, color):
    # Oval body with legs.
    pygame.draw.ellipse(surf, color, (cx - r, cy - r // 2, 2 * r, r), 2)
    for dx in (-r, -r // 2, 0, r // 2, r):
        pygame.draw.line(surf, color, (cx + dx // 2, cy), (cx + dx, cy + r // 2), 1)

def _icon_lizard(surf, cx, cy, r, color):
    # Zig-zag (reptilian silhouette).
    pygame.draw.lines(surf, color, False,
                      [(cx - r, cy), (cx - r // 2, cy + r // 3),
                       (cx, cy - r // 3), (cx + r // 2, cy + r // 3),
                       (cx + r, cy)], 2)

def _icon_beast(surf, cx, cy, r, color):
    # Paw: large circle with four smaller pads.
    pygame.draw.circle(surf, color, (cx, cy + r // 4), r * 2 // 3, 2)
    for dx, dy in ((-r // 2, -r // 2), (r // 2, -r // 2),
                   (-r, 0), (r, 0)):
        pygame.draw.circle(surf, color, (cx + dx, cy + dy), max(2, r // 4), 2)

def _icon_luminian(surf, cx, cy, r, color):
    # Radiant: circle with outward rays.
    pygame.draw.circle(surf, color, (cx, cy), r // 2, 2)
    import math as _m
    for i in range(8):
        ang = _m.pi / 4 * i
        pygame.draw.line(surf, color,
                         (cx + int(r * 0.55 * _m.cos(ang)),
                          cy + int(r * 0.55 * _m.sin(ang))),
                         (cx + int(r * _m.cos(ang)),
                          cy + int(r * _m.sin(ang))), 2)

def _icon_default(surf, cx, cy, r, color):
    # Generic diamond outline.
    pygame.draw.polygon(surf, color,
                        [(cx, cy - r), (cx + r, cy), (cx, cy + r), (cx - r, cy)], 2)

FAMILY_ICONS = {
    "dragon":   _icon_dragon,
    "beastman": _icon_beastman,
    "undead":   _icon_undead,
    "arcana":   _icon_arcana,
    "demon":    _icon_demon,
    "aquan":    _icon_aquan,
    "bird":     _icon_bird,
    "plantoid": _icon_plantoid,
    "vermin":   _icon_vermin,
    "bug":      _icon_vermin,
    "lizard":   _icon_lizard,
    "beast":    _icon_beast,
    "luminian": _icon_luminian,
    "luminion": _icon_luminian,
    "amorph":   _icon_default,
}

# ── Bitmap mob-family icons (loaded from data/mob_icons/) ────────────────────
# Keys are lowercase family names (derived from filenames). Values are the
# raw pygame.Surface at native size; scaled versions are cached per-size.
#
# Two source directories are scanned and merged into the same dict:
#   1) MOB_ICONS_DIR  (OmniWatch/icons/mob/) — canonical mob family icons
#                                              (Goblin.png, Worm.png, etc.)
#   2) MOBDATA_DIR/mobicons/                 — also holds per-mob BG-wiki
#                                              images (cached on demand) AND
#                                              PC race icons. We pick up the
#                                              race icons here since users
#                                              prefer keeping all PC-/per-mob
#                                              imagery in one folder rather
#                                              than the icons/mob/ tree.
# Shared dict means a single get_mob_icon_scaled lookup works for both kinds
# of key (family for mobs, race-key for PCs).
_mob_icons_raw    = {}    # key (lower) → Surface
_mob_icons_scaled = {}    # (key, size) → Surface

# Set of race-key filename stems we expect for PC icons. Used to filter
# the mobdata/mobicons/ scan: that directory ALSO contains thousands of
# per-mob BG-wiki images (cached lazily by name), and we don't want to
# preload all of them at startup. Only race-key matches get pulled in.
_PC_RACE_KEYS = {
    "humemale", "humefemale",
    "elvaanmale", "elvaanfemale",
    "tarutarumale", "tarutarufemale",
    "mithra", "galka",
}

def load_mob_icons():
    """Scan MOB_ICONS_DIR + MOBDATA_DIR/mobicons/ for icon images.
    Filename (without ext) → key. The mobdata/mobicons/ scan is filtered
    to only PC race-key stems so we don't preload thousands of per-mob
    images that get fetched on demand elsewhere."""
    global _mob_icons_raw
    _mob_icons_raw = {}

    def _load_one(dir_path, *, restrict_to_race_keys=False):
        if not dir_path or not os.path.isdir(dir_path):
            return 0
        try:
            files = os.listdir(dir_path)
        except Exception as e:
            print(f"[OmniWatch] Could not list {dir_path}: {e}")
            return 0
        loaded = 0
        for fn in files:
            lower = fn.lower()
            if not (lower.endswith(".png") or lower.endswith(".bmp") or
                    lower.endswith(".jpg") or lower.endswith(".jpeg")):
                continue
            stem = os.path.splitext(fn)[0].lower()
            if restrict_to_race_keys and stem not in _PC_RACE_KEYS:
                continue
            try:
                surf = pygame.image.load(
                    os.path.join(dir_path, fn)).convert_alpha()
            except Exception as e:
                print(f"[OmniWatch] Could not load mob icon {fn}: {e}")
                continue
            _mob_icons_raw[stem] = surf
            loaded += 1
        return loaded

    fam_count  = _load_one(MOB_ICONS_DIR, restrict_to_race_keys=False)
    pc_dir     = os.path.join(MOBDATA_DIR, "mobicons") if MOBDATA_DIR else None
    pc_count   = _load_one(pc_dir, restrict_to_race_keys=True)
    print(f"[OmniWatch] Loaded {fam_count} mob family icons "
          f"+ {pc_count} PC race icons.")

load_mob_icons()

def get_mob_icon_scaled(key, size):
    """Return a scaled surface for the given family key, or None if no such icon."""
    if not key:
        return None
    key = key.lower()
    if key not in _mob_icons_raw:
        return None
    cache_key = (key, size)
    if cache_key in _mob_icons_scaled:
        return _mob_icons_scaled[cache_key]
    try:
        scaled = pygame.transform.smoothscale(_mob_icons_raw[key], (size, size))
    except Exception:
        scaled = pygame.transform.scale(_mob_icons_raw[key], (size, size))
    _mob_icons_scaled[cache_key] = scaled
    return scaled

# ── On-demand per-mob images from BG-wiki ────────────────────────────────
# Distinct from the family icons above. Family icons are bundled at
# install time and used as a fallback when a specific mob image isn't
# available. Per-mob images come from the merged mobdb:
#   image / image_url fields in mob_individuals.json.
#
# `image` is a filename STEM (e.g. "goblinleecher") — no extension. We
# resolve it to whichever extension exists on disk in mobicons/. This
# lets the user drop in either .png, .jpg, .jpeg, or .bmp without
# editing the JSON.
#
# Cache directory: <MOBDATA_DIR>/mobicons/. Created on first use.
# When the file isn't on disk and `image_url` is non-empty, we fire a
# background HTTP fetch to populate it. Family icon shows during the
# fetch — never blocks the render thread.

_mob_image_dir = None
if MOBDATA_DIR:
    _mob_image_dir = os.path.join(MOBDATA_DIR, "mobicons")
    try:
        os.makedirs(_mob_image_dir, exist_ok=True)
    except OSError as e:
        print(f"[OmniWatch] Could not create mobicons dir: {e}")
        _mob_image_dir = None

_mob_image_raw     = {}     # stem (str) → pygame.Surface | None (None = failed)
_mob_image_scaled  = {}     # (stem, size) → Surface
_mob_image_pending = set()  # stems currently downloading; prevents dup fetches
_mob_image_lock    = threading.Lock()

# Diagnostic: tracks which mob names we've already printed a
# lookup-debug line for, so the session log gets exactly one entry per
# mob name. Cleared on process restart.
_mob_image_logged  = set()
_mob_spells_logged = set()

# Extensions checked in order. First match wins.
_MOB_IMAGE_EXTS = (".png", ".jpg", ".jpeg", ".bmp", ".webp")


def _mob_image_resolve_path(stem):
    """Find <stem>.{png|jpg|...} on disk. Returns full path or None."""
    if not stem or not _mob_image_dir:
        return None
    for ext in _MOB_IMAGE_EXTS:
        path = os.path.join(_mob_image_dir, stem + ext)
        if os.path.isfile(path):
            return path
    return None


def _mob_image_load_local(stem):
    """Try to load the image from disk. Returns Surface or None."""
    path = _mob_image_resolve_path(stem)
    if not path:
        return None
    try:
        return pygame.image.load(path).convert_alpha()
    except Exception as e:
        # File may be corrupt (partial download from previous crash etc).
        # Remove it so the next fetch tries again.
        print(f"[OmniWatch] Bad mob image {os.path.basename(path)}: {e} — removing.")
        try: os.remove(path)
        except OSError: pass
        return None


def _mob_image_download(stem, url):
    """Background-thread function. Downloads `url` and saves as
    <stem>.<ext> under mobicons/, where <ext> is inferred from the
    URL's path. Then loads the surface for the main render thread to
    pick up on its next frame.

    Errors are logged but not raised — failed downloads just leave the
    family icon showing. We mark the stem as 'attempted' (None entry)
    so we don't retry every frame this session; the user can clear the
    cache to retry.
    """
    global _mob_image_raw
    try:
        req = urllib.request.Request(url, headers={
            "User-Agent": "OmniWatch/1.0 (BG-wiki image fetch)",
        })
        with urllib.request.urlopen(req, timeout=10) as resp:
            data = resp.read()
        if not data:
            raise RuntimeError("empty response")
        # Pick extension from the URL path. Default to .jpg if URL has
        # no recognizable extension — most scraped mob images are jpg.
        url_path = urllib.parse.urlparse(url).path.lower()
        ext = ".jpg"
        for candidate in _MOB_IMAGE_EXTS:
            if url_path.endswith(candidate):
                ext = candidate
                break
        path = os.path.join(_mob_image_dir, stem + ext)
        # Atomic-ish: write to .tmp then rename.
        tmp_path = path + ".tmp"
        with open(tmp_path, "wb") as f:
            f.write(data)
        os.replace(tmp_path, path)
        try:
            surf = pygame.image.load(path)
        except Exception as e:
            print(f"[OmniWatch] mob image fetched but unloadable {stem}: {e}")
            with _mob_image_lock:
                _mob_image_raw[stem] = None
            return
        with _mob_image_lock:
            _mob_image_raw[stem] = surf
    except Exception as e:
        print(f"[OmniWatch] mob image fetch failed {stem}: {e}")
        with _mob_image_lock:
            _mob_image_raw[stem] = None
    finally:
        with _mob_image_lock:
            _mob_image_pending.discard(stem)


def get_mob_image_scaled(stem, url, size):
    """Return a scaled per-mob image, or None if not available yet.

    `stem` is the filename without extension (e.g. "goblinleecher"). We
    look on disk for any of <stem>.{png|jpg|...} and use the first
    that exists.

    First call for a given stem: tries disk; if missing AND `url` is
    non-empty, kicks off a background download (returns None this
    frame). Subsequent calls return the scaled surface from cache.
    """
    if not stem or not _mob_image_dir:
        return None
    raw = _mob_image_raw.get(stem, "_NOT_TRIED_")
    if raw == "_NOT_TRIED_":
        raw = _mob_image_load_local(stem)
        if raw is not None:
            with _mob_image_lock:
                _mob_image_raw[stem] = raw
        elif url:
            with _mob_image_lock:
                if stem in _mob_image_pending:
                    return None
                _mob_image_pending.add(stem)
                _mob_image_raw[stem] = "_NOT_TRIED_"
            t = threading.Thread(
                target=_mob_image_download,
                args=(stem, url),
                daemon=True,
                name=f"mob-image-{stem}",
            )
            t.start()
            return None
        else:
            with _mob_image_lock:
                _mob_image_raw[stem] = None
            return None
    if raw is None:
        return None
    cache_key = (stem, size)
    if cache_key in _mob_image_scaled:
        return _mob_image_scaled[cache_key]
    try:
        if not raw.get_flags() & pygame.SRCALPHA:
            raw = raw.convert_alpha()
            _mob_image_raw[stem] = raw
        scaled = pygame.transform.smoothscale(raw, (size, size))
    except Exception as e:
        print(f"[OmniWatch] mob image scale failed {stem}: {e}")
        return None
    _mob_image_scaled[cache_key] = scaled
    return scaled

# ── Status icon cache (buff / debuff icons in icons/status/) ─────────────
# Mirrors _mob_icons_* but keyed by buff_id (int). The lua side extracts
# 32x32 BMPs from the buff DAT (icon_extractor.buff_by_id) into
# OmniWatch/icons/status/<id>.bmp at the moment a buff is first seen on
# any party member. We load lazily — first request for a given id reads
# the BMP off disk, caches the surface, and returns scaled copies on
# subsequent calls.
#
# Returns None if the file isn't on disk yet (lua hasn't extracted it
# this session, or the id is outside the buff DAT range). Render code
# should fall back to text label in that case.
_status_icon_dir = None
_status_icon_raw    = {}     # buff_id (int)         → Surface | None
_status_icon_scaled = {}     # (buff_id, size)       → Surface

# Resolved as a sibling of ICON_DIR (which is icons/equipment/). Don't
# search separately — same install root won the equipment lookup, and
# the lua side writes here unconditionally.
if ICON_DIR:
    _status_icon_dir = os.path.join(_icon_root, "status")
    try:
        os.makedirs(_status_icon_dir, exist_ok=True)
    except OSError as e:
        print(f"[OmniWatch] Could not create status icon dir: {e}")
        _status_icon_dir = None

def _status_icon_load_raw(buff_id):
    """Load <buff_id>.bmp from disk. Returns Surface or None."""
    if not _status_icon_dir:
        return None
    path = os.path.join(_status_icon_dir, f"{int(buff_id)}.bmp")
    if not os.path.isfile(path):
        return None
    try:
        return pygame.image.load(path).convert_alpha()
    except Exception as e:
        # Likely a partial-write from a recent extraction. Remove so the
        # next ensure_status_icon retry can write fresh bytes.
        print(f"[OmniWatch] Bad status icon {buff_id}.bmp: {e} — removing.")
        try: os.remove(path)
        except OSError: pass
        return None

def get_status_icon_scaled(buff_id, size):
    """Return a scaled status icon surface, or None if unavailable.

    Caches the raw load AND the per-size scaled result. Negative ids
    (synthetic sim-mode buffs) and ids outside the FFXI buff range
    short-circuit to None.
    """
    if buff_id is None or not _status_icon_dir:
        return None
    try:
        bid = int(buff_id)
    except (TypeError, ValueError):
        return None
    if bid <= 0 or bid > 1024:
        return None

    raw = _status_icon_raw.get(bid, "_NOT_TRIED_")
    if raw == "_NOT_TRIED_":
        raw = _status_icon_load_raw(bid)
        _status_icon_raw[bid] = raw
    if raw is None:
        return None

    cache_key = (bid, size)
    cached = _status_icon_scaled.get(cache_key)
    if cached is not None:
        return cached
    try:
        scaled = pygame.transform.smoothscale(raw, (size, size))
    except Exception:
        try:
            scaled = pygame.transform.scale(raw, (size, size))
        except Exception as e:
            print(f"[OmniWatch] status icon scale failed {bid}: {e}")
            return None
    _status_icon_scaled[cache_key] = scaled
    return scaled

